// Never print a raw code: an unlisted action is prettified ("order_item_qty" -> "Order item qty").
function actLabel(code) {
  const k = String(code || "").trim();
  if (!k) return "—";
  if (OP_ACTION_LABELS[k]) return OP_ACTION_LABELS[k];
  const w = k.replace(/_/g, " ").trim();
  return w.charAt(0).toUpperCase() + w.slice(1);
}
// which: "oplog_retention_days" (operation log) or "custlog_retention_days" (customer log).
//
// WHO MAY ACTUALLY CHANGE THIS — ANSWERED BY THE SERVER, NOT GUESSED HERE (owner, 2026-08-21).
// This drew a live dropdown for EVERYONE with no gate. A real manager is refused server-side (a
// retention dial in the hands of the person it audits is an off switch with extra steps), so every
// single use of that dropdown by a manager ended in a red refusal — and the refusal said "your
// owner hasn't given managers permission", pointing them at a permission that does not exist.
// Now `whoami.retention` says canEdit / why / locked and this simply repeats it — the same rule
// canDeleteBill follows, so the screen and the server cannot drift.
//
// And when the ADMIN has locked it, the restaurant is TOLD SO ("ever admin do will be visible to
// manager") — the window is still shown, with who set it. A locked control that just greys out
// with no reason is the thing he has objected to before.
function retentionControl(which) {
  const cur = Number((state.data.settings || {})[which]) || 90;
  const R = (typeof XRAY_WHO !== "undefined" && XRAY_WHO && XRAY_WHO.retention) || null;
  const label = (RETENTION_OPTS.find((o) => o.d === cur) || {}).label || cur + " days";
  // No answer yet (an old cached app.js against a new server, or whoami still in flight) →
  // show the READ-ONLY form. Never offer a control we cannot prove is allowed.
  if (!R || R.canEdit !== true) {
    const locked = !!(R && R.locked);
    const why = locked
      ? "Aevidine set this for every restaurant. You can see it, but only Aevidine can change it."
      : "Only the restaurant's owner can change how long logs are kept.";
    return `<span class="ret-ctl ret-ctl-ro" title="${esc(why)} Logs older than this are deleted automatically by a once-a-day cleanup. Your bills are never touched.">
        <i class="fas fa-clock-rotate-left"></i> Logs kept for <b>${esc(label)}</b>
        <em class="ret-by">${locked ? "🔒 set by Aevidine" : "owner only"}</em>
      </span>`;
  }
  const opts = RETENTION_OPTS
    .map((o) => `<option value="${o.d}"${o.d === cur ? " selected" : ""}>${o.label}</option>`)
    .join("");
  return `<label class="ret-ctl" title="Logs older than this are deleted automatically by a once-a-day cleanup. Your bills are never touched.">
      <i class="fas fa-clock-rotate-left"></i> Keep logs for
      <select class="ret-select" data-ret="${esc(which)}">${opts}</select>
    </label>`;
}
// Save a new retention choice. Sends ONLY this one field (a partial settings
// upsert leaves every other setting untouched), then updates local state so the
// dropdown stays put on the next redraw.
async function saveRetention(which, val) {
  const days = Math.min(Math.max(parseInt(val, 10) || 90, 1), 90);
  try {
    // No id here — the server keys settings by restaurant_id and fills the row's real id
    // itself. (Sending the legacy id:"site" used to collide with #1's PK on other tenants.)
    const _wq = await api("POST", "/settings", { [which]: days });
    state.data.settings = { ...(state.data.settings || {}), [which]: days };
    const lbl = (RETENTION_OPTS.find((o) => o.d === days) || {}).label || days + " days";
    okToast(_wq, "Saved — old logs auto-delete after " + lbl);
  } catch (e) {
    // BRANCH ON THE SERVER'S CODE, NOT ITS PROSE. A refusal here is a real answer ("Aevidine
    // locked it" / "owner only"), not a failure to reach the server, so it must not read like one.
    // api() carries the parsed reply on `e.data` (with `e.status`) — that is this panel's
    // contract for every call, so read the code from there and nowhere else.
    const code = (e && e.data && e.data.code) || "";
    if (code === "retention_locked" || code === "retention_manager_blocked") {
      toast(e.message || "That's not yours to change.", "err");
      // Put the dropdown back on the value that is really stored, so the screen never keeps
      // showing a window the restaurant is not on. Done to the element rather than through a
      // full redraw: this runs inside a tab whose own redraw would also refetch the log.
      const sel = document.querySelector('.ret-select[data-ret="' + which + '"]');
      if (sel) sel.value = String(Number((state.data.settings || {})[which]) || 90);
      return;
    }
    toast("Couldn't save retention: " + e.message, "err");
  }
}

// logDetailDialog: the click-to-open card showing a single log row's FULL info —
// exact date + time, who/what/where. `rows` is [{ label, value }]. Reuses the
// confirm-overlay look so it matches every other dialog in the editor.
function logDetailDialog(title, rows) {
  const wrap = document.createElement("div");
  wrap.className = "confirm-overlay";
  // A row can be a SECTION heading ({ section:"When" }) or a value line
  // ({ label, value }). Section headings render even with no value; value lines
  // are dropped when empty so a row is tidy but never shows a blank field. A
  // section whose every value line is empty is skipped so we don't leave a lone heading.
  const isVal = (r) => r && r.value != null && r.value !== "";
  const kept = [];
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    if (r && r.section) {
      // Look ahead: keep this heading only if a value line follows before the next heading.
      let hasVal = false;
      for (let j = i + 1; j < rows.length && !rows[j].section; j++) { if (isVal(rows[j])) { hasVal = true; break; } }
      if (hasVal) kept.push(r);
    } else if (isVal(r)) {
      kept.push(r);
    }
  }
  const body = kept
    .map((r) => r.section
      ? `<div class="ld-sec"${r.accent ? ` style="color:${esc(r.accent)}"` : ""}>${esc(r.section)}</div>`
      : `<div class="ld-row"><span class="ld-k">${esc(r.label)}</span><span class="ld-v"${r.strong ? ` style="font-weight:800${r.color ? `;color:${esc(r.color)}` : ""}"` : ""}>${esc(r.value)}</span></div>`)
    .join("");
  wrap.innerHTML = `
    <div class="confirm-box logdetail">
      <div class="confirm-msg"><b>${esc(title)}</b></div>
      <div class="ld-list">${body}</div>
      <div class="confirm-actions"><button class="btn confirm-ok">Close</button></div>
    </div>`;
  document.body.appendChild(wrap);
  requestAnimationFrame(() => wrap.classList.add("show"));
  const onKey = (e) => { if (e.key === "Escape") close(); };
  // data-closing matters even though this card asks nothing: it wears the shared
  // .confirm-overlay class, and confirmDialog refuses to open while an unanswered overlay of
  // that class is in the DOM. Without the stamp, the 200ms fade-out after closing a log card
  // silently answered "no" to the next confirm — a tap into thin air. (2026-07-30)
  const close = () => { wrap.setAttribute("data-closing", "1"); wrap.classList.remove("show"); document.removeEventListener("keydown", onKey); setTimeout(() => wrap.remove(), 200); };
  wrap.__lfhClose = close; // hardware Back closes via our close() (removes the keydown listener) — no leaked listener
  wrap.querySelector(".confirm-ok").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };
  document.addEventListener("keydown", onKey);
}

// Fetch the whole board in one call. `fromPoll` = silent (no error toast, and don't
// stomp the editor while the owner is typing in an input).
let lastBoardSig = ""; // last rendered board fingerprint — skip needless re-renders on poll
// When the TARGETED realtime path (pollTables) runs, it sets this to the changed table
// numbers so reconcileBoard's render step does an INCREMENTAL patchFloorTiles(those) instead
// of a full renderEditor() — that's the fix for the 300-table freeze (one breadcrumb must not
// rebuild the whole grid). Null = render full (initial load, full poll, tab switch, etc.).
let targetedPatchTables = null;

// ── Serve debounce ───────────────────────────────────────────────────────────
// Marking dishes served one-by-one USED to refetch the whole board (3 network
// GETs) and redraw on EVERY click — so serving 1,2,3,4,5… felt laggy and the
// 1-second poll redrew on top of it. Now each serve click updates the board
// LOCALLY and redraws instantly (no network), and we do ONE real server
// reconcile only after you've STOPPED clicking for 5 seconds. While that flush
// is pending, the background poll leaves the open panel alone so it can't redraw
// under your fingers. (The click still saves to the server immediately — it's
// only the refetch/redraw that waits.)
let serveFlushTimer = null;
const SERVE_FLUSH_MS = 5000;
function scheduleServeFlush() {
  if (serveFlushTimer) clearTimeout(serveFlushTimer);
  serveFlushTimer = setTimeout(() => { serveFlushTimer = null; loadSessions(); }, SERVE_FLUSH_MS);
}
function serveFlushPending() { return serveFlushTimer != null; }

// mergeTableSlice: drop ONE table's rows from the board/data caches and add the freshly
// fetched rows for it, leaving every other table untouched. Used wherever we load a single
// table's FULL slice (the selected-table detail in loadSessions/pollOrders/pollTables, and
// the ensure-load before a tile quick-action). Last-wins by design — safe to call without a
// stale-ticket guard; the next poll reconciles. (Factored out so the four call sites can't drift.)
function mergeTableSlice(t, selBoard, selOrders, selCalls) {
  t = String(t);
  const dedupeById = (arr) => { const m = new Map(); for (const x of arr) if (x && x.id != null) m.set(x.id, x); return [...m.values()]; };
  const b = state.board || {};
  const freshSessions = (selBoard && selBoard.sessions) || [];
  const freshOrders = selOrders || [];
  // Purge set = anything CURRENTLY cached under table t UNION anything in the FRESH payload —
  // not table t alone. A SHIFT moves a session/its orders to a new table_number server-side; if
  // an earlier cleanup call for the party's OLD table got dropped (e.g. superseded by a
  // realtime-triggered pollTables bumping the dataSeq stale-ticket while it was still in
  // flight — a real race, not hypothetical), the party's rows stay cached under the OLD
  // table_number forever. Purging by table-tag ALONE then never catches them, so the next merge
  // for the NEW table adds a second copy on top → doubled guest names / doubled dishes (each
  // still keyed by the same session/order id). Matching by id too — not just by the current
  // table_number tag — plus a final dedupeById() safety net, is what tablet's mergeSelectedSlice
  // already does; this brings the editor's merge in line with it.
  const oldSids = new Set((b.sessions || []).filter((s) => String(s.table_number) === t).map((s) => s.id));
  for (const s of freshSessions) oldSids.add(s.id);
  // ARCHIVED rows are NOT part of a table slice any more. Since the floor slice began asking
  // the server for the CURRENT party only (so a new party can never be handed the last one's
  // food), the response no longer contains that table's finished bills — and purging them here
  // would quietly empty them out of the Bills tab, which shares state.data.orders. So the slice
  // is authoritative for the table's LIVE rows only; anything already archived stays cached
  // until a real /orders fetch replaces it.
  const oldOids = new Set((state.data.orders || []).filter((o) => String(o.table_number) === t && !o.archived).map((o) => o.id));
  for (const o of freshOrders) oldOids.add(o.id);

  let orders = dedupeById((state.data.orders || []).filter((o) => !oldOids.has(o.id)).concat(freshOrders));
  orders = orders
    .filter((o) => !pendingDeletes.has(o.id))
    .map((o) => (pendingOrderOps.has(o.id) ? ((state.data.orders || []).find((x) => x.id === o.id) || o) : o));
  state.data.orders = orders;
  state.data.calls = dedupeById((state.data.calls || []).filter((c) => String(c.table_number) !== t).concat(selCalls || []));
  state.board = {
    sessions: dedupeById((b.sessions || []).filter((s) => !oldSids.has(s.id)).concat(freshSessions)),
    members: dedupeById((b.members || []).filter((m) => !oldSids.has(m.session_id)).concat((selBoard && selBoard.members) || [])),
    items: dedupeById((b.items || []).filter((i) => !oldSids.has(i.session_id)).concat((selBoard && selBoard.items) || [])),
    requests: (selBoard && selBoard.requests) || b.requests || [],
    blocklist: (selBoard && selBoard.blocklist) || b.blocklist || [],
  };
}

// Per-TABLE latest-wins guard: two overlapping loadTableSlice(t) calls (e.g. a slow one and
// a fast one during a table shift) could resolve out of order, letting the OLDER response
// clobber the newer cache for that table (the "real race, not hypothetical" the old comment
// flagged). Each fetch takes a ticket; a stale response whose ticket was superseded is dropped.
const tableSliceSeq = {};
// loadTableSlice(t): fetch ONE table's FULL slice (sessions/orders/calls ?table=N) and merge it
// into the board/data caches, so the helpers that read those caches (ordersForTable /
// callsForTable / openSessionForTable / itemsForOrder) return real rows for table t. The GRID
// renders from the slim summary and never needs this; it's for (1) the selected table's detail
// and (2) ENSURING a tile quick-action on a NON-selected table has the table's order ids to act
// on — without it those handlers would see an empty cache and do nothing.
async function loadTableSlice(t) {
  const key = String(t);
  const seq = (tableSliceSeq[key] = (tableSliceSeq[key] || 0) + 1);
  const q = "?table=" + encodeURIComponent(t);
  const [selBoard, selOrders, selCalls] = await Promise.all([api("GET", "/sessions" + q), api("GET", "/orders" + q), api("GET", "/calls" + q)]);
  if (seq !== tableSliceSeq[key]) return; // a newer slice for THIS table started — drop this stale one
  mergeTableSlice(t, selBoard, selOrders, selCalls);
}

// ensureTableSlice(t): load table t's full slice unless it's already the SELECTED table (whose
// slice is kept fresh by the pollers). Called at the top of every tile quick-action so the
// handler has table t's real order/call rows to act on, even when t isn't selected. Best-effort:
// a fetch failure leaves the caches as-is (the handler then no-ops rather than throwing).
// ensureTableSlice(t, force): make sure table t's FULL slice (sessions + orders + items) is in
// the client's board. Normally it trusts an already-open detail, whose slice the polls keep
// fresh. `force` refetches regardless — needed the moment something we just wrote lives on the
// SESSION row (an invoice number), because the summary refresh (pollTables) carries tiles only,
// so re-reading the board would hand back the pre-write copy. That cost a real bug: after
// generating an invoice, the bill popup read invoice_no as still null and treated its own
// successful invoice as a failure, so nothing printed.
async function ensureTableSlice(t, force = false) {
  if (!force && detailTables().includes(String(t))) return; // the open-detail table's slice is already kept fresh
  try { await loadTableSlice(t); } catch {}
}

// detailTable(): which ONE table has its full DETAIL open right now — the in-panel master-
// detail (state.selectedTable, Tables tab) OR the collapsed-mode pop-up modal (state.openSess).
// Either way that table needs its FULL slice loaded (the grid renders from the slim summary, so
// only the open detail's table pulls full order/member rows). Returns null when no detail is open.
function detailTable() {
  return state.selectedTable != null ? String(state.selectedTable)
       : state.openSess != null ? String(state.openSess)
       : null;
}
// detailTables(): EVERY table whose full detail needs to stay loaded right now — everything
// detailTable() covers, PLUS every floating popup (owner request, 2026-07-02 — multiple
// tables' details open at once, each a separate draggable card). Used wherever fetching/
// merging/redraw-gating must account for ALL open details, not just the docked one.
function detailTables() {
  const set = new Set();
  const dt = detailTable();
  if (dt != null) set.add(dt);
  for (const f of state.floatingTables) set.add(String(f.table));
  return [...set];
}

// loadSessions: fetch (or reuse) the live tables board and redraw the floor. The
// `fromPoll` flag means "this was the automatic 1-second refresh", so we stay quiet
// (no error toast) and avoid redrawing while the owner is typing or clicking.
async function loadSessions(fromPoll) {
  // On a manual/action refresh we fetch fresh data; on a poll tick pollOrders has
  // already refreshed state.board/orders/calls, so we just render from it (no
  // double round-trip).
  if (!fromPoll) {
    const seq = ++dataSeq;
    try {
      // TIER 1: the slim per-tile SUMMARY drives the GRID + side-panel queues + chimes (mig 101).
      // TIER 2: every table with a DETAIL open (docked, collapsed-mode modal, OR floating —
      // detailTables(), owner 2026-07-02: multiple floating popups at once) ALSO gets its FULL
      // slice fetched (sessions/orders/calls ?table=N) in parallel, one 3-request group per
      // table, so each detail renders complete order rows + members. The grid never needs them.
      const sels = detailTables();
      const summaryReq = api("GET", "/summary");
      const sliceReqs = sels.map((t) => {
        const q = "?table=" + encodeURIComponent(t);
        return Promise.all([api("GET", "/sessions" + q), api("GET", "/orders" + q), api("GET", "/calls" + q)]);
      });
      const [summary, ...slices] = await Promise.all([summaryReq, ...sliceReqs]);
      if (seq !== dataSeq) return; // a newer refresh started — drop this stale snapshot
      // Take the summary unless a floor action's save is still travelling (same shield the
      // board used) — or a refresh landing mid-action would flicker an optimistic tile back.
      if (!floorOpsInFlight) { state.summary = mergeServerSummary(summary); noticePrinterNews(); }
      // Merge EVERY open-detail table's full slice into the board/data caches (the rest of the
      // board is no longer fetched whole). The detail's ordersForTable/itemsForOrder read these.
      if (!floorOpsInFlight) sels.forEach((t, i) => mergeTableSlice(t, slices[i][0], slices[i][1], slices[i][2]));
      state.boardLoaded = true; // the live floor has arrived at least once → real tiles, not the skeleton
    } catch (e) {
      toast("Couldn't load tables: " + errText(e), "err");
      return;
    }
  }
  if (state.tab !== "tables") return;
  // "sig" is a fingerprint of everything the GRID + the open-detail panel draw (the slim
  // summary, the open-detail table's order rows, AND its SESSION row). If a poll arrives
  // and the fingerprint hasn't changed, there's literally nothing new — so skip the redraw.
  //
  // The session row still matters even though staff never open or close one: the detail
  // panel reads the party from openSessionForTable() (state.board.sessions), NOT from the
  // summary or the orders. A party can therefore arrive or end while summary+orders look
  // unchanged — and if the session row weren't part of this fingerprint, the dedup guard
  // would decide nothing happened and skip the redraw, leaving the detail stuck on the
  // previous party for seconds (owner report, 2026-07-02, back when opening was manual).
  // Folds in EVERY open detail (docked + every floating popup), not just one — a change to
  // ANY of them (including a popup you're not currently looking at) must still invalidate the
  // dedup guard and redraw.
  const _dts = detailTables();
  const selOrdersSig = _dts.length
    ? (state.data.orders || []).filter((o) => _dts.includes(String(o.table_number)))
    : [];
  const selSessSig = _dts.length
    ? (state.board.sessions || []).filter((s) => _dts.includes(String(s.table_number)))
    : [];
  const sig = JSON.stringify(state.summary) + "|" + JSON.stringify(selOrdersSig) + "|" + JSON.stringify(selSessSig) + "|" + JSON.stringify(state.floatingTables.map((f) => [f.table, f.pinned]));
  if (fromPoll && sig === lastBoardSig) return;
  // DON'T rebuild the floor mid-drag/resize of a floating popup: renderEditor() replaces
  // #editor.innerHTML, tearing the dragged card out from under the pointer so the drop is
  // lost (owner-facing glitch — a live poll landing mid-drag snapped the popup back). Defer
  // the redraw and flush it on pointerup. We intentionally DON'T update lastBoardSig here, so
  // the flushed loadSessions(true) still sees sig !== lastBoardSig and actually redraws.
  if (fromPoll && floatInteracting) { floatRenderPending = true; return; }
  const ed = $("#editor");
  // Don't yank the floor out from under the owner mid-edit: if they're typing in a field
  // during a background poll, hold off on the full redraw. CRUCIALLY, also DON'T advance
  // lastBoardSig while we skip — otherwise the update that landed while they typed is
  // swallowed forever (the next poll sees the same sig and dedups it away). Leaving the sig
  // stale makes the very next poll redraw; a one-shot blur listener flushes it the instant
  // they leave the field, so they never wait for the 60s backstop. (B19)
  const typing = document.activeElement && ed.contains(document.activeElement) && /^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName);
  if (fromPoll && typing) {
    if (!state._boardFlushArmed) {
      state._boardFlushArmed = true;
      document.activeElement.addEventListener("blur", () => { state._boardFlushArmed = false; loadSessions(true); }, { once: true });
    }
    renderTablePanel(); // the legacy pop-up is a separate overlay — safe to refresh
    return;
  }
  state._boardFlushArmed = false;
  lastBoardSig = sig;
  // Keep the in-panel table detail's scroll across a background re-render so a
  // live poll never flings a half-read order list back to the top.
  const prevBody = ed.querySelector(".tp-detail-body");
  const detailTop = prevBody ? prevBody.scrollTop : 0;
  renderEditor();
  const newBody = ed.querySelector(".tp-detail-body");
  if (newBody) newBody.scrollTop = detailTop;
  renderTablePanel(); // refresh the legacy pop-up panel too, if one is open
}

// ---- session staff actions ----
// Each of these calls the server, then reloads the board and shows a toast. They
// all follow the same shape: do the action, refresh, confirm (or report a failure).

// flipOrderItems: locally mark every dish row of an order — the optimistic
// half of the quick actions; the server is told right after in the background.
function flipOrderItems(o, from, to) {
  (state.board.items || []).forEach((it) => { if (it.order_id === o.id && (!from || it.status === from)) it.status = to; });
  (o.items || []).forEach((it) => { if (!from || (it.status || "received") === from) it.status = to; });
}

// ── "OPEN THIS TABLE" IS GONE (owner, 2026-07-31) ────────────────────────────────────
// openTableSession() / openAllTables() / closeAllTables() used to live here. Seating a
// table was a step staff had to remember before guests could order, and closing it was a
// step they had to remember after. Both are now automatic: the first order starts the
// party, a settled bill ends it (see maybeAutoSettle). Nothing in the panel opens or
// closes a table by hand any more, so those three functions — and the floor's
// "⬆ Open all / ⬇ Close all" card — were removed rather than left as dead buttons.
// /sessions/close-all and /sessions/open-all are now GONE from the server too (owner,
// 2026-08-04: "remove that option completely") — mig 268 drops both RPCs and the route
// handlers went with them, so the bulk close cannot be reached from anywhere. The single
// /sessions/open endpoint stays: the waiter tablet still seats a table by hand.
// summaryTableOpen() below stays: it answers
// "is anyone sitting here?", which the KOT/shift-table pickers still need.
// summaryTableOpen(t): is table t currently OPEN, per the slim summary? A tile is open
// when it has a summary entry whose state is anything but 'free' or 'req' (those two mean
// no open session). The board is no longer fetched whole, so the bulk actions read this.
// The seat count's chair (top-right of every floor tile) is Font Awesome's solid `fa-chair`
// — the same glyph the single-restaurant reference app uses, chosen by the owner 2026-08-03
// over the old hand-drawn outline. FA is already loaded by this panel (/panels/vendor/fa),
// so it costs no extra request; .ft-chair sizes it by font-size and inherits the text colour.
const CHAIR_SVG = `<i class="fas fa-chair ft-chair" aria-hidden="true"></i>`;

// ── AUDIT: every removal, searchable by whatever you remember ──────────────────────────────
// He asked to be able to find one fast — "from which bill, which item was related, which KOT was
// related … who did it". So the search box matches ALL of it at once: a KOT number, a bill number, a
// table, a dish name, a person's username, or the reason. One flat list, newest first, no filters to
// learn. Read is scoped + capped by the server (GET /audit).
// Keep in step with REMOVAL_KIND in app/aevinite/logs/page.tsx + app/owner/activity/page.tsx and
// with RemovalKind in lib/removalAudit.ts — a kind with no label here renders as its raw key.
// Guarded by npm run verify:audit.
const AUDIT_KIND = (function () {
  // ONE SET OF WORDS FOR ALL THREE PANELS (T7 pass 2, 2026-08-12). This was a third hand-written map
  // and it disagreed with the owner console on SIX of the eleven types — it said "Invoice voided"
  // while the manager's own button beside it reads "Reopen bill", and the owner reading the same
  // database row saw "Bill reopened". They live in /panels/auditsort.js now, loaded as a bare
  // <script> by index.html exactly as billdoc.js is (which is why they are not in lib/).
  // A stale cached app.js talking to a page without the script must not lose the Audit screen, so
  // there is a small literal fallback — the same words, so a cached panel says nothing different.
  var A = typeof LFH_AUDITSORT !== "undefined" ? LFH_AUDITSORT : null;
  if (A && A.KIND_LABEL) {
    var out = {};
    Object.keys(A.KIND_LABEL).forEach(function (k) { out[k] = [A.KIND_ICON[k] || "\u2022", A.KIND_LABEL[k]]; });
    return out;
  }
  return {
    order_cancelled: ["\uD83C\uDFAB", "KOT cancelled"], order_deleted: ["\uD83E\uDDFE", "Bill deleted"],
    dish_removed: ["\uD83C\uDF7D", "Dish removed from an order"], qty_reduced: ["\u2796", "Quantity reduced"],
    menu_item_deleted: ["\uD83D\uDCD5", "Menu item deleted"], invoice_voided: ["\u21A9\uFE0F", "Bill reopened"],
    discount_given: ["\uFF05", "Discount given"], payment_reverted: ["\u21BA", "Payment reverted"],
    on_the_house: ["\uD83C\uDF81", "Settled on the house"],
    bill_changed_after_reopen: ["\u21C4", "Bill changed after a reopen"],
    order_restored: ["\u267B\uFE0F", "Bill put back"],
  };
})();
// WHY this row was removed, in the words a person chose (the preset's own label + anything they
// typed), or an honest "no reason recorded" for a row from before the reason sheet existed.
//
// TOP LEVEL ON PURPOSE (T5 sweep, 2026-08-17). It lived as a `const` inside auditHtml(), and
// openRemovalDetail() — the card the owner asked for on 2026-08-04, "click and view the full …
// which KOT he deleted and what was the item, with time, day, everything" — calls it too. So
// clicking ANY row in Audit → Removals did nothing at all: the card is built as one template
// literal, the call threw "reasonTxt is not defined" before it was finished, and the throw landed
// in a click handler nobody awaits. Measured on the backup floor: 200 rows on screen, every one
// of them dead. Same shape as the ordersInGroup bug found the same day; verify:panel-scope now
// refuses either of them.
const auditReasonTxt = (r) => {
  const preset = REMOVAL_REASONS.find((x) => x[0] === r.reason_code);
  return [preset ? preset[1] : r.reason_code, r.reason_note].filter(Boolean).join(" — ") || "no reason recorded";
};
async function loadAudit() {
  try { state.audit = await api("GET", "/audit?limit=200"); }
  catch (e) { state.audit = { error: e.message }; }
  if (state.tab === "log" && state.logView === "audit") renderEditor();
}
// Which VIEWS of the Audit & logs tab this viewer gets (whoami.logParts — the Access
// screen's sub-options). Before whoami resolves, assume everything: the endpoints refuse
// a forbidden read anyway, and whoami's .then repaints with the real answer.
function logPartsAllowed() {
  const p = (XRAY_WHO && XRAY_WHO.logParts) || {};
  return { removals: p.removals !== false, activity: p.activity !== false, customers: p.customers !== false };
}
// The view to show: the remembered one when it's still allowed, else the first allowed
// (in sidebar order), else null (all three switched off).
function allowedLogView() {
  const parts = logPartsAllowed();
  const okOf = { audit: parts.removals, operations: parts.activity, customers: parts.customers };
  if (okOf[state.logView]) return state.logView;
  return ["audit", "operations", "customers"].find((v) => okOf[v]) || null;
}
function auditHtml() {
  const rows = Array.isArray(state.audit) ? state.audit : null;
  if (!rows) return `<div class="ed-head"><h2>Audit · removals</h2></div><div class="empty">${state.audit && state.audit.error ? esc("Couldn't load: " + state.audit.error) : "Loading…"}</div>`;
  const q = (state.auditQ || "").toLowerCase().trim();
  // SORT + FILTER BY TYPE, from the SAME module the owner console and the admin console use
  // (owner, 2026-08-11: "make something like sort thing where everything can be sorted, like what
  // is list of what"). /panels/auditsort.js is loaded as a plain script by index.html, exactly as
  // billdoc.js is — the words (AUDIT_KIND) were already shared; this is the behaviour beside them.
  // A stale cached app.js talking to a page without the script must not lose the screen, so every
  // use is guarded and falls back to the old flat, newest-first list.
  const AS = typeof LFH_AUDITSORT !== "undefined" ? LFH_AUDITSORT : null;
  const kindLabel = {}, kindIcon = {};
  Object.keys(AUDIT_KIND).forEach((k) => { kindIcon[k] = AUDIT_KIND[k][0]; kindLabel[k] = AUDIT_KIND[k][1]; });
  const reasonLabel = {};
  REMOVAL_REASONS.forEach((x) => { reasonLabel[x[0]] = x[1]; });
  // Chips from the WHOLE feed, so a chip count never changes when you tap it, and a type stays
  // reachable once you have narrowed to another one.
  const chips = AS ? AS.kindCounts(rows, kindLabel, kindIcon) : [];
  // A type that has gone from the feed (a stale chip after Refresh) falls back to All rather than
  // leaving an empty list with no way out.
  const auKind = state.auditKind && chips.some((c) => c.kind === state.auditKind) ? state.auditKind : "";
  const auSort = state.auditSort || (AS ? AS.DEFAULT_SORT : "new");
  const list = AS
    ? AS.view(rows, { kind: auKind, q, sort: auSort, kindLabel, reasonLabel })
    : rows.filter((r) => !q || [r.kot_no && "kot " + r.kot_no, r.kot_no, r.bill_no && "bill " + r.bill_no, r.bill_no,
        r.table_number && "table " + r.table_number, r.item_title, r.actor, r.reason_note, r.reason_code,
        (AUDIT_KIND[r.kind] || [])[1]].filter(Boolean).some((v) => String(v).toLowerCase().includes(q)));
  const shownMoney = AS ? AS.sumAmount(list) : 0;
  const when = (t) => { const d = new Date(t); return d.toLocaleString([], { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }); };
  return `<div class="ed-head"><h2>Audit · what was removed <span class="sub">· ${rows.length}</span></h2>
      <div style="display:flex;gap:8px"><button class="btn" id="auRefresh">↻ Refresh</button></div></div>
    <p class="au-lead">Everything taken out of the system, newest first — a cancelled ticket, a deleted bill, a dish off an order or off the menu — with the reason and the person. Every role is recorded, managers included.</p>
    ${chips.length > 1 ? `<div class="au-chips">
      <button class="au-chip${auKind === "" ? " on" : ""}" data-au-kind="">All <i>${rows.length}</i></button>
      ${chips.map((c) => `<button class="au-chip${auKind === c.kind ? " on" : ""}" data-au-kind="${esc(c.kind)}" title="Show only: ${esc(c.label)}">${c.icon} ${esc(c.label)} <i>${c.count}</i></button>`).join("")}
    </div>` : ""}
    <div class="au-controls">
      <input id="auQ" class="au-q" type="search" placeholder="Search a KOT, bill, table, dish, person or reason…" value="${esc(state.auditQ || "")}">
      ${AS ? `<label class="au-sort">Sort <select id="auSort">${AS.SORTS.map((o) => `<option value="${esc(o.id)}"${o.id === auSort ? " selected" : ""}>${esc(o.label)}</option>`).join("")}</select></label>` : ""}
    </div>
    ${list.length ? `<p class="au-count">${list.length} ${list.length === 1 ? "record" : "records"}${auKind ? " · " + esc(kindLabel[auKind] || auKind) : ""}${shownMoney > 0 ? " · " + inr(shownMoney) + " in total" : ""}</p>` : ""}
    ${list.length ? `<div class="au-rows">${list.map((r) => {
      const [ico, label] = AUDIT_KIND[r.kind] || ["•", r.kind];
      // ── NO INVOICE, NO BILL NUMBER (owner, 2026-08-26) ────────────────────────────────────
      // "whenever the print … is not clicked, the invoice has not been generated, so the KOT will
      // not know which bill number it is cut from. It will only [show] table and the time."
      // The internal `bill_no` is a daily counter a table takes the moment it opens — it is NOT a
      // document anyone has seen. Printing it beside a cancelled KOT made a manager read "Bill
      // #1074 was cancelled" when no bill had ever been issued, which is the confusion this whole
      // record exists to prevent. So it is shown ONLY once a tax invoice exists to attach it to;
      // until then the KOT is identified the way it is identified on the floor — table and time.
      const bits = [r.table_number ? "T" + esc(r.table_number) : "", r.kot_no != null ? "KOT #" + esc(r.kot_no) : "",
        (r.invoice_no && r.bill_no != null) ? "Bill #" + esc(r.bill_no) : "", r.invoice_no ? "Invoice " + esc(r.invoice_no) : "",
        r.item_title ? esc(r.item_title) + (r.qty > 1 ? " ×" + esc(r.qty) : "") : "",
        r.amount != null ? inr(parseFloat(r.amount) || 0) : ""].filter(Boolean).join(" · ");
      // ── THE TAGS, AND THE ONE QUESTION THAT MAY STILL BE OPEN (owner, 2026-08-18) ───────────
      // Tags come from the shared module, so this row wears the same words as the owner console and
      // the admin console. For a cancellation the answer tag is the one that matters: `unanswered`
      // is a real state — an old row, the tablet emptying an order dish by dish, or the automatic
      // archive when a table closes — and it is settled right here rather than being guessed.
      // The list sends the answer as a TEXT scalar (made:meta->>made) rather than the whole meta —
      // see the endpoint's note on why meta stays lazy. Normalise it before the shared tag map sees
      // it, so one row cannot read "unanswered" here and "no loss" on the owner's screen.
      const madeVal = r.made === true || r.made === "true" ? true : r.made === false || r.made === "false" ? false : null;
      const tags = AS && AS.tagsOf ? AS.tagsOf({ kind: r.kind, meta: { made: madeVal, loss_cost: r.amount } }) : [];
      const tagHtml = tags.length
        ? `<span class="au-tags">${tags.map((t) => `<span class="au-tag au-tag-${esc(t)}">${AS.tagIcon(t)} ${esc(AS.tagLabel(t))}</span>`).join("")}</span>`
        : "";
      const made = madeVal;
      const canAsk = r.kind === "order_cancelled" && r.order_id;
      const askHtml = canAsk ? `<div class="au-ask${made === null ? " open" : ""}">
        <span class="au-ask-q">${made === null ? "Was the food made?" : "Food made?"}</span>
        <button class="au-ask-b${made === true ? " on danger" : ""}" data-au-made="1" data-au-order="${esc(r.order_id)}"
          title="The food was cooked — it counts as a loss and the ingredients stay used">Yes, cooked</button>
        <button class="au-ask-b${made === false ? " on" : ""}" data-au-made="0" data-au-order="${esc(r.order_id)}"
          title="Never started — the ingredients go back into stock">No, never started</button>
      </div>` : "";
      return `<div class="au-row" role="group">
        <div class="au-main" data-au-open="${esc(r.id)}" role="button" tabindex="0" title="See exactly what was removed">
          <span class="au-ico" title="${esc(label)}">${ico}</span>
          <div class="au-mid"><b>${esc(label)}</b><span class="au-bits">${bits || "—"}</span>
            <span class="au-reason">${esc(auditReasonTxt(r))}</span>${tagHtml}</div>
          <div class="au-who"><b>${esc(r.actor || "—")}</b><small>${esc(r.actor_role || "")}</small><small>${esc(when(r.at))}</small></div>
        </div>${askHtml}
      </div>`;
    }).join("")}</div>`
    : `<div class="empty">${q ? "Nothing matches that." : auKind ? "Nothing of that kind — tap All to see everything." : "Nothing has been removed yet — this list fills itself as it happens."}</div>`}`;
}
function bindAudit() {
  const q = document.getElementById("auQ");
  if (q) q.oninput = () => { state.auditQ = q.value; const at = q.selectionStart; renderEditor();
    const n = document.getElementById("auQ"); if (n) { n.focus(); try { n.setSelectionRange(at, at); } catch {} } };
  const r = document.getElementById("auRefresh");
  if (r) r.onclick = () => { state.audit = null; renderEditor(); loadAudit(); };
  // The type chips and the sort box. Both only re-render what is already in hand — no request, no
  // egress — and neither is allowed to swallow the tap in silence: every one of them repaints.
  document.querySelectorAll("[data-au-kind]").forEach((b) => {
    b.onclick = () => { state.auditKind = b.dataset.auKind || ""; renderEditor(); };
  });
  const so = document.getElementById("auSort");
  if (so) so.onchange = () => { state.auditSort = so.value; renderEditor(); };
  // Click a row → the whole story (owner, 2026-08-04: "click and view the full — how it was and
  // what he changed, which KOT he deleted and what was the item, with time, day, everything").
  document.querySelectorAll("[data-au-open]").forEach((el2) => {
    const open = () => openRemovalDetail(el2.dataset.auOpen);
    el2.onclick = open;
    el2.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(); } };
  });
  // ── ANSWERING "was the food made?" FROM HERE (owner, 2026-08-18) ─────────────────────────────
  // The tap must never vanish: it is held while the server works (tapGuard), it says what happened
  // either way, and it reloads the record so the tag on the row matches the answer that was just
  // given. The buttons live OUTSIDE the row's own click target, so answering never also opens the
  // detail popup.
  document.querySelectorAll("[data-au-made]").forEach((b) => {
    b.onclick = async (e) => {
      e.stopPropagation();
      const made = b.dataset.auMade === "1";
      const orderId = b.dataset.auOrder;
      if (b.disabled) return;
      b.disabled = true;
      const was = b.textContent;
      b.textContent = "Saving…";
      try {
        const r2 = await api("POST", "/audit/classify", { order_id: orderId, made });
        // A QUEUED ANSWER IS NOT A RECORDED ANSWER (T5 sweep #7, 2026-08-22). With no signal the
        // outbox resolves { ok:true, queued:true }, so this said "Recorded as a loss — the
        // ingredients stay used" and then reloaded the record from the saved copy, where the row
        // still reads "Not answered yet". The screen contradicted its own toast, and the sentence
        // it chose was the one that claims an inventory consequence.
        if (wasQueued(r2)) {
          b.disabled = false; b.textContent = was;
          toast("Saved on this device ✓ — the answer will be recorded the moment you're back online.", "ok");
          return;
        }
        toast(made
          ? "Recorded as a loss" + (r2 && r2.lossCost ? " of " + inr(r2.lossCost) : "") + " — the ingredients stay used"
          : "Recorded — the ingredients go back into stock", "ok");
        state.audit = null; renderEditor(); loadAudit();
      } catch (err) {
        b.disabled = false; b.textContent = was;
        toast("Couldn't record that: " + (err && err.message ? err.message : "try again"), "err");
      }
    };
  });
}

// openRemovalDetail(id): the full record for ONE removal, in the same order and wording as the
// admin's and the owner's panels (components/admin/RemovalDetail.tsx) so nobody is shown a
// different story depending on which screen they opened.
//
// The item-by-item snapshot lives in `meta.was` and is fetched ONLY on a click — the list read is
// unchanged, because 200 snapshots for rows nobody opened is exactly the whole-board read the
// egress rules forbid. READ-ONLY: nothing here can put a bill back; that is the admin's alone.
async function openRemovalDetail(id) {
  if (!id) return;
  let d;
  try { d = await api("GET", "/audit?detail=" + encodeURIComponent(id)); }
  catch (e) { toast("Couldn't open that record: " + ((e && e.message) || e), "err"); return; }
  const m = (d && d.meta) || {};
  const w = m.was || null;
  const items = (w && Array.isArray(w.items)) ? w.items : [];
  const row = (k, v) => v == null || v === "" ? "" : `<div class="au-d-row"><span>${esc(k)}</span><b>${v}</b></div>`;
  const whenLong = (iso) => { if (!iso) return ""; try { const x = new Date(iso);
    return esc(x.toLocaleDateString(undefined, { weekday: "long", day: "numeric", month: "long", year: "numeric" })
      + " · " + x.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" })); } catch { return esc(iso); } };
  const optTxt = (o) => Array.isArray(o) ? o.map((x) => typeof x === "string" ? x : ((x && x.label) || "")).filter(Boolean).join(", ") : "";
  const label = (AUDIT_KIND[d.kind] || ["•", d.kind])[1];
  const lines = items.map((it) => {
    const qty = parseInt(it.qty, 10) || 1, unit = parseFloat(it.price) || 0;
    const opts = optTxt(it.options), rem = Array.isArray(it.removed) ? it.removed.filter(Boolean).join(", ") : "";
    return `<div class="au-d-item"><span>${esc(it.title || "—")}`
      + (opts ? `<small>+ ${esc(opts)}</small>` : "")
      + (rem ? `<small class="au-d-no">no ${esc(rem)}</small>` : "")
      + (it.note ? `<small><i>“${esc(it.note)}”</i></small>` : "")
      + `</span><span class="au-d-q">×${esc(qty)}</span><span class="au-d-amt">${inr(unit * qty)}</span></div>`;
  }).join("");
  /* BEFORE AND AFTER, SIDE BY SIDE, and the BILL — the same card the owner and the admin read
     (owner, 2026-08-12: "two box … before how it was looking and after how it was looking", and
     "the bill photo and all that details of the bill"). Both come ready-made from the endpoint
     (lib/auditDetail.ts): 'after' is the order read LIVE, so the right box always answers "how does
     it stand now" instead of freezing at a moment that has passed; the bill is the REAL document
     built by billdoc.js from the stored snapshot, never a picture. Guarded throughout — an older
     server that does not send them leaves the card exactly as it was. */
  const aft = d.__after || null;
  const goneNow = !aft || aft.state === "removed" || aft.state === "cancelled";
  // Resolved once: the snapshot's value if it kept one, else the row's own (see the note at
  // "Which KOT" below for why the bill number hides until an invoice exists).
  const invNo = (w && w.invoice_no) || d.invoice_no || null;
  const billNo = (w && w.bill_no != null) ? w.bill_no : (d.bill_no != null ? d.bill_no : null);
  const sideRows = [
    ["Kitchen ticket", w && w.kot_no != null ? "KOT #" + w.kot_no : null, aft && aft.kot_no != null ? "KOT #" + aft.kot_no : null],
    ["Table", w && w.table_number ? "T" + w.table_number : null, aft && aft.table_number ? "T" + aft.table_number : null],
    ["Lines", w && w.item_count != null ? w.item_count : null, aft && aft.item_count != null ? aft.item_count : null],
    ["Subtotal", w ? w.subtotal : null, aft ? aft.subtotal : null, 1],
    ["Discount", w ? w.discount : null, aft ? aft.discount : null, 1],
    [taxLabel(), w ? w.tax : null, aft ? aft.tax : null, 1],
    ["Total", w ? w.total : null, aft ? aft.total : null, 1],
    ["Status", w ? w.status : null, aft ? aft.status : null],
  ];
  const cellTxt = (v, isMoney) => (v == null || v === "" ? "—" : isMoney ? inr(v) : esc(String(v)));
  // Only compare where BOTH sides have a value — "—" against a number on a removed order is not a
  // change, it IS the removal, and the band above already says so.
  const moved = (a, b) => !goneNow && a != null && b != null && String(a) !== String(b);
  const sideBox = (which) => `<div class="au-side${which === 1 && goneNow ? " au-side-gone" : ""}">
      <div class="au-side-h">${which === 0 ? "Before" : (goneNow ? "After · removed" : "After · as it stands now")}</div>
      <div class="au-side-b">${sideRows.map((r) => {
        const v = which === 0 ? r[1] : r[2];
        const hot = moved(r[1], r[2]);
        return `<div class="au-side-r${hot ? " au-hot" : ""}"><span>${esc(r[0])}</span><b>${cellTxt(v, !!r[3])}</b></div>`;
      }).join("")}</div>
    </div>`;
  const changedNames = sideRows.filter((r) => moved(r[1], r[2])).map((r) => String(r[0]).toLowerCase());
  // ── WHAT THIS DID TO THE TABLE'S BILL (owner, 2026-08-26) ────────────────────────────────────
  // "the before and after in the audit section should be shown like actual … previously the whole
  // bill was this much and after cutting, this has been removed and the bill is this much."
  // The two boxes below compare the KOT with ITSELF — useful, but they never answer what it did to
  // the TABLE's bill, which is the question actually being asked. This band does, in one line, in
  // money, every time. The server works both figures out (lib/auditDetail.ts → auditBillSides);
  // an older server sends nothing and this simply does not draw.
  const bs = d.__billSides || null;
  const billSwing = bs ? `<div class="au-swing">
      <div class="au-swing-h">What this did to the bill</div>
      <div class="au-swing-row">
        <span class="au-swing-box"><i>Bill was</i><b>${inr(bs.before)}</b>${bs.lines_before != null ? `<em>${esc(bs.lines_before)} line${bs.lines_before === 1 ? "" : "s"}</em>` : ""}</span>
        <span class="au-swing-op">−</span>
        <span class="au-swing-box au-swing-cut"><i>Taken out</i><b>${inr(bs.removed)}</b>${bs.lines_before != null && bs.lines_after != null ? `<em>${esc(bs.lines_before - bs.lines_after)} line${(bs.lines_before - bs.lines_after) === 1 ? "" : "s"}</em>` : ""}</span>
        <span class="au-swing-op">=</span>
        <span class="au-swing-box au-swing-now"><i>Bill is now</i><b>${inr(bs.after)}</b>${bs.lines_after != null ? `<em>${esc(bs.lines_after)} line${bs.lines_after === 1 ? "" : "s"}</em>` : ""}</span>
      </div>
      ${bs.after === 0 && bs.removed > 0
        ? `<div class="au-swing-note">Nothing is left on this bill — every KOT on it has been cancelled, so the bill itself now counts as cancelled and was never a sale.</div>`
        : bs.removed === 0
        ? `<div class="au-swing-note">This bill is unchanged — what this record names is still on it.</div>`
        : ""}
    </div>` : "";
  const beforeAfter = w ? `${billSwing}<div class="au-d-head">Before and after</div>
      ${goneNow ? `<div class="au-gone-note">${aft && aft.state === "cancelled"
        ? "This ticket was cancelled — nothing was charged for it. The left column is what it held."
        : "This is off the books now. The left column is what it held when it was removed — the row itself is kept, which is why you can still read it."}</div>` : ""}
      <div class="au-sides">${sideBox(0)}${sideBox(1)}</div>
      ${changedNames.length ? `<div class="au-d-none">What moved is marked in amber: ${esc(changedNames.join(", "))}.</div>` : ""}` : "";
  // The bill goes in an IFRAME: it carries print CSS of its own and that must not leak onto the panel.
  // sandbox with nothing enabled — it is evidence being read, so it needs no scripts and must not
  // navigate. srcdoc is set from JS (not inlined into this template) so no quoting of the bill's own
  // markup is ever required.
  const billFrame = (typeof d.__billHtml === "string" && d.__billHtml)
    ? `<div class="au-d-head">The bill as it stood</div>
       <div class="au-billwrap"><iframe class="au-billframe" sandbox="allow-same-origin" title="The bill as it was when this happened"></iframe></div>
       <div class="au-d-none">Rebuilt from what was recorded at the time — the same document the printer produces, not a photo.</div>`
    : "";
  const html = `<div class="sx-modal-overlay au-detail-overlay"><div class="sx-modal au-detail">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>What exactly was removed</h3>
      <button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="au-d-body">
      <div class="au-d-head">What happened</div>
      ${row("What", esc(label))}
      ${row("When", whenLong(d.at))}
      ${row("Who", esc(d.actor || "—") + (d.actor_role ? ` · ${esc(d.actor_role)}` : ""))}
      ${row("Reason", esc(auditReasonTxt(d)))}
      ${d.amount != null ? row("Value removed", inr(parseFloat(d.amount) || 0)) : ""}
      <div class="au-d-head">Which KOT${invNo ? " / bill" : ""}</div>
      ${row("Kitchen ticket", (w && w.kot_no != null ? w.kot_no : d.kot_no) != null ? "KOT #" + esc((w && w.kot_no != null ? w.kot_no : d.kot_no)) : "—")}
      ${row("Table", (w && w.table_number) || d.table_number ? "T" + esc((w && w.table_number) || d.table_number) : "no table (walk-in / parcel)")}
      ${w && w.ordered_at ? row("Ordered at", whenLong(w.ordered_at)) : ""}
      ${invNo
        ? row("Bill number", billNo != null ? "#" + esc(billNo) : "\u2014") + row("Invoice", esc(invNo))
        : `<div class="au-d-none">No invoice was ever printed for this table, so this KOT belongs to no bill number — it is identified by its table and its time above. A bill number is only shown once a tax invoice exists to carry it.</div>`}
      ${w && w.customer ? row("Customer", esc(w.customer) + (w.customer_phone ? ` · ${esc(w.customer_phone)}` : "")) : ""}
      <div class="au-d-head">What was on it${w && w.item_count != null ? ` · ${esc(w.item_count)} line${w.item_count === 1 ? "" : "s"}` : ""}</div>
      ${lines ? `<div class="au-d-items">${lines}</div>`
        : d.item_title ? `<div class="au-d-items"><div class="au-d-item"><span>${esc(d.item_title)}</span><span class="au-d-q">×${esc(d.qty || 1)}</span><span class="au-d-amt"></span></div></div>`
        : `<div class="au-d-none">No item list was kept for this record — it was made before the Audit started snapshotting what it removes. Newer removals carry the full list.</div>`}
      ${w && (w.subtotal != null || w.total != null) ? `<div class="au-d-head">What the bill said</div>
        ${w.subtotal != null ? row("Subtotal", inr(w.subtotal)) : ""}
        ${parseFloat(w.discount) > 0 ? row("Discount", "− " + inr(w.discount) + (w.discount_note ? ` · ${esc(w.discount_note)}` : "")) : ""}
        ${w.tax != null ? row(taxLabel(), inr(w.tax)) : ""}
        ${w.total != null ? row("Total", inr(w.total)) : ""}
        ${row("State when removed", esc(w.status || "—") + (w.payment_status ? ` · ${w.payment_status === "paid" ? "was PAID" : "unpaid"}` : "") + (w.payment_method ? ` · ${esc(w.payment_method)}` : ""))}
        ${Array.isArray(w.allergies) && w.allergies.length ? row("Allergies", esc(w.allergies.join(", "))) : ""}` : ""}
      ${beforeAfter}
      ${billFrame}
      <div class="au-d-note">This is a record — nothing here can be changed. Only an Aevidine admin can put a deleted bill back.</div>
    </div>
  </div></div>`;
  const wrap = el(html);
  document.body.appendChild(wrap);
  // srcdoc set here rather than in the template: the bill's markup never has to survive being
  // quoted inside another string, and a failure to draw it can never stop the record opening.
  try {
    const fr = wrap.querySelector(".au-billframe");
    if (fr && typeof d.__billHtml === "string") {
      fr.onload = () => {
        try {
          const doc = fr.contentDocument;
          if (doc && doc.body) fr.style.height = Math.min(1400, Math.max(320, doc.body.scrollHeight + 24)) + "px";
        } catch (e) { /* keep the default height */ }
      };
      fr.srcdoc = d.__billHtml;
    }
  } catch (e) { /* the words and the money rows ARE the record; the bill is the illustration */ }
  const close = () => wrap.remove();
  wrap.__lfhClose = close;                     // hardware Back closes THIS, not the panel
  wrap.querySelector(".tbl-modal-close").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };
}


// Every table served as one party with t (t included), and every live order across them. Whole-party
// actions — Serve all, Mark paid, Accept all — must use these, or they silently touch ONE table of a
// merged bill: the reason "serve all" left the other tables unserved and "mark paid" left money owed.
function partyTablesOf(t) {
  const head = mergeParentOf(t) || String(t);
  const all = [String(head), ...mergeChildrenOf(head)];
  return all.length > 1 ? all : [String(t)];
}
async function ensurePartySlices(t) {
  // FORCE, deliberately. ensureTableSlice skips a table whose detail is open, trusting the pollers
  // to keep it fresh — but a whole-party action fires the instant a detail opens, before every
  // member's slice has landed, and it then acts on a PARTIAL party. That is exactly what happened:
  // "Accept all & prepare (2)" on a three-table party accepted two of the three, and the third was
  // then stuck un-accepted so it could not be served or paid. One forced round-trip per member is
  // cheap next to getting a bill wrong.
  await Promise.all(partyTablesOf(t).map((x) => ensureTableSlice(x, true).catch(() => {})));
}
function partyOrders(t) {
  const seen = new Set();
  return partyTablesOf(t).flatMap((x) => ordersForTable(x)).filter((o) => (seen.has(o.id) ? false : seen.add(o.id)));
}

// ── WHY WAS THIS REMOVED? (owner, 2026-08-01, mig 251) ─────────────────────────────────────
// "every KOT which has been deleted, every item, it's been deleted from the menu … it should ask for
//  the reason. And there should be a quick toggle where you just click 'by mistake' … and all that
//  record will be in the audit section … even if it is done by manager."
// One dialog for every removal in the panel: six one-tap reasons (By mistake first, because it is by
// far the most common and he asked for it by name), a note box for anything else, and no way to
// proceed without choosing. Returns { code, note } or null when cancelled.
const REMOVAL_REASONS = [
  ["mistake", "🙃 By mistake", "Tapped the wrong thing"],
  ["guest_changed", "🙋 Guest changed their mind", ""],
  ["wrong_table", "⇄ Wrong table", ""],
  ["sold_out", "🚫 Not available / sold out", ""],
  ["kitchen_error", "👨‍🍳 Kitchen error", ""],
  ["other", "✏️ Other reason", "Type it below"],
];
// Why a PRINTED bill is being reopened. Same shape as askRemovalReason, different words and
// different reasons — reopening is not a removal, it is almost always "they want to order more"
// (owner, 2026-08-05: "there should be a option of asking why you want to reopen ... and there
// will be a quick option that more things to add"). A free-text prompt made the commonest reason
// in the restaurant something a manager had to TYPE, every time, mid-service.
// The chosen reason travels with the void and the SERVER records it in the Audit.
const REOPEN_REASONS = [
  ["add_items", "🍽 Adding more items", "The guest wants to order more"],
  ["wrong_items", "✏️ Wrong items on the bill", ""],
  ["wrong_price", "₹ Wrong price or discount", ""],
  ["wrong_table", "⇄ Wrong table", ""],
  ["guest_request", "🙋 Guest asked for a change", ""],
  ["other", "✏️ Other reason", "Type it below"],
];
function askReopenReason(what) {
  return new Promise((resolve) => {
    const wrap = el(`<div class="sx-modal-overlay rr-overlay"><div class="sx-modal rr-modal">
      <div class="rr-head"><div class="rr-ico">↩</div><div class="rr-htxt">
        <h3>Why are you reopening this bill?</h3><p>${esc(what || "")}</p></div>
        <button class="tbl-modal-close rr-x" aria-label="Close">✕</button></div>
      <div class="rr-body"><div class="rr-grid">
        ${REOPEN_REASONS.map(([code, label, hint]) => `<button type="button" class="rr-opt" data-code="${code}">
          <b>${esc(label)}</b>${hint ? `<small>${esc(hint)}</small>` : ""}</button>`).join("")}
      </div>
      <label class="rr-notelbl" for="roNote">Anything to add <span class="muted">(optional — required for \u201cOther\u201d)</span></label>
      <input id="roNote" class="rr-note" type="text" maxlength="200" placeholder="e.g. adding 2 desserts">
      <p class="rr-foot-note">The invoice is voided (kept on record) and a NEW number is issued when you print again.
        This is recorded with your name in <b>Audit</b>, with the bill before and after.</p>
      </div>
      <div class="rr-foot"><button type="button" class="btn rr-cancel">Keep it closed</button>
        <button type="button" class="btn danger rr-go" disabled>Reopen bill</button></div>
    </div></div>`);
    document.body.appendChild(wrap);
    const note = wrap.querySelector(".rr-note"), go = wrap.querySelector(".rr-go");
    let code = null;
    const sync = () => { go.disabled = !code || (code === "other" && !note.value.trim()); };
    wrap.querySelectorAll(".rr-opt").forEach((b) => (b.onclick = () => {
      code = b.dataset.code;
      wrap.querySelectorAll(".rr-opt").forEach((x) => x.classList.toggle("sel", x === b));
      sync(); if (code === "other") note.focus();
    }));
    note.addEventListener("input", sync);
    // No manual back-layer: .sx-modal-overlay is already watched, and __lfhClose is the ONE
    // closer so the awaiting caller always gets an answer (see askRemovalReason for the story).
    function done(v) { wrap.remove(); resolve(v); }
    wrap.__lfhClose = () => done(null);
    wrap.querySelector(".rr-cancel").onclick = () => done(null);
    wrap.querySelector(".rr-x").onclick = () => done(null);
    wrap.onclick = (e) => { if (e.target === wrap) done(null); };
    go.onclick = () => { if (go.disabled) return; done({ code, note: note.value.trim() }); };
    setTimeout(() => wrap.querySelector(".rr-opt").focus(), 50);
  });
}
// askRemovalReason(what, opts)
//
// `opts.askMade` adds a SECOND required question, for a cancellation only (owner, 2026-08-18:
// "while kot delete button there will be one thing order was mode and order was not made like in red
// they have to choose"). It is required because the two answers do completely different things and
// neither may be guessed:
//   · cooked        → the ingredients are really gone. The kitchen-fire consumption stands and its
//                     cost becomes a food-loss expense.
//   · never started → the consumption is reversed and the ingredients go back on the shelf. NOTHING
//                     did this before: cancelling reversed nothing, so a mis-keyed order ate its
//                     ingredients for ever, with no record of why the shelf was short.
// Only cancelOrder passes it. Deleting a bill and removing a dish are different actions and keep the
// dialog they had.
function askRemovalReason(what, opts) {
  const askMade = !!(opts && opts.askMade);
  return new Promise((resolve) => {
    const wrap = el(`<div class="sx-modal-overlay rr-overlay"><div class="sx-modal rr-modal">
      <div class="rr-head"><div class="rr-ico">🗑</div><div class="rr-htxt">
        <h3>Why are you removing this?</h3><p>${esc(what || "")}</p></div>
        <button class="tbl-modal-close rr-x" aria-label="Close">✕</button></div>
      <div class="rr-body">${askMade ? `<div class="rr-made">
        <div class="rr-made-q">Was the food actually made?</div>
        <div class="rr-made-opts">
          <button type="button" class="rr-made-opt danger" data-made="1">
            <b>Yes — it was cooked</b><small>The ingredients are gone. It counts as a loss.</small></button>
          <button type="button" class="rr-made-opt" data-made="0">
            <b>No — never started</b><small>The ingredients go back into stock.</small></button>
        </div>
      </div>` : ""}<div class="rr-grid">
        ${REMOVAL_REASONS.map(([code, label, hint]) => `<button type="button" class="rr-opt" data-code="${code}">
          <b>${esc(label)}</b>${hint ? `<small>${esc(hint)}</small>` : ""}</button>`).join("")}
      </div>
      <label class="rr-notelbl" for="rrNote">Anything to add <span class="muted">(optional — required for “Other”)</span></label>
      <input id="rrNote" class="rr-note" type="text" maxlength="200" placeholder="e.g. guest allergic, printed twice…">
      <p class="rr-foot-note">This is recorded with your name in <b>Audit</b> — for every role, managers included.</p>
      </div>
      <div class="rr-foot"><button type="button" class="btn rr-cancel">Keep it</button>
        <button type="button" class="btn danger rr-go" disabled>Remove</button></div>
    </div></div>`);
    document.body.appendChild(wrap);
    const note = wrap.querySelector(".rr-note"), go = wrap.querySelector(".rr-go");
    let code = null, made = null;
    // Both questions must be answered when both are asked. "Unanswered" is a real state the Audit can
    // fix later (an old row, an offline replay, the automatic archive at table-close) — but it must
    // never be created by somebody standing right here with the answer.
    const sync = () => { go.disabled = !code || (code === "other" && !note.value.trim()) || (askMade && made === null); };
    wrap.querySelectorAll(".rr-opt").forEach((b) => (b.onclick = () => {
      code = b.dataset.code;
      wrap.querySelectorAll(".rr-opt").forEach((x) => x.classList.toggle("sel", x === b));
      sync(); if (code === "other") note.focus();
    }));
    wrap.querySelectorAll(".rr-made-opt").forEach((b) => (b.onclick = () => {
      made = b.dataset.made === "1";
      wrap.querySelectorAll(".rr-made-opt").forEach((x) => x.classList.toggle("sel", x === b));
      sync();
    }));
    note.addEventListener("input", sync);
    // ONE BACK LAYER, AND IT ANSWERS THE CALLER (sweep 2026-08-04).
    // This overlay wears `.sx-modal-overlay`, which wireOverlayBack()'s MutationObserver already
    // watches — so registering a layer here TOO gave one dialog two layers. The observer's runs
    // LAST (its callback is delivered at the end of the task), so it sat on top, and its closer is
    // `elm.__lfhClose ? elm.__lfhClose() : elm.remove()`. With no __lfhClose that was a bare
    // remove(): the box vanished, done() never ran, and the `await askRemovalReason(...)` every
    // caller is sitting on NEVER SETTLED — the action died mid-flight, and the leftover manual layer
    // then ate the person's next Back press with nothing on screen to explain it. Exactly the
    // "never leave a promise unresolved" rule (the tablet's #confirmOverlay had the same shape).
    // So: no manual layer, and __lfhClose is the one closer — the observer now cancels it properly.
    function done(v) { wrap.remove(); resolve(v); }
    wrap.__lfhClose = () => done(null);
    wrap.querySelector(".rr-cancel").onclick = () => done(null);
    wrap.querySelector(".rr-x").onclick = () => done(null);
    wrap.onclick = (e) => { if (e.target === wrap) done(null); };
    go.onclick = () => { if (go.disabled) return; done({ code, note: note.value.trim(), ...(askMade ? { made } : {}) }); };
    setTimeout(() => { const f = wrap.querySelector(askMade ? ".rr-made-opt" : ".rr-opt"); if (f) f.focus(); }, 50);
  });
}
// THE PANEL NO LONGER RECORDS REMOVALS ITSELF (2026-08-02). It used to POST /audit after each
// action, which is why only the two kinds this file remembered were ever written — a dish coming
// off an order, a reopened bill and a deleted menu item recorded nothing, and the waiter panel
// recorded nothing at all. The reason from askRemovalReason now travels WITH the action
// (reason_code / reason_note in the body or query), and the SERVER writes the row inside the
// endpoint that makes the change: see lib/removalAudit.ts. Do not reintroduce a client-side
// recorder — a record that depends on a panel remembering is not a record.

// ── MERGED TABLES (mig 249) ────────────────────────────────────────────────────────────────
// The floor read carries the live joins (state.summary.merges: parent_table + child_table). Two
// questions get asked all over the floor, so they live here once:
//   mergeChildrenOf(6) -> ["7","8"]   the tables being served as part of table 6's party
//   mergeParentOf(7)   -> "6"         the table that holds 7's bill, or null
// Wording rule the owner set: the parent says "merged with T7", the child says "access from T6",
// and a bill for a joined party reads "T6 + T7".
function mergeList() { return (state.summary && Array.isArray(state.summary.merges)) ? state.summary.merges : []; }
function mergeChildrenOf(t) {
  return mergeList().filter((m) => String(m.parent_table) === String(t)).map((m) => String(m.child_table))
    .sort((a, b) => (Number(a) || 0) - (Number(b) || 0));
}
function mergeParentOf(t) {
  const m = mergeList().find((x) => String(x.child_table) === String(t));
  return m ? String(m.parent_table) : null;
}
// WHO PUT THESE TABLES TOGETHER, AND WHEN (owner, 2026-08-14 — improvement 2).
// `table_merges` has recorded the person and the time on every merge since mig 308, and the floor
// summary has always SELECTed both (`merged_at, merged_by`) — nothing ever read them back. Two
// tables sharing one bill is the change most likely to be questioned afterwards ("who joined
// these?"), and until now the only way to answer was the audit log.
// Costs nothing: no new column, no new query, no extra byte on the wire — this reads fields the
// panel already has in `state.summary.merges`.
// A PARENT can hold several children, each joined at a different moment, so it reports the most
// recent one — that is the answer to "who did this to my floor just now". A CHILD reports its own.
// Returns "" when the row predates mig 308 (merged_by NULL): silence is honest, a made-up name
// is not.
function mergeCredit(t) {
  const rows = mergeList().filter((m) => String(m.child_table) === String(t) || String(m.parent_table) === String(t));
  if (!rows.length) return "";
  const latest = rows.slice().sort((a, b) => new Date(b.merged_at || 0) - new Date(a.merged_at || 0))[0];
  const who = String(latest.merged_by || "").trim();
  if (!who) return "";
  const when = latest.merged_at ? fmtClock(latest.merged_at) : "";
  return when ? `joined by ${who} at ${when}` : `joined by ${who}`;
}
// "T6 + T7" for a bill or a heading — the parent first, then every table joined to it.
function mergeGroupLabel(t) {
  const parent = mergeParentOf(t) || String(t);
  const kids = mergeChildrenOf(parent);
  return kids.length ? [parent, ...kids].map((x) => `T${x}`).join(" + ") : null;
}
// Plain words for the merge-aware refusals the table-ops RPCs answer with (mig 264) — a person
// reading "party_merged" learns nothing; these say what to do instead.
//
// THIS MAP MUST COVER EVERY CODE THE RPCs CAN ANSWER WITH (sweep 2026-08-04). Merge and move-a-KOT
// are mapped SERVER-side (mergeErrMsg / moveErrMsg in the editor route, returned as a 409 with
// prose), but **shift is not** — `sessions/:id/shift` returns the RPC's json straight through, so
// this map is the only translator on that path. It was missing three of the codes
// lfh_staff_shift_table actually returns, and both shift call sites fall back to `|| r.reason` —
// so a manager who opened Change table just as another device closed that party read the words
// "Couldn't shift: session_closed". Every code below is one the RPC can really return; if you add
// a reason to any of those functions, add its sentence here in the same commit.
// THE LIST ITSELF NOW LIVES IN public/panels/outbox.js (window.LFH_OUTBOX.REASONS), and is read
// from there rather than kept here twice. The same refusals reach a person by TWO routes — this
// panel's live toast, and the "Needs you" sheet when a saved change is refused on its way out —
// and while the wording lived only here, the second route showed the raw code and the waiter
// tablet had no map at all. One copy, in the file every panel's queue drains through, so the two
// can't drift. (outbox.js is loaded before this file in all three panels' index.html.)
// The fallback is for the impossible case of this panel running without the queue helper; it
// keeps the panel working rather than printing "undefined" at someone.
const KOT_REASON_TEXT = (window.LFH_OUTBOX && window.LFH_OUTBOX.REASONS) || {};

// IS THIS TABLE BUSY? — answered by exactly what the FLOOR SHOWS, never by the raw server state
// (owner, 2026-08-01: "see table 30 look[s] close[d] but at back-end it say[s] it's open — only
// table 6 is on, and you merge table it show[s] table 30 as open, why all this").
// He was looking at a real contradiction that MY change created. The server still reports the
// old open/close-era state 'waiting' (a party row with no guests and no orders — "Open, waiting
// for guests"), and normalizeTileState turns that into **Free** on the tile, because opening a
// table isn't a step any more. This function read the RAW state, so the floor called T30 free
// while Merge tables offered it as an open party to join. One answer now: whatever the tile says.
// Is splitting a bill offered at all? A per-restaurant switch, OFF by default (owner,
// 2026-08-01, mig 248: "in setting bill section is should have toggle to turn it on and off split
// and keep it off as default"). Read it HERE, never re-derive it: the option has three entry
// points (the KOT menu on desktop, the same menu on a phone, and the table's own footer) and a
// switch that only reaches two of them is worse than no switch.
function splitBillOn() {
  return !!(state.data.settings || {}).split_bill_enabled;
}

function summaryTableOpen(t) {
  return tableTileState(t).st !== "free";
}
// Does a party ROW exist at all, empty or not? Used only to keep such a table out of the
// "free table" lists: the floor calls it free, but shifting another party onto it would land two
// sessions on one table. It is offered in neither list, which is the honest answer for a state
// the floor deliberately no longer shows.
function tableHasAnyParty(t) {
  const tile = (state.summary.tiles || {})[String(t)];
  return !!tile && tile.state !== "free" && tile.state !== "req";
}
// ── CLOSING A TABLE IS A DECISION A PERSON MAKES (owner, 2026-08-02) ───────────────────────
// History, so this doesn't get flipped back a third time. The manual close/free path was
// deleted on 2026-07-31 with the open/close step, on the reasoning that "a settled table frees
// itself" — which was true, because lib/autoSettle ended the table the instant the last dish
// was served and the bill was paid. Using it showed why that is wrong: a party that has paid is
// usually still SITTING there, and their table vanished off the floor (or, with the restart
// mode, silently reset) while they were finishing their coffee. auto-settle is gone; this is
// what replaces it, and it only ever runs because somebody tapped it.
//
// It is offered ONLY on a finished table — every dish served AND the whole bill paid, in either
// order — so the server's own guard (lib/sessionClose.ts → closeBlock) can never refuse it, and
// there is no "close anyway" chain to pop up under a finger. The two states this deliberately
// does NOT cover are unchanged: money still owed, or food still cooking. A walk-out is still
// handled by cancelling the ticket, which keeps the void on the record instead of hiding an
// unpaid bill behind a closed table, and the waiter tablet keeps its own override close.
//
// `t` may be any table of a merged party; the tile always passes the table that HOLDS the bill.
async function closeFinishedTable(t) {
  // The floor tile is drawn from the slim summary, which can be a beat behind the truth — read
  // this table's real slice before acting on money. (Same reason openBillPreview forces it.)
  await ensureTableSlice(t, true);
  const sess = openSessionForTable(t);
  const live = partyOrders(t).filter((o) => o.status !== "cancelled");
  // A tap is never dropped in silence: if the tile was stale, say which half is still open
  // instead of returning with nothing on screen.
  if (!sess) { toast(`${tableLabel(t)} has no open party to close`, "err"); return; }
  const unpaid = live.some((o) => o.payment_status !== "paid");
  const unserved = live.some((o) => orderItemRows(o).some((r) => r.status !== "served"));
  if (unpaid || unserved) {
    toast(unpaid && unserved ? `${tableLabel(t)} still owes money and has food to serve` : unpaid ? `${tableLabel(t)} still owes money` : `${tableLabel(t)} still has food to serve`, "err");
    await pollTables([String(t)]); // put the tile back in step with the truth it just showed
    return;
  }
  // ONE TAP, NO QUESTION (owner, 2026-08-02: "close table should not have 2 step — whenever I
  // click close button"). There is nothing to weigh up by the time this button exists: the food
  // is all served and the money is all in, so "are you sure?" was asking staff to confirm a fact
  // the screen had already checked. It is also the most repeated job of a service, and a confirm
  // on it is a second tap per table, all night.
  // Safe to make immediate because it is not destructive and it is not final: the bill is kept
  // (it moves to Bills), nothing is deleted, and a table closed by mistake comes back through
  // "Restore to floor". The two guards above still refuse VISIBLY if the tile was stale.
  try {
    const _wq = await api("POST", `/sessions/${sess.id}/close`);
    state.selectedTable = null;
    state.openSess = null;
    document.querySelector(".tbl-modal-overlay")?.remove();          // the detail popup, if this came from there
    state.floatingTables = (state.floatingTables || []).filter((f) => !partyTablesOf(t).some((x) => String(x) === String(f.table)));
    await loadSessions();
    okToast(_wq, `${tableLabel(t)} closed — the bill is saved in Bills`);
  } catch (e) {
    // errText(), not e.message: a busy server or a dropped connection must read as itself here
    // (this panel already has that translator) — never "TimeoutError: The operation was aborted".
    toast("Couldn't close: " + errText(e), "err");
  }
}
// setSessAutoApprove: turn on/off "let new joiners in automatically" for a table.
async function setSessAutoApprove(id, value) {
  try { const _wq = await api("POST", "/sessions/" + id + "/auto-approve", { value: !!value }); await loadSessions(); okToast(_wq, value ? "Auto-approve on" : "Auto-approve off"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
// memberAction: approve a waiting guest, or remove one from the table.
// OPTIMISTIC: flip the local member NOW + redraw instantly, so a click feels immediate
// even with a big party — instead of waiting ~3s for the server round-trip + refetch
// (owner 2026-06-26: "whenever I click it, instantly it should update"). The awaited
// server call + loadSessions then confirm; on failure we revert the optimistic change.
async function memberAction(id, kind) {
  const m = (state.board.members || []).find((x) => x.id === id);
  const prev = m ? { approved: m.approved, removed: m.removed } : null;
  if (m) { if (kind === "approve") m.approved = true; else m.removed = true; refreshTableDetail(); }
  try {
    const _wq = await api("POST", "/members/" + id + "/" + (kind === "approve" ? "approve" : "remove"));
    await loadSessions();
    okToast(_wq, kind === "approve" ? "Approved" : "Removed");
  } catch (e) {
    if (m && prev) { m.approved = prev.approved; m.removed = prev.removed; refreshTableDetail(); } // revert on failure
    toast("Failed: " + e.message, "err");
  }
}
// Kick = remove now (works for the head too; the table stays open). Ban = kick +
// add to the blocklist (by member id, and phone if we have one).
async function kickMember(id) {
  if (!(await confirmDialog("Kick this guest from the table? Their access ends now — the table stays open.", "Kick"))) return;
  try { const _wq = await api("POST", "/members/" + id + "/remove"); await loadSessions(); okToast(_wq, "Guest removed"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
// Transfer the table: this guest becomes the HEAD (owns the tab, approves
// joiners) and the current head is kicked out — for when the original head left
// the café or never answers join requests. Confirmed first: it's a hand-over.
async function makeHead(id) {
  if (!(await confirmDialog("Make this guest the table's head? The current head is kicked out and this guest takes over approvals.", "Transfer"))) return;
  try { const _wq = await api("POST", "/members/" + id + "/make-head"); await loadSessions(); okToast(_wq, "Head transferred"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
async function banMember(id, phone) {
  if (!(await confirmDialog("Ban this guest? They're kicked now and added to the blocklist.", "Ban"))) return;
  try {
    const _wq = await api("POST", "/blocklist", { member_id: id, phone: phone || undefined }); // server also kicks them from their seat in the same call now (B23)
    await loadSessions(); okToast(_wq, "Banned");
  } catch (e) { toast("Failed: " + e.message, "err"); }
}
// itemStatus: move one session item forward (received → preparing → served).
// Saves to the server right away, then updates the board LOCALLY and redraws
// instantly (no refetch). The real reconcile happens 5s after the last click —
// see scheduleServeFlush — so serving several dishes in a row stays smooth.
async function itemStatus(id, status) {
  const it = (state.board.items || []).find((i) => i.id === id);
  const prev = it ? it.status : null;
  if (it) it.status = status;   // optimistic FIRST → the pill flips instantly (no waiting on the network)
  refreshTableDetail();         // instant redraw from local state (modal OR in-panel detail)
  scheduleServeFlush();         // sets the guard so the poll won't repaint under the finger; reconciles after the last click
  try {
    await api("POST", "/items/" + id + "/status", { status });   // persist in the background
    // Serving a dish is easy to mis-tap — offer a few-second takeback (owner, 2026-07-22).
    if (status === "served" && prev && prev !== "served" && window.LFH_UNDO) {
      const ord = it ? (state.data.orders || []).find((x) => x.id === it.order_id) : null;
      LFH_UNDO.show({
        message: `${(it && it.title) || "Dish"} served`,
        sub: ord ? `T${ord.table_number} · tap undo to put it back` : "Tap undo to put it back",
        onUndo: () => editorUndoServe([{ kind: "session", id, prev }]),
      });
    }
  } catch (e) {
    if (it && prev != null) { it.status = prev; refreshTableDetail(); } // revert the optimistic change on failure
    toast("Failed: " + e.message, "err");
  }
}
// resolveRequest: approve or dismiss a queued "let me in / open this table" request.
// OPTIMISTIC: the request row leaves the queue instantly; the real refresh
// afterwards brings in whatever the approval created (e.g. the new session).
async function resolveRequest(id, status) {
  // The tile badges read the SUMMARY's requests now, so the optimistic removal
  // mutates state.summary.requests (the row leaves the queue instantly); the refresh afterwards
  // brings in whatever the approval created (e.g. the new session) via a fresh summary.
  const before = (state.summary.requests || []);
  state.summary = Object.assign({}, state.summary, { requests: before.filter((r) => r.id !== id) });
  floorOpsInFlight++;
  loadSessions(true);
  try { const _wq = await api("POST", "/requests/" + id + "/resolve", { status }); floorOpsInFlight--; await loadSessions(); okToast(_wq, status === "approved" ? "Approved" : "Dismissed"); }
  catch (e) { floorOpsInFlight--; state.summary = Object.assign({}, state.summary, { requests: before }); loadSessions(true); toast("Failed: " + e.message, "err"); }
}
// block: add a phone/table to the blocklist (opts says which).
async function block(opts) {
  try { const _wq = await api("POST", "/blocklist", opts); await loadSessions(); okToast(_wq, "Blocked"); }
  catch (e) { toast("Couldn't block: " + e.message, "err"); }
}
// unblock: remove an entry from the blocklist.
async function unblock(id) {
  try { const _wq = await api("DELETE", "/blocklist/" + id); await loadSessions(); okToast(_wq, "Unblocked"); }
  catch (e) { toast("Couldn't unblock: " + e.message, "err"); }
}
// attendCall: mark a waiter call as handled.
// OPTIMISTIC: the row leaves the "Needs" list (and the tile emoji) instantly. The "Needs"
// card + tile emojis read the SUMMARY's calls now, so we mutate state.summary.calls; the
// refresh on success reconciles (the tile's hasCall flag comes from the server tile).
async function attendCall(id) {
  const before = state.summary.calls || [];
  const target = before.find((c) => c.id === id);
  state.summary = Object.assign({}, state.summary, { calls: before.filter((c) => c.id !== id) });
  floorOpsInFlight++;
  loadSessions(true);
  try {
    const _wq = await api("PATCH", "/calls/" + id, { resolved: true });
    floorOpsInFlight--;
    if (target && target.table_number) await pollTables([String(target.table_number)]); else await loadSessions();
    // A mis-tapped "Done" silently drops a real guest call — offer a takeback (2026-07-22).
    if (window.LFH_UNDO) LFH_UNDO.show({
      message: "Call attended",
      sub: target ? `T${target.table_number} · ${target.note || "call"} — tap undo` : "Tap undo to put the call back",
      icon: "🔔",
      onUndo: async () => { try { await api("PATCH", "/calls/" + id, { resolved: false }); await loadSessions(); } catch (e) { toast("Undo failed: " + e.message, "err"); await loadSessions(); } },
    });
    else okToast(_wq, "Marked attended");
  }
  catch (e) { floorOpsInFlight--; state.summary = Object.assign({}, state.summary, { calls: before }); loadSessions(true); toast("Failed: " + e.message, "err"); }
}

// ===================== UNIFIED FLOOR — one control center for every table =====================
// One map; tap a table to open ONE panel that does it all: open the table, take & advance
// orders (per-item when it's a session, order-level otherwise), manage guests, attend calls,
// see the bill, mark paid, and free the table. Works whether dining sessions are on or off.

// Five quick lookups used all over the unified floor — each filters the loaded
// data down to one table (or one order):
const ordersForTable = (t) => {
  const list = (state.data.orders || []).filter((o) => !o.archived && (o.table_number || "").trim() === String(t)); // live orders at table t
  const sessionsOn = !!(state.data.settings || {}).sessions_enabled;
  // If sessions are ON and this table has NO open session, any leftover non-archived
  // orders belong to a CLOSED session (stale) — the meal's over, nobody's there. Don't
  // paint the tile with them; the table is Free. (Same guard callsForTable uses, so a
  // closed table can never keep showing "Preparing"/"Served" from an old order.)
  // A MERGED CHILD'S PARTY IS ITS PARENT'S (mig 249). Its orders keep their own table number, but
  // they live on the parent's session — so without this the guard below reads "no party at this
  // table" and hides food that is on the joint bill. The server's ?table= slice resolves the same
  // way, so client and server agree about whose orders these are.
  const sess = openSessionForTable(t) || (mergeParentOf(t) ? openSessionForTable(mergeParentOf(t)) : null);
  if (sessionsOn && !sess) return [];
  // WHOSE ORDERS ARE THESE? (owner reports, 2026-07-30 and 2026-07-31 — two doors to one bug.)
  //
  // An order belongs to the party sitting here NOW when it carries THIS session's id — or when it
  // has NO session but was taken DURING this sitting (banquet / legacy paths, which is why
  // party-less rows must never be hidden).
  //
  // The 2026-07-30 door: this used to gate only on "is the table open?", so a new party inherited
  // the previous party's leftover live orders — a free Aangan table opened as "Preparing · 5
  // dishes · ₹1,150 due" from 9-day-old orders.
  // The 2026-07-31 door: the fix for that still admitted EVERY party-less row, with no date test
  // at all. Table 2 held two live orders from 7 JULY with session_id NULL, so its tile said
  // "0/1 served" (the server counts the party's one dish — correct) while its detail said 7 dishes
  // / ₹6,048, and "Mark all paid" would have billed tonight's guests for July. An order older than
  // the party cannot be the party's.
  //
  // The SERVER (the ?table= slice and lfh_table_view_summary) enforces the same rule, so the
  // browser isn't even sent the strays — this is the client agreeing, not the client deciding.
  // Never widen it back to "any session-less row" or to table_number.
  // No party row at all (a sessions-OFF restaurant on legacy data): there is nothing to compare
  // against, so the table's own live rows are the best truth available. Since migration 237 every
  // new order carries a party, so this is history only — and it must not dereference a null.
  if (!sess) return list;
  const since = sess.opened_at ? new Date(sess.opened_at).getTime() - 60000 : 0; // 60s: an order can land a moment before its session row exists
  const mine = (o) => o.session_id === sess.id
    || (!o.session_id && (!since || new Date(o.created_at || 0).getTime() >= since));
  return list.filter(mine);
};
const openSessionForTable = (t) => (state.board.sessions || []).find((s) => String(s.table_number) === String(t) && s.status === "open"); // t's open session
// sliceLoaded(t): has table t's FULL slice (its session row OR any live order) landed in
// memory yet? The two-tier design (mig 101) only fetches a table's full slice when its
// detail opens — so before that first fetch, ordersForTable/openSessionForTable are empty
// even for an occupied table. This tells the detail builder whether to render the real
// dish rows (loaded) or an instant "loading details…" placeholder driven by the always-
// fresh summary tile (streaming) — the stale-while-revalidate pattern that removes the
// 1-2s blank-panel wait without any extra fetch. (owner report, 2026-07-02)
function sliceLoaded(t) {
  const s = String(t);
  const has = (x) => (state.board.sessions || []).some((y) => String(y.table_number) === String(x))
      || (state.data.orders || []).some((o) => !o.archived && String(o.table_number) === String(x));
  // A MERGED TABLE HAS NO SESSION OF ITS OWN, so asking only about ITS table number answered "not
  // loaded yet" forever and the detail sat on a spinner that never resolved — which is exactly the
  // "I can't go inside the detail view of 7 and 8" he reported. Its party's slice is what matters.
  const head = (typeof mergeParentOf === "function" && mergeParentOf(s)) || null;
  return has(s) || (head ? has(head) : false);
}
// Open (unresolved) waiter calls at table t. Safety net: when dining sessions are
// ON, a call only counts while the table is actually OPEN — so a free/closed table
// can never show a lingering "call" badge even if a stale row slipped through.
const callsForTable = (t) => {
  const list = (state.data.calls || []).filter((c) => !c.resolved && (c.table_number || "").trim() === String(t));
  const sessionsOn = !!(state.data.settings || {}).sessions_enabled;
  // A MERGED CHILD'S PARTY IS ITS PARENT'S (T3 sweep, 2026-08-10) — the same fix ordersForTable
  // was given right above, and calls were left behind. A joined table has no session of its own,
  // so this guard answered "the table is closed, hide its calls" about a table that is serving food:
  //   · the tile lost its 💧/🙋 badge the moment you SELECTED it (unselected it comes from the
  //     summary, which has no such guard) — the exact "tile flips on selection" class of bug;
  //   · and tablePanelParts builds the Calls section from this helper, so the raised hand could
  //     not be answered from the table it was raised at (its partner's popup filters by ITS own
  //     table number, so it wasn't there either).
  // The call keeps the table number it was rung at (mig 308 moves only its session_id), which is
  // what puts the badge on the right tile — so this stays a PER-TABLE list. partyCalls() below is
  // the whole-party view the detail needs.
  const sess = openSessionForTable(t) || (mergeParentOf(t) ? openSessionForTable(mergeParentOf(t)) : null);
  if (sessionsOn && !sess) return [];
  return list;
};
// Every open call across a merged party, deduped, newest last. A party is ONE bill and ONE detail
// popup ("every table will show every order"), so the calls it lists must be the party's — a call
// rung at T7 is answerable from T6 and from T7, because they are the same guests.
const partyCalls = (t) => {
  const seen = new Set();
  return partyTablesOf(t).flatMap((x) => callsForTable(x)).filter((c) => (seen.has(c.id) ? false : seen.add(c.id)));
};
// An "open" request is MOOT once the table is open (already fulfilled) — never show it
// on an open table. join/access requests stay valid on an open table. (owner, 2026-06-18)
const reqsForTable = (t) => (state.board.requests || []).filter((r) => String(r.table_number) === String(t) && !(r.type === "open" && openSessionForTable(t)));
const itemsForOrder = (oid) => (state.board.items || []).filter((i) => i.order_id === oid); // the session items belonging to one order

// Per-item rows for an order, unified: session order_items if present, else the items JSON.
function orderItemRows(o) {
  const rows = itemsForOrder(o.id);
  // IS THIS ORDER'S BILL ALREADY INVOICED? (owner, 2026-08-26.) Worked out ONCE here rather than
  // at each of the ~6 places that draw a dish row, so "invoiced" cannot come to mean two things on
  // two screens. A live invoice number locks the row's 🗑; a VOIDED one does not, because that
  // bill was deliberately reopened. Rides on every row so itemRowHtml() needs no extra argument.
  const _s = o.session_id ? (state.board.sessions || []).find((x) => x.id === o.session_id) : null;
  const invoiceLive = !!(_s && _s.invoice_no != null && !_s.invoice_voided);
  // Carry options/removed/note through so the table panel can show the full
  // customization (what the guest chose, what to leave out) — not just the name.
  // is_mrp rides along from order_items (mig 270) so every screen that lists a dish can wear
  // the MRP stamp — the flag is FROZEN on the sold line, so a reprint says what it said then.
  if (rows.length) return rows.map((it) => ({ kind: "session", invoiceLive, id: it.id, title: it.title, qty: it.qty, status: it.status, options: it.options, removed: it.removed, note: it.note, price: Number(it.unit_price) || 0, added: it.added_allergens, removedFlag: it.removed_flag, is_mrp: !!it.is_mrp, tax_mode: it.tax_mode }));
  return (o.items || []).map((it, idx) => ({ kind: "legacy", invoiceLive, orderId: o.id, idx, title: it.title, qty: it.qty, status: it.status || "received", options: it.options, removed: it.removed, note: it.note, price: Number(it.price) || 0, is_mrp: !!it.is_mrp, tax_mode: it.tax_mode }));
}

// What the guest tapped, as an emoji for the tile / call list.
function callEmoji(note) {
  const n = (note || "").toLowerCase();
  if (n.includes("water")) return "💧";
  if (n.includes("cutlery") || n.includes("fork") || n.includes("spoon")) return "🍴";
  if (n.includes("napkin")) return "🧻";
  if (n.includes("clean")) return "🧹";
  if (n.includes("bill") || n.includes("check") || n.includes("cheque")) return "🧾";
  return "🙋";
}

// One tile's state — every situation gets its OWN colour (free/seated/new/prep/bill/done).
// Given a table number, this works out everything the tile needs: its colour (st),
// its label/sub-label, the little corner badges (requests, joiners, cart, calls),
// whether the outline should be red (unpaid) or green (paid), and a few flags the
// floor uses to decide which quick-action button to show.
//
// TWO-TIER (2026-06-27): the GRID renders 300 tiles from the slim server SUMMARY
// (state.summary.tiles) — NOT the full board, which is no longer fetched whole. So
// tableTileState DISPATCHES: the SELECTED table (whose full slice we DO fetch on tap,
// into state.board/state.data) is computed live from the board so its detail head-pill
// and optimistic flips stay pixel-identical; every OTHER tile reads the pre-computed
// summary tile. The summary is produced by lfh_table_view_summary, which mirrors
// tableTileStateFromBoard's rules EXACTLY (parity verified DB-side, mig 101).
// ── Special table types (VIP / Family / Owner's Guest) + khata — mig 166 ──────
// The tile look for each mark. APPROVED design (docs/superpowers/specs/
// 2026-07-22-table-tags-mockup.html) — VIP + Family ship exactly as the mockup.
const TABLE_TAG_INFO = {
  vip:    { label: "VIP",           emoji: "👑", ribbon: "👑 VIP" },
  family: { label: "Family",        emoji: "🏠", ribbon: "FAMILY" },
  guest:  { label: "Owner's guest", emoji: "🤝", ribbon: "GUEST" },
};
// The feature ladder's application rung, resolved from settings (mig 166):
// admin's switch AND (owner's toggle, only while the admin transferred control).
function tableTagsOn() {
  const s = state.data.settings || {};
  return s.table_tags_allowed === true && (s.table_tags_owner_control !== true || s.table_tags_enabled !== false);
}
// Is PAY LATER (khata) switched on for this restaurant? Its own module ladder — mirrors
// khataLadder() in lib/tableTags.ts, which is what every server gate reads.
function khataOn() {
  const s = state.data.settings || {};
  return s.khata_allowed === true && (s.khata_owner_control !== true || s.khata_enabled !== false);
}
// May the CURRENT viewer use a tag/khata action? Admin + owner always (higherView);
// a real manager needs the owner-granted power (whoami.effectivePowers).
function tagActionAllowed(flag) {
  // ADMIN X-RAY rule (owner 2026-07-22): the admin view always sees module buttons,
  // tinted (XRAY_CONTROLS) when off for real staff; the server lets the admin through.
  if (XRAY_WHO && XRAY_WHO.actor === "admin") return true;
  // Pay later has its OWN feature switch (settings.khata_*, mig 235) — it stopped sharing
  // table_tags_* when Access was rebuilt. This check still read table tags, so a restaurant
  // with Pay later switched OFF was still shown the "📒 Pay Later" button in the payment
  // popup (and the khata tab), and the server — which reads the right column — refused the
  // tap. Same ladder as lib/tableTags.ts → khataLadder. (owner, 2026-08-02)
  if (!(flag === "khata" ? khataOn() : tableTagsOn())) return false;
  if (XRAY_WHO && XRAY_WHO.higherView) return true;
  return xrayGrantedForManager(flag);
}
// May the CURRENT viewer take an order? Admin + owner always; a real manager needs the
// owner-granted take_orders power. Used by the floor's "tap an empty table to start ordering"
// shortcut, which has no button for XRAY_CONTROLS to hide — so the check has to be made here.
// (The order-builder's own Send is server-checked too; this only decides what a tap opens.)
function takeOrdersAllowed() {
  if (XRAY_WHO && XRAY_WHO.actor === "admin") return true;
  if (XRAY_WHO && XRAY_WHO.higherView) return true;
  return xrayGrantedForManager("take_orders");
}
// This table's mark ('' when none) — the slim summary carries it for every tile.
// ADMIN X-RAY rule (owner 2026-07-23): the admin console sees/uses EVERY feature, so a
// mark ALWAYS renders in the admin view regardless of the restaurant's feature toggle.
// A real manager/waiter sees it only when the feature is actually on for them.
function tagForTable(t) {
  const adminView = XRAY_WHO && XRAY_WHO.actor === "admin";
  if (!adminView && !tableTagsOn()) return "";
  const tile = (state.summary.tiles || {})[String(t)];
  return (tile && tile.tag) || "";
}
// The mark that governs the PARTY's bill — this table's own, else any member's.
// WHY THIS EXISTS (T3 sweep, 2026-08-10): the family sat at T7 and were then joined to T6, so the
// bill lives on T6 while the 🏠 mark is on T7. The SERVER already reads it this way — the
// on-the-house handler searches the parent and every child, with the comment "their comp must not
// stop working because the bill now lives on T28" — so a panel that asked about ONE table hid a
// button the server would have accepted. Ask the same question the server asks.
function partyTag(t) {
  for (const x of partyTablesOf(t)) { const g = tagForTable(x); if (g) return g; }
  return "";
}

// ── NO MORE "OPEN" / "CLOSED" TABLES (owner, 2026-07-31) ─────────────────────────────
// Opening and closing a table was removed from every screen. A party now starts BY ITSELF
// at the first order and ends BY ITSELF when the bill is paid. The party row (the session)
// still exists underneath — it is what keeps a table showing only its OWN orders, and what
// carries the bill/invoice number — but staff never see it or manage it.
//
// So a table that has a party but NO orders is simply AVAILABLE: the old
// "Open · waiting for guests" tile is not a state a person needs to know about. The server
// summary still computes it (that SQL is shared with other panels), so this is the ONE
// place it gets re-presented — and BOTH tile paths (summary + board) run through here, so
// the grid can never disagree with itself.
function normalizeTileState(s) {
  if (s.st === "waiting") { s.st = "free"; s.label = "Free"; s.meta = ""; }
  else if (s.st === "free") s.meta = ""; // "tap to open" was open/close-era wording
  return s;
}

function tableTileState(t) {
  // SELECTED table → live-from-board (we have its full slice; keeps detail + optimism exact).
  if (state.selectedTable != null && String(state.selectedTable) === String(t) && state.board && (state.board.sessions || []).length >= 0) {
    // Only use the board path when we actually have this table's slice loaded; otherwise
    // fall through to the summary so we never render a selected table as blank "Free".
    const hasSlice = (state.board.sessions || []).some((s) => String(s.table_number) === String(t))
      || (state.data.orders || []).some((o) => String(o.table_number) === String(t));
    if (hasSlice) return normalizeTileState(tableTileStateFromBoard(t));
  }
  return normalizeTileState(tableTileStateFromSummary(t));
}

// Build a tile from the slim server summary (state.summary.tiles[t]). The summary already
// carries the computed state/label/meta/counts/due/pay + the badge COUNTS; we only rebuild
// the small derived bits the renderer wants: the badges HTML (call emojis come from the
// summary's tiny per-restaurant calls[] list, filtered to this table) and the `done` flag.
function tableTileStateFromSummary(t) {
  const tile = (state.summary.tiles || {})[String(t)];
  if (!tile) return { st: "free", label: "Free", meta: "tap to open", badges: "", guests: 0, counts: { nw: 0, ck: 0, rd: 0, sv: 0 }, pay: "", done: false, hasNew: false, hasCall: false, hasReq: false, hasJoin: false };
  const calls = (state.summary.calls || []).filter((c) => !c.resolved && (c.table_number || "").trim() === String(t));
  let badges = "";
  if (tile.reqs) badges += `<span class="ftb req">📨${tile.reqs}</span>`;
  if (tile.pending) badges += `<span class="ftb join">🙋${tile.pending}</span>`;
  calls.slice(0, 3).forEach((c) => { badges += `<span class="ftb call">${callEmoji(c.note)}</span>`; });
  if (calls.length > 3) badges += `<span class="ftb call ftb-more">+${calls.length - 3}</span>`;
  return {
    st: tile.state, label: tile.label, meta: tile.meta, badges,
    guests: Number(tile.members) || 0, // how many people actually sat down (sessions-on only)
    counts: tile.counts || { nw: 0, ck: 0, rd: 0, sv: 0 },
    pay: tile.pay || "",
    done: tile.state === "done" && tile.pay !== "red", // served AND paid → offer RST/CLS
    hasNew: !!tile.hasNew, hasCall: !!tile.hasCall, hasReq: !!tile.hasReq, hasJoin: !!tile.hasJoin,
  };
}

// The ORIGINAL full-board computation — now used ONLY for the selected table's detail (and
// as the parity reference the SQL summary mirrors). Unchanged logic.
function tableTileStateFromBoard(t) {
  // THE PARTY'S orders, not one table's own (owner, 2026-08-03: after a merge the SELECTED
  // parent's tile read "0/2 served" while the server summary — and every unselected render —
  // said "0/4"). The summary RPC counts by SESSION, which spans the whole merged party; this
  // live path must count the same set or the tile flip-flops on selection. partyOrders is
  // ordersForTable when no merge is live, so solo tables are byte-identical to before.
  const os = partyOrders(t);
  const sess = openSessionForTable(t) || (mergeParentOf(t) ? openSessionForTable(mergeParentOf(t)) : null);
  const mem = sess ? membersOf(sess.id) : [];
  const pending = mem.filter((m) => !m.approved).length;
  const cart = sess && Array.isArray(sess.cart) ? sess.cart : []; // shared cart being built, not yet ordered
  const cartCount = cart.reduce((a, it) => a + (parseInt(it.qty, 10) || 1), 0);
  const calls = callsForTable(t);
  const reqs = reqsForTable(t); // pending open/join/access requests (guest asked staff to let them in)
  // EXCLUDE cancelled orders from the dish tally — a cancelled order's item rows keep their last
  // status (ready/cooking/served), so counting them made the SELECTED tile disagree with (a) the
  // detail head (which filters cancelled via liveRowsAll), (b) the SQL summary every OTHER tile
  // uses (mig 105: WHERE status <> 'cancelled'), and (c) the tablet (ordersOf). That mismatch was
  // the "click a table → its served/total jumps + state flips wrong" bug (owner 2026-07-06). PARITY
  // IS LAW: this now matches all three. (Money/`due`/`pay` already exclude cancelled via isUnpaidBill.)
  const liveOs = os.filter((o) => o.status !== "cancelled"); // the orders that actually count (summary uses this too)
  const items = liveOs.flatMap((o) => orderItemRows(o));
  // Counts are by QUANTITY (plates), not row count — a "2× Cappuccino" line is 2 cooking, not 1.
  // Mirrors the summary RPC (mig 105) and the tablet detail so every tile agrees. (owner 2026-06-29)
  const qtyOf = (i) => Math.max(0, parseInt(i.qty, 10) || 1);
  const anyReceived = items.some((i) => i.status === "received");
  const anyPreparing = items.some((i) => i.status === "preparing");
  const anyReady = items.some((i) => i.status === "ready"); // cooked, waiting for the waiter
  // An order only becomes an "unpaid bill" (red outline) once it's ACCEPTED. A
  // brand-new order still sitting at "received" hasn't been confirmed by staff
  // yet, so it shouldn't flag the table red — that starts when you accept it.
  const isUnpaidBill = (o) => o.status !== "cancelled" && o.status !== "received" && o.payment_status !== "paid";
  const unpaid = os.some(isUnpaidBill);
  // discount-before-tax (billMath) so the tile "due" matches the bill / server summary
  const due = billMath(os.filter(isUnpaidBill)).total;

  let st = "free", label = "Free", meta = "tap to open";
  if (liveOs.length) { // gate on NON-cancelled orders — matches the summary's v_has_orders (mig 105 excludes cancelled)
    if (anyReceived) { st = "new"; label = "New order"; }
    // ANY cooked-but-unserved dish turns the tile pink ("Ready to serve") — even if
    // OTHER dishes are still cooking — so staff see at a glance there's something to
    // carry out. (Was: only when EVERY dish was ready, because anyPreparing was checked
    // first.) Now matches the tablet's tile precedence (new → ready → prep). (2026-06-18)
    else if (anyReady) { st = "ready"; label = "Ready to serve"; } // food cooked, not yet carried out
    else if (anyPreparing) { st = "prep"; label = "Preparing"; }

    // No separate "Bill due" fill anymore (owner, 2026-06-10): payment is
    // already told by the OUTLINE (red = unpaid, green = paid), so a fully
    // served table just says "Served" until it's paid, then "Cleared".
    else if (unpaid) { st = "bill"; label = "Served"; } // served but money still due → yellow "to pay" tile
    else { st = "done"; label = "Cleared"; }
    const served = items.filter((i) => i.status === "served").reduce((a, i) => a + qtyOf(i), 0);
    const totalQ = items.reduce((a, i) => a + qtyOf(i), 0);
    // \u00a0 between the amount and "due" so a wrap can never leave "₹483" on one line and
    // "due" on the next — the money and what it means stay one unbreakable chunk.
    meta = items.length ? `${served}/${totalQ} served${due > 0 ? ` · ${inr(due)}\u00a0due` : ""}` : `${liveOs.length} order${liveOs.length > 1 ? "s" : ""}`;
  } else if (sess) {
    // Someone actually seated → teal "Seated". Open but nobody seated yet → a
    // bright YELLOW "waiting" tile (owner: an open-but-empty table should light up
    // yellow, not look dark/off). The building cart isn't shown on the tile.
    if (mem.length) { st = "seated"; label = `Seated · ${mem.length}`; meta = "no orders yet"; }
    else { st = "waiting"; label = "Open"; meta = "waiting for guests"; }
  } else if (reqs.length) {
    // free table, but a guest is asking to be let in -> make it shout for attention
    st = "req"; label = "Wants in";
    meta = reqs[reqs.length - 1].type === "open" ? "asked to open" : "asked for access";
  }
  let badges = "";
  if (reqs.length) badges += `<span class="ftb req">📨${reqs.length}</span>`;
  if (pending) badges += `<span class="ftb join">🙋${pending}</span>`;
  // One emoji per ACTIVE waiter call (water 💧, napkins 🧻, clean 🧹…), up to 3,
  // then a "+N" pill if there are more. The cart is deliberately NOT badged here.
  calls.slice(0, 3).forEach((c) => { badges += `<span class="ftb call">${callEmoji(c.note)}</span>`; });
  if (calls.length > 3) badges += `<span class="ftb call ftb-more">+${calls.length - 3}</span>`;
  return {
    st, label, meta, badges,
    guests: mem.filter((m) => m.approved !== false).length, // people actually seated here
    // Per-status dish counts → the tile progress bar (matches the tablet's .tstrip).
    counts: {
      nw: items.filter((i) => i.status === "received").reduce((a, i) => a + qtyOf(i), 0),
      ck: items.filter((i) => i.status === "preparing").reduce((a, i) => a + qtyOf(i), 0),
      rd: items.filter((i) => i.status === "ready").reduce((a, i) => a + qtyOf(i), 0),
      sv: items.filter((i) => i.status === "served").reduce((a, i) => a + qtyOf(i), 0),
    },
    // Outline = payment, but ONLY once an order is accepted: red = an accepted
    // unpaid bill, green = accepted & fully paid, none = nothing accepted yet (a
    // brand-new "received" order shows no pay ring until staff accepts it).
    pay: unpaid ? "red" : (os.some((o) => o.status !== "cancelled" && o.status !== "received" && o.payment_status === "paid") ? "green" : ""),
    done: st === "done" && !unpaid, // served AND paid → offer RST/CLS (never free an unpaid table)
    hasNew: anyReceived,        // a new order waiting to be accepted
    hasCall: calls.length > 0,
    hasReq: reqs.length > 0,    // a guest is waiting to be let in
    hasJoin: pending > 0,       // a partner asked to join and awaits approval
  };
}

// floorTileHtml(i): build the FULL outer HTML for ONE floor tile (table number i).
// This is the SINGLE source of truth for a tile's markup — BOTH the full-floor render
// (floorHtml's loop) AND the incremental patch (patchFloorTiles) call this, so a tile
// drawn either way is byte-identical (no path-divergent rendering). The state/label/
// meta/badges/quick all come from tableTileState(i) exactly as before.
// ── THE TILE'S SHAPE IS FIXED (owner drawing, 2026-07-31) ────────────────────────────
// Every tile carries the SAME four rows in the SAME places, whatever the table is doing,
// so a floor of 40 tables reads as one grid instead of 40 different little cards:
//
//   row 1   T1  ································  🪑 4     (name left, seats right)
//   row 2   the notification badges, when there are any
//   row 3   the LIVE STATUS pill (+ the dish progress bar)
//   row 4   ⏻  ＋ Take order ···························  🧾 BILL
//
// "Take order" is on EVERY tile (sessions off means there is no seat-them-first step), and
// the small printer opens the bill preview — where Print / Generate invoice / Mark paid
// live, so paying a table is one popup instead of a chain of confirms. ⏻ CLOSE joins the row on
// a FINISHED table only (see finishedHere below) and ends the table in one tap.
// ── PARCELS ARE NOT ON THE FLOOR (owner, 2026-08-14) ──────────────────────────────
// They used to be: a strip of Parcel tiles under the tables, each staying until it had been BOTH
// printed and paid (his 2026-08-02 rule). He removed it — "below the table, the parcel will not
// show. Parcel will only show in the platform thing." The 🛵 Platform / 🥡 Parcels tab is the one
// place a parcel is worked now, it carries a live count on its own badge, and it hides itself
// entirely when neither the parcel nor the delivery module is on (syncPlatformTab), which is the
// second half of the same instruction.
//
// todaysParcels() STAYS — the parcel's NUMBER is still needed wherever a parcel is opened
// (openParcelTile, the Platform board). The number is its place among TODAY's parcels, counted
// over every one of them including cancelled and handed-over rows (a sale is never deleted here —
// see the billing compliance rules), which is what keeps "Parcel 3" called Parcel 3 for the rest
// of the day whatever happens to Parcel 2.
function todaysParcels() {
  // THE RESTAURANT'S DAY, NOT THE CLOCK'S (sweep 2026-08-04). This used local midnight while
  // every other day on this panel starts at 05:00 (businessDayStartMs, used by the Bills tab), so
  // between 00:00 and 05:00 "Parcel 1" and the bill series disagreed about which day it was — the
  // numbering rolled over hours before the business day it belongs to ended.
  const dayStart = businessDayStartMs();
  return (state.data.platform || [])
    .filter((o) => o.source === "parcel" && o.created_at && new Date(o.created_at) >= dayStart)
    .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))
    .map((o, i) => ({ ...o, parcel_no: i + 1 }));
}
// What the CURRENT viewer may do, for the floor's own gating. Same rule the order builder
// uses: an admin/owner looking in sees everything (tinted where it's off for the staff
// below); a real manager gets what the ladder grants.
function qopCanFloor(flag) {
  if (XRAY_WHO && XRAY_WHO.higherView) return true;
  return xrayGrantedForManager(flag);
}
// ── DOES THIS RESTAURANT HAVE THE FEATURE AT ALL? ────────────────────────────────────────
// The module ladder, computed from the settings row the panel already holds — ONE copy of
// the formula, because it used to be written out at four call sites and they drifted.
// `undefined` settings (before the first load) reads as OFF, so nothing flashes on and then
// off again for a restaurant that doesn't have it.
//
// TWO SEPARATE MODULES, and they are easy to mix up (mig 259 — see the box at the top of
// lib/tableTags.ts):
//   parcelModuleOn()   → parcel_*    the counter parcel THIS restaurant's staff punch in
//   platformModuleOn() → takeaway_*  Zomato / Swiggy / the restaurant's own website
//
// NOTE THERE IS NO X-RAY OVERRIDE HERE, deliberately. Higher-view reveals what a ROLE has
// not been granted (tinted, and the server lets the admin through); it must never reveal a
// FEATURE the restaurant doesn't have, because the server refuses that for everyone. That
// mismatch is exactly what let a whole parcel be typed into QO/P and then refused at the
// last tap (owner, on Aangan, 2026-08-02).
function moduleOn(prefix) {
  const s = state.data.settings || {};
  return s[prefix + "_allowed"] === true
    && (s[prefix + "_owner_control"] !== true || s[prefix + "_enabled"] !== false);
}
const parcelModuleOn = () => moduleOn("parcel");
const platformModuleOn = () => moduleOn("takeaway");
// (parcelStripHtml lived here. The floor no longer carries a Parcel strip — owner, 2026-08-14:
// "below the table, the parcel will not show. Parcel will only show in the platform thing." The
// 🛵 Platform / 🥡 Parcels tab is the ONE place a parcel is worked, and that tab already appears
// whenever EITHER module is on and disappears when both are off (syncPlatformTab), which is the
// rest of the same instruction. parcelTileHtml + openParcels went with it rather than being left
// as builders nothing calls; todaysParcels stays — openParcelTile still numbers a parcel with it.)
function floorTileHtml(i) {
  const s = state.data.settings || {};
  const { st, label, meta, badges, counts, pay, hasNew, guests, done } = tableTileState(i); // everything this tile needs
  // Status progress bar (new→cooking→ready→served), same colours as the tablet's .tstrip.
  const cTot = counts.nw + counts.ck + counts.rd + counts.sv;
  const strip = cTot > 0 ? `<div class="ft-strip">${counts.nw ? `<i style="width:${(counts.nw / cTot) * 100}%;background:#f59e0b"></i>` : ""}${counts.ck ? `<i style="width:${(counts.ck / cTot) * 100}%;background:#4f9dff"></i>` : ""}${counts.rd ? `<i style="width:${(counts.rd / cTot) * 100}%;background:#ec4899"></i>` : ""}${counts.sv ? `<i style="width:${(counts.sv / cTot) * 100}%;background:#22c55e"></i>` : ""}</div>` : "";
  const allServed = cTot > 0 && counts.nw === 0 && counts.ck === 0 && counts.rd === 0;
  // THE BILL BUTTON IS AVAILABLE WHILE THE FOOD IS STILL COOKING (owner, 2026-08-01: "we can
  // print when order [is] being cook"). This REVERSES his 2026-07-31 instruction ("till everything
  // is not [served] I don't want the option for the print thing") — he changed his mind after
  // using it, which is his call: in a real service the printed bill often goes to the table before
  // the last dish lands. Any table with something on it can be billed.
  // THE BILL BUTTON WAITS FOR EVERY DISH AGAIN (owner, 2026-08-01: "until fully not served don't
  // show that print option thing"). This reverses his own instruction from earlier the same day
  // ("we can print when order being cook") — his call, and this is the newer one. What did NOT
  // change is what the two buttons MEAN once you are in the bill: Print issues the invoice and
  // prints it, Generate invoice only issues it.
  // Nothing but "everything is served" opens the bill (owner, 2026-08-01: "until fully not served
  // don't show that print option thing"). An earlier version also allowed it whenever money was
  // owed — which is true of every unpaid table, so the gate did nothing.
  const mergedTo = mergeParentOf(i);
  const mergeKids = mergedTo ? [] : mergeChildrenOf(i);
  const pTile = mergedTo ? tableTileState(mergedTo) : null;
  const pCounts = pTile ? pTile.counts : null;
  const pTot = pCounts ? pCounts.nw + pCounts.ck + pCounts.rd + pCounts.sv : 0;
  const pStrip = pTot > 0
    ? `<div class="ft-strip">${pCounts.nw ? `<i style="width:${(pCounts.nw / pTot) * 100}%;background:#f59e0b"></i>` : ""}${pCounts.ck ? `<i style="width:${(pCounts.ck / pTot) * 100}%;background:#4f9dff"></i>` : ""}${pCounts.rd ? `<i style="width:${(pCounts.rd / pTot) * 100}%;background:#ec4899"></i>` : ""}${pCounts.sv ? `<i style="width:${(pCounts.sv / pTot) * 100}%;background:#22c55e"></i>` : ""}</div>`
    : "";
  const canBill = allServed;
  // A joined table offers the bill too, and it opens the PARTY's bill (the table that holds it) —
  // same button, same place, no hierarchy on the floor.
  const canBillHere = mergedTo ? (pTot > 0 && pCounts.nw === 0 && pCounts.ck === 0 && pCounts.rd === 0) : canBill;
  // A FINISHED TABLE SAYS SO AND WAITS (owner, 2026-08-02). The table used to end ITSELF the
  // moment the last dish was served and the bill was settled (lib/autoSettle, now deleted) —
  // so a party that had paid but was still sitting there had its table wiped out from under
  // them, and there was no button anywhere to end a table on purpose. Now nothing happens on
  // its own: the tile grows a ✓ CLOSE control beside the bill, and a person decides when the
  // guests have actually left.
  //
  // "Finished" is BOTH halves — every dish served AND the whole bill paid — and it does not
  // care which happened first (`done` is derived from the table's state + pay ring, not from
  // the order of events, so paying up front and serving afterwards reaches it exactly the same
  // way as serving first and paying at the end). A merged child shows its PARTY's state,
  // because the money and the food live on the table that holds the bill.
  const finishedHere = mergedTo ? !!(pTile && pTile.done) : !!done;
  // ROW 3 — A LINE, NOT A BOX (owner, 2026-08-01: "there shouldn't be the preparation box; there
  // should be a line which shows the colour — you can see how the colour works on the top — you
  // don't need to write 'Preparing' and create that whole box. And at the end of the line there
  // will be the number, like 0 out of 3 served … maybe we need just 0/3 serve only, that much
  // written, nothing more, in small").
  // So the word ("Preparing") is gone — the tile's own colour already says the state, which is
  // exactly his point — and what's left is the progress line plus a tiny count riding at its end.
  // The line keeps the per-state segments (amber new · blue cooking · pink on the pass · green
  // served), so it still shows the MIX at a glance, not just a total.
  // THE LINE RUNS THE FULL WIDTH, WITH THE COUNT ABOVE IT (owner, 2026-08-01: "the line should be
  // full — on top of line that should be written"). First pass put the count beside the line, which
  // ate about a third of the bar; now the bar is the whole tile width and "0/3 served" sits over it.
  const servedTxt = cTot > 0 ? `${counts.sv}/${cTot} served` : "";
  // A MERGED CHILD IS NOT A FREE TABLE (owner, 2026-08-01: "on the table number seven it should be
  // completely written, merge with six … access from six"). Its party lives on the parent, so it has
  // no session of its own and the summary calls it free — which is exactly the lie he caught. Here
  // it wears its own state: the chip naming every other table in the party, its PARTY's progress
  // line, and tapping it opens its detail, where Unmerge lives.
  // (An earlier version of this comment claimed a child shows "no ＋ Take order and no bill button".
  // It does show both, and that is right — `isEmpty` is false for a child, and an order punched at
  // T7 joins the party's one bill (migs 250/264), which is what a waiter standing at T7 wants; the
  // bill button carries `mergedTo` so it opens the bill's real home. The comment was describing
  // behaviour the code never had — corrected in the 2026-08-04 sweep so nobody "fixes" it away.)
  // ROW 3 for a merged pair. The child's whole row is the message; the parent keeps its progress
  // line and gains a chip naming what it carries, in the accent colour so it reads as a state and
  // not as decoration.
  // EVERY table in the party names ALL the others (owner, 2026-08-01: "if 3 merge it will show all
  // 3 merge" + "no hierarchy"). With 6+7+8 joined, table 7's chip reads "⇄ with T6 T8" — not just
  // its parent — so no tile reads as subordinate to another.
  const partyTables = mergedTo
    ? [mergedTo, ...mergeChildrenOf(mergedTo).filter((k) => String(k) !== String(i))]
    : mergeKids;
  const mergeWith = partyTables.map((k) => "T" + k);
  // REJECTED (owner, 2026-08-11) — docs/REJECTED-IDEAS.md R9: no "how long have they been merged"
  // age on this chip ("⇄ with T7 · 40m"). Offered as a way to spot a merge somebody forgot to undo;
  // he skipped it. The chip names the party and nothing else.
  // The tooltip now also names WHO joined them and when (owner, 2026-08-14 — improvement 2), read
  // from fields the summary already carries. A hover is desktop-only, so the same sentence is
  // printed as text in the table's own detail head, which is where a phone reads it.
  const credit = mergeCredit(i);
  const mergeChip = mergeWith.length
    ? `<div class="ft-merge ft-merge-parent" title="Served as one party with ${esc(mergeWith.join(" + "))} — one bill${credit ? " · " + esc(credit) : ""}">⇄ with ${esc(mergeWith.join(" "))}</div>`
    : "";
  // The child's row is the LOUDEST thing on the tile (owner, 2026-08-01: "in the seven it should be
  // written in big words, it is merge with six … it should be written in big and all those things
  // should be visible"). Big "MERGED", then the table it belongs to on its own line.
  // The child shows the SAME live line as the table it is merged with — same party, same food, so
  // "4/6 served" belongs on both tiles — with the MERGED wording under it.
  const statusRow = mergedTo
    ? (pTot > 0
      ? `<div class="ft-line" title="${esc(pTile.label || "")}"><span class="ft-linenum">${esc(pCounts.sv)}/${esc(pTot)} served</span>${pStrip}</div>`
      // A JOINED TABLE WITH NOTHING ORDERED YET STILL GETS A ROW 3 (sweep 2026-08-04). This branch
      // used to render an empty string, so a child whose party had no dishes on it (just merged, or
      // everything cancelled) came out as a number, a merge chip and dead space — the exact "blank
      // row read as a broken tile" the plain branch below exists to prevent. Worse, `.ft-line` is
      // what carries `margin-top:auto`, so without it the chip floated up and the tile stopped
      // lining up with its neighbours. It says what it is instead.
      : `<div class="ft-line ft-line-plain" title="Joined party — nothing ordered yet"><span class="ft-linenum">Joined</span></div>`)
    : cTot > 0
    ? `<div class="ft-line" title="${esc(label)}${meta ? " · " + esc(meta) : ""}"><span class="ft-linenum">${esc(servedTxt)}</span>${strip}</div>`
    // No dishes yet (free, or a party sitting with nothing ordered): there is no progress to draw,
    // so the one word that IS information stays. A blank row here read as a broken tile.
    : `<div class="ft-line ft-line-plain" title="${esc(label)}"><span class="ft-linenum">${esc(label)}</span></div>`;
  // ROW 4 — the actions, and there are none on an EMPTY table (owner, 2026-07-31: "when the
  // table is free and you click the table directly the ordering thing should pop, no option for
  // take order — and whenever an order is going on, then we want the take order option").
  // So: a free tile IS the button (tapping it opens the order builder — see the tile-click
  // handler), and "＋ Take order" only appears once there is something to add to.
  // It keeps the data-take-order hook, so the existing take_orders permission check
  // (XRAY_CONTROLS) and the server's own re-check apply to it unchanged.
  // A brand-new order still gets its one-tap ✓ accept: it's the fastest thing a manager does,
  // and burying it in the detail would cost a tap on every single order.
  const isEmpty = st === "free" && !mergedTo;
  // ✕ CLOSE goes FIRST — the leftmost thing in the row (owner, 2026-08-02: "close button I want
  // on the left … you don't have to write close on it, red colour and icon and that's it, it will
  // be on left of add order"). So it is a plain red square with no label at any size: the only
  // worded button in this row stays ＋ Take order, which must remain the BIGGEST control on every
  // tile ("never make take order button small"). It only exists on a finished table, so on every
  // other tile the row is unchanged.
  const acts = (finishedHere ? `<button class="ft-ico ft-ico-close" data-close-table="${mergedTo || i}" title="Everything served and the bill is paid — close ${esc(tableLabel(i))} and free it" aria-label="Close ${esc(tableLabel(i))}"><i class="fas fa-power-off" aria-hidden="true"></i></button>` : "")
    // TWO FACES, ONE BUTTON, EXACTLY ONE SHOWN. The stylesheet's container ladder picks between them
    // by how wide the tile actually is: "＋ Take order" while it genuinely fits, and the bare ＋ when
    // it does not (a crowded tile, a dense floor, a finished table).
    //
    // REJECTED (owner, 2026-08-17) — docs/REJECTED-IDEAS.md R31: there is NO third, short "Order"
    // face, and there must never be one again. The T3 sweep (2026-08-06) added one, this sweep
    // briefly restored it after a later change had made it unreachable, and he removed it looking at
    // the real tile: "instead of order is written that should be just a plus icon, nothing else, and
    // it should stay like that" — plus, about the tile as a whole, "at the end of the day, UI should
    // stay like this. I don't care if you increase the size of or maybe whatever you do."
    // So: never add a word between the two faces, and never report the bare ＋ on a narrow tile as a
    // bug. The size may change; the two faces may not.
    + (isEmpty ? "" : `<button class="ft-take" data-take-order="${i}" title="Add another order for ${esc(tableLabel(i))}"><span class="ft-take-x">＋</span><span class="ft-take-t">Take order</span></button>`)
    + (hasNew ? `<button class="ft-ico ft-ico-go" data-quick-accept="${i}" title="Accept the new order" aria-label="Accept the new order"><i class="fas fa-check"></i></button>` : "")
    // REJECTED (owner, 2026-08-17) — docs/REJECTED-IDEAS.md R32: there is no 🍽️ Serve-all on the
    // tile. Offered as a way to make serving one tap instead of two ("tile → 🍽️ Serve all"), he said
    // "we will not do any of that stuff". Serving stays two taps. It also protects this row, which he
    // has ruled on twice (R4, and "never make take order button small"): a fifth control on an 89px
    // tile could only take room from ＋ Take order. Do not add one.
    // The printer wears its OWN colour, never the table's state colour (owner, 2026-08-01: "print
    // notification icon should have its own COLOUR"). On a green Served tile it was a green button
    // on a green tile — the one control you look for while closing a table, camouflaged.
    // The bill control reads as a control, not a glyph (owner, 2026-08-01: "if you can improve ui
    // of that print icon more i would love that"): its own paper colour, a receipt icon with the
    // word BILL beside it, and on a dense floor the word drops and the icon stays — the same
    // shed-detail rule the ＋ Take order button follows.
    + (canBillHere ? `<button class="ft-ico ft-ico-bill" data-bill-preview="${mergedTo || i}" title="Bill for ${esc(tableLabel(i))} — preview, print, invoice, mark paid" aria-label="Bill for ${esc(tableLabel(i))}"><i class="fas fa-receipt ft-bill-ico" aria-hidden="true"></i><span class="ft-bill-t">Bill</span></button>` : "");
  // Seats — ALWAYS visible, top-right (owner drawing: "no. of person can sit on table").
  // ONE shared answer for "how many fit here" — see seatsForTable(): this table's own number,
  // else the floor's default, else 4.
  //
  // HISTORY, so neither half of this gets undone again (owner, 2026-08-01, twice in one evening):
  // first he said the corner number was wrong ("it's not the amount of people can sit there"),
  // and the truth was that nobody had ever entered a capacity, so every tile was stating a fact
  // out of thin air. I answered by showing NOTHING — which was worse: the waiter tablet, the
  // Table setting card and the QR card all still said 4, so only this screen went blank and the
  // number he asked for disappeared ("i cant [see] the amout of people on tbale view"). The real
  // answer is a capacity that IS his: a floor-wide default he can set in one field, per-table
  // overrides on top, and every screen reading the same helper.
  const seats = seatsForTable(s, i);
  // WHO IS ACTUALLY SITTING THERE (owner, 2026-08-01: "where no. of people sit on that, show").
  // With guests seated it reads "2/4" — two of the four chairs taken; otherwise just the capacity.
  // The seated number only exists when guest sessions are on, because that is the only time
  // anybody tells the app how many people sat down.
  const seatTxt = guests > 0 ? (seats ? `${guests}/${seats}` : String(guests)) : (seats ? String(seats) : "");
  const seatTip = guests > 0
    ? (seats ? `${guests} seated of ${seats} seats` : `${guests} seated`)
    : (seats ? `${seats} seats` : "");
  // Display name (mig 131): the tile badge shows the name when one is set — the
  // number stays in the tooltip (and everywhere data lives).
  const tnm = ((s.table_names || {})[String(i)] || "").trim();
  // ONE DIGIT IS FINE, TWO IS TOO BIG (owner, 2026-08-01). The number is sized to the tile, so on
  // a compact floor "34" filled the row and crowded the seat count. Step the face down by how many
  // characters it actually has — a named table ("Terrace 2") steps down again.
  const numTxt = String(tnm || i);
  const numCls = numTxt.length >= 4 ? " ft-num-xs" : numTxt.length >= 2 ? " ft-num-sm" : "";
  // Special table type (mig 166): a corner ribbon + pill badge layered OVER the state
  // look — the strip/label/pay ring keep working, the tag is unmistakable on top.
  const tag = tagForTable(i);
  const tinfo = TABLE_TAG_INFO[tag];
  const mergedEither = !!mergedTo || mergeKids.length > 0;
  const payShown = mergedTo && pTile ? (pTile.pay || pay) : pay;
  return `<div class="ftile ft-${mergedEither ? "merged" : st}${mergeKids.length ? " ft-has-merged" : ""}${payShown ? " pay-" + payShown : ""}${finishedHere ? " ft-finished" : ""}${tinfo ? ` ft-tag tag-${tag}` : ""}${String(state.selectedTable) === String(i) ? " ft-sel" : ""}" data-floor-table="${i}" role="button" tabindex="0" title="${isEmpty ? "Tap to take an order" : "Tap to open this table"}">
        ${tinfo ? `<div class="ft-ribbon" aria-hidden="true">${tinfo.ribbon}</div>` : ""}
        <div class="ft-top"><span class="ft-num${numCls}" ${tnm ? `title="T${i}"` : ""}>${esc(numTxt)}</span>${seatTxt ? `<span class="ft-seats" title="${esc(seatTip)}">${CHAIR_SVG}${esc(seatTxt)}</span>` : ""}</div>
        ${badges ? `<div class="ft-badges">${badges}</div>` : ""}
        ${tinfo ? `<span class="ft-tagbadge">${tinfo.emoji} ${esc(tinfo.label)}</span>` : ""}
        ${statusRow}${mergeChip}
        ${acts ? `<div class="ft-act">${acts}</div>` : ""}</div>`;
}

// (The floor's three right-hand cards — "Requests", "Needs" and "To accept" — were deleted
// with the side panel itself (owner, 2026-07-31). Nothing they told you was lost: each tile
// carries its own badges for calls / joiners / people waiting, the stats strip still counts
// "NEEDS YOU", and a new order keeps its one-tap ✓ right on the tile.

// The floor normally draws tables 1..table_count, but a table numbered ABOVE the current
// count can still be OCCUPIED (e.g. the count was lowered while it had a live order). Extend
// the drawn range to cover any such table so it never vanishes from the grid / "to accept" /
// stats (and its bill stays reachable/payable). (fixed 2026-07-06)
// floorTableList(baseN): the table numbers to draw — the floor plan plus any occupied table
// ABOVE it, and nothing in between. This used to return a bigger MAX instead of a list, so
// the grid drew every number up to the highest occupied one: a 30-table floor with a stray
// order on T48 rendered 48 tiles, 17 of them tables that don't exist (and a restaurant that
// shrank from 300 would render hundreds of phantoms). QA sweep 2026-07-30 — the waiter
// tablet now uses the identical helper, so the two floors always agree.
function floorTableList(baseN) {
  const out = [];
  for (let i = 1; i <= baseN; i++) out.push(i);
  const tiles = (state.summary && state.summary.tiles) || {};
  // AN OUT-OF-RANGE TABLE ONLY EARNS A TILE IF IT HAS SOMETHING ON IT (owner, 2026-08-01: "we have
  // only 30 tables, why are the last 2 showing"). The range is extended so a table numbered above
  // the count can't hide its money — but a tile the server reports as FREE has no money to hide,
  // so it was pure noise. Two junk rows from a test script (table "9343531") were enough to grow a
  // 30-table floor to 32. Anything genuinely occupied — or asking to be let in — still appears.
  const extras = Object.keys(tiles)
    .map((k) => parseInt(k, 10))
    .filter((k) => Number.isFinite(k) && k > baseN)
    // A JOINED TABLE IS NOT A FREE ONE (T3 sweep, 2026-08-06). A merged child has no session of its
    // own — its party lives on the parent — so the summary reports its state as `free` (mig 238's
    // `belong` CTE needs a session id). Without the merge test, a merged child numbered above the
    // table count fell through this filter and vanished off the floor while its party was live,
    // taking the one tile that reaches its Unmerge with it.
    .filter((k) => { const st = (tiles[String(k)] || {}).state; return (st && st !== "free") || !!mergeParentOf(k); })
    .sort((a, b) => a - b);
  return out.concat(extras);
}

// floorStatsHtml(): the floor-wide stats strip (Occupied / To pay / Needs you). Computed by
// looping tableTileState over EVERY table (cheap — no DOM) so the patch can refresh it without
// rebuilding the grid. Shared by floorHtml and patchFloorTiles.
// REJECTED (owner, 2026-08-11) — docs/REJECTED-IDEAS.md R10: "To pay" stays a COUNT. Do not add the
// rupee total beside it ("To pay 2 · ₹1,659"); it was offered and refused.
// STILL REJECTED HERE, and here is where the line is (2026-08-20). He asked for a money split on the
// ADMIN console's Bills → CLOSED UNPAID tile ("₹… food was made · ₹… never made") and it was built.
// That is a different screen, a different reader and a different question: an oversight ledger the
// admin opens to check a day that has finished, not the live floor a manager works off during
// service. This line stays a count. Do not read the admin change as permission for this one.
function floorStatsHtml() {
  const s = state.data.settings || {};
  // Shown WHATEVER the session setting says (fixed 2026-07-31). It used to return nothing at
  // all when dining sessions were off — which is now the normal setup — so the floor lost its
  // "how full am I / who owes me" line for exactly the restaurants that live on this screen.
  // None of the three numbers needs sessions: they count tables, money and things waiting.
  const _tcKey = tableCountKey();
  let cachedN = _tcKey ? parseInt(localStorage.getItem(_tcKey), 10) : NaN;
  if (!Number.isFinite(cachedN) || cachedN < 1) cachedN = 12;
  const n = Math.max(1, parseInt(s.table_count, 10) || cachedN);
  let cOcc = 0, cPay = 0;
  // ONE list, built once — it is walked twice below and every tile costs a tableTileState() call.
  const drawnList = floorTableList(n);
  // NEEDS YOU COUNTS TABLES, NOT A MIXTURE OF TABLES AND ROWS (T3 sweep, 2026-08-10). It used to be
  // cNew + cCall + reqN + joinN, where the first two were counted once per TABLE and the last two
  // once per ROW: one table holding four waiter calls read "Needs you 1", and four people waiting to
  // be let in at one table read "Needs you 4". A number that means two different things depending on
  // what happened is a number staff stop trusting. It is now the plain answer to the plain question
  // — how many TABLES want me — so it can never be larger than the floor, and a table that has both
  // a new order and a raised hand is still one place to walk to.
  const needy = new Set();
  for (const i of drawnList) {
    const { st, pay, hasNew, hasCall } = tableTileState(i);
    if (hasNew || hasCall) needy.add(String(i));
    // A JOINED TABLE IS OCCUPIED, whatever the server calls it (T3 sweep, 2026-08-06). A merged
    // child has no session of its own, so mig 238 reports its state as `free` — while the tile
    // right beside this number is drawn purple and obviously busy. With T6+T7 joined and six
    // people on them, the header read "Occupied 1/30" over two full tables, and a number that
    // disagrees with the picture beside it is a number staff stop trusting.
    // MONEY IS DELIBERATELY NOT WIDENED: the party's whole bill already rides on the table that
    // holds it, so counting the child in "To pay" too would show two bills where there is one.
    const joined = !!mergeParentOf(i);
    if (joined || (st !== "free" && st !== "req")) cOcc++;
    if (pay === "red" || st === "bill") cPay++;
  }
  // Count only what a person can actually SEE and act on from this floor: something waiting at
  // a table that is drawn here. A request for a table the restaurant doesn't have (a stale row,
  // a table that was removed) used to be counted anyway — and now that the queue card is gone
  // it would sit in "Needs you" forever with nothing on screen to answer it. A number nobody
  // can act on teaches staff to ignore the number.
  const drawn = new Set(drawnList.map(String));
  const atTable = (x) => drawn.has(String(x && x.table_number));
  for (const r of (state.summary.requests || [])) if (atTable(r)) needy.add(String(r.table_number));
  for (const j of (state.summary.joiners || [])) if (atTable(j)) needy.add(String(j.table_number));
  const needsYou = needy.size;
  // THE TOTAL IS WHAT IS ON SCREEN (T3 sweep, 2026-08-10). The bottom half was the table COUNT while
  // the top half walked floorTableList — which deliberately includes an occupied table numbered
  // ABOVE that count, so its money can't hide. Thirty tables all busy plus one live order on table
  // 34 printed "31/30 Occupied". The drawn list IS the floor, so it is both halves; with no strays
  // it equals the table count exactly, which is every ordinary day.
  const total = drawnList.length || n;
  return `<div class="floor-stats"><div class="fstat"><div class="fstat-n">${cOcc}/${total}</div><div class="fstat-l">Occupied</div></div><div class="fstat warn"><div class="fstat-n">${cPay}</div><div class="fstat-l">To pay</div></div><div class="fstat alert" title="${needsYou === 1 ? "1 table wants you" : needsYou + " tables want you"}"><div class="fstat-n">${needsYou}</div><div class="fstat-l">Needs you</div></div></div>`;
}

// floorPlan(): this restaurant's hand-written floor plan, or null for the classic grid.
// Returns null unless BOTH are true: the restaurant is set to Custom, and a plan exists for its
// slug in floor-layouts.js. Anything malformed (no tables array) counts as no plan — a typo in a
// hand-written file must fall back to a working floor, not break the screen.
function floorPlan() {
  const s = state.data.settings || {};
  if (s.floor_layout_mode !== "custom") return null;
  const slug = (state.data.restaurant || {}).slug || "";
  const plan = (window.LFH_FLOOR_LAYOUTS || {})[slug];
  if (!plan || !Array.isArray(plan.tables) || !plan.tables.length) return null;
  return plan;
}

// customFloorHtml(plan, n): draw the owner's plan. Each table sits where he put it (1-based
// x/y, optional w/h) on a CSS grid of plan.cols columns; the tiles themselves are the SAME
// floorTileHtml every other view uses, so a table behaves identically wherever it is drawn.
//
// A table that exists on the floor but ISN'T in the plan still appears, in its own row
// underneath: a half-finished plan may look unfinished, but it may never hide a table (and with
// it, that table's money).
function customFloorHtml(plan, n) {
  const cols = Math.max(1, Math.min(40, parseInt(plan.cols, 10) || 12));
  const placed = new Set();
  const cells = plan.tables.map((row) => {
    const t = String(row.t);
    placed.add(t);
    const x = Math.max(1, parseInt(row.x, 10) || 1);
    const y = Math.max(1, parseInt(row.y, 10) || 1);
    const w = Math.max(1, parseInt(row.w, 10) || 1);
    const h = Math.max(1, parseInt(row.h, 10) || 1);
    // Row offset: zone captions occupy a row of their own, so a table's y is shifted down by
    // however many captions sit above it. Keeps the owner's numbers meaning what he wrote.
    const above = (plan.zones || []).filter((z) => (parseInt(z.y, 10) || 1) <= y).length;
    return `<div class="fplan-cell" style="grid-column:${x} / span ${w};grid-row:${y + above} / span ${h}">${floorTileHtml(row.t)}</div>`;
  }).join("");
  const zones = (plan.zones || []).map((z) => {
    const y = Math.max(1, parseInt(z.y, 10) || 1);
    const above = (plan.zones || []).filter((o) => (parseInt(o.y, 10) || 1) < y).length;
    return `<div class="fplan-zone" style="grid-column:1 / -1;grid-row:${y + above}">${esc(z.label || "")}</div>`;
  }).join("");
  const missing = floorTableList(n).filter((i) => !placed.has(String(i)));
  const extra = missing.length
    ? `<div class="floor-plan-note">Not placed on the plan yet — ${missing.length} table${missing.length > 1 ? "s" : ""}:</div>
       <div class="ftile-grid" style="--per-row-pc:${floorPerRow()}">${missing.map((i) => floorTileHtml(i)).join("")}</div>`
    : "";
  // ROW HEIGHTS, spelled out. A table row is exactly as tall as a column is wide, so a 1×1 table
  // is a SQUARE and the owner's w/h mean what they look like: 3 wide × 1 tall draws as a long
  // table, not as a giant square (which is what happened when every tile forced its own 1:1).
  // A zone caption gets min-content — a line of text, not a table-sized band.
  const zoneRows = new Set((plan.zones || []).map((z, i) => {
    const y = Math.max(1, parseInt(z.y, 10) || 1);
    return y + (plan.zones || []).filter((o, j) => j < i && (parseInt(o.y, 10) || 1) < y).length;
  }));
  let maxRow = 0;
  plan.tables.forEach((row) => {
    const y = Math.max(1, parseInt(row.y, 10) || 1);
    const h = Math.max(1, parseInt(row.h, 10) || 1);
    const above = (plan.zones || []).filter((z) => (parseInt(z.y, 10) || 1) <= y).length;
    maxRow = Math.max(maxRow, y + above + h - 1);
  });
  const rowSizes = [];
  for (let r = 1; r <= maxRow; r++) rowSizes.push(zoneRows.has(r) ? "min-content" : "var(--fplan-sq)");
  return `<div class="fplan-wrap"><div class="fplan" style="--fplan-cols:${cols};grid-template-rows:${rowSizes.join(" ")}">${zones}${cells}</div></div>${extra}`;
}

// floorHtml: build the whole unified floor — the grid of table tiles on the left
// (with a legend and on-tile quick buttons) and a side panel on the right holding
// the session toggles, café location, requests queue and blocklist.

// floorPerRow: the ADMIN's tables-per-row number for this restaurant (settings.floor_per_row,
// mig 226). It is one ADMIN-owned per-restaurant setting — it replaced per-device S/M/L buttons on
// 2026-07-30 because a manager's phone and a manager's desktop each remembered a different size and
// no admin could set either. The manager panel only READS it; its own card was removed on
// 2026-08-02 ("that will be only set by admin") and no switch brings it back.
//
// ⚠️ THIS NUMBER IS NOT WHAT EVERY SCREEN DRAWS — CHANGED 2026-08-15, AND IT USED TO SAY THE
// OPPOSITE IN CAPITALS. The rule now (owner): a phone draws 2 per row, a phone turned sideways
// draws 4, and from about ten inches up the floor draws EXACTLY this number, at every width above
// it. "It is fixed and it is rule … we don't need twelve, it is only for PC … after ten inch you
// have to follow whatever is given — if I have tell twelve, there should be twelve listed. There
// shouldn't be horizontal scroll anywhere."
//
// So this function still returns HIS number, unchanged — the bands are applied in CSS, not here.
// The value is written onto the grid as the custom property `--per-row-pc`, and the stylesheet
// turns it into the effective `--per-row` per band. Two reasons it is done there and not here:
// a rotation becomes one media-query flip with nothing to re-render, and an inline `--per-row`
// would beat any stylesheet rule, which is exactly the trap that would make the bands silently do
// nothing.
//
// WHAT THIS REPLACED, so nobody restores it from the old comments: the floor used to draw all N
// columns on every device and SCROLL SIDEWAYS on a phone (a 72px minimum tile, the x-scroll on the
// grid alone, and a "→ N more" chip announcing the tables off the right edge). All of it is gone.
// Bounds and the band constants both live in lib/floorLayout.ts — if these change, change them
// there too, and keep the database CHECK constraint no narrower than the max.
const FLOOR_PER_ROW_MIN = 2, FLOOR_PER_ROW_MAX = 12, FLOOR_PER_ROW_DEFAULT = 12;
// ── A FINGER NEEDS A BIGGER SQUARE THAN A MOUSE DOES (owner, 2026-08-05, applied here 2026-08-16)
// "When it is horizontal at least four to five to six can be shown… IF THERE IS TWELVE, THEN SIX
// WILL BE SHOWN… it should look properly and able to click properly."
//
// He said that about the WAITER panel and it was built there and only there, so the two floors
// disagreed on the same iPad — 6 tiles on the waiter's, 12 on the manager's — and a 10.9-inch iPad
// held UPRIGHT drew 12 across 820px, which is 57px squares: the number and the colour fit, the
// buttons do not, and a long table name truncates. That was never a decision anybody made; it was
// one instruction applied to one panel. Same sentence, same cap, same code shape as
// public/panels/tablet/app.js — so a manager and a waiter looking at the same tablet see the same
// floor.
//
// 12 becomes 6, 8 becomes 6, and a restaurant that deliberately chose a small number keeps it
// (4 stays 4). A PC is untouched: a mouse reports `pointer: fine`, so `coarse` is what tells the
// two apart — the same question the stylesheet's bands ask, so the JS and the CSS can never
// disagree about what a touchscreen is.
//
// It does NOT apply in the admin's layout PREVIEW: that iframe exists to show what the PC floor
// will look like, so capping it there would preview a screen the admin is not setting.
// Below tablet size the CSS bands are tighter anyway (2 upright, 4 turned) and simply win.
const FLOOR_PER_ROW_TOUCH_MAX = 6;
function isTouchDevice() {
  try { return window.matchMedia("(pointer: coarse)").matches; } catch { return false; }
}
function floorPerRow() {
  // The admin preview slider wins while it's driving (never persisted — see state).
  const raw = state.floorPerRowPreview != null
    ? state.floorPerRowPreview
    : (state.data.settings || {}).floor_per_row;
  const clamp = (v) => Math.min(Math.max(v, FLOOR_PER_ROW_MIN), FLOOR_PER_ROW_MAX);
  const n = Math.round(Number(raw));
  if (Number.isFinite(n)) {
    const v = clamp(n);
    // Remember the REAL number (never the preview slider's temporary one) so the next open paints
    // the floor at the right width straight away instead of re-flowing once /all lands.
    // The number CACHED is his, uncapped — the cap is a property of the DEVICE, not of the
    // restaurant, so a manager who opens the floor on a tablet and later on a laptop must not have
    // taught the laptop to draw 6.
    if (state.floorPerRowPreview == null) { const k = perRowKey(); if (k) { try { localStorage.setItem(k, String(v)); } catch {} } }
    return touchCap(v);
  }
  // Settings haven't arrived yet — use what this restaurant drew last time, not the generic
  // default. Falls back to the default only on a device that has never opened this floor.
  const k = perRowKey();
  const cached = k ? parseInt(localStorage.getItem(k), 10) : NaN;
  return touchCap(Number.isFinite(cached) ? clamp(cached) : FLOOR_PER_ROW_DEFAULT);
}
// The cap, in one place, applied to BOTH the settings answer and the cached-first-paint one — a
// first paint that drew 12 and then re-flowed to 6 is exactly the flicker the cache exists to stop.
function touchCap(v) {
  if (FLOOR_PREVIEW) return v;                       // the admin is previewing the PC floor
  return isTouchDevice() ? Math.min(v, FLOOR_PER_ROW_TOUCH_MAX) : v;
}

// The admin layout-preview slider talks to this panel here. Only listened for in preview
// mode, only from our own origin, and it does exactly one thing: change the CSS variable
// on the existing grid. It deliberately does NOT re-render or refetch — dragging a slider
// must not fire a request per step, and reflowing the grid is all that has to happen.
if (FLOOR_PREVIEW) {
  window.addEventListener("message", (e) => {
    if (e.origin !== location.origin) return;
    const d = e.data;
    if (!d || d.type !== "lfh:floor-per-row" ) return;
    const n = Math.round(Number(d.perRow));
    if (!Number.isFinite(n)) return;
    state.floorPerRowPreview = Math.min(Math.max(n, FLOOR_PER_ROW_MIN), FLOOR_PER_ROW_MAX);
    document.querySelectorAll(".ftile-grid").forEach((g) => {
      // --per-row-pc, not --per-row: the stylesheet's phone/tablet bands compute the effective
      // --per-row from it, and they are switched off in preview mode (body.floor-preview) so the
      // admin always sees the PC floor he is actually setting, whatever size this iframe is.
      g.style.setProperty("--per-row-pc", String(state.floorPerRowPreview));
    });
  });
}

function floorHtml() {
  const s = state.data.settings || {};
  const sessionsOn = !!s.sessions_enabled;
  // Number of tables to draw. On the very FIRST paint the settings haven't
  // loaded yet, so without help we'd default to 12 and then jump to the real 13
  // a moment later — a visible "one tile forms, then another" flicker in the
  // skeleton. Fix: remember the real count in localStorage and use it as the
  // default, so the skeleton starts at the right size. (Falls back to 12 only
  // on a browser that has never loaded this editor.)
  const _tcKey = tableCountKey();
  let cachedN = _tcKey ? parseInt(localStorage.getItem(_tcKey), 10) : NaN;
  if (!Number.isFinite(cachedN) || cachedN < 1) cachedN = 12;
  const n = Math.max(1, parseInt(s.table_count, 10) || cachedN);
  if (s.table_count && _tcKey) { try { localStorage.setItem(_tcKey, String(parseInt(s.table_count, 10))); } catch {} }
  // Side-panel queues now come from the slim SUMMARY aggregates (tiny — only pending rows),
  // not the full board (which is no longer fetched whole). Same shapes the cards expect.
  // (The blocklist is NOT read here: this side panel never rendered it. The one place it shows
  // is the Customer log tab's 🚫 Blocked panel, which has its own fetch. A `const blocks = …`
  // sat here unused — removed rather than left looking like a wired feature.)

  // legend — every state + its colour. ("Bill due" was removed: payment is
  // already shown by the red/green outline, so a fill colour for it was noise.)
  // ONLY THE STATES THIS RESTAURANT CAN ACTUALLY BE IN (owner, 2026-08-01: "when session is not on
  // then remove Seated because you don't know — same for New order — Wants in also — remove the pink
  // one also"). Wants in / Seated are guest-session concepts: with sessions off nobody joins a table,
  // so the app never knows who is sitting and those words would be promising information it doesn't
  // have. "Ready to serve" (pink) goes with them at his request. What's left is what a sessions-off
  // floor really shows: free, cooking, served — plus the paid/unpaid ring.
  // HE MEANT EVERYWHERE, NOT JUST SESSIONS-OFF (owner, 2026-08-01: "on the top I have told you to
  // remove this all colour thing — you don't remove that, it's still listed. See this."). I had
  // gated the trim on `sessions_enabled`, so on the restaurant he actually tests (French House,
  // sessions ON) nothing changed and the seven-word strip was still there. The list is now the
  // same three everywhere — Free, Preparing, Served — because those are the words he wants on his
  // floor. "Called" survives only where a guest CAN call a waiter (that needs sessions), and he
  // asked for it gone with sessions off: "whenever the session is off, also remove that called
  // thing also".
  // NOTE: with sessions on, a tile can still turn amber (new order) or pink (on the pass) with no
  // legend entry to explain it. That is his call and he made it twice; the state word is still in
  // every tile's tooltip and in the table's own detail popup.
  // "· live" IS A PROMISE, SO IT HAS TO BE CHECKED (2026-08-12).
  //
  // The floor is drawn from whatever the last read returned, and with the offline layer in front
  // of it that is sometimes the copy saved on THIS DEVICE. Measured with every read held for 12
  // seconds: 31 tiles painted from a board saved at 9:06 pm, under a heading that still read
  // "Table view · live", with the connection pill on a calm grey "Connecting…". A manager could
  // settle a bill against a floor a quarter of an hour old and never be told.
  //
  // The offline bar above is the loud signal (public/panels/offline.js) — this is the quiet one,
  // in the two words that made the claim in the first place. Costs nothing: the offline layer
  // already knows, so this is a read of a boolean.
  const floorLiveTag = () => {
    try {
      if (window.LFH_OFF && window.LFH_OFF.isStale && window.LFH_OFF.isStale()) {
        return `<span class="sub floor-saved">· saved copy</span>`;
      }
    } catch (e) { /* the offline layer isn't there → it can only be live */ }
    return `<span class="sub">· live</span>`;
  };
  // REJECTED (owner, said twice; recorded 2026-08-15 as docs/REJECTED-IDEAS.md R25): adding the
  // missing colours to this strip. A tile can turn AMBER (new order) or PINK (on the pass) with no
  // entry here, so the legend explains 3 of the 5 colours — that is deliberate, not an oversight.
  // The state word is still in every tile's tooltip and in the table's own detail popup. Do not
  // "complete" this array.
  const LEG = [["free", "Free"], ["prep", "Preparing"], ["bill", "Served"]];
  // Purple = merged (owner, 2026-08-01: "the background will turn purple … there should be a purple
  // colour tag also on the top where all the colour thing has been shown"). Only listed while
  // something IS merged, so the strip stays as short as he asked for the rest of the time.
  if (mergeList().length) LEG.push(["merged", "Merged"]);
  // THE BELL ONLY WHERE A GUEST CAN ACTUALLY RING IT (owner, 2026-08-01: "whenever the session is
  // off, also remove that called thing" and then "if [the] menu will [be] off then this also
  // [should] not show"). Two things have to be true: the restaurant runs guest sessions, AND the
  // Waiter calls feature is on. With the guest menu's bell switched off nobody can ever ring, so a
  // legend entry for it is explaining a colour the floor can never show.
  const callsPossible = sessionsOn && featureOn("waiter_calls");
  const legend = `<div class="floor-legend"><span class="lgcap">inside:</span>${LEG.map(([k, v]) => `<span class="lgi"><i class="ldot ldot-${k}"></i>${v}</span>`).join("")}${callsPossible ? `<span class="lgi"><i class="ldot ldot-call">🔔</i>called</span>` : ""}<span class="lgcap">outline:</span><span class="lgi"><i class="lring lring-red"></i>unpaid</span><span class="lgi"><i class="lring lring-green"></i>paid</span></div>`;

  // FIRST PAINT before the live board has arrived: show a shimmer skeleton sized
  // to the real table count, instead of briefly drawing every table as "Free"
  // (that looked like the whole floor had reset on every refresh). The board
  // loads a moment later — boardLoaded flips true — and the real tiles replace
  // this. Mirrors the menu's loading skeleton so the two screens feel the same.
  if (!state.boardLoaded) {
    // left: a shimmer tile per table, sized to the (cached) real count.
    let skel = "";
    // (floorLiveTag is defined just above this renderer.)
    for (let i = 1; i <= n; i++) {
      skel += `<div class="ftile ftile-skel" aria-hidden="true"><div class="sk-num"></div><div class="sk-lbl"></div><div class="sk-meta"></div></div>`;
    }
    const skelMain = `<div class="floor-main"><div class="ed-head floor-head"><h2>Table view ${floorLiveTag()}</h2>${legend}</div><div class="ftile-grid" style="--per-row-pc:${floorPerRow()}">${skel}</div></div>`;
    // The floor is the WHOLE width now — there is no right-hand panel to leave room for
    // (owner, 2026-07-31), so the skeleton is just the grid.
    return `<div class="floor-wrap floor-collapsed">${skelMain}</div>`;
  }

  let tiles = "";
  for (const i of floorTableList(n)) {
    tiles += floorTileHtml(i); // SHARED tile builder — single source of truth (full render + patch)
  }
  // The header keeps ONLY the safe Refresh button. Open all / Close all used to
  // sit right beside it, styled the same — one fast click aimed at Refresh once
  // closed the entire floor (owner hit this 2026-06-11). They now live in the
  // side panel's "Dining sessions" card, well away from the speed-click zone.
  // Stats strip — the whole floor's health at a glance (Occupied / To pay / Needs you).
  // Built by the shared floorStatsHtml() so the patch path can refresh it identically.
  const statsStrip = floorStatsHtml();
  // ⚡ QO/P (Quick order / Parcel) — the general order button at the top of the floor, not
  // tied to any table. REPLACES the old 🥡 New Parcel button that sat here (owner,
  // 2026-08-02): it does the same job and more — build the order fast by drilling category
  // → dish → category, then choose at the END whether it goes to a table or out as a
  // Parcel. New Parcel is not kept alongside it; that would be two doors to one action,
  // which is how people learn neither (the same reason 🏷 Type lives only in the KOT menu).
  //
  // GATE: take_orders (XRAY_CONTROLS → [data-qop]) + the matching server gate, because the
  // button can now place a DINE-IN order too. The Parcel destination inside it keeps its own
  // `parcel` gate — the picker hides that bar when the takeaway module isn't live — so a
  // manager can no longer reach parcels through a door that skips the parcel permission.
  // The admin's own switch for this screen (mig 257, Access → Main features). It is the
  // outermost gate: off = the restaurant simply doesn't have QO/P and the button isn't
  // rendered at all, leaving 🧾 KOT ▾ on its own. Unset/true = has it, and then the two
  // permissions below decide what it can DO. Admin/owner looking in still see it (the
  // standing x-ray rule) so they can tell it apart from a permission they forgot to grant.
  // THE BUTTON CHANGES IDENTITY WITH THE TWO SUB-SWITCHES (owner, 2026-08-02). It is never a
  // QO/P button with half of itself missing — it becomes whichever thing the restaurant
  // actually has, named for that thing:
  //   both on   → ⚡ QO/P        · the quick screen, ending in "table or Parcel?"
  //   tables on → Quick order    · the SAME quick screen, with no Parcel at the end
  //   parcel on → 🥡 New Parcel  · the original parcel builder, a different screen entirely
  //   both off  → nothing        · the header keeps only 🧾 KOT ▾
  // Each half still needs its underlying permission too — a sub-switch can only take away.
  const qopOn = s.qop_allowed !== false || !!(XRAY_WHO && XRAY_WHO.higherView);
  const qopTables = qopOn && s.qop_tables_allowed !== false && qopCanFloor("take_orders");
  // The Parcel half needs the PARCEL module (parcel_*, mig 259) — not the Platforms one. It
  // used to consult state.parcelOn, which is only set once the 🛵 board has been fetched and
  // was left `undefined` on exactly the restaurants that don't have the board, so the panel
  // read "on" and offered a destination the server then refused.
  const qopParcel = qopOn && s.qop_parcel_allowed !== false && qopCanFloor("parcel") && parcelModuleOn();
  const parcelBtn =
      (qopTables && qopParcel) ? `<button class="btn primary ed-parcel-btn" data-qop="quick" title="Quick order / Parcel — build an order fast, then send it to a table or out as a parcel">⚡ QO/P</button>`
    : qopTables ? `<button class="btn primary ed-parcel-btn" data-qop="quick" title="Quick order — build an order fast and send it to a table">⚡ Quick&nbsp;order</button>`
    : qopParcel ? `<button class="btn primary ed-parcel-btn" data-qop="parcel" title="Start a takeaway / parcel order — no table needed">🥡 New&nbsp;Parcel</button>`
    : "";
  // NOTE: the 👥 "Who serves what" button used to sit here. It moved to Settings → Access
  // (owner, 2026-07-30) — that is now its ONE home. The reason it was ever on the floor was
  // that Settings is gated by `edit_settings`, so a manager with only `table_assign` had no
  // way in; that's handled properly now by the Settings tab and the Access row each opening
  // for "edit_settings|table_assign" / "manage_staff|table_assign" (see XRAY_TABS /
  // XRAY_CONTROLS). Don't re-add a floor button without re-checking those gates.
  // Waiter sections (migs 222-225) — the entry point that ACTUALLY works for a manager.
  // The same editor also sits in Settings → Tables, but that whole tab is gated by the
  // SEPARATE `edit_settings` power, so a manager granted only `table_assign` could never
  // reach it. Sections belong to the floor anyway, so the live Table view is the natural
  // home. Same builder → one source of truth, no chance of the two drifting.
  // 👥 "Who serves what" is NOT on the floor (owner, 2026-07-31: "I do not want this option
  // completely on top"). Its home is Settings → Access, where the waiter rota belongs.
  // In its place: 🧾 KOT ▾ for the WHOLE floor (owner, same day — "I want the KOT option on the
  // top where who does what was, and it will have to choose a table and it will work after like
  // it was before"). It asks which table first, then opens the same table-and-KOT menu the table
  // popup opens — including "Table type", which is how a table gets marked VIP BEFORE anyone has
  // ordered (there is no popup to reach on an empty table any more: tapping one starts an order).
  const kotBtn = tableOpsOn() ? `<button class="btn" id="floorKot" title="Table &amp; KOT operations — mark a table VIP, change table, merge, move a KOT or dish, split, reprint">🧾 KOT ▾</button>` : "";
  // ── CLASSIC or CUSTOM (mig 242) ────────────────────────────────────────────────────────
  // Classic = tables in order, N per row. Custom = the room's real shape, hand-written by the
  // owner in public/panels/floor-layouts.js and keyed by restaurant slug. A restaurant set to
  // Custom with no plan written yet falls back to Classic and SAYS so — choosing the mode must
  // never be able to empty someone's floor.
  const plan = floorPlan();
  const gridHtml = plan
    ? customFloorHtml(plan, n)
    : `<div class="ftile-grid" style="--per-row-pc:${floorPerRow()}">${tiles}</div>`;
  // Two different honest notes, because "custom is on" has two very different states.
  // The SECOND one is the T13 cross-panel finding (2026-08-13): when a plan IS drawn here, the
  // waiter tablet still shows the classic grid — it does not load floor-layouts.js at all — so the
  // same floor is arranged two ways on two devices in the same room. Say so on the screen that has
  // the plan rather than leaving a waiter and a manager to discover it mid-shift. (The owner chose
  // to warn rather than build the tablet half; the full note is at the top of floor-layouts.js.)
  const planNote = (s.floor_layout_mode === "custom" && !plan)
    ? `<div class="floor-plan-note">Custom layout is on for this restaurant, but no floor plan has been written for it yet — showing the classic grid. The plan lives in <b>public/panels/floor-layouts.js</b>.</div>`
    : plan
      ? `<div class="floor-plan-note">This is your custom floor plan. Note: the <b>waiter tablet</b> still shows the plain grid — it doesn't draw the plan yet.</div>`
      : "";
  // Parcels hang BELOW the room, in their own strip — they are floor work with no table,
  // so they must not be mixed into the table grid (classic or custom).
  // Header order (owner, 2026-08-02): the two buttons stay TOGETHER in the right-hand
  // cluster — 🧾 KOT ▾ immediately to the LEFT of ⚡ QO/P. "Left" here means left OF QO/P,
  // not the far left of the bar beside the title (which is where it first landed and the
  // owner sent it back). Parcels hang BELOW the room in their own strip — they are floor
  // work with no table, so they must not be mixed into the table grid (classic or custom).
  // EVERYTHING THAT ISN'T A TABLE LIVES IN THE HEADER ROW (owner, 2026-08-03: "this all stuff
  // …should be shifted on top, beside the table live view and beside the KOT and all that
  // option, so that we get space for the actual table view"). The three stat tiles and the
  // colour legend used to be two full-width blocks stacked UNDER the header, costing ~90px of
  // height before a single table was drawn — on his phone that was most of the first screen.
  // They are the same builders (so patchFloorTiles still swaps .floor-stats in place); only
  // where they sit changed, and .floor-head's CSS shrinks them to header-sized chips.
  // Order across the row: title · stats · legend ——— 🧾 KOT ▾ · ⚡ QO/P. The two buttons are
  // wrapped in ONE element on purpose: left loose in a wrapping flex row they came apart the
  // moment the row wrapped (an iPad put both at the far LEFT of line two — the placement the
  // owner rejected on 2026-08-02). As a pair with `margin-left:auto` they stay together, right.
  // (The "→ N more" chip lived here. It announced how many tables were off the right-hand edge,
  // because the floor used to keep all N columns on a phone and scroll sideways. Nothing scrolls
  // sideways any more — owner, 2026-08-15: "there shouldn't be horizontal scroll anywhere" — so the
  // chip, its wrapper and syncFloorMore()'s measuring pass went with the scroll they described.)
  const gridBlock = gridHtml;
  const main = `<div class="floor-main"><div class="ed-head floor-head"><h2>Table view ${floorLiveTag()}</h2>${statsStrip}${legend}<span class="floor-head-acts">${kotBtn}${parcelBtn}</span></div>${planNote}${gridBlock}</div>`;

  // ── NO RIGHT-HAND PANEL AT ALL (owner, 2026-07-31) ─────────────────────────────────
  // The floor used to end in a 300–460px rail that was either whole-floor cards ("To accept",
  // Requests, Needs, Blocked) or the selected table's detail docked in place. Both are gone:
  //   · the cards, because with sessions off they are empty most of the day and the badges on
  //     the tiles already say who needs something ("we don't even need the right side panel");
  //   · the docked detail, because a table must open as a POPUP and nothing else ("only popup
  //     option, no right side popup option at all") — one way in, so a tile tap always does the
  //     same thing whatever else is on screen.
  // The floor therefore gets the full width, which is also what makes the compact tiles read
  // properly. The cards' builders were deleted rather than left unreferenced.

  // FLOATING LAYER: every table in state.floatingTables gets its own draggable card,
  // rendered above the grid — fully independent of each other (owner,
  // 2026-07-02: "this only happens in popup mode, not the side thing — when the side thing
  // is closed [docked] that still happens [normally]"). Non-pinned cards get their
  // left/top/width from layoutFloatingRow() right after this markup lands (bindFloor);
  // pinned ones (dragged) keep the exact x/y/w they were dropped at.
  const floatingLayerHtml = state.floatingTables.map((f) => {
    const parts = tablePanelParts(f.table, "float");
    const { headPill, headMeta, requestsSec, sessionSec, ordersSec, callsSec, billSec, foot } = parts;
    const dockBtn = ""; // nothing to dock INTO any more — the side panel is gone (2026-07-31)
    // A PINNED card keeps its dragged/resized geometry (x/y/w/h); a free one gets only its
    // auto-arrange width here and its left/top/width from layoutFloatingRow after render.
    const styleParts = [`width:${f.w || 400}px`];
    if (f.pinned && f.x != null) { styleParts.push(`left:${f.x}px`, `top:${f.y}px`, "right:auto"); if (f.h) styleParts.push(`height:${f.h}px`); }
    return `<div class="tp-detail-floating${f.pinned ? " tp-pinned" : ""}" data-floating-table="${esc(f.table)}" style="${styleParts.join(";")}">
      <div class="tp-detail" data-table-detail="${esc(f.table)}">
        <div class="tp-detail-head">
          <div class="tp-detail-top"><h3>${esc(tableLabel(f.table))}</h3>${headPill}${parts.kotHeadBtn || ""}${dockBtn}<button class="tp-detail-close" data-float-close="${esc(f.table)}" aria-label="Close" title="Close">✕</button></div>
          ${headMeta}
        </div>
        <div class="tp-detail-body">${requestsSec}${sessionSec}${ordersSec}${callsSec}${billSec}</div>
        <div class="tp-detail-foot">${foot}</div>
      </div>
      <div class="tp-resize-handle" data-float-resize="${esc(f.table)}" title="Drag to resize"></div>
    </div>`;
  }).join("");
  // ONE layout, one way in: the grid at full width, with any open table floating above it.
  // (`floor-collapsed` is what that full-width mode has always been called in the CSS.)
  return `<div class="floor-wrap floor-collapsed">${main}</div>${floatingLayerHtml}`;
}

// patchFloorTiles(tables): the INCREMENTAL update path. Instead of rebuilding all ~300 tiles
// + re-binding ~300 listeners (the freeze at 300 tables), it replaces ONLY the named tiles'
// nodes via the shared floorTileHtml builder, then refreshes just the small floor-wide bits
// (the stats strip + the Requests/Needs queue cards) in place. The grid's .ftile-grid is
// NOT rebuilt, and the delegated click handler lives on #editor (an ancestor that survives),
// so replaced tile/card nodes need NO re-binding. If the grid/tile isn't present (different
// tab, skeleton, or detail open), it falls back to a full renderEditor() so we never leave a
// half-updated screen. Returns true if it patched, false if it fell back.
function patchFloorTiles(tables) {
  // The fallbacks below use loadSessions(true) — NOT a bare renderEditor() — because that's
  // the exact render step this path replaces in reconcileBoard. loadSessions(true) does three
  // things a bare renderEditor() drops: it preserves the in-panel detail's scroll, and it calls
  // renderTablePanel() to refresh the COLLAPSED-MODE MODAL (which lives on document.body, outside
  // #editor, so renderEditor alone never updates it → a stale modal until the 60s backup poll).
  // It's fromPoll=true → no fetch, no recursion (the slice was already awaited before reconcile).
  // Only valid on the Tables tab with the real grid drawn. Skeleton (pre-boardLoaded) or a
  // missing grid → full render is the safe path.
  const ed = $("#editor");
  const grid = ed && ed.querySelector(".ftile-grid");
  if (state.tab !== "tables" || !state.boardLoaded || !grid) { loadSessions(true); return false; }
  // A DETAIL node (docked / collapsed-mode modal / floating popup) + its slice rows only need
  // the full render path when the CHANGED table is the one being viewed. Previously we fell back
  // whenever ANY detail was open — but a detail is open during almost all normal work, so every
  // event (even on an unrelated table) rebuilt all ~300 tiles and the floor froze (the exact
  // 300-table freeze this patch path exists to prevent). Now: if a changed table's own detail is
  // open, full-render so that detail refreshes; otherwise patch just the changed tiles and leave
  // the open (unrelated) detail untouched — its data didn't change, so it's already correct.
  const openDetails = detailTables();
  if (openDetails.length && tables.some((t) => openDetails.includes(String(t)))) { loadSessions(true); return false; }
  const _t0 = performance.now();
  let patched = 0;
  for (const t of tables) {
    const el = ed.querySelector('[data-floor-table="' + String(t) + '"]');
    if (!el) { loadSessions(true); return false; } // a named tile isn't on the grid → safe full render
    el.outerHTML = floorTileHtml(t); // SHARED builder → byte-identical to a full render's tile
    patched++;
  }
  // Floor-wide bits that a single-table change can still move (occupancy counts, the queues):
  // refresh ONLY those nodes in place — never the grid. Their buttons are delegated, so swapping
  // the nodes can't orphan a listener.
  const statsEl = ed.querySelector(".floor-stats");
  if (statsEl) statsEl.outerHTML = floorStatsHtml();
  // (No queue cards to refresh any more — the stats strip above is the only floor-wide node.)
  // A patch draws the new summary WITHOUT updating loadSessions' lastBoardSig fingerprint.
  // If a later FULL poll lands carrying the PREVIOUS summary (a wake/reconnect/platform event
  // whose summary happens to match the pre-patch one), loadSessions(true) would see an unchanged
  // sig and skip the redraw — leaving the screen on the patched state. Invalidate the sig so the
  // next full poll always redraws once (cheaper than re-stringifying the summary here).
  lastBoardSig = "";
  // THE 🔔 IS PART OF THE FLOOR, SO IT HAS TO BE PATCHED WITH IT (T5 sweep, 2026-08-17).
  // syncGuestBell() ran only from renderEditor(), and this path exists precisely to AVOID a full
  // render — which is the path every realtime breadcrumb takes (a waiter call, a join request and
  // a new order all name their table). Measured on the backup: a targeted refetch fired zero bell
  // syncs while a full one fired one, so the count in the top bar sat still until the 60-second
  // backstop came round. It reads nothing and fetches nothing — the rows are already in
  // state.summary, which the lines above have just refreshed. Deferred the same way renderEditor
  // defers it, so it never lands inside the paint it is describing.
  setTimeout(syncGuestBell, 0);
  window.__lfhPerf.patches++;
  window.__lfhPerf.tilesPatched += patched;
  window.__lfhPerf.lastMs = performance.now() - _t0;
  return true;
}

// bindFloorDelegation: attach the floor's click handling ONCE on the stable #editor
// container (it never gets replaced — renderEditor only ever rewrites its innerHTML).
// Why delegation instead of per-tile onclick? At 300 tables the old bindFloor re-bound
// ~300 listeners on EVERY render; with one delegated handler, patched/replaced tile nodes
// (and the in-place-refreshed Requests/Needs cards) need NO re-binding — the listener lives
// on the parent and finds the clicked target via .closest(). A boolean guard means repeated
// renders never stack duplicate listeners.
//
// IMPORTANT: every data-attr handled here lives on a node that the PATCH path may replace
// (the tiles, and the #fcReq / #fcNeeds cards). That's exactly why they MUST be delegated —
// id-based handlers on those nodes would die the moment patchFloorTiles swaps them. The
// id-based controls that the patch NEVER touches (Open all/Close all, the side toggle,
// the Block input, the Blocked card's Unblock, the resizer, and the selected-table
// detail panel) stay in bindFloor and are re-wired on full renders.
let floorDelegationBound = false;
function bindFloorDelegation() {
  if (floorDelegationBound) return;
  floorDelegationBound = true;
  const ed = $("#editor");
  ed.addEventListener("click", (e) => {
    // Only act while the floor (Tables tab) is showing — #editor is shared by every tab.
    if (state.tab !== "tables") return;
    // The SELECTED-table detail panel lives INSIDE #editor too and reuses the same
    // data-mem-*/data-req-*/data-call-attend attrs — but it's wired by bindTablePanel's
    // own handlers (it has extra actions like Kick/Attend-all the floor cards don't). So if
    // the click landed inside the detail panel, let those handlers own it — don't double-fire.
    // (The collapsed-mode modal renders on document.body, outside #editor, so it never reaches
    // here at all.)
    if (e.target.closest("[data-table-detail]")) return;
    // QUICK ACTIONS + queue-card buttons FIRST (they're nested inside the tile / cards);
    // matching one and returning replicates the old stopPropagation so a quick button
    // never ALSO triggers the tile-select below. Check most-specific targets, then the tile.
    let b;
    // The tile's two own buttons (owner, 2026-07-31): ＋ Take order on every tile, and the
    // printer that opens the bill preview. Scoped to a .ftile so a detail panel rendered
    // inside #editor can never be double-handled by this floor-wide listener.
    if ((b = e.target.closest("[data-take-order]")) && b.closest(".ftile")) { openTakeOrder(b.dataset.takeOrder, null); return; }
    if ((b = e.target.closest("[data-bill-preview]"))) { openBillPreview(b.dataset.billPreview); return; }
    if ((b = e.target.closest("[data-close-table]"))) { closeFinishedTable(b.dataset.closeTable); return; }
    if ((b = e.target.closest("[data-quick-accept]")))   { acceptTableOrders(b.dataset.quickAccept); return; }
    // ── WHAT USED TO BE HERE, AND WHY IT ISN'T (T3 sweep, 2026-08-06) ─────────────────────────
    // Eight more branches sat here and not one of them could ever fire:
    //   · [data-quick-attend] / [data-quick-pay] / [data-quick-requests] — NO tile emits these.
    //     floorTileHtml's action row is close / take-order / quick-accept / bill-preview and
    //     nothing else; the side-panel cards these three belonged to went with the panel itself
    //     on 2026-07-31.
    //   · [data-mem-*] / [data-req-*] / [data-call-attend] — these ARE rendered, but only inside
    //     tablePanelParts, and the very first line of this handler returns for anything inside
    //     [data-table-detail]. bindTablePanel wires them directly, which is the whole reason for
    //     that early return.
    // Dead code that reads as live wiring costs real time: it made markTablePaid and attendCall
    // look like they had a floor entry point they do not have. If a floor-level (non-detail) card
    // ever comes back, wire it HERE and say so — don't restore these on the assumption they worked.
    // TILE SELECT last — only reached when no button above matched.
    const tile = e.target.closest("[data-floor-table]");
    if (tile) {
      // An EMPTY table goes STRAIGHT into taking an order (owner, 2026-07-31) — that is the only
      // thing anyone wants from a free table, so making them open a popup first and press a
      // button in it was one tap of pure ceremony. A table with something on it opens its popup,
      // where the order, the bill and the KOT tools live.
      // The permission still decides: a manager without take_orders gets the popup instead of a
      // builder they aren't allowed to use (and the server refuses it regardless).
      const ft = tile.dataset.floorTable;
      if (mergeParentOf(ft)) openFloatingTable(ft);          // merged child → its detail, where Unmerge is
      else if (tableTileState(ft).st === "free" && takeOrdersAllowed()) openTakeOrder(ft, null);
      else openFloatingTable(ft);
    }
  });
  // A TILE SAYS IT IS A BUTTON, SO IT HAS TO BEHAVE LIKE ONE (sweep 2026-08-04). Every tile renders
  // `role="button" tabindex="0"`, which puts all ~300 of them in the tab order and promises a
  // keyboard can use them — but the only handler was the click above, so Enter and Space did
  // nothing. Worse, the panel's global shortcut handler reads a bare 1-9 as "jump to the Nth tab",
  // so a keyboard user on the floor got silence from Enter and got thrown off the screen by a digit.
  // Delegated on the same stable ancestor for the same reason (a patched tile keeps working), and it
  // routes through the SAME click path, so tap and key can never drift apart.
  ed.addEventListener("keydown", (e) => {
    if (state.tab !== "tables") return;
    if (e.key !== "Enter" && e.key !== " " && e.key !== "Spacebar") return;
    const tile = e.target.closest && e.target.closest("[data-floor-table]");
    if (!tile || e.target.closest("button")) return;   // a real button inside the tile handles itself
    e.preventDefault();                                 // Space must not scroll the floor
    tile.click();
  });
}

// FLOATING POPUP SLOT MODEL (owner, 2026-07-02/03). The row is a grid of state.floatCols
// columns that GROWS as popups are added: 1 popup = one BIG centered card, 2 = halves,
// 3 = thirds … capped at MAX_FLOATING (owner: "if only 1, size should be big; as I add,
// it should become small"). Each non-pinned popup owns a stable slot INDEX inside that
// grid — dragging one out (→ PINNED, releases its slot) or closing one leaves a GAP and
// NEVER moves the rest ("everything should stay as it is"); the gap is re-used by the next
// table opened. Only ADDING a popup when no gap is free grows the grid (everyone reflows
// slightly smaller — the one movement the owner explicitly asked for). When no slotted
// popup remains (all dragged away / closed), the grid resets so the next popup starts
// big from the middle again. On a PHONE (isPhoneLayout) it's ONE full-width popup at a
// time — no drag, no resize, no side-by-side (owner, 2026-07-03).
const MAX_FLOATING = 5;
const FLOAT_MAX_W = 640; // don't let 1–2 popups stretch absurdly wide on a big monitor
// True WHILE a floating popup is being dragged or resized: a background poll's
// renderEditor() would rebuild #editor and drop the drag, so loadSessions() defers
// its redraw until pointerup (see the guard in loadSessions + the flush in the up handlers).
let floatInteracting = false;
let floatRenderPending = false;
// flushFloatRender(): call on drag/resize end — replays the redraw we deferred, if any.
function flushFloatRender() { floatInteracting = false; if (floatRenderPending) { floatRenderPending = false; loadSessions(true); } }
const isPhoneLayout = () => window.matchMedia("(max-width: 760px)").matches;
// addFloating(t): open table t as a floating popup. Fills the left-most empty gap in the
// current grid first; grows the grid by one column when there's no gap. Returns true if open.
function addFloating(t) {
  t = String(t);
  if (isPhoneLayout()) {
    // Phone = single-popup mode: the new table REPLACES whatever was floating.
    if (state.floatingTables.length === 1 && state.floatingTables[0].table === t) return true;
    state.floatingTables = [{ table: t, pinned: false, slot: 0, x: null, y: null, w: null, h: null }];
    state.floatCols = 1;
    return true;
  }
  if (state.floatingTables.some((f) => f.table === t)) return true;         // already open
  if (state.floatingTables.length >= MAX_FLOATING) { toast(`Up to ${MAX_FLOATING} table windows open at once.`, "err"); return false; }
  const slotted = state.floatingTables.filter((f) => !f.pinned && f.slot != null);
  if (!slotted.length) state.floatCols = 0; // fresh grid → this popup starts big in the middle
  const used = new Set(slotted.map((f) => f.slot));
  let slot = null;
  for (let s = 0; s < state.floatCols; s++) if (!used.has(s)) { slot = s; break; } // re-use a vacated gap first
  if (slot == null) {
    if (state.floatCols >= MAX_FLOATING) { toast(`Up to ${MAX_FLOATING} table windows open at once.`, "err"); return false; }
    slot = state.floatCols; state.floatCols += 1; // no gap → grow the grid (existing cards shrink to fit)
  }
  state.floatingTables.push({ table: t, pinned: false, slot, x: null, y: null, w: null, h: null });
  return true;
}

// layoutFloatingRow(): position every NON-pinned popup at its slot inside the CURRENT grid
// (state.floatCols columns, centered as a row, each column capped at FLOAT_MAX_W). Slot
// indexes are stable, so drag-outs/closes never move the rest; only a grid GROWTH (add with
// no free gap) re-computes everyone's width. Pinned cards keep their dropped/resized geometry.
function layoutFloatingRow() {
  // TOP adds the admin/owner ribbon's height (0 for real staff) — the inline top set
  // below overrides the CSS default, so it must do the same --ribbon-h subtraction or
  // popups tuck under the topbar in admin view.
  const ribbonH = parseInt(getComputedStyle(document.documentElement).getPropertyValue("--ribbon-h")) || 0;
  const GAP = 14, MARGIN = 20, TOP = 70 + ribbonH;
  const phone = isPhoneLayout();
  const cols = Math.max(1, Math.min(MAX_FLOATING, state.floatCols || 1));
  const avail = window.innerWidth - (phone ? 16 : MARGIN * 2);
  const slotW = phone ? avail : Math.min((avail - (cols - 1) * GAP) / cols, FLOAT_MAX_W);
  const rowW = cols * slotW + (cols - 1) * GAP;
  const startX = Math.max(phone ? 8 : MARGIN, (window.innerWidth - rowW) / 2);
  state.floatingTables.forEach((f) => {
    if (f.pinned || f.slot == null) return; // pinned = free-floating; keep its own position
    const el = document.querySelector(`[data-floating-table="${CSS.escape(String(f.table))}"]`);
    if (el) { el.style.left = (startX + f.slot * (slotW + GAP)) + "px"; el.style.top = (phone ? 62 + ribbonH : TOP) + "px"; el.style.width = slotW + "px"; el.style.height = ""; el.style.right = "auto"; }
  });
}

// bindFloor: wire up the unified floor after a FULL render — the once-attached delegated
// click handler covers tiles + quick buttons + the Requests/Needs queue cards (so the
// patch path never has to re-bind them); here we wire only the controls the patch never
// touches (bulk open/close, the side toggle, settings, location, block, unblock, resizer,
// and the selected-table detail panel).
// (syncFloorMore() lived here — it counted the tiles past the grid's right edge to keep the
// "→ N more" chip honest. Both are gone with the sideways scroll itself (owner, 2026-08-15). R8 in
// docs/REJECTED-IDEAS.md — his refusal to make that chip smarter — moved to Reversed for the only
// reason a rejection ever should: the thing it was about no longer exists.)
// THE COLOUR KEY MOVES INTO THE ☰ MENU ON A PHONE (item 23, owner gave permission 2026-09-01:
// "can do the two things I give you the permission").
//
// WHY: on a 360px screen the floor header is 169px, and 45px of that is the two-line colour key.
// The first table sat 300px down a 780px screen and a manager saw FOUR tables of 31, against the
// waiter tablet's six. The key is a learning aid — you read it in your first week and never again —
// so it is the one block in that header that does not need to be on screen while you work.
//
// WHAT THIS IS NOT: it does not touch `const LEG`. Every entry R25 protects is still there, in the
// same order, saying the same thing — the strip stays exactly as short as he asked for, it just
// lives one tap away on the smallest screen. And it does not re-flow the 🧾 KOT ▾ / ⚡ QO/P pair,
// which is what R11 settled; that line is untouched at every width.
//
// ABOVE 760px NOTHING MOVES: the key stays in the header where it has always been.
function syncLegendToDrawer() {
  const tabs = document.getElementById("mainTabs");
  if (!tabs) return;
  const phone = window.matchMedia("(max-width: 760px)").matches;
  let slot = tabs.querySelector(".nav-legend");
  if (!phone) { if (slot) slot.remove(); return; }   // back on a big screen: give it up again
  const live = document.querySelector(".floor-head .floor-legend");
  if (!live) return;
  if (!slot) {
    slot = document.createElement("div");
    slot.className = "nav-legend";
    const h = document.createElement("div");
    h.className = "nav-legend-h";
    h.textContent = "What the colours mean";   // textContent: never build a label from HTML
    slot.appendChild(h);
    tabs.appendChild(slot);
  }
  // MOVE the live node, never a clone: the floor re-renders this element on every board update
  // (merged tables add a "Merged" entry and remove it again), and a clone would quietly go stale.
  const held = slot.querySelector(".floor-legend");
  if (held !== live) { if (held) held.remove(); slot.appendChild(live); }
}

function bindFloor() {
  bindFloorDelegation(); // attach the delegated tile/quick/queue handler ONCE
  syncLegendToDrawer();  // phone: the colour key lives in the ☰ menu (item 23)
  const ed = $("#editor");
  // (The ↻ Refresh button was removed — the floor is live via realtime + the 60s backup poll,
  //  so a manual refresh was redundant and looked broken. Coordinator-relayed owner request.)
  // Bulk open/close for the whole floor (both confirm before acting).
  // New Parcel → the take-order dish picker in PARCEL mode (no table → a takeaway
  // order in the Platform system). Gated by the take_orders x-ray (below) + server.
  // ⚡ QO/P — the quick order builder. It takes NO table: the destination (a table, or
  // Parcel) is chosen at the very end, inside the builder.
  // "parcel" → the original parcel builder (a different screen); "quick" → the drill-down.
  ed.querySelectorAll("[data-qop]").forEach((b) => (b.onclick = () =>
    openTakeOrder(null, null, b.dataset.qop === "parcel" ? { parcel: true } : { quick: true })));
  // (No #floorSections binding — the 👥 "Who serves what" button left the floor on 2026-07-31
  //  ("I do not want this option completely on top") and its ONE home is Settings → Access. The
  //  binding outlived the button by five weeks; removed in the T3 sweep, 2026-08-06.)
  // (No Open all / Close all bindings — the buttons no longer exist; see bulkCard.)
  { const kb = ed.querySelector("#floorKot"); if (kb) kb.onclick = () => openKotTablePicker(); }
  // (The printer-trouble strip's three bindings lived here — [data-prok] "✓ Resolved",
  // [data-prhere] "Print here instead" and [data-prsetup] "where does the paper come out".
  // DELETED sweep #8 T7. The bands came off the floor on 2026-08-31 with their builders
  // (printerStripHtml / printStationStripHtml / bindPrintStationStrip — see the obituary above
  // noticePrinterNews), but these three querySelectorAll calls stayed, and NOTHING in the
  // product has emitted data-prok / data-prhere / data-prsetup since. Twenty-two lines that
  // read as live wiring for a strip that does not exist, which is exactly what the owner's
  // "there is two printing things, one is working and one is just showing" rule forbids.
  // printJobHere() went with them — it had one caller, the dead [data-prhere] line.
  // The live readout is the 🔔 bell (syncGuestBell's `kind: "printer"` rows); a stuck ticket
  // is still printable by hand from 🧾 KOT ▾ → Print / reprint a KOT → Print KOT.
  // Do not put a band back above the table grid.
  // (No Blocked-card / docked-detail / resizer / float-out bindings — the right-hand panel
  // and everything that lived in it are gone. A table opens as a popup, full stop.)
  // Every floating card: wire its own detail actions (through the SAME bindTablePanel every
  // other host uses), its Close button, and drag-to-pin on its header.
  ed.querySelectorAll("[data-floating-table]").forEach((card) => {
    const t = String(card.dataset.floatingTable);
    const detail = card.querySelector("[data-table-detail]");
    if (detail) {
      const parts = tablePanelParts(t, "float"); // must match the render above
      const rerender = () => {
        const body = card.querySelector(".tp-detail-body");
        const top = body ? body.scrollTop : 0;
        renderEditor();
        const c2 = $("#editor").querySelector(`[data-floating-table="${CSS.escape(t)}"] .tp-detail-body`);
        if (c2) c2.scrollTop = top;
      };
      const closeThis = () => { closeFloatingTable(t); };
      bindTablePanel(detail, t, parts, { rerender, close: closeThis });
    }
    const closeBtn = card.querySelector("[data-float-close]");
    if (closeBtn) closeBtn.onclick = () => closeFloatingTable(t);
    // Drag-to-pin: once dragged, this card is EXCLUDED from auto-arrange (owner, 2026-07-02
    // — "if you once move it, it will not be a part of auto") and the rest re-share the
    // space among themselves. Clamped so it can't be dragged fully off-screen.
    const head = card.querySelector(".tp-detail-head");
    if (head) head.onpointerdown = (e) => {
      if (isPhoneLayout()) return; // phone = one fixed full-width popup — no drag/pin
      if (e.target.closest("button")) return; // don't start a drag from Dock/✕
      e.preventDefault();
      const startX = e.clientX, startY = e.clientY;
      const rect = card.getBoundingClientRect();
      const startLeft = rect.left, startTop = rect.top;
      try { head.setPointerCapture(e.pointerId); } catch {}
      // Suspend the auto-arrange left/top/width transition WHILE dragging — otherwise each
      // pointermove's style change animates instead of jumping instantly, and worse,
      // getBoundingClientRect() on drop can read a still-mid-animation position instead of
      // where the pointer actually let go.
      card.classList.add("dragging");
      floatInteracting = true; // pause poll-driven redraws so the drag can't be torn out
      let moved = false;
      const move = (ev) => {
        moved = true;
        const maxLeft = window.innerWidth - card.offsetWidth - 8;
        const maxTop = window.innerHeight - 60; // leave enough of the header on-screen to grab again
        const x = Math.min(Math.max(8, startLeft + (ev.clientX - startX)), Math.max(8, maxLeft));
        const y = Math.min(Math.max(8, startTop + (ev.clientY - startY)), Math.max(8, maxTop));
        card.style.left = x + "px"; card.style.top = y + "px"; card.style.right = "auto";
      };
      const up = () => {
        head.removeEventListener("pointermove", move);
        head.removeEventListener("pointerup", up);
        card.classList.remove("dragging");
        if (!moved) { flushFloatRender(); return; } // a plain click on the header — not a drag, nothing to pin
        const f = state.floatingTables.find((x) => x.table === t);
        if (f) {
          const rect2 = card.getBoundingClientRect();
          // Pin it AND release its slot → leaves a gap the next new popup will fill; the other
          // slotted cards keep their fixed positions (they never move because one was dragged).
          f.pinned = true; f.slot = null; f.x = rect2.left; f.y = rect2.top; f.w = rect2.width;
        }
        card.classList.add("tp-pinned"); // instant visual feedback — the class also lands from the data on the next render anyway
        layoutFloatingRow(); // no-op for the others (fixed slots); just keeps things consistent
        flushFloatRender(); // resume redraws + replay any poll we deferred mid-drag (now that f.x/y/w are set)
      };
      head.addEventListener("pointermove", move);
      head.addEventListener("pointerup", up);
    };
    // Resize by dragging the bottom-right corner (owner, 2026-07-02: "you should be able to
    // make it small"). Like a drag, resizing PINS the card — it keeps its size+position and
    // drops out of the auto-arrange; the others re-share the row. Stores h so a re-render
    // (e.g. a live poll) keeps the size the owner set.
    const rez = card.querySelector("[data-float-resize]");
    if (rez) rez.onpointerdown = (e) => {
      if (isPhoneLayout()) return; // phone: no resize (the handle is also display:none in CSS)
      e.preventDefault(); e.stopPropagation();
      const startX = e.clientX, startY = e.clientY;
      const rect = card.getBoundingClientRect();
      const startW = rect.width, startH = rect.height, left = rect.left, top = rect.top;
      try { rez.setPointerCapture(e.pointerId); } catch {}
      card.classList.add("dragging");
      floatInteracting = true; // pause poll-driven redraws so the resize can't be torn out
      const move = (ev) => {
        const w = Math.min(Math.max(280, startW + (ev.clientX - startX)), window.innerWidth - left - 12);
        const h = Math.min(Math.max(180, startH + (ev.clientY - startY)), window.innerHeight - top - 12);
        card.style.width = w + "px"; card.style.height = h + "px";
      };
      const up = () => {
        rez.removeEventListener("pointermove", move); rez.removeEventListener("pointerup", up);
        card.classList.remove("dragging");
        const f = state.floatingTables.find((x) => x.table === t);
        if (f) { const r = card.getBoundingClientRect(); f.pinned = true; f.slot = null; f.x = r.left; f.y = r.top; f.w = r.width; f.h = r.height; }
        card.classList.add("tp-pinned");
        layoutFloatingRow();
        flushFloatRender(); // resume redraws + replay any poll we deferred mid-resize
      };
      rez.addEventListener("pointermove", move);
      rez.addEventListener("pointerup", up);
    };
  });
  layoutFloatingRow();
}

// (The floor's saveSetting()/saveGeo() helpers were deleted with the side panel's
// "Features · rarely changed" card on 2026-07-29 — dining-session switches and the café
// location are edited only in Settings → "Dining sessions" / the admin panel now.)

// ---- the ONE panel that handles a table end to end ----
// open/closeTablePanel: remember which table's big control panel is open. Opening kicks
// off a fresh load so the panel is never showing stale data — that SAME load's own
// renderTablePanel() call (see loadSessions) is what actually draws the modal; we don't
// also render synchronously here (owner report, 2026-07-02: "why 2 time load" — rendering
// instantly with whatever was cached, THEN again a moment later once the real fetch
// landed, was a guaranteed double-render/flicker on every open, not just an occasional
// race). A modal appearing a beat after the tap (one real network round-trip) reads as
// normal; two back-to-back redraws reads as broken.
// Render the modal INSTANTLY (from the summary-driven streaming view — see tablePanelParts),
// THEN loadSessions() fetches the slice and re-renders with real dish rows. Instant because
// the first paint is summary-accurate (not stale/empty), so there's no wrong-then-corrected
// flicker — just the dish list filling in. (owner report, 2026-07-02: the modal took 1-2s
// to appear at all; this is the stale-while-revalidate fix.)
function openTablePanel(table) { state.openSess = String(table); renderTablePanel(); loadSessions(); }
function closeTablePanel() { state.openSess = null; document.querySelector(".tbl-modal-overlay")?.remove(); }

// (selectTable / deselectTable are gone with the docked detail — openFloatingTable below is
// the ONE way a table opens now. state.selectedTable stays as "which table is open", because
// that is what makes its tile show the selected ring and read from the full board slice rather
// than the slim summary.)

// Sync hardware-BACK layers to the open table details. On a phone the table detail is a
// floating popup (or the docked detail on desktop); neither registered with LFH_BACK, so
// pressing Android BACK on an open table popup left the panel instead of closing the popup.
// Each open detail gets exactly one back layer; Back (or a UI close) peels one at a time.
const _tableBackLayers = new Map(); // key -> unregister()
function syncTableBackLayers() {
  if (!window.LFH_BACK) return;
  const openKeys = new Set();
  state.floatingTables.forEach((f) => openKeys.add("float:" + f.table));
  if (!state.floatingTables.length && state.selectedTable != null) openKeys.add("dock:" + state.selectedTable);
  // Register a layer for any newly-open detail.
  openKeys.forEach((k) => {
    if (_tableBackLayers.has(k)) return;
    const off = LFH_BACK.layer("table-detail", () => {
      _tableBackLayers.delete(k); // Back already popped this layer — don't rewind it again
      if (k.slice(0, 6) === "float:") {
        const t = k.slice(6);
        state.floatingTables = state.floatingTables.filter((f) => String(f.table) !== String(t));
      } else {
        state.selectedTable = null;
      }
      renderEditor();
    });
    _tableBackLayers.set(k, off);
  });
  // Drop layers for details closed by other means (✕, shift, close, free).
  [..._tableBackLayers.keys()].forEach((k) => {
    if (!openKeys.has(k)) { const off = _tableBackLayers.get(k); _tableBackLayers.delete(k); try { off(); } catch (e) {} }
  });
}

// followShiftedTable(from, to): after a party is shifted, move whatever detail was showing
// the SOURCE table onto the DESTINATION — in BOTH view modes. selectTable(to) alone only
// moved the DOCKED detail; in popup/phone mode the OLD table stayed floating and the moved
// party looked like it vanished (no popup for its new home). This handles the floating popup,
// the docked detail, and the legacy modal, then refetches the new table's slice.
function followShiftedTable(from, to) {
  from = String(from); to = String(to);
  const fi = state.floatingTables.findIndex((f) => String(f.table) === from);
  if (fi >= 0) {
    if (state.floatingTables.some((f) => String(f.table) === to)) state.floatingTables.splice(fi, 1); // dest already floats → just drop the old
    else state.floatingTables[fi].table = to;
  }
  if (String(state.selectedTable) === from) state.selectedTable = to;
  if (String(state.openSess) === from) state.openSess = to;
  renderEditor();  // instant repaint at the new table
  loadSessions();  // fetch the destination's full slice
}

// openFloatingTable(t): open (or re-focus) table t as a popup. This is THE way a table opens
// (owner, 2026-07-31) — there is no docked alternative any more. It paints instantly from the
// slim summary (accurate: guests/dishes/due), then loadSessions fills in the dish rows. A second
// tap on an already-open table is a no-op rather than a duplicate card.
function openFloatingTable(table) {
  // A MERGED CHILD HOLDS NOTHING OF ITS OWN: its orders live on the parent's party. Without the
  // parent's slice the detail (and worse, the unmerge confirm) would say "nothing was ordered at
  // this table" about food that is on the bill. Fetch the parent too, once, before rendering.
  // OPENING ANY TABLE OF A PARTY LOADS THE WHOLE PARTY (owner: "every table will show every order").
  // Each table's orders live in its OWN ?table= slice — they keep their own table number, which is
  // what makes an unmerge exact — so a party's detail needs every member's slice. Fetching only the
  // parent (from a child) left table 7 showing 3 of the party's 6 tickets.
  const _head = mergeParentOf(table) || table;
  const _party = [String(_head), ...mergeChildrenOf(_head)].filter((x) => String(x) !== String(table));
  for (const _k of _party) {
    ensureTableSlice(_k).then(() => { if (state.floatingTables.some((f) => String(f.table) === String(table))) renderEditor(); }).catch(() => {});
  }
  const _mp = mergeParentOf(table);
  if (_mp) {
    // …and re-render once it lands. The detail paints instantly (that is the point of the
    // streaming view), so a fire-and-forget fetch would leave the first paint saying "nothing was
    // ordered at this table" about food that is on the joint bill — and the unmerge confirm reads
    // the same list, so it would promise the wrong thing.
    ensureTableSlice(_mp).then(() => { if (state.floatingTables.some((f) => String(f.table) === String(table))) renderEditor(); })
      .catch(() => {});
  }
  if (!addFloating(table)) return; // at the cap
  state.selectedTable = String(table); // marks the tile + makes it read from the full slice
  renderEditor();  // instant, summary-accurate
  loadSessions();  // fetch slice → re-render with full dish rows
}
// closeFloatingTable(t): the ONE way a table popup closes (its ✕, the back button, a table that
// got freed). It also clears the "open table" marker when nothing is left open — otherwise the
// tile kept its selected ring and kept pulling that table's full slice on every poll.
function closeFloatingTable(t) {
  state.floatingTables = state.floatingTables.filter((f) => String(f.table) !== String(t));
  if (String(state.selectedTable) === String(t)) {
    state.selectedTable = state.floatingTables.length ? String(state.floatingTables[0].table) : null;
  }
  renderEditor();
}

// refreshTableDetail: redraw whichever table-detail view is currently open after a
// local (optimistic) change, so the instant feedback works in BOTH places. There
// are two: the legacy pop-up modal (state.openSess) and the new in-panel master-
// detail (state.selectedTable). renderTablePanel() only redraws the modal — it bails
// when no modal is open — so on its own it leaves the in-panel detail stale. This
// covers both, and preserves the in-panel body's scroll so serving a dish doesn't
// fling the list back to the top.
function refreshTableDetail() {
  if (state.openSess != null) { renderTablePanel(); return; }
  // FLOATING POPUPS (popup mode — the default detail view now): the detail lives in the
  // floating layer, which ONLY renderEditor() rebuilds. Optimistic actions (serve a dish,
  // approve/deny a member) call refreshTableDetail expecting an INSTANT repaint — without
  // this branch the local change didn't paint until the next poll, so serving a dish in a
  // popup looked like it took ~2s (owner report, 2026-07-03). The per-order accept/serve-all
  // already repaint via loadSessions(true)→renderEditor; this covers the per-DISH path too.
  // Preserve every open popup's scroll so serving a dish doesn't fling the list to the top.
  if (state.floatingTables.length) {
    const ed = $("#editor");
    const scrolls = {};
    ed.querySelectorAll("[data-floating-table]").forEach((c) => { const b = c.querySelector(".tp-detail-body"); if (b) scrolls[c.dataset.floatingTable] = b.scrollTop; });
    renderEditor();
    const ed2 = $("#editor");
    Object.keys(scrolls).forEach((t) => { const b = ed2.querySelector(`[data-floating-table="${CSS.escape(t)}"] .tp-detail-body`); if (b) b.scrollTop = scrolls[t]; });
    return;
  }
  if (state.selectedTable != null) {
    const ed = $("#editor");
    const body = ed.querySelector(".tp-detail-body");
    const top = body ? body.scrollTop : 0;
    renderEditor();
    const b2 = ed.querySelector(".tp-detail-body");
    if (b2) b2.scrollTop = top;
  }
}

// Tables currently in STAFF EDIT mode (after the kitchen-confirm). Module-level so
// it survives the panel's poll-driven re-renders. (owner, 2026-06-17)
const editTables = new Set();

// One dish row: its own status pill + next-step tap. Works for session items (order_items)
// AND legacy items (orders.items JSON) — so dishes are served one at a time either way.
// `editing` (staff edit mode) adds qty steppers + a note edit on each real dish row.
function itemRowHtml(row, editing = false) {
  // Redesigned row layout (master-detail): qty · name+detail · price · [chip + serve + 🗑].
  // The status now reads as a CHIP on the right next to its actions (was a pill on the
  // left), so the eye runs name → price → status → action in one line.
  let serveBtn = "";
  // A dish that's cooking OR ready (kitchen finished it) can be served from here.
  if (row.status === "preparing" || row.status === "ready") {
    const attr = row.kind === "session"
      ? `data-item-next="${esc(row.id)}" data-item-status="served"`
      : `data-legacy-order="${esc(row.orderId)}" data-legacy-idx="${row.idx}" data-legacy-status="served"`;
    serveBtn = `<button class="icon-serve" title="Serve this dish" ${attr}>🍽️</button>`;
  }
  const priceTag = `<span class="sx-item-price">${row.price > 0 ? inr(row.price * row.qty) : ""}</span>`;
  // 🗑 Delete this single dish from the order. ONLY for session items (they have a
  // real order_item id the server can delete + reconcile); legacy JSON-only orders
  // have no per-item row, so we don't offer it there. Deleting recomputes the bill
  // total server-side (see lfh_delete_order_item) so no stale money is left behind.
  // …but NOT once it's SERVED — a delivered dish is a financial record; you don't
  // silently delete it (mirror the tablet, which also blocks delete on served).
  // …and not once the invoice is printed (owner, 2026-08-26) — same rule as the ✕ Cancel above,
  // and the server has always refused it here (invoiceLockedByItem); the button simply stopped
  // being offered for the served case only. `itemRowInvoiceLive` is set by the caller from the
  // session this row belongs to; absent (a legacy order, a parcel) it is false and nothing changes.
  const delBtn = (row.kind === "session" && row.status !== "served" && !row.invoiceLive) ? `<button class="icon-del sx-item-del" data-item-del="${esc(row.id)}" data-item-name="${esc(row.title)}" title="Remove this dish from the order">🗑</button>` : "";
  // status label: friendlier words for the chip (class stays the raw status for colour).
  // "preparing", not "cooking": the tile above this card and the guest's own order tracker both
  // say Preparing (the tile's label comes from the DATABASE, lfh_table_view_summary), so calling
  // the same status "cooking" here made ONE order read three ways inside one modal — Preparing
  // on the pill, cooking in the legend, COOKING on the badge (T15 sweep, 2026-08-05). The KITCHEN
  // board keeps "Cooking" on purpose: that is the word a cook uses, on the cook's own screen.
  const STLABEL = { received: "new", preparing: "preparing", ready: "ready", served: "served", cancelled: "cancelled" };
  // STAFF EDIT (a real dish): qty −/＋ steppers + a "✎ Edit" button (allergens +
  // kitchen note) on a FULL-WIDTH row below the dish. Split into two separate gates:
  //   qty steppers  — blocked once READY/SERVED (re-prices the bill; you can't
  //                   un-serve part of a dish once it's out).
  //   ✎ Edit        — allowed at ANY status (owner, 2026-07-03 — "allergy can be
  //                   added to all items"). Allergens/notes are metadata, never
  //                   money, so there's no integrity reason to lock them once served.
  const canEditQty = editing && row.kind === "session" && row.status !== "served" && row.status !== "ready";
  const canEditDish = editing && row.kind === "session";
  const editRow = canEditDish
    ? `<div class="sx-dish-edit-row">${canEditQty ? `<span class="sx-item-edit"><button class="sx-qty" data-qty-dec="${esc(row.id)}" data-qty="${esc(row.qty)}" title="Fewer">−</button><button class="sx-qty" data-qty-inc="${esc(row.id)}" data-qty="${esc(row.qty)}" title="More">＋</button></span>` : ""}<button class="sx-dish-edit-btn" data-edit-dish="${esc(row.id)}" title="Edit allergens & note for this dish">✎ Edit</button></div>`
    : "";
  // ✎− on the dish NAME when an allergen was REMOVED after the order was placed
  // (we flag that something was removed without naming the gone item).
  const remMark = row.removedFlag ? ` <span class="alg-removed" title="An allergen was removed after the order was placed">✎−</span>` : "";
  return `<div class="sx-item${editing ? " editing" : ""}"><span class="sx-item-qty">×${esc(row.qty)}</span><div class="sx-item-info"><span class="sx-item-name">${esc(row.title)}${dishNoTag(row.title)}${mrpPill(row)}${remMark}</span>${itemDetailLine(row)}</div>${priceTag}<div class="sx-item-acts"><span class="ord-pill ${esc(row.status)}">${esc(STLABEL[row.status] || row.status)}</span>${serveBtn}${delBtn}</div>${editRow}</div>`;
}

// openDishEditModal: ONE editor for a single placed dish — toggle which allergens to
// AVOID (the 6 standard ones PLUS any custom like "water"), type a NEW custom allergen,
// and write a kitchen note. Replaces the old browser prompt() + scattered inline chips
// with one clean, dynamic modal (owner, 2026-06-17). Save persists in a single go:
//   • adding an allergen → written to THIS dish's own list (order_items.removed)
//   • removing one → cleared from the dish AND the order-wide "avoid" list so it's gone
//   • the note → order_items.note
function openDishEditModal(itemId, rerender) {
  document.querySelector(".dish-edit-overlay")?.remove();
  // The live floor's cache (state.board.items) only holds OPEN tables' dishes. A
  // settled/archived bill (opened from the Bills view) isn't there — fall back to
  // each order's own embedded items JSONB, which carries the same id/removed/note
  // fields (kept in sync by lfh_sync_order_items_json), so the SAME modal works for
  // both a live table's dish and a past bill's dish. (owner, 2026-07-03 — "allergy
  // can be added to all items")
  let item = (state.board.items || []).find((i) => i.id === itemId);
  let order = item ? ((state.data.orders || []).find((o) => o.id === item.order_id) || {}) : null;
  if (!item) {
    for (const o of (state.data.orders || [])) {
      const found = (Array.isArray(o.items) ? o.items : []).find((i) => i.id === itemId);
      if (found) { item = { ...found, order_id: o.id }; order = o; break; }
    }
  }
  order = order || {};
  // Normalise an allergen: lowercase, trim, strip a leading "no " so typing "no water"
  // or "water" both store "water" (the UI prepends "NO" when it shows it).
  const norm = (s) => String(s || "").trim().toLowerCase().replace(/^no[\s-]+/, "");
  const itemRemoved = (Array.isArray(item.removed) ? item.removed : []).map(norm).filter(Boolean);
  const orderAllergies = (Array.isArray(order.allergies) ? order.allergies : []).map(norm).filter(Boolean);
  const initial = new Set([...itemRemoved, ...orderAllergies]); // what the dish avoids now
  const working = new Set(initial);                             // live working copy until Save
  const STD = ALLERGENS.map((a) => a.slug);
  const labelFor = (slug) => { const a = ALLERGENS.find((x) => x.slug === slug); return a ? a.label : "🚫 " + slug; };
  const chipsHtml = () => {
    const std = ALLERGENS.map((a) => `<span class="chip dish-alg-chip ${working.has(a.slug) ? "on" : ""}" data-slug="${esc(a.slug)}">${esc(a.label)}</span>`).join("");
    // Custom allergens are their own chips — tap one to REMOVE it (same as a standard chip).
    const cust = [...working].filter((s) => !STD.includes(s)).map((s) => `<span class="chip dish-alg-chip on" data-slug="${esc(s)}">${esc(labelFor(s))}</span>`).join("");
    // ＋ Other instead of a text box always sitting there (owner, 2026-08-04: "I don't want
    // an allergy box, I want an Other option in the listed allergies").
    return std + cust + `<span class="chip dish-alg-chip alg-other" data-alg-other="1" title="Type an allergy that isn't listed">＋ Other</span>`;
  };
  const wrap = el(`<div class="sx-modal-overlay dish-edit-overlay"><div class="sx-modal dish-edit-modal">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>Edit dish · ${esc(item.title)}</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="dish-edit-body">
      <div class="dish-edit-lbl">⚠ Allergies to avoid <span class="muted small">— tap to add or remove</span></div>
      <div class="dish-alg-list"></div>
      <div class="dish-edit-lbl" style="margin-top:15px">✎ Note for the kitchen</div>
      <textarea class="dish-edit-note" rows="2" maxlength="200" placeholder="e.g. less ice, extra chocolate"></textarea>
    </div>
    <div class="dish-edit-foot"><button type="button" class="btn dish-edit-cancel">Cancel</button><button type="button" class="btn primary dish-edit-save">Save</button></div>
  </div></div>`);
  document.body.appendChild(wrap);
  wrap.querySelector(".dish-edit-note").value = item.note || "";
  const listEl = wrap.querySelector(".dish-alg-list");
  const bindChips = () => {
    listEl.querySelectorAll("[data-slug]").forEach((c) => (c.onclick = () => {
      const s = c.dataset.slug; working.has(s) ? working.delete(s) : working.add(s); redraw();
    }));
    // ＋ Other → type an allergy the six don't cover; it joins the row as its own chip.
    const other = listEl.querySelector("[data-alg-other]");
    if (other) other.onclick = async () => { const v = await allergyPrompt(working); if (v) { working.add(v); redraw(); } };
  };
  const redraw = () => { listEl.innerHTML = chipsHtml(); bindChips(); };
  redraw();
  const close = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = close;
  wrap.querySelector(".dish-edit-cancel").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };
  const same = (a, b) => JSON.stringify(a.slice().sort()) === JSON.stringify(b.slice().sort());
  wrap.querySelector(".dish-edit-save").onclick = async () => {
    const note = wrap.querySelector(".dish-edit-note").value.trim();
    const removed = [...initial].filter((s) => !working.has(s));  // cleared → drop everywhere
    const added = [...working].filter((s) => !initial.has(s));    // new avoids → this dish only
    const newItemRemoved = [...new Set([...itemRemoved.filter((s) => !removed.includes(s)), ...added])];
    const newOrderAllergies = orderAllergies.filter((s) => !removed.includes(s));
    try {
      // Each save carries the value this modal OPENED with. If another device changed the
      // same thing while it was open, the server refuses and says what it holds now, instead
      // of one person's "more spicy" silently wiping another's "less spicy".
      // SAVED-NOT-SENT IS ANSWERED BY WHICHEVER CALL RAN, and it has to be a name that still
      // EXISTS at the toast (sweep #8 T7). This block used to declare `const _wq` INSIDE the
      // note branch and read it eleven lines below, outside that block — a name nothing can see
      // there. So every successful dish edit saved, closed, refreshed, and THEN threw
      // "_wq is not defined" into the catch, which told the person "Couldn't save: …" about an
      // edit that had already gone through. Same shape as attendTableCalls(): one flag, set by
      // whichever of the three writes actually ran.
      let anyQueued = false;
      if (note !== String(item.note || "").trim()) {
        anyQueued = wasQueued(await api("POST", `/items/${item.id}/note`, { note }, { expect: { table: "order_items", id: item.id, fields: { note: String(item.note || "") } } })) || anyQueued;
      }
      if (!same(newItemRemoved, itemRemoved)) {
        anyQueued = wasQueued(await api("POST", `/items/${item.id}/removed`, { removed: newItemRemoved }, { expect: { table: "order_items", id: item.id, fields: { removed: itemRemoved } } })) || anyQueued;
      }
      if (order.id && !same(newOrderAllergies, orderAllergies)) {
        anyQueued = wasQueued(await api("POST", `/orders/${order.id}/allergies`, { allergies: newOrderAllergies }, { expect: { table: "orders", id: order.id, fields: { allergies: orderAllergies } } })) || anyQueued;
      }
      close();
      await loadSessions(); if (rerender) rerender();
      okToast(anyQueued ? { queued: true } : null, "Dish updated");
    } catch (e) {
      // SOMEONE ELSE GOT THERE FIRST. Close, refresh, and hold the message on screen long
      // enough to be read — this person's edit did NOT save and they need to know why.
      const clash = e && e.data && e.data.clash;
      if (clash) {
        close();
        await loadSessions(); if (rerender) rerender();
        toast(clash.plain + " " + clash.todo, "err", undefined, 9000);
        return;
      }
      toast("Couldn't save: " + errText(e), "err");
    }
  };
}

// tablePanelParts: build ALL the inner HTML sections for ONE table's full detail
// (guests, the live building cart, the merged orders, waiter calls, the bill, and
// the footer action buttons). This is the SHARED brain behind both views:
//   • renderTablePanel() — the old pop-up modal (kept for any caller that still uses it)
//   • the Tables-tab right side panel — the new master-detail (renders this IN PLACE)
// Pulling it out means the two views can never drift apart again.
// Returns the pieces + the computed { sess, os } so the caller can wire up.
//
// `host` says WHERE the result is about to be rendered — "float" (a table popup) or "modal"
// (the legacy pop-up). Both get the identical footer; the old third host, the docked side
// rail, went with the side panel (2026-07-31). Default "float" so a caller that forgets still
// gets the full footer rather than silently losing a button.
function tablePanelParts(t, host = "float") {
  const sessionsOn = !!(state.data.settings || {}).sessions_enabled;
  // A MERGED PARENT'S DETAIL SHOWS THE WHOLE PARTY (owner, 2026-08-01: "after being merge, the table
  // six detail view should also show the dish of the seven table also, because they are merged").
  // Each table's orders arrive in its OWN ?table= slice (they keep their own table number, which is
  // what makes an unmerge exact), so the parent's detail has to gather its children's slices too.
  // openFloatingTable fetches them; here they are simply concatenated, newest first.
  // ONE PARTY, ONE LIST OF ORDERS, WHICHEVER TABLE YOU OPENED (owner, 2026-08-01: "every table will
  // show every order"). Each table's orders arrive in its own ?table= slice — they keep their own
  // table number, which is what makes an unmerge exact — so the detail gathers the whole party.
  const partyHead = mergeParentOf(t) || t;                    // the table holding the bill
  const partyAll = [String(partyHead), ...mergeChildrenOf(partyHead)];
  const isParty = partyAll.length > 1;
  const kids = mergeChildrenOf(t);
  const os = isParty
    ? partyAll.flatMap((x) => ordersForTable(x))
        .sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0))
    : ordersForTable(t);
  // The child's own table has no session — the bill number, the guests and the status pill all
  // belong to the party, which lives on partyHead. (A solo table: partyHead === t.)
  const sess = openSessionForTable(partyHead) || openSessionForTable(t);
  // THE PARTY'S calls, like the orders line above (T3 sweep, 2026-08-10). A call keeps the table
  // number it was rung at, so a call from T7 was listed on neither popup once T7 joined T6: T7's
  // was emptied by the session guard and T6's filters by its own number. Same set as the orders,
  // same reason — these are the same guests on the same bill.
  const calls = partyCalls(t);

  // ── PENDING REQUESTS for THIS table (a guest tapped "open this table" / "join" /
  // asked for a waiter on their phone). These used to live ONLY in the floor's side
  // "Requests" card + the tile's 📨 badge — the table DETAIL (docked, floating popup
  // AND the legacy modal) never showed them, so staff opening a "Wants in" table saw
  // just "This table isn't open yet" with no way to accept the person (owner,
  // 2026-07-28). Built from the ALWAYS-fresh summary (not the per-table slice) so the
  // card shows even while the slice is still streaming in; an "open" request hides
  // once the table is actually open (same rule as reqsForTable). The buttons reuse
  // data-req-approve/deny → resolveRequest and are wired by bindTablePanel, which all
  // three detail hosts share.
  const tReqs = (state.summary.requests || []).filter((r) => String(r.table_number) === String(t) && !(r.type === "open" && (sess || summaryTableOpen(t))));
  const REQ_WORDS = { open: "is asking to open this table", join: "is asking to join this table", access: "asked for a waiter" };
  const reqOkLabel = (r) => (r.type === "open" ? "✓ Open for them" : r.type === "access" ? "✓ Attend" : "✓ Let them in");
  const requestsSec = tReqs.length ? `<div class="sx-sec tp-req-sec"><div class="sx-sec-h">📨 Someone's waiting <span class="sub">· ${tReqs.length}</span></div>${tReqs.map((r) =>
    `<div class="sx-req"><div class="sx-req-info"><b>${esc(r.name || r.phone || "A guest")}</b> ${esc(REQ_WORDS[r.type] || "sent a request")}<small>${esc(timeAgo(r.created_at))}</small></div><div class="sx-req-actions"><button class="btn small" data-req-deny="${esc(r.id)}" title="Dismiss this request">✕</button><button class="btn small primary" data-req-approve="${esc(r.id)}">${reqOkLabel(r)}</button></div></div>`
  ).join("")}</div>` : "";

  // ── INSTANT RENDER (stale-while-revalidate): before this table's full slice has loaded,
  // render the head + a light "loading details…" body from the ALWAYS-fresh summary tile
  // (guests/dishes/due/status — everything but the individual dish rows), so the popup
  // opens instantly with accurate numbers instead of a 1-2s blank "isn't open yet". The
  // dish rows + guest rows + action buttons stream in the moment the slice lands (~sub-
  // second) and the detail re-renders. Only kicks in for an OCCUPIED table whose slice
  // isn't in yet — a genuinely free table renders its real "Open this table" state.
  const sumTile = (state.summary.tiles || {})[String(t)] || {};
  const streaming = !sliceLoaded(t) && summaryTableOpen(t);

  // Both totals are net of any discounts staff have given. While streaming, the summary
  // tile's precomputed `due` stands in (it's server-computed net of discounts too).
  // Money is computed via billMath (per-bill, discount BEFORE tax, this restaurant's tax
  // rate) — the SAME helper the printed bill uses — so the pay screen, the receipt and
  // the Z-report always agree. (Was summing the STORED per-order total, which carried a
  // flat 5% on the pre-discount subtotal → the staff collected a different amount than
  // the bill said.) A table settles all-or-nothing, so `due` is the unpaid slice's total.
  // EXCLUDE 'received' (not-yet-accepted) orders from the due — a brand-new order isn't a
  // confirmed bill yet, so it doesn't count toward "Due". This matches the floor tile
  // (isUnpaidBill excludes received) AND the summary RPC (status NOT IN ('received','cancelled')).
  // Without this, the detail head showed a HIGHER due than the tile the moment a guest added a
  // new order staff hadn't accepted, and the streaming due (from the RPC) blipped up when the
  // slice landed. (owner 2026-07-06)
  const unpaidOs = os.filter((o) => o.status !== "cancelled" && o.status !== "received" && o.payment_status !== "paid");
  const mBill = billMath(os);
  const mDue = billMath(unpaidOs);
  const due = streaming ? (Number(sumTile.due) || 0) : mDue.total;
  const billTotal = streaming ? (Number(sumTile.due) || 0) : mBill.total;

  // ── HEAD: a status pill, a one-line summary (bill #, guests, dishes, due) and a
  // dish-status PROGRESS BAR (how much of this table is served vs cooking vs new).
  // Both detail views (in-panel + legacy modal) render these so they stay identical.
  // A merged child's own summary tile reads "free" (its party lives on the parent), so the
  // status pill comes from the table that HOLDS the party — same rule the floor tile follows.
  const tile = tableTileState(isParty ? partyHead : t);
  // VIP / Family / Owner's-guest mark (mig 166) shown right in the detail HEADER so a
  // marked table is unmistakable when opened — not only on the floor tile (owner
  // 2026-07-23: "the mark is not showing in that table thing"). tagForTable already
  // gates on the feature being on.
  const hdrTag = TABLE_TAG_INFO[tagForTable(t)];
  const headTagPill = hdrTag ? `<span class="tp-tagpill tag-${tagForTable(t)}">${hdrTag.emoji} ${esc(hdrTag.label)}</span>` : "";
  let headPill = `<span class="tp-pill tp-pill-${esc(tile.st)}">● ${esc(tile.label)}</span>${headTagPill}`;
  const liveRowsAll = os.filter((o) => o.status !== "cancelled").flatMap((o) => orderItemRows(o));
  // Count dishes by QUANTITY (a "2× Cappuccino" row is 2 dishes), matching both the summary
  // tile and the floor tile's "0/3 served" — so the head's numbers stay identical whether
  // they come from the summary (streaming) or the loaded rows, with no 3→2 blip when the
  // slice lands.
  const sc = sumTile.counts || { nw: 0, ck: 0, rd: 0, sv: 0 }; // summary per-status dish counts (already by qty)
  const qsum = (pred) => liveRowsAll.filter(pred).reduce((s, r) => s + Math.max(1, parseInt(r.qty, 10) || 1), 0);
  const cServed = streaming ? (sc.sv || 0) : qsum((r) => r.status === "served");
  const cCook = streaming ? ((sc.ck || 0) + (sc.rd || 0)) : qsum((r) => r.status === "preparing" || r.status === "ready");
  const cRecv = streaming ? (sc.nw || 0) : qsum((r) => r.status === "received");
  const dishN = streaming ? (cServed + cCook + cRecv) : qsum(() => true);
  const nItems = dishN || 1;
  const guestsN = streaming ? (Number(sumTile.members) || 0) : (sess ? membersOf(sess.id).length : 0);
  const subLine = `<div class="tp-det-sub">${sess && sess.bill_no != null ? `<span>Bill <b>#${esc(sess.bill_no)}</b></span>` : ""}<span><b>${guestsN}</b> guest${guestsN === 1 ? "" : "s"}</span><span><b>${dishN}</b> dish${dishN === 1 ? "" : "es"}</span>${due > 0 ? `<span>Due <b>${inr(due)}</b></span>` : billTotal > 0 ? `<span>Total <b>${inr(billTotal)}</b></span>` : ""}</div>`;
  const progress = dishN ? `<div class="tp-prog"><div class="tp-prog-bar"><span class="pp-served" style="width:${(cServed / nItems) * 100}%"></span><span class="pp-cook" style="width:${(cCook / nItems) * 100}%"></span><span class="pp-recv" style="width:${(cRecv / nItems) * 100}%"></span></div><div class="tp-prog-leg"><span><i class="pl-served"></i>${cServed} served</span><span><i class="pl-cook"></i>${cCook} preparing</span><span><i class="pl-recv"></i>${cRecv} new</span></div></div>` : "";
  let headMeta = subLine + progress;

  // STREAMING: head is accurate from summary; the actionable body (guest rows, dish rows,
  // bill breakdown, action buttons) needs the slice, so show a light shimmer line for each
  // until it lands. Return here so the heavy per-order builders below never run on empty data.
  if (streaming) {
    const loadRow = `<div class="sx-loading"><span class="sx-load-dot"></span> Loading details…</div>`;
    const sessionSec = sessionsOn ? `<div class="sx-sec"><div class="sx-sec-h">Guests <span class="sub">· ${guestsN}</span></div>${loadRow}</div>` : "";
    const ordersSec = `<div class="sx-sec"><div class="sx-sec-h">Orders <span class="sub">· ${dishN}</span></div>${loadRow}</div>`;
    return { sess: null, os: [], headPill, headMeta, requestsSec, sessionSec, ordersSec, callsSec: "", billSec: "", foot: "" };
  }

  let sessionSec = "";
  if (sessionsOn) {
    if (sess) {
      const mem = membersOf(sess.id);
      const memRows = mem.length ? mem.map((m) => {
        const owner = m.role === "owner";
        const status = m.approved ? `<span class="sx-ok">approved</span>` : `<span class="sx-wait">waiting</span>`;
        // Kick (remove now) and Ban (kick + blocklist) are available for EVERYONE,
        // including the head — staff have full control from the table view.
        let acts = "";
        if (!m.approved) acts += `<button class="btn small primary" data-mem-approve="${esc(m.id)}">Approve</button><button class="btn small" data-mem-deny="${esc(m.id)}">Deny</button>`;
        else acts += `<button class="btn small" data-mem-kick="${esc(m.id)}">Kick</button>`;
        // Any guest who isn't the head can be handed the table (owner's "transfer"):
        // they become head + approved; the old head is kicked by the server.
        if (!owner) acts += `<button class="btn small" data-mem-head="${esc(m.id)}" title="Make them the table's head — the current head is kicked">Transfer</button>`;
        acts += `<button class="btn small danger" data-mem-ban="${esc(m.id)}" data-ban-phone="${esc(m.phone || "")}">Ban</button>`;
        return `<div class="sx-mem"><div class="sx-mem-info">${owner ? "👑 " : "🤝 "}<b>${esc(m.name || (owner ? "Head" : "Guest"))}</b> ${status}${m.phone_verified ? ` <span class="sx-ok">✓</span>` : ""}</div><div class="sx-mem-acts">${acts}</div></div>`;
      }).join("") : `<div class="sx-empty">No one has joined yet.</div>`;
      sessionSec = `<div class="sx-sec"><div class="sx-sec-h">Guests <span class="sub">· ${mem.length}</span><label class="sx-auto"><input type="checkbox" id="sxAuto" ${sess.auto_approve ? "checked" : ""}> auto-approve</label></div>${memRows}</div>`;
    } else {
      // No party here yet. There is nothing to DO about that any more (no "Open this
      // table" step) — taking an order starts the party — so this just states the fact.
      sessionSec = `<div class="sx-sec"><div class="sx-sec-h">Guests</div><div class="sx-empty">Nobody here yet — taking an order seats them.</div></div>`;
    }
  }

  // IS EVERY DISH OUT? One predicate, used by the Edit toggle, the invoice button and nothing else
  // guessing at it separately. A cancelled ticket doesn't hold the table back; a ticket still at
  // 'received' hasn't even been accepted, so it is certainly not served.
  const allOut = os.length > 0 && os.every((o) => o.status === "cancelled"
    || (o.status !== "received" && orderItemRows(o).every((r) => r.status === "served")));
  let ordersSec;
  if (!os.length) {
    ordersSec = `<div class="sx-sec"><div class="sx-sec-h">Orders</div><div class="sx-empty">No orders yet.</div></div>`;
  } else {
    // Un-accepted (new) orders stay SEPARATE so each can be accepted — separation
    // only while accepting. Once accepted, every dish MERGES into one combined list
    // with a SINGLE bill; no per-order split, no per-order total/pay (owner, 2026-06-14).
    // The separate order rows still live in the DB as the log of which came first.
    const newOrders = os.filter((o) => o.status === "received");
    const liveOrders = os.filter((o) => o.status !== "received" && o.status !== "cancelled");
    // The order's items (from order_items, same source the tablet uses) WITH the
    // order-wide allergens distributed onto each item's "removed" — so every dish
    // shows "no dairy", identical to the tablet. This is what made the two detail
    // views disagree before (the popup showed only each item's own removals).
    const withAllergens = (o) => { const a = Array.isArray(o.allergies) ? o.allergies : []; return orderItemRows(o).map((r) => ({ ...r, removed: [...new Set([...(Array.isArray(r.removed) ? r.removed : []), ...a])] })); };
    const when = (o) => o.created_at ? new Date(o.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : "";
    const editing = editTables.has(String(t)); // staff EDIT mode for this table?
    // While editing, each KOT card gets allergen toggle chips ("avoid in all dishes")
    // + an "＋ Add dish" button. Allergy/add are PER-ORDER (per KOT). (owner, 2026-06-17)
    const orderEditExtras = (o) => {
      if (!editing) return "";
      const aSet = new Set((Array.isArray(o.allergies) ? o.allergies : []).map((x) => String(x).toLowerCase()));
      const chips = ALLERGENS.map((a) => `<span class="chip oae-chip ${aSet.has(a.slug) ? "on" : ""}" data-alg="${esc(o.id)}" data-slug="${a.slug}">${esc(a.label)}</span>`).join("")
        // Typed allergies (from ＋ Other) sit alongside the standard six and come off the same way.
        + [...aSet].filter((s) => !ALG_STD.includes(s)).map((s) => `<span class="chip oae-chip on" data-alg="${esc(o.id)}" data-slug="${esc(s)}">${esc(algLabel(s))}</span>`).join("")
        + `<span class="chip oae-chip alg-other" data-alg="${esc(o.id)}" data-alg-other="1" title="Type an allergy that isn't listed">＋ Other</span>`;
      return `<div class="tp-edit-extras"><div class="tp-edit-alg"><span class="muted small">⚠ Avoid (all dishes):</span>${chips}</div><button class="btn small" data-add-dish-order="${esc(o.id)}">＋ Add dish</button></div>`;
    };
    // Each un-accepted (NEW) order is its own highlighted card with its own Accept —
    // dishes share the same row layout as the rest (via itemRowHtml).
    // ✕ Cancel — void this whole ticket. THE walk-out escape hatch (owner, 2026-07-31): with
    // "close table" gone, this is how a table whose guests left without paying gets cleared,
    // and it's the honest way round — the void stays on the record with who did it, instead of
    // an unpaid bill vanishing behind a closed table. Cancelling the table's LAST live order
    // frees the table by itself (see cancelOrder). Gated by void_bills, whose own description
    // is "…or closing a table unpaid after a walk-out"; the server re-checks it.
    //
    // NOT ONCE THE FOOD IS OUT (owner, 2026-08-01: "after the order is served, why the option to
    // cancel?"). A served dish was eaten — voiding it says the sale never happened, which is both
    // untrue and the shape of thing this app must never make easy. So Cancel disappears as soon as
    // anything on the ticket has been served; from then on a correction goes through mark-unpaid or
    // a credit note, which keep the sale on the books. A part-served ticket counts as served: the
    // guest has eaten something.
    const anyServed = (o) => orderItemRows(o).some((r) => r.status === "served") || o.status === "served";
    // ── AND NOT ONCE THE INVOICE IS PRINTED (owner, 2026-08-26) ────────────────────────────────
    // "whenever the invoice has been printed — like you have clicked the print button — after
    // [that] you won't be able to delete the thing." A printed tax invoice is a document the guest
    // is holding; taking a KOT off the bill behind it would leave the paper and the record
    // disagreeing, and the number carrying a total that exists nowhere. The way out is REOPEN
    // (which retires the number and records why) or, once settled, a credit note — both keep the
    // sale on the books. The server refuses it as well (invoiceLockedByOrder in the editor route);
    // this only stops offering a button that would be refused, because hiding is never the guard.
    // A VOIDED invoice does not lock: that bill was reopened on purpose.
    const invoiceLive = !!(sess && sess.invoice_no != null && !sess.invoice_voided);
    const cancelBtn = (o) => ((anyServed(o) || invoiceLive) ? "" : `<button class="btn small danger tp-cancel-order" data-cancel-order="${esc(o.id)}" title="Void this KOT — nothing is charged for it">✕ Cancel</button>`);
    const newBlocks = newOrders.map((o) => {
      const rows = withAllergens(o).map((r) => itemRowHtml(r, editing)).join("");
      return `<div class="tp-order tp-order-new"><div class="tp-order-head"><span class="kot-chip">${o.kot_no != null ? "KOT #" + esc(o.kot_no) : "New order"}</span>${when(o) ? `<span class="tp-when">${when(o)}</span>` : ""}<span class="tp-newtag">new</span></div>${rows}${orderEditExtras(o)}<div class="tp-order-foot">${cancelBtn(o)}<button class="btn small primary tp-accept" data-accept="${esc(o.id)}">✓ Accept order</button></div></div>`;
    }).join("");
    // ACCEPTED orders are GROUPED into per-KOT cards (so you can see which ticket each
    // dish came from) but they still settle as ONE bill — no per-order total/pay/discount
    // (owner, 2026-06-14: one merged bill). Per-dish serve/delete live on each row.
    const mergedBlock = liveOrders.map((o) => {
      const rows = withAllergens(o).map((r) => itemRowHtml(r, editing)).join("");
      // An already-PAID ticket is not cancellable (the server refuses it too — a refund goes
      // through mark-unpaid or a credit note), so it shows no Cancel.
      const cb = o.payment_status === "paid" ? "" : cancelBtn(o);
      let foot = cb ? `<div class="tp-order-foot">${cb}</div>` : "";
      return `<div class="tp-order"><div class="tp-order-head"><span class="kot-chip">${o.kot_no != null ? "KOT #" + esc(o.kot_no) : "Order"}</span>${when(o) ? `<span class="tp-when">${when(o)}</span>` : ""}</div>${rows}${orderEditExtras(o)}${foot}</div>`;
    }).join("");
    const mergedBadge = liveOrders.length > 1 ? `<span class="sx-badge2">${liveOrders.length} merged · one bill</span>` : "";
    // Edit/Done toggle: the gated entry to staff editing. The confirm fires on Edit.
    // NOT ONCE THE FOOD IS OUT (owner, 2026-08-01: "after being served, why still an edit
    // option?"). Editing exists for a ticket being built or cooked — changing a quantity or
    // adding a dish to a meal the guest has already eaten rewrites what happened. Allergen info
    // is NOT lost with it: each dish keeps its own ✎ inside the bill (Bills → a bill), which is
    // deliberately allowed at any status (owner, 2026-07-03 — "allergy can be added to all items").
    const editToggle = allOut ? "" : (editing
      ? `<button class="btn small primary tp-edit-toggle" data-done-table="${esc(t)}">✓ Done editing</button>`
      : `<button class="btn small tp-edit-toggle" data-edit-table="${esc(t)}">✎ Edit</button>`);
    // THE HEADING COUNTS WHAT IS ON THE SCREEN (T5 sweep, 2026-08-17). It counted `os`, which
    // includes CANCELLED tickets — and a cancelled ticket is deliberately drawn nowhere in this
    // detail (its record lives in Bills and in Audit). Measured on the backup floor: table 1 held
    // six voided tickets and the section read "Orders · 6" over an empty box, which reads as a
    // screen that failed to load rather than a table with nothing on it. So the number is the
    // number of tickets listed, and when there are none the voided ones are named in a sentence
    // instead of being counted in silence.
    const shownN = newOrders.length + liveOrders.length;
    const voidedN = os.length - shownN;
    // REJECTED (owner, 2026-08-17) — docs/REJECTED-IDEAS.md R33: this sentence is where it STOPS.
    // Offered a next step for a table in this state — a line saying what to do, or a ⏻ that ends an
    // empty party — he said "we will not do any of that stuff". State the truth and leave it: the
    // bill is in the record, the table is usable, and no table ends itself (mig 254).
    const voidNote = shownN === 0 && voidedN > 0
      ? `<div class="sx-empty">Nothing on this table — ${voidedN} cancelled ticket${voidedN === 1 ? "" : "s"}, kept in Bills.</div>`
      : "";
    ordersSec = `<div class="sx-sec"><div class="sx-sec-h">Orders <span class="sub">· ${shownN}</span>${mergedBadge}${editToggle}</div>${newBlocks}${mergedBlock}${voidNote}</div>`;
  }

  // Each active call (water, napkins, clean…) gets its own "Done" button so staff
  // can clear them one at a time; if there are several, an "Attend all" clears them together.
  const callsSec = calls.length ? `<div class="sx-sec"><div class="sx-sec-h">Calls <span class="sub">· ${calls.length}</span></div>${calls.map((c) => `<div class="sx-call">${callEmoji(c.note)} ${esc(c.note || "Waiter call")} <button class="btn small primary" data-call-attend="${esc(c.id)}">Done</button></div>`).join("")}${calls.length > 1 ? `<button class="btn small" data-attend-all="${esc(t)}">✓ Attend all (${calls.length})</button>` : ""}</div>` : "";
  // When several orders are still unpaid, offer a single "Mark all paid" so staff
  // settle the whole table at once instead of paying each order separately.
  // Payment + discount now live on the single MERGED bill (per-order pay/disc were
  // removed when the orders merged). Mark-paid settles the whole table at once.
  const anyUnpaidBill = os.some((o) => o.status !== "cancelled" && o.payment_status !== "paid");
  const payAllBtn = anyUnpaidBill ? `<button class="btn primary" id="sxPayAll">💳 Mark ${os.length > 1 ? "all " : ""}paid</button>` : "";
  // The bill discount writes to the first non-cancelled order's record; the bill
  // total already nets every order's discount, so it shows correctly on the merged bill.
  const discTarget = os.find((o) => o.status !== "cancelled");
  // NOT ON AN ISSUED BILL (owner, 2026-08-01: "once the invoice is generated, why the option for
  // discount? Only when you reopen the invoice you can add a discount"). An invoice is a numbered
  // document with a total on it — changing the money behind it while it stands is exactly what a
  // billing app must not make easy. Reopen (which voids the invoice, with a reason, on the record)
  // brings the button back. `invoicedNow` is computed below the same way Print/Reopen use it.
  const _inv = !!sess && sess.invoice_no != null && !sess.invoice_voided;
  const discBtn = discTarget && !_inv ? `<button class="btn" data-disc="${esc(discTarget.id)}" data-disc-cur="${esc(Number(discTarget.discount) || 0)}" data-disc-max="${esc(discTarget.total)}" title="Give a discount on the bill">− Discount</button>` : "";
  // Split-bill helper: tells staff each guest's even share of the bill total. Doesn't change the bill
  // or payment — the manager still marks the whole bill paid once collected.
  // Split among guests = what's still DUE (exclude any order already paid), not the
  // whole historical total — matches the KOT-on split-settle path.
  const splitDue = billMath(os.filter((o) => o.status !== "cancelled" && o.payment_status !== "paid")).total || mBill.total;
  // A CANCELLED TICKET IS NOT A BILL (T5 sweep, 2026-08-17). Every money control below asked
  // `os.length`, which counts voided tickets too — so a table whose every ticket had been
  // cancelled still offered 🍴 Split and 🖨 Print bill over a ₹0 total. Split is merely useless
  // there; Print is not: it issues the tax invoice first, so it would draw the next number off
  // the restaurant's series for a sale that never happened. That is the exact thing the BILL
  // MODAL was fixed to stop on 2026-08-16 and that migration 331 refuses server-side — this
  // screen was simply never given the same test, so the tap was offered and then refused.
  const billableOs = os.filter((o) => o.status !== "cancelled");
  const splitBtn = billableOs.length && splitBillOn() ? `<button class="btn" data-split="${esc(splitDue)}" title="Split the bill evenly between guests">🍴 Split</button>` : "";
  // Invoice-first billing (owner 2026-07-24): NO direct Print on a running tab — show
  // "Generate invoice" first; Print (+ Reopen) appears only once an invoice exists. A
  // settled bill is always invoiced (markTablePaid auto-generates it), so it shows Print.
  const invoicedNow = !!sess && sess.invoice_no != null && !sess.invoice_voided;
  // BILLABLE WHILE THE KITCHEN IS STILL WORKING (owner, 2026-08-01: "we can print when [the]
  // order [is] being cook, and print means generate invoice and print, and generate invoice is
  // just generate invoice"). This REPLACES his 2026-07-31 rule ("why generate invoice when an item
  // is still cooking — remove that"): he changed his mind after using it, and the two buttons now
  // mean exactly what he said —
  //   🖨 Print          → issues the invoice if there isn't one, then prints it (one tap, one job)
  //   🧾 Generate invoice → issues the invoice and nothing else
  // Both are offered on any table that has orders, cooking or not. The compliance rules are
  // untouched: an issued invoice still locks the bill (no discount until ↩ Reopen voids it, which
  // is recorded), and nothing here can erase a sale.
  const printBtn = !billableOs.length ? "" : (invoicedNow
    ? `<button class="btn" id="sxPrint">${billPrintLabel(sess, os)}</button><button class="btn" id="sxReopen" title="Void the invoice to change the bill again">↩ Reopen</button>`
    // ONE button (owner, 2026-08-05: "print means generate invoice and print ... once the bill is
    // printed, the invoice has been generated"). Print already issues-then-prints; a second
    // button that ONLY issues was the thing making people ask which one comes first, and it
    // could leave a numbered invoice with no paper. Nothing about compliance changes — the
    // invoice is still issued before anything prints, and it still locks the bill.
    : `<button class="btn primary" id="sxPrint" title="Issues the tax invoice, then prints the bill">${billPrintLabel(sess, os, "bill")}</button>`);
  // The bill now shows a full BREAKDOWN (subtotal · discount · GST · total) summed
  // across the table's non-cancelled orders, not just a one-line "Due/Total".
  // Breakdown from billMath (same rate + discount-before-tax rule as the printed bill),
  // NOT the stored per-order subtotal/tax columns (tax there is a flat 5%, pre-discount).
  // MRP lines (mig 270) split this stack in two: the first row shows only the TAXABLE part
  // and renames to "Food subtotal", and an "MRP items" row lands after tax and before the
  // grand total — so the column adds up on screen the same way it adds up on the paper. A
  // composition-scheme restaurant shows no tax row at all (it may not charge the diner GST).
  const sumNontax = mrpPart(mBill);
  const sumSub = sumNontax > 0 ? mBill.taxableBase : mBill.subtotal;
  const sumTax = mBill.tax;
  const sumDisc = mBill.disc;
  const billSec = os.length ? `<div class="sx-sec"><div class="sx-sec-h">Bill${sess && sess.bill_no != null ? ` <span class="sub">· bill #${esc(sess.bill_no)}</span>` : ""}</div><div class="tp-bill">${sumSub > 0 ? `<div class="tp-bl"><span>${sumNontax > 0 ? "Food subtotal" : "Subtotal"}</span><b>${inr(sumSub)}</b></div>` : ""}${sumDisc > 0 ? `<div class="tp-bl disc"><span>Discount${discPct(sumSub, sumDisc) ? ` (${discPct(sumSub, sumDisc)})` : ""}</span><b>− ${inr(sumDisc)}</b></div>` : ""}${sumTax > 0 && !mBill.composition ? `<div class="tp-bl"><span>${esc(taxLabel())}</span><b>${inr(sumTax)}</b></div>` : ""}${sumNontax > 0 ? `<div class="tp-bl"><span>MRP items</span><b>${inr(sumNontax)}</b></div>` : ""}<div class="tp-bl grand"><span>${due > 0 ? "Total due" : "Total"}</span><span class="tp-bl-amt">${inr(due > 0 ? due : billTotal)}</span></div></div></div>` : "";

  // The PRIMARY table-wide action: accept everything that's new, else serve everything
  // that's cooked. (Per-order Accept stays on each new card; per-dish Serve on each row.)
  // Count orders with un-accepted (received) DISHES — item-level, so it matches the
  // floor tile's "New order" cue and the accept action (acceptTableOrders). Was
  // order-level (o.status==="received"), which hid "Accept all" for a preparing order
  // that still had a freshly-added received dish. (2026-06-26)
  const newOrdersN = os.filter((o) => o.status !== "cancelled" && orderItemRows(o).some((r) => r.status === "received")).length;
  const anyUnservedAccepted = os.some((o) => o.status !== "cancelled" && o.status !== "received" && orderItemRows(o).some((r) => r.status !== "served"));
  let primaryBtn = "";
  if (newOrdersN) primaryBtn = `<button class="btn primary tp-accept-all" data-accept-all="${esc(t)}">✓ Accept all &amp; prepare${newOrdersN > 1 ? ` (${newOrdersN})` : ""}</button>`;
  else if (anyUnservedAccepted) primaryBtn = `<button class="btn green tp-serve-all-orders" data-serve-all-orders="${esc(t)}">🍽️ Serve all</button>`;
  // ✕ CLOSE TABLE IS BACK, AND IT IS GATED (owner, 2026-08-02: "close table in the detail view
  // also should only show when all mark is paid and all the serve has been completed").
  // It was removed on 2026-07-31 because auto-settle freed a paid table by itself; auto-settle
  // is gone (a party that has paid is usually still sitting there), so the table now waits for a
  // person. The gate is the SAME two halves the floor tile uses, in either order — every dish
  // served AND the whole bill paid — so the button simply is not there while either is open, and
  // the server can never refuse the tap. Guests who left without paying are still handled by
  // cancelling the ticket, which records the void instead of hiding an unpaid bill.
  const liveOsEnd = os.filter((o) => o.status !== "cancelled");
  const allServedEnd = liveOsEnd.length > 0 && liveOsEnd.every((o) => orderItemRows(o).every((r) => r.status === "served"));
  const tableFinished = !!sess && allServedEnd && !anyUnpaidBill;
  const endBtn = tableFinished ? `<button class="btn primary" id="sxClose" title="Everything served and the bill is paid — close this table and free it">✓ Close table</button>` : "";
  // ONE sticky action bar holds every table-wide action: the primary action + pay +
  // discount on the LEFT, then table-management (shift/print/restart/close) on the RIGHT.
  // (No 🏷 Type builder here any more — the one place to mark a table is the KOT ▾ menu, which
  // reaches it for a free table too. Two doors to one action is how people learn neither.)
  // KOT ▾ (Table & KOT operations) lives in the detail HEADER, not this crowded bar
  // (owner, 2026-07-22 — "keep the kot option at the top"): tablePanelParts returns it
  // as kotHeadBtn and BOTH detail headers (docked + floating) render it next to Float.
  // While the menu is on, the footer DROPS its duplicates: 🍴 Split (lives inside KOT)
  // and ⇄ Change table (the KOT menu owns the same action). Ladder off → both render as before.
  const kotOn = tableOpsOn() && !!sess;
  const kotHeadBtn = kotOn
    ? `<button class="tp-detail-float tp-kot-head" id="sxKot" title="Table &amp; KOT operations — change table, merge, move a KOT or dish, split, reprint">🧾 KOT ▾</button>`
    : "";
  const shiftFallbackBtn = !kotOn && sess ? `<button class="btn" id="sxShift" title="Move this party to another table">⇄ Change table</button>` : "";
  // ＋ Take order — start a brand-new order for this table, like the waiter tablet.
  // Gated by the take_orders manager power: XRAY_CONTROLS hides it for a manager without
  // the power (and tints it for an admin/owner looking in); the server re-checks too.
  //
  // It used to be hidden in one of the two hosts (the narrow docked rail, where the order
  // builder was cramped). There is only the popup now, and the floor tile itself, so the
  // host test is gone.
  const takeOrderBtn = `<button class="btn primary tp-take-order" data-take-order="${esc(t)}">＋ Take order</button>`;
  // WHAT THE FOOTER HOLDS, and what it deliberately doesn't (owner, 2026-08-01):
  //   · no 🏷 Type — it is in the KOT ▾ menu, and having it twice teaches nobody where it lives;
  //   · no ↻ Restart — it belonged to the open/close family that was removed. A finished table
  //     clears itself, and a table to be emptied by hand is dealt with by cancelling the ticket.
  // `let`, because a merged party appends its Unmerge row to this footer below.
  let foot = `${takeOrderBtn}${primaryBtn}${payAllBtn}${discBtn}${kotOn ? "" : splitBtn}<span class="tp-foot-spacer"></span>${shiftFallbackBtn}${printBtn}${endBtn}`;

  // A MERGED CHILD'S DETAIL (mig 249). Its orders and bill live on the parent, so showing the usual
  // empty sections would say "nothing here" about a table that is very much in use. Instead the
  // whole detail is the message plus the two things you can do: jump to the table that holds the
  // bill, or split them apart (owner: "you can only unmerge by clicking on the seven number table").
  // THE PARTY IS NAMED IN THE TITLE AND UNMERGED FROM THE BOTTOM (owner, 2026-08-01: "we don't want
  // this interface … where the table name is, we will write six plus seven plus eight … and at the
  // very bottom there will be a button to unmerge, and for that particular table it will unmerge that
  // particular table from it"). The per-table rows card is gone: the orders list above already shows
  // the whole party, so listing each table again was the same information twice.
  if (isParty) {
    headPill = `<span class="sx-party-title">${partyAll.map((x) => "T" + esc(x)).join(" + ")}</span>`;
    // …and WHO joined them (owner, 2026-08-14 — improvement 2). This head line is the phone's copy
    // of the tile tooltip: a phone has no hover, so without it the answer would exist only on a
    // desktop. Absent (silently) on a merge made before mig 308 started recording the actor.
    const credit = mergeCredit(t);
    headMeta = `one party · one bill${sess && sess.bill_no != null ? ` · bill #${esc(sess.bill_no)}` : ""}${credit ? ` · ${esc(credit)}` : ""}`;
    // ONE button, for the table whose screen this is. Opening T7 offers "Unmerge T7"; opening the
    // table that holds the bill offers to release each of the others, one button each, because there
    // is nothing to detach IT from.
    const unmergeBtns = mergeParentOf(t)
      ? `<button class="btn danger sx-unmerge" data-unmerge="${esc(t)}">⇹ Unmerge T${esc(t)}</button>`
      : mergeChildrenOf(t).map((k) => `<button class="btn danger sx-unmerge" data-unmerge="${esc(k)}">⇹ Unmerge T${esc(k)}</button>`).join("");
    foot = `${foot}<div class="sx-unmerge-row">${unmergeBtns}</div>`;
  }
  return { sess, os, headPill, headMeta, kotHeadBtn, requestsSec, sessionSec, ordersSec, callsSec, billSec, foot };
}

// Ask the manager for a price at order time — used for "open price" dishes (as-per-MRP /
// market-price items like a soft-drink can or mineral water, which carry NO price in the
// menu). Resolves a positive number (rupees), or null if cancelled. Mirrors the waiter
// tablet's pricePrompt; the server re-validates + clamps, this is only the entry. (2026-07-29)
const pricePrompt = (title, current) => new Promise((resolve) => {
  const ov = document.createElement("div");
  Object.assign(ov.style, { position: "fixed", inset: "0", background: "rgba(4,8,18,.66)", backdropFilter: "blur(3px)", zIndex: "100000", display: "flex", alignItems: "center", justifyContent: "center", padding: "16px" });
  const box = document.createElement("div");
  Object.assign(box.style, { width: "min(92vw,340px)", background: "var(--panel)", color: "var(--text)", borderRadius: "16px", padding: "20px", boxShadow: "0 20px 60px rgba(0,0,0,.5)", fontFamily: "system-ui,sans-serif" });
  box.innerHTML = `
    <div style="font-size:16px;font-weight:800;margin:0 0 6px">💰 Enter price</div>
    <div style="font-size:13px;color:var(--muted);margin:0 0 12px">Price for <b>${esc(title || "this item")}</b> (per item)</div>
    <div style="display:flex;align-items:center;gap:8px">
      <span style="font-size:20px;font-weight:800;color:var(--muted)">₹</span>
      <input class="pr-in" type="text" inputmode="decimal" maxlength="8" placeholder="0" autocomplete="off"
        value="${current != null && current > 0 ? esc(String(current)) : ""}"
        style="flex:1;min-width:0;box-sizing:border-box;padding:12px;border-radius:10px;border:1px solid var(--line);background:var(--bg,#141009);color:var(--text);font-size:20px;font-weight:800;outline:none" />
    </div>
    <div class="pr-err" style="font-size:12px;color:#fca5a5;min-height:16px;margin:6px 2px 0"></div>
    <div style="display:flex;gap:10px;margin-top:12px">
      <button class="pr-cancel" style="flex:1;padding:11px;border:0;border-radius:10px;font-weight:700;background:var(--panel-2);color:var(--text);cursor:pointer">Cancel</button>
      <button class="pr-ok" style="flex:1;padding:11px;border:0;border-radius:10px;font-weight:700;background:var(--gold);color:#14110d;cursor:pointer">Add</button>
    </div>`;
  ov.appendChild(box);
  document.body.appendChild(ov);
  const input = box.querySelector(".pr-in");
  const errEl = box.querySelector(".pr-err");
  setTimeout(() => { input.focus(); input.select(); }, 50);
  let backOff = window.LFH_BACK ? LFH_BACK.layer("editor-price", () => done(null)) : null;
  const done = (val) => { if (backOff) { backOff(); backOff = null; } ov.remove(); resolve(val); };
  // Keep only digits + one dot as the manager types.
  input.oninput = () => { input.value = input.value.replace(/[^0-9.]/g, "").replace(/(\..*)\./g, "$1"); };
  box.querySelector(".pr-cancel").onclick = () => done(null);
  box.querySelector(".pr-ok").onclick = () => {
    const v = Number(input.value);
    if (!v || v <= 0) { errEl.textContent = "Enter a price greater than 0."; return; }
    if (v > 100000) { errEl.textContent = "That price looks too high."; return; }
    done(Math.round(v * 100) / 100);
  };
  input.onkeydown = (e) => { if (e.key === "Enter") box.querySelector(".pr-ok").click(); else if (e.key === "Escape") done(null); };
  ov.onclick = (e) => { if (e.target === ov) done(null); };
});

// What the ＋ Other chip opens: type an allergy the six standard chips don't cover.
// Resolves the normalised word, or null if cancelled. Deliberately a small dialog and
// NOT a box sitting under the chips — the per-dish chip row redraws itself on every
// tap, which would wipe half-typed text (the same class of silent tap-loss the tap
// guard exists for). Mirrors pricePrompt so it looks and behaves like the panel's
// other one-field asks. `already` is the set this row has, so a repeat is caught.
const allergyPrompt = (already) => new Promise((resolve) => {
  const ov = document.createElement("div");
  Object.assign(ov.style, { position: "fixed", inset: "0", background: "rgba(4,8,18,.66)", backdropFilter: "blur(3px)", zIndex: "100000", display: "flex", alignItems: "center", justifyContent: "center", padding: "16px" });
  const box = document.createElement("div");
  Object.assign(box.style, { width: "min(92vw,360px)", background: "var(--panel)", color: "var(--text)", borderRadius: "16px", padding: "20px", boxShadow: "0 20px 60px rgba(0,0,0,.5)", fontFamily: "system-ui,sans-serif" });
  box.innerHTML = `
    <div style="font-size:16px;font-weight:800;margin:0 0 6px">⚠ Add an allergy</div>
    <div style="font-size:13px;color:var(--muted);margin:0 0 12px">Anything the kitchen must leave out — it prints on the ticket, not the bill.</div>
    <input class="alg-in" type="text" maxlength="24" placeholder="e.g. coriander" autocomplete="off" autocapitalize="none"
      style="width:100%;box-sizing:border-box;padding:12px;border-radius:10px;border:1px solid var(--line);background:var(--bg,#141009);color:var(--text);font-size:17px;font-weight:700;outline:none" />
    <div class="alg-err" style="font-size:12px;color:#fca5a5;min-height:16px;margin:6px 2px 0"></div>
    <div style="display:flex;gap:10px;margin-top:12px">
      <button class="alg-cancel" style="flex:1;padding:11px;border:0;border-radius:10px;font-weight:700;background:var(--panel-2);color:var(--text);cursor:pointer">Cancel</button>
      <button class="alg-ok" style="flex:1;padding:11px;border:0;border-radius:10px;font-weight:700;background:var(--gold);color:#14110d;cursor:pointer">Add</button>
    </div>`;
  ov.appendChild(box);
  document.body.appendChild(ov);
  const input = box.querySelector(".alg-in");
  const errEl = box.querySelector(".alg-err");
  setTimeout(() => { input.focus(); input.select(); }, 50);
  let backOff = window.LFH_BACK ? LFH_BACK.layer("editor-allergy", () => done(null)) : null;
  const done = (val) => { if (backOff) { backOff(); backOff = null; } ov.remove(); resolve(val); };
  box.querySelector(".alg-cancel").onclick = () => done(null);
  box.querySelector(".alg-ok").onclick = () => {
    const v = normAlg(input.value);
    // Every refusal SAYS why — an Add that just does nothing reads as a broken button.
    if (!v) { errEl.textContent = "Type what the kitchen should leave out."; return; }
    if (already && already.has(v)) { errEl.textContent = `“${v}” is already on this list.`; return; }
    done(v);
  };
  input.oninput = () => { errEl.textContent = ""; };
  input.onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); box.querySelector(".alg-ok").click(); } else if (e.key === "Escape") done(null); };
  ov.onclick = (e) => { if (e.target === ov) done(null); };
});

// Compact dish-picker modal for ADDING a dish to an already-placed order (staff
// edit). Lists the live menu with a search; tapping a dish adds it (qty 1) and the
// bill re-prices itself server-side. Stays open so several can be added. (2026-06-17)
function openAddDishModal(orderId, rerender) {
  document.querySelector(".add-dish-overlay")?.remove();
  const dishes = (state.data.items || []).filter((d) => !(d.tags || []).includes("sold-out"));
  const rowsFor = (q) => {
    const ql = (q || "").trim().toLowerCase();
    const list = dishes.filter((d) => !ql || (d.title || "").toLowerCase().includes(ql));
    return list.length
      // An open-price dish has no menu price — say "Set price" instead of a misleading ₹0.
      ? list.map((d) => `<button class="add-dish-row" data-add="${esc(d.id)}"><span>${esc(d.title)}</span><span class="muted">${d.open_price ? "Set price" : inr(parseFloat(d.price) || 0)}</span></button>`).join("")
      : `<div class="muted" style="padding:14px">No dishes match.</div>`;
  };
  const wrap = el(`<div class="sx-modal-overlay add-dish-overlay"><div class="sx-modal add-dish-modal"><div class="tbl-modal-head"><div class="tp-detail-top"><h3>Add a dish</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div><input type="search" class="add-dish-search" placeholder="🔎 Search dishes…"><div class="add-dish-list">${rowsFor("")}</div></div></div>`);
  document.body.appendChild(wrap);
  const listEl = wrap.querySelector(".add-dish-list");
  const bind = () => listEl.querySelectorAll("[data-add]").forEach((b) => (b.onclick = async () => {
    try {
      // Open-price dish (as-per-MRP): ask for the price first — the server refuses a ₹0 line.
      const d = dishes.find((x) => String(x.id) === b.dataset.add);
      let price;
      if (d && d.open_price) { price = await pricePrompt(d.title); if (price == null) return; }
      const r = await api("POST", `/orders/${orderId}/add-item`, { dishId: b.dataset.add, qty: 1, ...(price != null ? { price } : {}) });
      if (r && r.ok === false) { toast("Couldn't add: " + (r.reason || "rejected"), "err"); return; }
      okToast(r, "Dish added — bill updated");
      await loadSessions(); if (rerender) rerender();
    } catch (e) { toast("Failed: " + e.message, "err"); }
  }));
  bind();
  const search = wrap.querySelector(".add-dish-search");
  search.oninput = () => { listEl.innerHTML = rowsFor(search.value); bind(); };
  wrap.querySelector(".tbl-modal-close").onclick = () => wrap.remove();
  wrap.onclick = (e) => { if (e.target === wrap) wrap.remove(); };
  search.focus();
}

// ── THE BILL POPUP — finish a table in ONE place (owner, 2026-07-31) ─────────────
// The little printer on a floor tile opens this. It shows the bill the way it will PRINT
// (every dish, its add-ons, discount, tax, total), and carries the three things a finished
// table needs, in the order they actually happen: Print → (invoice) → Mark paid.
//
// Why one popup instead of the old route (tile → detail panel → hunt the footer → confirm →
// confirm): closing out a table is the most repeated job of a service, and it was the most
// scattered. Paying from here also frees the table by itself, so a table is done in two taps.
//
// TWO BUTTONS UNTIL IT IS PRINTED (owner, 2026-07-31: "there should only be option of generate
// invoice and print … when printed then mark as paid"). A running tab offers exactly
// 🧾 Generate invoice and 🖨 Print. **Mark paid appears only once the bill is issued** — which
// Print does by itself, so the real sequence on the floor is: Print → Mark paid → the table
// frees itself. Asking for money before the guest has a bill in their hand was the wrong order,
// and three buttons on a fresh tab made the common one harder to find.
//
// Print never dead-ends on the invoice-first rule: a bill with no invoice yet gets one generated
// (that IS the document that prints) and THEN prints, in the same tap.
async function openBillPreview(t) {
  // THE WHOLE PARTY, ALWAYS (owner, 2026-08-03). This popup was reading ordersForTable(t) —
  // one table's own orders — so a merged party's bill preview (and the paper it printed)
  // showed HALF the food and HALF the money: proven live at ₹662 shown for a ₹1,323 party.
  // partyOrders gathers every member table's slice; on a normal table it is ordersForTable.
  t = mergeParentOf(String(t)) || String(t); // the popup always speaks for the table HOLDING the bill
  await ensurePartySlices(t); // ALWAYS current: this popup shows money and issues documents
  const live = () => partyOrders(t).filter((o) => o.status !== "cancelled");
  let os = live();
  if (!os.length) { toast(`${tableLabel(t)} has nothing to bill yet`, "ok"); return; }
  const sess = openSessionForTable(t);
  const m = billMath(os); // discount-before-tax — the SAME math the printed bill uses
  const pct = Math.round(m.rate * 10000) / 100;
  const invoiced = !!sess && sess.invoice_no != null && !sess.invoice_voided;
  const anyUnpaid = os.some((o) => o.payment_status !== "paid");
  // "DUE" MUST MEAN WHAT IS STILL OWED (T18 sweep, 2026-08-16). This popup adds up every
  // non-cancelled order — paid ones included — and then labelled that figure "Total due". On a
  // part-settled bill (one order collected, another not — a state ordersLiveHtml explicitly
  // counts) it read "Total due ₹1,000" while only ₹400 was owed, and 💳 Mark paid then opened the
  // payment sheet asking for ₹400. Two screens, two taps apart, answering "what do they owe?"
  // differently is how a cashier stops trusting the till. The bill TOTAL is unchanged — the paper
  // must still show the whole bill — so when part of it is already collected the popup states all
  // three figures instead of putting the wrong word over one of them.
  const paidOs = os.filter((o) => o.payment_status === "paid");
  const partPaid = anyUnpaid && paidOs.length > 0;
  const paidSoFar = partPaid ? billMath(paidOs).total : 0;
  const stillDue = Math.round((m.total - paidSoFar) * 100) / 100;
  // A brand-new order can't be paid before staff accept it — the same rule the orders list
  // enforces. Say so on the button instead of letting the tap fail.
  const anyReceived = os.some((o) => o.status === "received");
  // One line per DISH, not per KOT: identical lines across the party's orders combine, with
  // their quantities summed — the same rule the printed bill uses (combineBillLines).
  const lines = combineBillLines(os.flatMap((o) => orderItemRows(o))).map((i) => {
    const det = itemDetailLine(i);
    return `<div class="bm-line"><span class="bm-nm">${esc(i.title)} <span class="bm-q">×${esc(i.qty)}</span>${mrpPill(i)}${det}</span><span class="bm-line-right"><span class="bm-pr">${inr((parseFloat(i.price) || 0) * (parseInt(i.qty, 10) || 1))}</span></span></div>`;
  }).join("");
  const wrap = document.createElement("div");
  wrap.className = "bill-overlay";
  wrap.innerHTML = `<div class="bill-modal">
      <div class="bm-head"><b>${esc(mergeGroupLabel(t) ? `Tables ${mergeGroupLabel(t)}` : tableLabel(t))}${sess && sess.bill_no != null ? ` · Bill #${esc(sess.bill_no)}` : ""}</b>${invoiced ? `<span class="inv-chip">invoice #${esc(sess.invoice_no)}</span>` : `<span class="inv-chip pending">not invoiced</span>`}</div>
      <div class="bm-sub">${esc(sess && sess.customer_name ? sess.customer_name : "")}${anyUnpaid ? "" : " · paid"}</div>
      <div class="bm-items">${lines}</div>
      <div class="bm-totals">
        ${mrpTotalsRows(m, pct)}
        ${partPaid
          ? `<div class="bm-trow"><span>Total</span><span>${inr(m.total)}</span></div>
             <div class="bm-trow"><span>Already paid</span><span>− ${inr(paidSoFar)}</span></div>
             <div class="bm-trow grand"><span>Still due</span><span>${inr(stillDue)}</span></div>`
          : `<div class="bm-trow grand"><span>${anyUnpaid ? "Total due" : "Total"}</span><span>${inr(m.total)}</span></div>`}
      </div>
      <div class="bm-actions">
        ${/* Print below already issues-then-prints; a separate issue-only button is the confusion
             the owner removed on 2026-08-05. */ ""}
        <button class="btn primary" data-bp-print>${billPrintLabel(sess, live())}</button>
        ${invoiced && anyUnpaid ? `<button class="btn green" data-bp-pay${anyReceived ? ` disabled title="Accept the order first — a bill can only be paid once the order is accepted."` : ""}>💳 Mark paid</button>` : ""}
        <button class="btn confirm-cancel" data-bp-close>Close</button>
      </div>
    </div>`;
  document.body.appendChild(wrap);
  requestAnimationFrame(() => wrap.classList.add("show"));
  const onEsc = (e) => { if (e.key === "Escape") close(); };
  const close = () => { wrap.classList.remove("show"); document.removeEventListener("keydown", onEsc); setTimeout(() => wrap.remove(), 180); };
  wrap.__lfhClose = close; // hardware BACK closes THIS layer (and drops the Esc listener)
  document.addEventListener("keydown", onEsc);
  wrap.onclick = (e) => { if (e.target === wrap) close(); };
  wrap.querySelector("[data-bp-close]").onclick = close;
  // Print: invoice first if there isn't one (that's the document that prints), then paper.
  // Re-read the session AFTER generating — generateInvoice refreshes it, and printing a
  // stale copy would put a bill on paper with no invoice number on it.
  // Re-open the popup after issuing/printing, so it comes back showing 💳 Mark paid — the next
  // thing that happens at that table — instead of leaving stale buttons on screen.
  //
  // openBillPreview force-refreshes this table's slice, so re-opening always reads the invoice
  // number that was just issued rather than the copy the screen was built from.
  const reopen = async () => { close(); await openBillPreview(t); };
  wrap.querySelector("[data-bp-print]").onclick = async () => {
    let ss = openSessionForTable(t);
    const needsInvoice = ss && (ss.invoice_no == null || ss.invoice_voided);
    if (needsInvoice) {
      await generateInvoice(ss.id);
      await ensureTableSlice(t, true); // the invoice lives on the SESSION row — re-read it
      ss = openSessionForTable(t);
      if (!ss || ss.invoice_no == null || ss.invoice_voided) return; // cancelled or failed — generateInvoice already said which
    }
    printBill(t, ss || { invoice_no: null, bill_no: null }, live(), { party: true }); // a LIVE bill — the party label applies
    if (needsInvoice) await reopen();
  };
  // (the issue-only button was removed 2026-08-05 — Print issues then prints)
  // Mark paid runs the normal payment popup (method + khata/on-the-house where allowed),
  // and the server frees the table once the bill is settled and everything is served.
  //
  // The invoice is made FIRST, deliberately. A restaurant that requires a customer on the bill
  // can't be invoiced without a mobile + name, and that used to be asked AFTER the payment sheet
  // closed — a dialog appearing under a finger that had just tapped Cash, which is the one thing
  // this app never does. Asking before any money moves keeps it one straight sequence:
  // Mark paid → (who is this bill for?) → how did they pay? → done.
  // Cancelling the customer sheet does NOT block the payment: staff must always be able to take
  // money that's in their hand. The bill stays invoice-able from this same popup afterwards.
  const payBtn = wrap.querySelector("[data-bp-pay]");
  if (payBtn && !payBtn.disabled) payBtn.onclick = async () => {
    close();
    let ss = openSessionForTable(t);
    if (ss && (ss.invoice_no == null || ss.invoice_voided)) { await generateInvoice(ss.id); await loadSessions(); }
    await markTablePaid(t, { skipAutoInvoice: true });
  };
}

// ── TAKE ORDER — start a BRAND-NEW dine-in order from the manager panel ─────────
// Mirrors the waiter tablet's order-builder (open table → browse dishes → build a
// cart → send to kitchen) rendered with the editor's own components/styling, posting
// to the manager's server-priced POST /order. Gated by the take_orders manager power
// (the button only shows when the manager has it; the server re-checks managerCan). (2026-07-22)
function localizeCat(name, slug) {
  if (name && typeof name === "object") return name.en || Object.values(name).find((v) => v) || slug;
  return name || slug;
}
// QUICK mode (⚡ QO/P, owner 2026-08-02) is a THIRD mode of this same builder, not a
// second builder. The cart rules underneath are subtle — a dish carrying an allergy or
// note is its own line, an open-price line keys on its typed amount, two lines that
// match after an edit merge back — and the last time an order screen was written twice
// the open-price rule reached one of them a day late. So quick mode changes only two
// things: HOW you browse (drill down category → dish → back to categories, instead of
// one long scroll-spy list) and WHEN the destination is chosen (at the end, from a
// picker whose top option is Parcel, instead of being fixed before you start).
function openTakeOrder(table, rerender, opts = {}) {
  const quick = !!opts.quick;             // ⚡ QO/P — destination asked LAST
  // `parcel` is settled up-front for the 🥡 New Parcel button, but in quick mode it is
  // only known once the manager picks a destination — hence `let`, not `const`.
  let parcel = !!opts.parcel;            // parcel mode = a no-table order (Platform system)
  let destTable = table;                  // the table this order lands on (quick mode fills it in last)
  let qoCat = null;                       // quick mode: the category being browsed (null = the category list)
  let custName = "", custPhone = "";      // parcel-only optional customer fields
  document.querySelector(".to-overlay")?.remove();
  const dishes = (state.data.items || []).filter((d) => !(d.tags || []).includes("sold-out"));
  const cats = (state.data.categories || []).filter((c) => dishes.some((d) => d.category === c.slug));
  // Dishes with an unknown/empty category still need a home so "all shown" holds.
  const uncategorised = dishes.filter((d) => !cats.some((c) => c.slug === d.category));
  // icon/colour ride along so quick mode's category cards can wear the same identity the
  // guest menu gives each category (a wall of identical grey cards is slower to aim at).
  const sections = cats.map((c) => ({ slug: c.slug, name: localizeCat(c.name, c.slug), icon: c.icon || "", color: c.color || "", items: dishes.filter((d) => d.category === c.slug) }))
    .concat(uncategorised.length ? [{ slug: "_other", name: "Other", icon: "", color: "", items: uncategorised }] : []);

  // A cart line is one VARIANT of a dish: the same dish with different allergens/notes
  // is a SEPARATE line (like the tablet). Each line has a stable uid so edits never
  // reshuffle the DOM. Tap-to-add only ever touches the PLAIN variant.
  const cart = [];               // [{ uid, id, title, price, qty, note, avoid:Set }]
  const orderAvoid = new Set();  // whole-order allergens
  let orderNote = "";
  // A DISCOUNT ON AN ORDER THAT DOESN'T EXIST YET (owner, 2026-08-03: "you are not able to give
  // discount in the quick order? make sure there is a discount thing also"). Every other discount
  // in this panel edits a bill that is already on the floor; here the order is still being built,
  // so the amount is HELD and travels with the order to the server, which applies it in the same
  // request that creates the order — never a second "apply it afterwards" call that could land
  // after a bill was printed, or not land at all. Stored the way the server stores it: rupees off
  // the PRE-TAX subtotal.
  let discAmount = 0, discNote = "";
  let q = "";
  let uidSeq = 0;
  const editing = new Set();     // cart-line UIDs whose per-dish editor is open

  const byUid = (uid) => cart.find((c) => c.uid === uid);
  // A line's identity for de-duping. An open-price line also keys on its PRICE — two
  // as-per-MRP cans rung at different prices are genuinely different lines and must
  // never be merged (that would silently drop one of the typed prices).
  const sig = (l) => [...l.avoid].sort().join(",") + "|" + (l.note || "").trim() + (l.open_price ? "|₹" + l.price : "");
  const isPlain = (l) => !l.avoid.size && !(l.note || "").trim();
  const plainLine = (id) => cart.find((c) => c.id === id && isPlain(c));
  const qtyIn = (id) => cart.filter((c) => c.id === id).reduce((s, c) => s + c.qty, 0);
  // Tapping a dish adds to its PLAIN line only — a line carrying an allergy or note is a
  // distinct variant and is never grown by a tap (fixes "add plain → lands on the dairy one").
  // tax_mode rides on the cart line (mig 270) so the discount modal can cap on the TAXABLE
  // part of a cart that has not been placed yet. Without it an MRP bottle in the basket would
  // look discountable here and be refused by the server a second later.
  const addOne = (id) => { const l = plainLine(id); if (l) { l.qty = Math.min(99, l.qty + 1); return; } const d = dishes.find((x) => x.id === id); if (d) cart.push({ uid: ++uidSeq, id, title: d.title, price: parseFloat(d.price) || 0, qty: 1, note: "", avoid: new Set(), tax_mode: d.tax_mode }); };
  // Open-price (as-per-MRP) dish: the menu carries NO price, so the manager types it at
  // order time. A first tap opens the price pad; later taps just grow the existing line
  // (the price is already set — tap the line's ₹ to change it). (2026-07-29)
  const addOneAsync = async (id) => {
    const d = dishes.find((x) => x.id === id);
    if (d && d.open_price) {
      const l = plainLine(id);
      if (l) { l.qty = Math.min(99, l.qty + 1); return true; }
      const p = await pricePrompt(d.title);
      if (p == null) return false;
      cart.push({ uid: ++uidSeq, id, title: d.title, price: p, qty: 1, note: "", avoid: new Set(), open_price: true, tax_mode: d.tax_mode });
      return true;
    }
    addOne(id);
    return true;
  };
  const incUid = (uid) => { const l = byUid(uid); if (l) l.qty = Math.min(99, l.qty + 1); };
  const decUid = (uid) => { const i = cart.findIndex((c) => c.uid === uid); if (i < 0) return; if (cart[i].qty > 1) cart[i].qty--; else { cart.splice(i, 1); editing.delete(uid); } };
  // After an edit two lines can end up identical (same dish + allergy + note) — merge them.
  const dedupe = () => { for (let i = 0; i < cart.length; i++) for (let j = cart.length - 1; j > i; j--) { if (cart[i].id === cart[j].id && sig(cart[i]) === sig(cart[j])) { cart[i].qty = Math.min(99, cart[i].qty + cart[j].qty); editing.delete(cart[j].uid); cart.splice(j, 1); } } };

  const dishTile = (d) => {
    const n = qtyIn(d.id);
    // No photo (or a dead image URL) → show a default image, not a blank box (owner 2026-07-24).
    // An <img> (not a CSS background) so onerror can also swap a broken URL to the default; the
    // Aevidine mark is a neutral placeholder shown contained + dimmed so it reads as "no photo".
    const DEFAULT_DISH_IMG = "/brand/aevidine-mark.svg";
    const hasImg = !!d.image;
    const img = `<span class="to-dish-img"><img src="${esc(hasImg ? d.image : DEFAULT_DISH_IMG)}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${DEFAULT_DISH_IMG}';this.style.objectFit='contain';this.style.opacity='.5';this.style.padding='16%';this.style.boxSizing='border-box'" style="width:100%;height:100%;display:block;box-sizing:border-box;object-fit:${hasImg ? "cover" : "contain"};${hasImg ? "" : "opacity:.5;padding:16%;"}" /></span>`;
    // Big image + name/price; the WHOLE tile taps to add (plain). The only button is a
    // large ✎ on the right to set this dish's allergens/note — no +/− (add by tapping,
    // reduce from the order list on the right). ×N shows the running count for this dish.
    // Open-price (as-per-MRP) dish: no menu price to show — prompt the manager instead of
    // printing a misleading ₹0.
    return `<div class="to-dish ${n ? "has" : ""}" data-dish="${esc(d.id)}" role="button" tabindex="0" title="Tap to add">${img}<span class="to-dish-meta"><span class="to-dish-t">${esc(d.title)}</span><span class="to-dish-p">${d.open_price ? "Set price" : inr(parseFloat(d.price) || 0)}</span></span><span class="to-dish-side">${n ? `<b class="to-dish-n">×${n}</b>` : ""}<button class="to-dish-edit" data-tile-edit="${esc(d.id)}" title="Allergens & note for this dish">✎</button></span></div>`;
  };
  // A quick-mode CATEGORY card: the name, how many dishes are in it, and the category's
  // own colour down the left edge. Tapping it drills into that category's dishes.
  //
  // NO PICTURE, and no square standing in for one (owner, 2026-08-03: "in the category
  // option, remove that photo thing — a category doesn't have a photo"). It used to wear a
  // rounded square holding the name's first letter, which read as an empty photo slot; a
  // category has nothing to put in one, so the square was a hole. The colour bar down the
  // left edge carries the identity instead, and the name gets the whole card — which is
  // also what lets the names stay readable when 40 categories have to share one screen.
  // (Dishes keep their photo — they have a real one.)
  const catCard = (s) => {
    const n = s.items.length;
    return `<button class="qo-cat" data-qocat="${esc(s.slug)}"${s.color ? ` style="--qo-c:${esc(s.color)}"` : ""}>
      <span class="qo-cat-tx">
        <span class="qo-cat-n">${esc(s.name)}</span>
        <span class="qo-cat-c"><b>${n}</b><i> dish${n === 1 ? "" : "es"}</i></span>
      </span>
    </button>`;
  };
  const listHtml = () => {
    const ql = q.trim().toLowerCase();
    // `qo-grid` marks a grid that fitBrowse() is allowed to size to the space it has;
    // it is only ever added in quick mode (the two scroll-spy modes keep scrolling).
    const fitCls = quick ? " qo-grid" : "";
    if (ql) { // searching → one flat grid of matches, no headers
      const list = dishes.filter((d) => (d.title || "").toLowerCase().includes(ql));
      return list.length ? `<div class="to-grid${fitCls}">${list.map(dishTile).join("")}</div>` : `<div class="muted" style="padding:16px">No dishes match "${esc(q)}".</div>`;
    }
    // ⚡ QUICK — two levels, never both at once. Level 1 is the category cards; level 2 is
    // one category's dishes. Adding a dish drops straight back to level 1, which is what
    // makes "category, dish, category, dish" fast without a scroll in between.
    if (quick) {
      if (!qoCat) return sections.length
        ? `<div class="qo-cats qo-grid">${sections.map(catCard).join("")}</div>`
        : `<div class="muted" style="padding:16px">No dishes on the menu yet.</div>`;
      const s = sections.find((x) => x.slug === qoCat);
      if (!s) return `<div class="muted" style="padding:16px">That category is gone.</div>`;
      return s.items.length
        ? `<div class="to-grid qo-grid">${s.items.map(dishTile).join("")}</div>`
        : `<div class="muted" style="padding:16px">Nothing in ${esc(s.name)} right now.</div>`;
    }
    // not searching → every category shown, in order, each its own scroll-spy section
    return sections.map((s) => `<section class="to-sec" data-sec="${esc(s.slug)}"><h4 class="to-sec-h">${esc(s.name)}</h4><div class="to-grid">${s.items.map(dishTile).join("")}</div></section>`).join("");
  };
  // Quick mode's breadcrumb bar, in place of the scroll-spy chip strip: where you are,
  // and the way back out of a category.
  // The bar also carries the COUNT of what you're looking at (owner, 2026-08-03: "every
  // category, how many items are there, how many categories are there"), so the size of
  // the menu is a fact on screen rather than something you work out by counting tiles.
  const drillHtml = () => {
    const ql = q.trim();
    const nDish = dishes.length;
    let here, sub;
    if (ql) {
      const m = dishes.filter((d) => (d.title || "").toLowerCase().includes(ql.toLowerCase())).length;
      here = `Search · “${esc(ql)}”`; sub = `${m} match${m === 1 ? "" : "es"}`;
    } else if (qoCat) {
      const s = sections.find((x) => x.slug === qoCat) || { name: "", items: [] };
      here = esc(s.name); sub = `${s.items.length} dish${s.items.length === 1 ? "" : "es"}`;
    } else {
      here = "All categories";
      sub = `${sections.length} categor${sections.length === 1 ? "y" : "ies"} · ${nDish} dish${nDish === 1 ? "" : "es"}`;
    }
    const back = (qoCat || ql) ? `<button class="qo-back" type="button">‹ Categories</button>` : "";
    return `${back}<span class="qo-crumb">${here}</span><span class="qo-count">${sub}</span>`;
  };
  const catChips = () => sections.map((s, i) => `<button class="to-cat ${i === 0 ? "on" : ""}" data-jump="${esc(s.slug)}">${esc(s.name)}</button>`).join("");
  // One allergy row = the six standard chips, then any TYPED ones already on this list
  // (always "on" — tapping one takes it off again, same as a standard chip), then the
  // ＋ Other chip that opens the box to type a new one.
  const algChips = (set, kind, id) => {
    const at = (slug) => `${slug == null ? "" : `data-alg="${esc(slug)}" `}data-kind="${kind}"${id ? ` data-line="${esc(id)}"` : ""}`;
    const std = ALLERGENS.map((a) => `<span class="chip to-alg-chip ${set.has(a.slug) ? "on" : ""}" ${at(a.slug)}>${esc(a.label)}</span>`).join("");
    const cust = [...set].filter((s) => !ALG_STD.includes(s)).map((s) => `<span class="chip to-alg-chip on" ${at(s)}>${esc(algLabel(s))}</span>`).join("");
    return std + cust + `<span class="chip to-alg-chip alg-other" ${at(null)} data-alg-other="1" title="Type an allergy that isn't listed">＋ Other</span>`;
  };
  const cartLines = () => cart.length
    ? cart.map((c) => {
        const open = editing.has(c.uid);
        const cues = [c.avoid.size ? `⚠ no ${[...c.avoid].join(", ")}` : "", c.note ? `📝 ${c.note}` : ""].filter(Boolean).join(" · ");
        return `<div class="to-line ${open ? "editing" : ""}">
          <div class="to-line-main">
            <span class="to-line-t">${esc(c.title)}${cues ? `<span class="to-line-cue">${esc(cues)}</span>` : ""}</span>
            <span class="to-step"><button class="to-q" data-ldec="${c.uid}" aria-label="One fewer">−</button><b>${c.qty}</b><button class="to-q" data-linc="${c.uid}" aria-label="One more">＋</button></span>
            ${c.open_price
              ? `<button class="to-line-p to-price-edit" data-price="${c.uid}" title="Tap to change this price" style="background:none;border:0;padding:0;color:var(--gold);font:inherit;cursor:pointer;text-decoration:underline dotted">${inr((parseFloat(c.price) || 0) * c.qty)}</button>`
              : `<span class="to-line-p">${inr((parseFloat(c.price) || 0) * c.qty)}</span>`}
            <button class="to-edit ${open ? "on" : ""}" data-edit="${c.uid}" title="Allergens & note for this dish">✎</button>
            <button class="to-rm" data-rm="${c.uid}" aria-label="Remove">🗑</button>
          </div>
          ${open ? `<div class="to-line-edit"><div class="to-lbl">Avoid in this dish</div><div class="to-alg">${algChips(c.avoid, "line", c.uid)}</div><input class="to-line-note" data-line="${c.uid}" maxlength="120" placeholder="Note for this dish (e.g. extra spicy)" value="${esc(c.note)}"></div>` : ""}
        </div>`;
      }).join("")
    : `<div class="muted" style="padding:14px 4px">No dishes yet — tap a dish to add it.</div>`;
  // Estimate INCLUDES tax so the "≈ ₹" staff quote matches the server's bill.
  //
  // A PARCEL IS PRICED EXACTLY LIKE A TABLE — no special case (2026-08-05). It used to be
  // quoted here at the bare item subtotal, on the old rule that "a parcel is stored & charged
  // at the item subtotal, like every other Platform order". That rule ended on 2026-08-02,
  // when the /parcel route started storing `splitBill(picked, parcelSet, parcelDisc).total` —
  // subtotal + tax — precisely so the record equals the paper. The quote was never moved with
  // it, so the counter screen said ₹250 while the parcel tile a second later said ₹262.50 and
  // the customer was charged the second number. One formula for both, so they cannot drift
  // again: whatever the server would charge is what this footer says.
  const cartSub = () => cart.reduce((s, c) => s + (parseFloat(c.price) || 0) * c.qty, 0);
  // The cart's taxable/untaxed split (mig 270), by the SAME rule the server prices it by —
  // for a parcel too, since lib/tax.ts splitBill() is what prices both.
  const cartSplit = () => splitCartLines(cart, state.data.settings);
  // The held discount can never be worth more than the TAXABLE food: emptying the cart after
  // typing ₹200 off must not leave ₹200 of discount attached to a ₹50 order, and it may never
  // eat into an MRP line, whose price is final (same cap the server applies).
  // Same cap rule as billMath / mig 272: with tax, only the taxable base may be discounted;
  // with no tax, everything except the locked MRP lines. The parcel route applies the very
  // same cap (`splitBill(...).discountBase`), so offering a bigger one here only produced a
  // refusal at the last tap — the failure the QO/P destination gates exist to remove.
  const discCap = () => {
    const sp = cartSplit();
    const rate = (taxModel(state.data.settings) || {}).rate || 0;
    return rate > 0 ? sp.taxableBase : Math.max(0, Math.round((sp.taxableBase + sp.nontax - sp.mrpAmount) * 100) / 100);
  };
  const discOf = () => Math.round(Math.min(Math.max(discAmount, 0), discCap()) * 100) / 100;
  // THE NUMBER, and then the way it is written. They were one function returning a formatted
  // string, so the one caller that needed the FIGURE — the parcel's "Pay now & print" sheet —
  // could not have it and reached for the pre-tax subtotal instead (T18 sweep, 2026-08-16).
  const estTotalNum = () => {
    const sp = cartSplit();
    const rate = (taxModel(state.data.settings) || {}).rate || 0;
    const d = discOf();
    // The SAME one formula billMath uses — subtotal − discount + tax, with tax charged on
    // what is left of the taxable base. It stays right when the rate is 0 and the discount
    // has landed on the untaxed part, which a `taxable + tax + untaxed` shape would not.
    const taxable = Math.max(0, sp.taxableBase - Math.min(d, sp.taxableBase));
    return Math.round((sp.taxableBase + sp.nontax - d + Math.round(taxable * rate * 100) / 100) * 100) / 100;
  };
  const estTotal = () => inr(estTotalNum());
  // May THIS person discount? Same power the table detail's − Discount button is gated by
  // (XRAY_CONTROLS → [data-disc] → give_discounts), checked HERE in JS as well.
  //
  // WHY IN JS — AND NOT FOR THE REASON THIS COMMENT USED TO GIVE (T18 sweep, 2026-08-16). It said
  // the x-ray observer cannot see this modal "because it lives on document.body — outside the
  // panel the observer watches". That is not true and was worth correcting where someone can read
  // it: applyHierarchyView() queries `document.querySelectorAll(entry.selector)` document-WIDE and
  // its MutationObserver watches document.body with `subtree: true`, which is exactly how the bill
  // modal's own money buttons get hidden. The real reason is narrower and still binding: this
  // button carried NO `data-disc`, so the x-ray's selector never matched it and the JS check was
  // the only gate it had. A future session reading the old reason, finding it false, and deleting
  // this check as redundant would have handed a manager without give_discounts a working discount
  // button. Both halves now: the marker below so the x-ray covers it like every other money
  // control, and this check so the button is never even built.
  const canDiscount = () => (XRAY_WHO && XRAY_WHO.higherView ? true : xrayGrantedForManager("give_discounts"));

  const headTitle = quick ? "⚡ QO/P <span class=\"qo-sub\">· quick order / parcel</span>"
    : parcel ? "🥡 New Parcel"
    : `＋ Take order · T${esc(table)}`;
  const wrap = el(`<div class="sx-modal-overlay to-overlay"><div class="sx-modal to-modal${quick ? " to-quick" : ""}">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>${headTitle}</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div>${parcel ? `<div class="to-cust"><input class="to-cust-name" maxlength="120" placeholder="Customer name (optional)"><input class="to-cust-phone" maxlength="20" inputmode="tel" placeholder="Phone (optional)"></div>` : ""}</div>
    <div class="to-body">
      ${quick ? "" : `<aside class="to-rail"><div class="to-rail-h">Categories<i>${sections.length}</i></div><div class="to-crail" data-swipe-hint data-swipe-count>${catChips()}</div></aside>`}
      <div class="to-menu">
        <input type="search" class="to-search" placeholder="🔎 Search dishes…">
        ${quick ? `<div class="qo-drill">${drillHtml()}</div>` : ""}
        <div class="to-list">${listHtml()}</div>
      </div>
      <div class="to-cart">
        <div class="to-cart-h">This order</div>
        <div class="to-lines">${cartLines()}</div>
        <div class="to-extras">
          <div class="to-lbl">⚠ Avoid (whole order)</div>
          <div class="to-alg">${algChips(orderAvoid, "order")}</div>
          <textarea class="to-note" rows="2" placeholder="Note for the kitchen (optional)"></textarea>
        </div>
        <div class="to-foot">
          <div class="to-total">≈ <b>${estTotal()}</b><span class="to-disc-tag" hidden></span></div>
          ${canDiscount() ? `<button class="btn to-disc-btn" type="button" data-disc title="Give a discount on this order">− Discount</button>` : ""}
          ${quick
            ? `<button class="qo-cartbtn" type="button" aria-expanded="false" title="Show / hide the order you're building"><b class="qo-cartn">0</b> <span class="qo-cartl">items</span> <span class="qo-cartcar" aria-hidden="true">▴</span></button><button class="btn primary to-send qo-place" ${cart.length ? "" : "disabled"}>Place order →</button>`
            : parcel
            ? `<div class="to-pay"><button class="btn green to-send" data-pay="now" ${cart.length ? "" : "disabled"}>Pay now &amp; print</button><button class="btn primary to-send" data-pay="later" ${cart.length ? "" : "disabled"}>Pay on pickup</button></div>`
            : `<button class="btn primary to-send" ${cart.length ? "" : "disabled"}>Send to kitchen</button>`}
        </div>
      </div>
    </div>
  </div></div>`);
  document.body.appendChild(wrap);

  // Whatever this modal starts, this modal ends — quick mode watches the window and the
  // browse block for size changes, and a live observer on a removed node outlives every
  // order taken after it. Every close path goes through here (✕, backdrop, back button,
  // a sent order), so there is one place to hang that tidy-up.
  const onClose = [];
  const close = () => { while (onClose.length) { try { onClose.pop()(); } catch {} } wrap.remove(); };
  wrap.__lfhClose = close;

  const listEl = wrap.querySelector(".to-list");
  const linesEl = wrap.querySelector(".to-lines");
  const catsEl = wrap.querySelector(".to-crail");  // the left category box; null in quick mode — it has a drill bar instead
  const drillEl = wrap.querySelector(".qo-drill");  // null in the two scroll-spy modes
  const totalEl = wrap.querySelector(".to-total b");
  const sendBtns = [...wrap.querySelectorAll(".to-send")]; // parcel has TWO (pay now / pay later); dine-in has one
  if (parcel) {
    const nm = wrap.querySelector(".to-cust-name"); if (nm) nm.oninput = (e) => { custName = e.target.value; };
    const ph = wrap.querySelector(".to-cust-phone"); if (ph) ph.oninput = (e) => { custPhone = e.target.value; };
  }

  const paintCart = () => {
    linesEl.innerHTML = cartLines(); bindCart(); totalEl.textContent = estTotal();
    sendBtns.forEach((b) => (b.disabled = !cart.length));
    // The discount has to be VISIBLE next to the total it changed, or a ₹200 reduction is a
    // number nobody can account for at the counter.
    const tag = wrap.querySelector(".to-disc-tag"), d = discOf();
    if (tag) { tag.hidden = !(d > 0); tag.textContent = d > 0 ? ` (− ${inr(d)} off)` : ""; }
    const db = wrap.querySelector(".to-disc-btn");
    if (db) db.textContent = d > 0 ? `− ${inr(d)} off` : "− Discount";
    // Quick mode's phone bar states what's in the order while the list itself is folded away.
    const cn = wrap.querySelector(".qo-cartn");
    if (cn) {
      const qty = cart.reduce((s, c) => s + c.qty, 0);
      cn.textContent = String(qty);
      const lbl = wrap.querySelector(".qo-cartl"); if (lbl) lbl.textContent = qty === 1 ? "item" : "items";
    }
  };

  // ── ⚡ QO/P: THE WHOLE MENU ON ONE SCREEN, WHATEVER SIZE IT IS ──────────────────
  // (owner, 2026-08-03: "every category… it should show in one panel, one screen, you
  //  don't have to scroll down because it's quick… more than twenty five, still it
  //  should show in one panel".)
  //
  // A quick order is only quick if the thing you're aiming at is ALREADY on screen — a
  // scroll is a search, and searching is what the search box is for. So quick mode does
  // not use a fixed tile size at all: it measures the block it actually has and works
  // out the columns × rows that put ALL of them in it, then sizes every tile (and its
  // text, badge, photo) to match. 8 categories get big cards; 27 get medium ones; 60 get
  // small ones — same one screen, no scrollbar.
  //
  // The honest floor: below a readable tile it STOPS shrinking and lets the block scroll
  // again. A wall of 8px text nobody can read in a rush would be worse than a scroll —
  // this is the one case where "one screen" gives way.
  const FIT = {
    // ratio = the tile shape each kind wants (w/h). A category is a badge + a short name,
    // so it likes a squarish card; a dish is photo + name + price + ✎, so it likes a wide row.
    // The phone floor is genuinely lower, not a scaled guess: a phone is held ~30cm away,
    // not read across a counter, and the badge/photo drop out down there — so the tile only
    // has to hold two lines of name and a count.
    cat:  { minW: 100, maxW: 300, minH: 46, maxH: 152, ratio: 1.55, pMinW: 66, pMaxW: 180, pMinH: 40 },
    dish: { minW: 140, maxW: 330, minH: 54, maxH: 126, ratio: 2.35, pMinW: 132, pMaxW: 210, pMinH: 46 },
  };
  const GAP = 8;
  let fitting = false;
  function fitBrowse() {
    if (!quick || fitting) return;
    // Set BEFORE measuring: on a phone the category level is allowed a taller block than
    // the dish level (choosing a category is the step where the order list matters least),
    // and that rule changes the very height this function is about to read.
    listEl.classList.toggle("qo-lvl-cats", !qoCat && !q.trim());
    const grid = listEl.querySelector(".qo-grid");
    if (!grid) { listEl.classList.remove("qo-noscroll"); return; }
    const n = grid.children.length;
    if (!n) return;
    const phone = window.innerWidth <= 760;
    const kind = grid.classList.contains("qo-cats") ? "cat" : "dish";
    const c = FIT[kind];
    const minW = phone ? c.pMinW : c.minW;
    const maxW = phone ? c.pMaxW : c.maxW;
    const minH = phone ? c.pMinH : c.minH;

    fitting = true;
    try {
      const cs = getComputedStyle(listEl);
      const availW = listEl.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
      const availH = listEl.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
      if (!(availW > 60) || !(availH > 60)) return; // not laid out yet — the observer will call back

      // First guess: give every tile an equal share of the box, shaped the way this kind
      // wants it (w = √(area × ratio)), then cap it so a 4-category menu doesn't become
      // four wall-sized banners.
      const share = (availW * availH) / n;
      let cols = Math.round(availW / Math.min(maxW, Math.max(minW, Math.sqrt(share * c.ratio))));
      const maxCols = Math.max(1, Math.min(n, Math.floor((availW + GAP) / (minW + GAP))));
      cols = Math.max(1, Math.min(cols, maxCols));
      // The shape to fall back to if this menu turns out not to fit at all. It is worked out
      // from the tile size that READS well, not from the number of tiles — for a count that
      // can't fit, "an equal share of the box each" is a share too small to read.
      const roomy = Math.max(1, Math.min(maxCols, Math.round(availW / Math.min(maxW, minW * 1.6))));
      let rows = Math.ceil(n / cols);
      let h = (availH - (rows - 1) * GAP) / rows;
      // Too squashed? MORE per row means FEWER rows, which makes every tile taller.
      while (h < minH && cols < maxCols) { cols++; rows = Math.ceil(n / cols); h = (availH - (rows - 1) * GAP) / rows; }
      const fits = h >= minH;
      // It genuinely does not fit (60 categories on a 360px phone is not a thing that fits).
      // Then GO BACK to the comfortable shape and let the block scroll — squeezing to the
      // narrowest columns AND scrolling anyway is the worst of both: you'd be scrolling
      // through tiles you can't read either.
      if (!fits) cols = roomy;
      h = Math.min(Math.max(h, minH), c.maxH);
      const w = (availW - (cols - 1) * GAP) / cols;

      // Everything the tile draws scales off these two numbers, so one measurement styles
      // the whole grid — no per-tile work, no layout thrash.
      // A CATEGORY card carries only words now (no picture, no square standing in for one),
      // so its name owns the tile's full width and may be sized more generously than a dish
      // name, which still shares its row with a photo and the ✎ button.
      const nameW = kind === "cat" ? 0.125 : 0.098;
      const name = Math.max(11, Math.min(kind === "cat" ? 17 : 15, Math.min(h * 0.30, w * nameW)));
      const sub = Math.max(9.5, Math.min(13, name * 0.76));
      // How many lines the name may take, and how tall its box may get — both worked out
      // from the room actually left once the padding and the count line have had theirs,
      // rather than guessed at 2. The line budget is measured against the SMALLEST font a
      // name is ever allowed to shrink to, so a long name has somewhere to go (unclip()
      // below only shrinks the ones that need it); the box height is the hard stop that
      // keeps a 3-line name from spilling out of its own tile.
      // At the tightest tier the dish count stops being a line under the name and becomes a
      // small number in the tile's corner (see .qo-tiny in the stylesheet) — so it costs the
      // name no height, and a 40px tile can still give a two-word category two full lines
      // instead of squeezing it onto one and shrinking it to 9px.
      const tiny = h < 58 || w < 128;
      const vpad = Math.min(6, h * 0.08);
      const room = Math.max(14, h - vpad * 2 - (tiny ? 0 : sub * 1.25));
      const lines = Math.max(1, Math.min(3, Math.floor(room / (9.8 * 1.16))));
      grid.style.gridTemplateColumns = `repeat(${cols}, minmax(0, 1fr))`;
      // FLOOR, never round: rounding 42.75 up to 43 across 8 rows is 2px more than the block
      // has, and 2px of overflow is a scrollbar — the exact thing this whole function exists
      // to remove. Losing a fraction of a pixel per row costs nothing.
      grid.style.gridAutoRows = `${Math.floor(h)}px`;
      grid.style.gap = `${GAP}px`;
      grid.style.setProperty("--qo-h", `${Math.round(h)}px`);
      grid.style.setProperty("--qo-name", `${name.toFixed(1)}px`);
      grid.style.setProperty("--qo-sub", `${sub.toFixed(1)}px`);
      grid.style.setProperty("--qo-pad", `${Math.round(Math.max(5, Math.min(16, h * 0.13)))}px`);
      grid.style.setProperty("--qo-vpad", `${vpad.toFixed(1)}px`);
      grid.style.setProperty("--qo-edit", `${Math.round(Math.max(28, Math.min(42, h * 0.55)))}px`);
      grid.style.setProperty("--qo-img", `${Math.round(Math.max(0, Math.min(64, h - 14)))}px`);
      grid.style.setProperty("--qo-lines", String(lines));
      grid.style.setProperty("--qo-nameh", `${Math.floor(room)}px`);
      grid.classList.add("qo-fit");
      // Under these a dish's photo stops being a help and starts stealing the name's room,
      // so it goes and the words carry the tile on their own.
      grid.classList.toggle("qo-tiny", tiny);
      grid.classList.toggle("qo-noimg", kind === "dish" && (h < 62 || w < 190));
      listEl.classList.toggle("qo-noscroll", fits);
      unclip(grid);
    } finally { fitting = false; }
  }
  // ONE font size for the whole grid can't know that "Sizzling Brownie" is twice the width
  // of "Dal". A name that still doesn't fit its tile gets its OWN slightly smaller size
  // until it does — because a category cut to "Tandoor Start…" is exactly the tile a person
  // has to stop and think about, which is the opposite of quick. Batched: every tile is
  // MEASURED, then every tile is WRITTEN, so the browser lays out ≤3 times, not once per tile.
  function unclip(grid) {
    const els = [...grid.querySelectorAll(".qo-cat-n, .to-dish-t")];
    if (!els.length) return;
    els.forEach((e) => (e.style.fontSize = ""));
    // A SINGLE WORD IS NEVER BROKEN IN HALF — it shrinks instead (2026-08-05). These names
    // carry `overflow-wrap: anywhere`, which is what stops a long name overflowing its tile,
    // but it also lets the browser split a word that merely doesn't fit the line: "Sandwiches"
    // came out as "Sandwiche / s" on the owner's phone. Two lines are by design; a word cut
    // with no hyphen is not — it just reads as a rendering fault. So a one-word name that has
    // wrapped counts as "over" and goes through the same shrink loop below as a clipped one.
    const oneWord = (e) => !/\s/.test((e.textContent || "").trim());
    const wrapped = (e) => {
      const lh = parseFloat(getComputedStyle(e).lineHeight) || 0;
      return lh > 0 && e.scrollHeight > lh * 1.5;
    };
    for (let pass = 0; pass < 3; pass++) {
      const over = els.filter((e) => e.scrollHeight > e.clientHeight + 1 || (oneWord(e) && wrapped(e)));
      if (!over.length) return;
      over.forEach((e) => {
        const cur = parseFloat(e.style.fontSize || getComputedStyle(e).fontSize) || 13;
        if (cur > 9.6) e.style.fontSize = Math.max(9.5, cur * 0.87).toFixed(1) + "px";
      });
    }
  }

  const paintList = () => {
    listEl.innerHTML = listHtml();
    if (drillEl) { drillEl.innerHTML = drillHtml(); bindDrill(); }
    bindList(); syncSpy(); fitBrowse();
  };

  // Quick mode's two navigation controls: a category card drills in, "‹ Categories"
  // comes back out (and clears a search, since a search is the other way to leave the
  // category list).
  function bindDrill() {
    if (!drillEl) return;
    const back = drillEl.querySelector(".qo-back");
    if (back) back.onclick = () => { qoCat = null; if (q) { q = ""; const s = wrap.querySelector(".to-search"); if (s) s.value = ""; } paintList(); };
  }
  function bindList() {
    // ✎ on a tile — set this dish's allergens/note (edits the plain line, creating it first).
    listEl.querySelectorAll("[data-tile-edit]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); openTileEdit(b.dataset.tileEdit); }));
    // Quick mode: a category card opens that category's dishes.
    listEl.querySelectorAll("[data-qocat]").forEach((b) => (b.onclick = () => { qoCat = b.dataset.qocat; paintList(); listEl.scrollTop = 0; }));
    // Whole tile is a tap-to-add target (ignore a click that landed on the ✎).
    // In quick mode adding a dish also steps BACK to the category list — that return trip
    // is the whole point of the mode (owner: "category item, category item, very fast").
    // A search stays put instead: you searched to add several matches, not to leave.
    listEl.querySelectorAll(".to-dish").forEach((t) => (t.onclick = async (e) => {
      if (e.target.closest("[data-tile-edit]")) return;
      if (!(await addOneAsync(t.dataset.dish))) return;
      if (quick && qoCat && !q.trim()) qoCat = null;
      paintList(); paintCart(); flashCart();
    }));
  }
  // A dish added from the far side of a wide screen is easy to miss, so the order list
  // pulses and scrolls to the line that just changed — the tap always leaves a mark.
  function flashCart() {
    const last = linesEl.querySelector(".to-line:last-child");
    if (!last) return;
    last.classList.remove("qo-flash");
    void last.offsetWidth; // restart the animation even on the same element
    last.classList.add("qo-flash");
    try { last.scrollIntoView({ block: "nearest" }); } catch {}
  }
  // Per-dish allergen + note popup opened from a dish tile's ✎ — mirrors the tablet's
  // per-item editor. Edits the PLAIN line (adds it first if needed); giving it an
  // allergy/note turns it into its own variant, so a later tap starts a fresh plain line.
  async function openTileEdit(id) {
    let l = plainLine(id);
    // addOneAsync (not addOne) so an open-price dish still asks for its price here — the ✎
    // route must never be able to create a ₹0 as-per-MRP line.
    if (!l) { if (!(await addOneAsync(id))) return; l = plainLine(id); paintList(); paintCart(); }
    if (!l) return;
    wrap.querySelector(".to-tileedit-overlay")?.remove();
    // Same row as everywhere else: the six, the typed ones, then ＋ Other.
    const chips = () => ALLERGENS.map((a) => `<span class="chip to-alg-chip ${l.avoid.has(a.slug) ? "on" : ""}" data-alg="${a.slug}">${esc(a.label)}</span>`).join("")
      + [...l.avoid].filter((s) => !ALG_STD.includes(s)).map((s) => `<span class="chip to-alg-chip on" data-alg="${esc(s)}">${esc(algLabel(s))}</span>`).join("")
      + `<span class="chip to-alg-chip alg-other" data-alg-other="1" title="Type an allergy that isn't listed">＋ Other</span>`;
    const ov = el(`<div class="to-tileedit-overlay"><div class="to-tileedit">
      <div class="to-te-head"><b>${esc(l.title)}</b><button class="to-te-x" aria-label="Done">✕</button></div>
      <div class="to-lbl">⚠ Avoid in this dish</div><div class="to-alg to-te-alg">${chips()}</div>
      <input class="to-line-note to-te-note" maxlength="120" placeholder="Note for this dish (e.g. extra spicy)" value="${esc(l.note)}">
      <button class="btn primary to-te-done">Done</button>
    </div></div>`);
    wrap.querySelector(".to-modal").appendChild(ov);
    // THE PHONE'S BACK BUTTON MUST CLOSE THIS SHEET, NOT THE WHOLE ORDER (2026-08-05).
    // The panel-wide adapter (wireOverlayBack) cannot see this one twice over: the class is
    // not in its selector list, and it observes document.body WITHOUT `subtree`, while this
    // overlay is appended inside `.to-modal`. So the top registered layer was the take-order
    // modal itself — one Back press closed the whole builder and a nine-dish cart went with
    // it. Registered explicitly through the sanctioned LFH_BACK API, exactly as pricePrompt
    // and allergyPrompt in this same file do; `off()` runs on every close path.
    let backOff = window.LFH_BACK ? LFH_BACK.layer("editor-tile-edit", () => done()) : null;
    const done = () => { if (backOff) { const f = backOff; backOff = null; f(); } ov.remove(); dedupe(); paintCart(); paintList(); };
    ov.querySelector(".to-te-x").onclick = done;
    ov.querySelector(".to-te-done").onclick = done;
    ov.onclick = (e) => { if (e.target === ov) done(); };
    const algEl = ov.querySelector(".to-te-alg");
    const bindAlg = () => ov.querySelectorAll(".to-alg-chip").forEach((chip) => (chip.onclick = async () => {
      // A typed allergy adds or removes a chip, so the row is redrawn; a standard one
      // just flips on/off in place.
      if (chip.dataset.algOther) { const v = await allergyPrompt(l.avoid); if (v) { l.avoid.add(v); algEl.innerHTML = chips(); bindAlg(); } return; }
      const s = chip.dataset.alg; l.avoid.has(s) ? l.avoid.delete(s) : l.avoid.add(s);
      if (!ALG_STD.includes(s)) { algEl.innerHTML = chips(); bindAlg(); return; }
      chip.classList.toggle("on", l.avoid.has(s));
    }));
    bindAlg();
    ov.querySelector(".to-te-note").oninput = (e) => { l.note = e.target.value; };
  }
  function bindCart() {
    linesEl.querySelectorAll("[data-linc]").forEach((b) => (b.onclick = () => { incUid(+b.dataset.linc); paintList(); paintCart(); }));
    linesEl.querySelectorAll("[data-ldec]").forEach((b) => (b.onclick = () => { decUid(+b.dataset.ldec); paintList(); paintCart(); }));
    linesEl.querySelectorAll("[data-rm]").forEach((b) => (b.onclick = () => { const uid = +b.dataset.rm; const i = cart.findIndex((c) => c.uid === uid); if (i >= 0) { editing.delete(uid); cart.splice(i, 1); } paintList(); paintCart(); }));
    // Closing a line's editor de-dupes (in case its allergy/note now matches another line).
    linesEl.querySelectorAll("[data-edit]").forEach((b) => (b.onclick = () => { const uid = +b.dataset.edit; if (editing.has(uid)) { editing.delete(uid); dedupe(); } else editing.add(uid); paintList(); paintCart(); }));
    // per-dish allergen chips + per-dish note (no de-dupe mid-edit so lines don't collapse under you)
    linesEl.querySelectorAll('.to-alg-chip[data-kind="line"]').forEach((chip) => (chip.onclick = async () => {
      const l = byUid(+chip.dataset.line); if (!l) return;
      // ＋ Other → ask for the word first, then add it exactly like a standard chip.
      if (chip.dataset.algOther) { const v = await allergyPrompt(l.avoid); if (v) { l.avoid.add(v); paintList(); paintCart(); } return; }
      const s = chip.dataset.alg; l.avoid.has(s) ? l.avoid.delete(s) : l.avoid.add(s); paintList(); paintCart();
    }));
    linesEl.querySelectorAll(".to-line-note").forEach((inp) => (inp.oninput = () => { const l = byUid(+inp.dataset.line); if (l) l.note = inp.value; }));
    // Tap an open-price line's amount to re-type it before sending.
    linesEl.querySelectorAll("[data-price]").forEach((b) => (b.onclick = async () => {
      const l = byUid(+b.dataset.price); if (!l) return;
      const p = await pricePrompt(l.title, l.price);
      if (p == null) return;
      l.price = p; dedupe(); paintList(); paintCart();
    }));
  }

  // ── Category scroll-spy: the active chip in the left box follows the list scroll, and
  //    tapping a chip jumps to that section — exactly like the guest menu / tablet. ──
  // The box lays out as a GRID on desktop/tablet and as a FLEX row on a phone (see
  // .to-crail in style.css), so ask the CSS which shape it is rather than repeating the
  // breakpoint here — one place decides, and they can't drift apart.
  const railIsStrip = () => !!catsEl && getComputedStyle(catsEl).display === "flex";
  const jumpTo = (slug) => {
    // A search replaces the sections with one flat list, so there is nothing to jump to
    // and the tap would do NOTHING — a silently swallowed tap. Clear the search first,
    // then jump: the tap always produces the thing it promises.
    if (q) {
      q = ""; const s = wrap.querySelector(".to-search"); if (s) s.value = "";
      paintList();
    }
    const sec = listEl.querySelector(`.to-sec[data-sec="${CSS.escape(slug)}"]`);
    if (sec) listEl.scrollTo({ top: sec.offsetTop - listEl.offsetTop - 4, behavior: "smooth" });
  };
  const syncSpy = () => {
    const secs = [...listEl.querySelectorAll(".to-sec")];
    if (!secs.length || !catsEl) return; // searching (flat list), or quick mode — no spy
    const top = listEl.scrollTop + 8;
    let active = secs[0].dataset.sec;
    for (const s of secs) { if (s.offsetTop - listEl.offsetTop <= top) active = s.dataset.sec; }
    const strip = railIsStrip();
    catsEl.querySelectorAll("[data-jump]").forEach((b) => {
      const on = b.dataset.jump === active; b.classList.toggle("on", on);
      // Only the phone's sideways strip has to chase the active chip. In the left box
      // every chip is already on screen, so scrolling it would be movement for nothing.
      // Nudge the strip's OWN horizontal scroll only — never scrollIntoView (it scrolls a
      // vertical ancestor and hides the strip).
      if (on && strip) { const cr = catsEl.getBoundingClientRect(), br = b.getBoundingClientRect(); catsEl.scrollBy({ left: (br.left + br.width / 2) - (cr.left + cr.width / 2), behavior: "smooth" }); }
    });
  };

  // ── The no-scroll guarantee for the category box ──
  // The point of the box is that EVERY category is on screen, so the layout is measured,
  // never assumed: try the roomiest step first and go tighter only as far as needed. A
  // fixed grid would work for one restaurant's menu and put a scrollbar back for the next
  // one — the fit has to depend on how many categories there actually are. (Same idea as
  // fitBrowse for the ⚡ QO/P grid.)
  const RAIL_STEPS = [
    { cols: 1, fs: 13,   h: 40, gap: 7, pad: "9px 12px" },
    { cols: 2, fs: 13,   h: 38, gap: 7, pad: "8px 10px" },
    { cols: 2, fs: 12.5, h: 36, gap: 6, pad: "7px 8px"  },
    { cols: 2, fs: 12,   h: 34, gap: 5, pad: "6px 7px"  },
    { cols: 3, fs: 11.5, h: 32, gap: 5, pad: "6px 6px"  },
    { cols: 3, fs: 11,   h: 30, gap: 4, pad: "5px 5px"  },
  ];
  const fitRail = () => {
    if (!catsEl || railIsStrip()) return;   // phone keeps the sideways strip
    for (const s of RAIL_STEPS) {
      catsEl.style.setProperty("--rail-cols", s.cols);
      catsEl.style.setProperty("--rail-fs", s.fs + "px");
      catsEl.style.setProperty("--rail-h", s.h + "px");
      catsEl.style.setProperty("--rail-gap", s.gap + "px");
      catsEl.style.setProperty("--rail-pad", s.pad);
      if (catsEl.scrollHeight <= catsEl.clientHeight + 1) return s;   // fits — stop here
    }
    return RAIL_STEPS[RAIL_STEPS.length - 1];                         // tightest we have
  };

  if (catsEl) catsEl.querySelectorAll("[data-jump]").forEach((b) => (b.onclick = () => jumpTo(b.dataset.jump)));
  listEl.addEventListener("scroll", () => { window.requestAnimationFrame(syncSpy); }, { passive: true });
  // Measured, so it must be re-measured whenever its size can change: the modal is laid
  // out a frame after it joins the page, the window can be resized, and a tablet rotating
  // changes everything. Whatever this modal starts, this modal ends (see onClose).
  if (catsEl) {
    window.requestAnimationFrame(() => fitRail());
    const onFit = () => fitRail();
    window.addEventListener("resize", onFit);
    window.addEventListener("orientationchange", onFit);
    onClose.push(() => { window.removeEventListener("resize", onFit); window.removeEventListener("orientationchange", onFit); });
  }

  bindList(); bindCart();
  // Quick mode's grid is sized from a MEASUREMENT, so it has to be re-measured whenever
  // the block it lives in changes size: the modal is laid out one frame after it is added
  // to the page, the window can be resized, and a phone rotating changes everything.
  if (quick) {
    requestAnimationFrame(fitBrowse);           // first real measurement, after layout settles
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(() => fitBrowse()) : null;
    if (ro) ro.observe(listEl);
    const onWin = () => fitBrowse();
    window.addEventListener("resize", onWin);
    window.addEventListener("orientationchange", onWin);
    onClose.push(() => { try { ro && ro.disconnect(); } catch {} window.removeEventListener("resize", onWin); window.removeEventListener("orientationchange", onWin); });
    // The phone's order bar: folded away, the menu owns the screen; tapped, the order
    // slides up over it. Place order and the running total never move either way, so the
    // one button that finishes the job is always under the thumb.
    const cartBtn = wrap.querySelector(".qo-cartbtn");
    const modalEl = wrap.querySelector(".to-modal");
    if (cartBtn && modalEl) cartBtn.onclick = () => {
      const open = modalEl.classList.toggle("qo-open");
      cartBtn.setAttribute("aria-expanded", open ? "true" : "false");
      const car = cartBtn.querySelector(".qo-cartcar"); if (car) car.textContent = open ? "▾" : "▴";
      fitBrowse(); // the browse block just changed size — re-fit to what's left
    };
  }
  const search = wrap.querySelector(".to-search");
  search.oninput = () => { q = search.value; paintList(); };
  wrap.querySelector(".to-note").oninput = (e) => { orderNote = e.target.value; };
  // The whole-order row. A TYPED allergy adds/removes a whole chip, so that case redraws
  // the row and rebinds; a standard chip only flips its class, which keeps the common
  // tap flicker-free. The row lives outside paintCart's markup, hence its own painter.
  const orderAlgEl = wrap.querySelector(".to-extras .to-alg");
  function paintOrderAlg() { if (!orderAlgEl) return; orderAlgEl.innerHTML = algChips(orderAvoid, "order"); bindOrderAlg(); }
  function bindOrderAlg() {
    wrap.querySelectorAll('.to-alg-chip[data-kind="order"]').forEach((chip) => (chip.onclick = async () => {
      if (chip.dataset.algOther) { const v = await allergyPrompt(orderAvoid); if (v) { orderAvoid.add(v); paintOrderAlg(); } return; }
      const s = chip.dataset.alg; orderAvoid.has(s) ? orderAvoid.delete(s) : orderAvoid.add(s);
      if (!ALG_STD.includes(s)) { paintOrderAlg(); return; }
      chip.classList.toggle("on", orderAvoid.has(s));
    }));
  }
  bindOrderAlg();
  wrap.querySelector(".tbl-modal-close").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };

  // − Discount. Deliberately the SAME openDiscountModal every bill on this floor uses, in its
  // pending mode — not a second discount screen. The owner asked for the interface he already
  // knows ("discount interface should be same as … the parcel detail view"), and a money UI
  // written twice is how one copy quietly drifts from the other (the open-price rule reached
  // one order screen a day late for exactly that reason). It is handed a synthetic bill made
  // of the cart: pre-tax subtotal, this restaurant's rate, and the amount already held.
  const discBtn = wrap.querySelector(".to-disc-btn");
  if (discBtn) discBtn.onclick = () => {
    const rate = (taxModel(state.data.settings) || {}).rate || 0;
    // The synthetic bill carries the SPLIT, not just a subtotal (mig 270), so the modal caps
    // on the taxable part and refuses out loud when someone tries to discount an MRP line —
    // the same answer the server would give a moment later, given before the tap instead of
    // after it. A PARCEL GETS THE SAME SPLIT: it is priced by the same splitBill() a table is
    // (see estTotal above), so pretending its whole value was discountable let a manager take
    // ₹250 off a bill with a ₹100 sealed bottle in it and only learn at the last tap.
    const sp = cartSplit();
    const cap = discCap();
    openDiscountModal(
      { discount: discOf(), discount_note: discNote },
      null, null,
      { rate, subtotal: Math.round((sp.taxableBase + sp.nontax) * 100) / 100, disc: discOf(),
        taxableBase: sp.taxableBase, nontax: sp.nontax, mrpAmount: sp.mrpAmount,
        discountBase: cap, discountFixed: Math.round((sp.taxableBase + sp.nontax - cap) * 100) / 100,
        composition: taxModel(state.data.settings).composition },
      true,                                   // whole-bill: nothing else on this order to preserve
      { onApply: (amount, note) => { discAmount = amount; discNote = note; paintCart(); } },
    );
  };

  // What THIS viewer may actually do with a quick order. An admin or owner looking in
  // gets both halves (the standing x-ray rule: a higher role sees every feature, tinted
  // where it's off for the staff below); a real manager gets exactly what the ladder
  // grants — module allowed by the admin, kept on by the owner, granted to them.
  const qopCan = (flag) => (XRAY_WHO && XRAY_WHO.higherView ? true : xrayGrantedForManager(flag));

  // ── QUICK mode, step 2: WHERE does this order go? ──────────────────────────────
  // Parcel first, as one wide bar across the top — it is the destination with no table
  // at all, so it does not belong in a grid of tables (owner, 2026-08-02). Under it,
  // every table, marked free or busy. A busy table joins that table's existing bill,
  // exactly as ＋ Take order on that table would.
  function openDestPicker() {
    dedupe();
    if (!cart.length) { toast("Add at least one dish first", "err"); return; }
    document.querySelector(".qo-dest-overlay")?.remove();
    const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
    const tiles = [];
    for (let i = 1; i <= n; i++) {
      // A JOINED TABLE IS NOT A FREE ONE (T18 sweep, 2026-08-16). summaryTableOpen() reads the
      // tile state, and a merged CHILD's own tile says "free" because its party lives on the
      // parent — the same lie the shift picker already guards against (mig 264) and the floor tile
      // already writes its own state for. So this grid offered T7 as "free" while T7 was joined to
      // T6, and the order then landed on T6's bill: the right bill, but not the one the person was
      // told they were opening. It names the bill it will join instead.
      const par = mergeParentOf(String(i));
      const busy = summaryTableOpen(i) || !!par;
      const mark = par ? `joins ${esc(tableLabel(par))}` : busy ? "joins bill" : "free";
      tiles.push(`<button class="qo-dest-t${busy ? " busy" : ""}" data-qodest="${i}"><b>${esc(tableLabel(i))}</b><small>${mark}</small></button>`);
    }
    // EACH destination re-checks its OWN permission here (owner, 2026-08-02). QO/P is one
    // door onto two features, so a manager given only one of them must be offered only that
    // one: parcel-only staff get the Parcel bar with no table grid, dine-in-only staff get
    // the tables with no Parcel bar. Checked in JS rather than left to the x-ray observer —
    // NOT because the observer can't see this picker (it can: applyHierarchyView queries
    // document-wide and observes document.body with subtree, corrected T18 2026-08-16), but
    // because these two destinations carry no XRAY_CONTROLS selector of their own, and a
    // destination that would be REFUSED must not be offered at all rather than shown greyed.
    // TWO gates per destination, and BOTH must pass (mig 258):
    //   · the admin's sub-switch under QO/P in Access — "may this screen send there at all";
    //   · the underlying permission — "may this person do that anywhere".
    // The sub-switch can only ever take away, never grant: a restaurant without "Take a new
    // order" gets no tables however qop_tables_allowed is set.
    const st = state.data.settings || {};
    const canTable = st.qop_tables_allowed !== false && qopCan("take_orders");
    // Plus the third gate, the one this screen was missing: does the restaurant HAVE the
    // Parcel feature (parcel_*, its own module again since mig 259 — not Platforms). No
    // x-ray exception: the server refuses a parcel on a restaurant without the module for
    // the admin as well, so showing the bar to a higher role only builds a wall.
    const canParcel = st.qop_parcel_allowed !== false && qopCan("parcel") && parcelModuleOn();
    const parcelBar = canParcel ? `<button class="qo-dest-parcel" data-qop-parcel="1">Parcel</button>` : "";
    const ov = el(`<div class="sx-modal-overlay qo-dest-overlay"><div class="sx-modal qo-dest-modal">
      <div class="tbl-modal-head"><div class="tp-detail-top"><h3>Where does it go?</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
      <div class="qo-dest-body">
        ${parcelBar}
        ${canTable
          ? `<div class="qo-dest-lbl">${parcelBar ? "…or send it to a table" : "Send it to a table"}</div><div class="qo-dest-grid">${tiles.join("")}</div>`
          : `<div class="qo-dest-lbl">Table orders aren't part of your access — this order goes out as a parcel.</div>`}
      </div>
    </div></div>`);
    document.body.appendChild(ov);
    const closeDest = () => ov.remove();
    ov.__lfhClose = closeDest;
    ov.querySelector(".tbl-modal-close").onclick = closeDest;
    ov.onclick = (e) => { if (e.target === ov) closeDest(); };
    // Parcel → the same /parcel path the 🥡 button uses, always PAY ON PICKUP: the order
    // now lives as a Parcel tile on the floor until it has been printed AND paid, which is
    // the whole reason the tile exists.
    const pb = ov.querySelector("[data-qop-parcel]");
    if (pb) pb.onclick = () => { closeDest(); parcel = true; send(false, "later"); };
    ov.querySelectorAll("[data-qodest]").forEach((b) => (b.onclick = () => { closeDest(); parcel = false; destTable = b.dataset.qodest; send(false, null); }));
  }

  async function send(confirmDuplicate = false, payMode = null) {
    dedupe();
    if (!cart.length) { toast("Add at least one dish first", "err"); return; }
    // Per-dish avoid + note ride in each item's note (no server change): "⚠ no X, Y · note".
    const items = cart.map((c) => {
      const parts = [c.avoid.size ? `⚠ no ${[...c.avoid].join(", ")}` : "", (c.note || "").trim()].filter(Boolean);
      // The typed price rides along ONLY for an open-price line; the server (lfh_price_order)
      // honours it just for a dish flagged open_price and prices everything else from the DB.
      return { id: c.id, qty: c.qty, price: c.open_price ? c.price : undefined, note: parts.join(" · ") || undefined };
    });
    const allergies = [...orderAvoid];

    // ── Parcel: a no-table TAKEAWAY order → /parcel (lands in the Platform board). ──
    if (parcel) {
      const payNow = payMode === "now";
      // Quick mode already asked the real question ("where does it go?") and was answered
      // with Parcel — asking again would be the second dialog on one decision.
      // "PAY NOW" ASKS HOW, IT DOES NOT ASSUME CASH (2026-08-05 — the third place this same
      // fault lived, after the floor's parcel tile and the Platform board's Collect button).
      // It posted method: "cash" unconditionally, so a parcel paid by UPI at the counter was
      // booked as cash and the day's cash-vs-digital split — the one a GST audit looks at —
      // was wrong by its whole value. The method sheet REPLACES the old yes/no confirm rather
      // than stacking on top of it: it asks a real question and it has its own Cancel, so this
      // is the same number of taps it always was, exactly as settling a table works.
      // Pay-on-pickup takes no money here, so it keeps the plain confirm.
      let payMethod = null;
      if (payNow) {
        // THE SHEET ASKS FOR WHAT THE PAPER WILL SAY (T18 sweep, 2026-08-16). This handed the sheet
        // `cartSub() - discOf()` — the PRE-TAX subtotal — while the /parcel route stores, and
        // printParcelReceipt prints, `splitBill(...).total` = subtotal − discount + tax. So the
        // counter was told to collect ₹250 on a parcel whose receipt and whose recorded sale both
        // said ₹263, and the till came up short by the tax on every counter-paid parcel. It is the
        // THIRD home of one fault: the on-screen quote (2026-08-05) and the stored total
        // (2026-08-02) were each moved onto the real total and this one was left behind. One
        // function answers now — estTotalNum() — so they cannot drift again.
        const picked = await openPaymentMethodModal(Math.max(0, estTotalNum()), "Take payment for this parcel", { methodOnly: true, crm: false });
        if (!picked || picked.special) return;   // cancelled — nothing is sent
        payMethod = picked.method;
      } else if (!quick && !(await confirmDialog("Send this parcel to the kitchen (pay on pickup)?", "Send"))) return;
      sendBtns.forEach((b) => (b.disabled = true));
      try {
        // The discount travels WITH the order (2026-08-03). Not a follow-up POST: a second call
        // can fail on its own, or land after "Pay now & print" has already put paper in a
        // customer's hand at the undiscounted price. The server re-clamps it to the food value
        // and re-checks this role's % cap — the client's number is a request, never the ruling.
        const r = await api("POST", "/parcel", { items, allergies, note: orderNote || null, customer: custName || null, phone: custPhone || null, paid: payNow, method: payMethod, discount: discOf() || undefined, discountNote: discOf() > 0 ? (discNote || undefined) : undefined });
        if (r && r.queued) { toast("Saved ✓ — the parcel will send when you're back online.", "ok"); close(); return; }
        toast(r && r.kot_no != null ? `Parcel sent! Ticket #${r.kot_no}${payNow ? " · paid" : " · pay on pickup"}` : "Parcel sent to the kitchen", "ok");
        // "Pay now & print" → a customer receipt for the counter printer (pay-on-pickup doesn't).
        //
        // THE DISCOUNT HAS TO TRAVEL ONTO THE PAPER (2026-08-05). This bag was built from the
        // cart alone and carried no discount, so printParcelReceipt read `o.discount` as
        // undefined, priced the full lines and added tax on all of them: a ₹500 parcel with
        // ₹50 off was charged ₹472.50 and the customer was handed a bill saying ₹525. The
        // parcel TILE's Print button never had this problem because it passes the stored row.
        // `total` is the server's own figure when it answered, so the fallback for a legacy
        // row with unpriced lines is the truth too, not the pre-discount sum.
        if (payNow) { try { printParcelReceipt({ kot: r && r.kot_no, phone: custPhone, bill_no: r && r.bill_no, invoice_no: r && r.invoice_no, invoice_at: r && r.invoice_at, created_at: r && r.created_at, items: cart.map((c) => ({ title: c.title, qty: c.qty, price: c.price })), total: (r && r.total != null) ? r.total : cart.reduce((s, c) => s + (parseFloat(c.price) || 0) * c.qty, 0), discount: discOf() || 0, discount_note: discOf() > 0 ? (discNote || null) : null, customer: custName, method: payMethod || "cash", paid: true }); } catch {} }
        close();
        try { loadPlatform(); } catch {}
        if (rerender) rerender();
      } catch (e) {
        sendBtns.forEach((b) => (b.disabled = false));
        toast("Couldn't send: " + ((e && e.message) || e), "err");
      }
      return;
    }

    // NO "are you sure" (owner, 2026-07-31 — "less clicks, no unnecessary two-time ask"). The
    // button you just pressed says "Send to kitchen" on a cart you built dish by dish; asking
    // again adds a tap to the single most repeated action of a service and teaches staff to
    // dismiss dialogs without reading them. A mis-send is still covered: the server refuses an
    // identical order within 3 seconds (which DOES ask, because then the question is real), and
    // the order can be cancelled from the table.
    sendBtns.forEach((b) => (b.disabled = true));
    try {
      // Same rule as the parcel path: the discount is part of the order, applied server-side in
      // the same request. On a table that ALREADY has a bill discount the server ADDS to it
      // rather than replacing it — a discount typed for these dishes must not silently wipe the
      // one the table was already given.
      const r = await api("POST", "/order", { table: String(destTable), items, allergies, note: orderNote || null, discount: discOf() || undefined, discountNote: discOf() > 0 ? (discNote || undefined) : undefined, ...(confirmDuplicate ? { confirmDuplicate: true } : {}) });
      if (r && r.queued) { toast("Saved ✓ — it'll send to the kitchen when you're back online.", "ok"); close(); await loadSessions(); if (rerender) rerender(); return; }
      // The pricer can REFUSE an order (sold out / off the menu / an open-price line with no
      // price) and still answer 200 with {ok:false}. Say so honestly and KEEP the cart open so
      // the flagged dish can be fixed and resent — never toast "sent" for an order that wasn't.
      if (!r || r.ok !== true) {
        const reason = r && r.reason, item = r && r.item;
        // The RPC runs its OWN double-tap guard under a per-table lock (mig 202) and answers 200
        // with duplicateWarning — a different shape from the route's 409 handled below. Re-offer
        // "send anyway" here too, or a genuine re-send would dead-end.
        if (r && r.duplicateWarning) {
          if (await confirmDialog("This looks identical to an order you just sent for this table. Send it AGAIN anyway?", "Send anyway")) return send(true);
          sendBtns.forEach((b) => (b.disabled = !cart.length));
          return;
        }
        // Plain language only — never surface a raw reason code to staff.
        const msg = reason === "sold_out" ? `😕 ${item || "A dish"} just sold out — remove it from the order and send again.`
          : reason === "unknown_item" ? `😕 ${item || "A dish"} is no longer on the menu — remove it and send again.`
          : reason === "price_required" ? `💰 ${item || "A dish"} needs a price — tap its amount in the order list and enter one.`
          : reason === "empty_order" ? "There's nothing in this order yet — add a dish first."
          : `Couldn't send the order${item ? ` (${item})` : ""}. Nothing was sent — please try again.`;
        toast(msg, "err");
        sendBtns.forEach((b) => (b.disabled = !cart.length));
        return;
      }
      toast(r && r.kot_no != null ? `Sent! Kitchen ticket #${r.kot_no}` : "Order sent to the kitchen", "ok");
      close(); await loadSessions(); if (rerender) rerender();
    } catch (e) {
      sendBtns.forEach((b) => (b.disabled = false));
      if (e && e.status === 409 && e.data && e.data.duplicateWarning) {
        if (await confirmDialog("This looks identical to an order you just sent. Send it anyway?", "Send anyway")) return send(true);
        return;
      }
      toast("Couldn't send: " + e.message, "err");
    }
  }
  // Quick mode's one button doesn't send — it asks WHERE first, and the picker sends.
  sendBtns.forEach((b) => (b.onclick = () => (quick ? openDestPicker() : send(false, b.dataset.pay || null))));
  bindDrill();
  syncSpy();
  // Quick mode leads with the category cards, so don't raise a keyboard over them.
  if (!quick) search.focus();
}

// Shift-table PICKER — mirrors the tablet's nice modal (was a bare prompt() here):
// a grid of the FREE tables to move this party (orders + calls + bill) onto. Only
// free tables show, so you can't pick an occupied one. (owner, 2026-06-18)
function openShiftPicker(t, sess) {
  document.querySelector(".shift-overlay")?.remove();
  const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  const free = [];
  // "Free to move to" = not THIS table, no party row on it at all, AND with no pending "wants in"
  // request (a request-only table reads as not-open, so without this a shift could land on a table
  // a guest is waiting to open, stranding their request).
  const reqTables = new Set((state.summary && state.summary.requests || []).map((r) => String(r.table_number)));
  // A merged CHILD is not a free table (mig 264): its own summary tile reads "free" (its party
  // lives on the parent), but shifting onto it would land a second party on a joined table.
  //
  // ⚠️ tableHasAnyParty, NOT summaryTableOpen (T3 sweep, 2026-08-06). The two are not the same
  // question and this door had the wrong one: summaryTableOpen reads the NORMALISED tile state, and
  // normalizeTileState turns a party row with no guests and no orders ('waiting') into **Free** —
  // so this list offered a table that already holds a party, the server refused with
  // `target_occupied`, and the manager was told a table the floor draws as Free "already has a party
  // on it". tableHasAnyParty exists precisely for this (see its own comment) and the DESKTOP door
  // — openKotColumns → freeTables() — has always used it. Two doors, one answer.
  // EVERY TABLE IS SHOWN, THE UNAVAILABLE ONES DIMMED (owner, 2026-08-07: "in the move table you
  // can also be able to see all the thing, but the thing which are filled will be greyed out").
  // Before this the list held only the free ones, so a table was simply ABSENT and a manager could
  // not tell whether T12 was missing because it was busy, because it was joined to another table, or
  // because his restaurant does not have a T12. Now the whole floor is on screen in order, and each
  // one that cannot take the party says WHY in a word. The reasons are exactly the conditions below,
  // and the server still refuses independently — this is presentation, never the guard.
  // ONE word each, deliberately: "party on it" wrapped onto two lines in a ~70px tile and made those
  // tiles taller than their neighbours, so the grid stopped reading as a grid.
  const whyBlocked = (i) => {
    if (String(i) === String(t)) return "this one";
    if (mergeParentOf(i)) return "joined";
    if (tableHasAnyParty(i)) return "taken";
    if (reqTables.has(String(i))) return "wants in";
    return "";
  };
  // floorTableList, not 1..n — an occupied table numbered above the count is a real place a party
  // can be moved to, and it was simply absent from this grid (T3 sweep, 2026-08-10).
  const allT = floorTableList(n);
  for (const i of allT) if (!whyBlocked(i)) free.push(i);
  const grid = allT.map((i) => {
    const why = whyBlocked(i);
    const label = tileFace(i);
    // A blocked table is a real <button> kept `disabled` rather than a <div>: it stays in the same
    // grid position and keeps its tooltip, and `disabled` is what stops the tap (and takes it out of
    // the tab order) without any handler of ours having to decide.
    return why
      ? `<button class="btn shiftpick shiftpick-off" disabled aria-disabled="true" title="${esc(label)} — ${esc(why)}"><span class="shiftpick-t">${esc(label)}</span><small class="shiftpick-why">${esc(why)}</small></button>`
      : `<button class="btn shiftpick" data-shiftto="${i}" title="Move this party to ${esc(label)}"><span class="shiftpick-t">${esc(label)}</span><small class="shiftpick-why">free</small></button>`;
  }).join("");
  const noneNote = free.length ? "" : `<div class="muted small" style="padding:0 14px 10px">Nothing is free right now — every table is either taken, joined, or waiting on a guest.</div>`;
  const wrap = el(`<div class="sx-modal-overlay shift-overlay"><div class="sx-modal shift-modal"><div class="tbl-modal-head"><div class="tp-detail-top"><h3>Move ${esc(tableLabel(t))} →</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div><div class="muted small" style="padding:0 14px 10px">Move this party — orders, calls &amp; bill included — to a free table. Dimmed tables can't take it:</div>${noneNote}<div class="shiftgrid">${grid}</div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  wrap.querySelectorAll("[data-shiftto]").forEach((b) => (b.onclick = async () => {
    const to = b.dataset.shiftto; closeM();
    try {
      const r = await api("POST", `/sessions/${sess.id}/shift`, { to });
      if (!r.ok) { toast("Couldn't shift: " + (KOT_REASON_TEXT[r.reason] || r.reason || ""), "err"); return; }
      okToast(r, `Shifted to ${tileFace(to)}`);
      followShiftedTable(t, to); // follow the party to its new home in docked OR popup mode
    } catch (e) { toast("Failed: " + e.message, "err"); }
  }));
}

// ── KOT ▾ — Table & KOT operations (PetPooja-style unified menu; owner 2026-07-22) ──
// ONE menu on the table detail for every table/bill operation. Ladder-gated (mig 172):
// admin depth knob → owner grants manager → (tablet has its own rung). Ops arrive in
// phases — the menu lists only what's built, so it grows without UI rework.
// Whether to render the KOT ▾ menu for THIS viewer — the ADMIN X-RAY rule (owner,
// 2026-07-22): from the admin console EVERY feature renders, greyed (xray-off tint via
// XRAY_CONTROLS) when it's not actually on for the real staff, and it genuinely works
// when the admin taps it (the server's tableOpsGate lets the admin super-user through).
// Everyone else follows the ladder: the MODULE must be effective (whoami
// features.table_ops — admin switch AND, when transferred, the owner's toggle); a real
// manager additionally needs the owner's table_ops grant (effectivePowers), while the
// OWNER's higherView sees it tinted when the manager grant is off. Before whoami
// resolves we render the plain Shift fallback — never a button that would 403.
function tableOpsOn() {
  const w = XRAY_WHO;
  if (!w) return false;
  if (w.actor === "admin") return true; // admin view: always visible, tinted when off-for-staff
  if (!(w.features && w.features.table_ops)) return false; // module off: gone for owner + manager
  return w.higherView ? true : !!(w.effectivePowers && w.effectivePowers.table_ops);
}

// One-time styles for the KOT action sheet + its pickers — a proper PetPooja-grade
// surface, not bare buttons (owner design feedback, 2026-07-22). Uses the panel's own
// CSS variables so it follows the theme.
(function injectKotMenuStyles() {
  const css = `
  .kotm-sheet { max-width: 460px; }
  .kotm-head { padding: 16px 18px 10px; }
  .kotm-title { display:flex; align-items:center; gap:10px; }
  .kotm-title h3 { margin:0; font-size:17px; }
  .kotm-bill { color: var(--muted); font-size:12.5px; margin-top:3px; }
  .kotm-list { padding: 6px 12px 14px; }
  .kotm-row { display:flex; align-items:center; gap:13px; width:100%; text-align:left;
    background: var(--panel-2); border:1px solid var(--line); border-radius:12px;
    padding:14px 16px; margin:0 0 9px; cursor:pointer; font:inherit; color:inherit;
    transition: transform .06s, border-color .12s, background .12s; }
  .kotm-row:hover:not(:disabled) { border-color: var(--gold); background: color-mix(in srgb, var(--gold) 6%, var(--panel-2)); }
  .kotm-row:active:not(:disabled) { transform: scale(.985); }
  .kotm-row:disabled { opacity:.45; cursor:default; }
  .kotm-ico { width:46px; height:46px; border-radius:11px; flex:none; display:flex; align-items:center;
    justify-content:center; font-size:19px; background: color-mix(in srgb, var(--gold) 13%, transparent);
    border:1px solid color-mix(in srgb, var(--gold) 30%, transparent); }
  .kotm-txt b { font-size:15.5px; display:block; }
  .kotm-txt small { color: var(--muted); font-size:12.5px; line-height:1.35; display:block; margin-top:1px; }
  .kotm-chev { margin-left:auto; color: var(--muted); font-size:15px; flex:none; }
  .kotm-off-why { font-size:10.5px; color: var(--muted); border:1px solid var(--line);
    border-radius:999px; padding:2px 8px; margin-left:auto; flex:none; }
  .tp-kot-head { font-weight:700; }
  .kotm-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(88px,1fr)); gap:8px; padding:4px 0 6px; }
  .kotm-tile { border:1px solid var(--line); border-radius:12px; background:var(--panel-2);
    padding:10px 6px; text-align:center; cursor:pointer; font:inherit; color:inherit; }
  .kotm-tile b { display:block; font-size:15px; }
  .kotm-tile small { display:block; color:var(--muted); font-size:10.5px; margin-top:2px; }
  .kotm-tile.occ { border-color: color-mix(in srgb, var(--gold) 45%, transparent);
    background: color-mix(in srgb, var(--gold) 8%, var(--panel-2)); }
  .kotm-tile:hover:not(:disabled) { border-color: var(--gold); }
  /* A table that cannot take the party is DIMMED, not hidden (owner, 2026-08-07): it keeps its place
     in the grid and says why in a word, so "T12 is busy" reads differently from "there is no T12". */
  .kotm-tile-off { opacity: .42; cursor: default; border-style: dashed; background: transparent; }
  .kotm-tile-off small { font-weight: 700; white-space: nowrap; }
  /* THE TABLE PICKER (owner, 2026-08-01): as wide as the screen allows, as many tables per row as
     fit, and each one wearing its own state colour + words. Same --c state variables the floor
     tiles use (.ft-free/.ft-prep/…), so the popup and the floor can never disagree. */
  /* IT SHOULD LOOK LIKE THE FLOOR (owner, 2026-08-01: "I wanted it with colour and stuff just like
     the table live view, and all square same … it's too wide, keep the max width, not this broad").
     So: SQUARE tiles, the same state colours as a floor tile (the ft-* classes carry --c, and this
     sheet inherits them), and a sheet that is a panel rather than the whole window. The placement
     never changes with content — every tile holds the same rows whether it has one ticket or five. */
  .kotp-sheet { max-width: min(92vw, 880px); width: min(92vw, 880px); }
  /* --kotp-min is the tile's minimum width, and fitKotPicker() below LOWERS it until the whole
     floor fits on one screen (owner, 2026-08-14: "when the amount of table is more that we have to
     scroll, at that time make it like it will show all on table first"). It is a starting point
     here, not a fixed size. */
  .kotp-grid { grid-template-columns: repeat(auto-fill, minmax(var(--kotp-min, 96px), 1fr));
    gap: var(--kotp-gap, 9px); padding: 2px; }
  /* ONE scroller for the whole picker, not one per grid — the sheet now holds two SECTIONS
     (in use, then free) and a scrollbar per section would be two thumbs on one sheet. */
  .kotp-scroll { max-height: min(64vh, 560px); overflow-y: auto; }
  /* EXPAND IT ON A PHONE (owner, 2026-08-13: "also expand the selection screen and stuff").
     The desktop cap he asked for on 2026-08-01 — "it's too wide, keep the max width, not this
     broad" — is untouched above; this only widens and lengthens the sheet where the screen is
     small, because at 360px the old 92vw + 96px columns showed about two tables at a time. */
  @media (max-width: 760px) {
    /* The overlay's own 20px padding was the real cap — it left a 360px phone a 320px sheet no
       matter what width the sheet asked for. 8px here is what actually widens it. */
    .kotpick-overlay { padding: 8px; }
    .kotp-sheet { max-width: 100%; width: 100%; max-height: 94vh; }
    .kotp-grid { --kotp-min: 78px; --kotp-gap: 7px; }
    .kotp-scroll { max-height: calc(94vh - 132px); }
  }
  /* AUTO-SWITCH BY COUNT (owner, 2026-08-13: "when there are less table which can be visible on
     the screen then ok, but when there are more then it auto switch"). A big floor gets denser
     squares so more of it lands on one screen. Small but NOT too small — 62px stays above the
     44px tappable floor, and the least useful line (the sub-line) is the only thing that goes. */
  /* ── IT FITS, IT DOES NOT SCROLL (owner, 2026-08-14) ──────────────────────────────────────
     "When the amount of table is more that we have to scroll — at that time make it like it will
     show all on table first." So the size is MEASURED, not guessed: fitKotPicker() shrinks
     --kotp-min a step at a time until the sections stop overflowing their box. That keeps his
     earlier "auto switch" rule (2026-08-13) and goes further — a 48-table floor and a 300-table
     floor both land on one screen instead of only the first one doing so.
     WHAT SHRINKING COSTS, shed in the same priority order the floor tiles use: first the sub-line
     (₹ due / served count), then the state word, then the paid/unpaid pill. The NUMBER and the
     STATE COLOUR never go — those are what you are picking by.
     THE FLOOR IS 44px AND IS NOT NEGOTIABLE: below that a square stops being reliably tappable, so
     a floor too big to fit at 44px scrolls, honestly, rather than becoming untappable. */
  .kotp-scroll.kotp-sm .kotp-tile b { font-size: 14px; }
  .kotp-scroll.kotp-sm .kotp-tile .kotp-state { font-size: 9px; }
  .kotp-scroll.kotp-sm .kotp-tile .kotp-meta { display: none; }
  .kotp-scroll.kotp-xs .kotp-tile { padding: 4px 3px; }
  .kotp-scroll.kotp-xs .kotp-tile b { font-size: 12.5px; }
  .kotp-scroll.kotp-xs .kotp-tile .kotp-state,
  .kotp-scroll.kotp-xs .kotp-tile .kotp-pay { display: none; }
  /* SECTIONS — IN USE FIRST, FREE AFTER (owner, 2026-08-13). Every operation behind this button
     (merge, move a KOT, split, reprint, mark VIP) is about a table that has something on it, and
     on a 300-table floor the two that were in use sat buried under 298 free ones. Free tables stay
     pickable — marking a table VIP before the guests order is one reason this button exists. */
  .kotp-sec-title { display: flex; align-items: center; gap: 8px; margin: 12px 2px 8px;
    font-size: 11.5px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
  .kotp-sec-title:first-child { margin-top: 2px; }
  .kotp-sec-title .n { color: var(--text); }
  .kotp-sec-title::after { content: ""; flex: 1 1 auto; height: 1px; background: var(--line); }
  .kotp-empty { margin: 2px 2px 8px; font-size: 12px; color: var(--muted); }
  /* NO --c HERE. This stylesheet is injected at runtime, so it lands AFTER style.css: setting --c
     on .kotp-tile beat the .ft-prep / .ft-bill state colours the tile also carries, and every tile
     came out the neutral grey. The ft-* class is the one source of the state colour (.ft-free
     supplies the grey), exactly as on the floor. */
  .kotp-tile { aspect-ratio: 1 / 1; min-height: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 1px; padding: 7px 6px; text-align: center;
    border-radius: 14px; border: 1.5px solid color-mix(in srgb, var(--c) 55%, var(--line));
    background: linear-gradient(157deg, color-mix(in srgb, var(--c) 16%, var(--panel)), var(--panel) 78%);
    transition: transform .12s ease, box-shadow .16s ease; }
  .kotp-tile:hover { transform: translateY(-2px); box-shadow: 0 10px 24px rgba(0,0,0,0.4); border-color: var(--gold); }
  .kotp-tile b { font-size: 17px; font-weight: 800; color: color-mix(in srgb, var(--c) 78%, var(--text)); }
  .kotp-tile .kotp-state { display:block; font-size:10px; font-weight:700; color: color-mix(in srgb, var(--c) 72%, var(--text)); }
  /* WRAPS, never truncates (T11 desktop sweep 2026-08-05). This was nowrap+ellipsis in an
     84px box holding a ~100px string, so EVERY busy tile cut the money off mid-number:
     "0/1 served · ₹48…" when the truth was "₹483 due", and "₹1,4…" for ₹1,407. An ellipsis
     inside a number is the worst place for one — ₹48 is a believable amount, so a manager had
     no way to know it was wrong, and the word "due" was cut off too. The tile has vertical
     room, so the line wraps instead; the money keeps its own unbroken chunk. */
  .kotp-tile .kotp-meta { display:block; font-size:9px; color: var(--muted); line-height:1.25; max-width:100%;
    white-space:normal; overflow-wrap:anywhere; }
  .kotp-tile .kotp-pay { display:inline-block; margin-top:2px; font-size:8.5px; font-weight:800; letter-spacing:.04em; text-transform:uppercase;
    padding:1px 5px; border-radius:999px; border:1px solid currentColor; }
  .kotp-tile .kotp-pay.unpaid { color:#ef4444; }
  .kotp-tile .kotp-pay.paid   { color:#22c55e; }
  /* Same light-mode lift the floor tiles get, or the colour vanishes over a white panel. */
  html[data-theme="light"] .kotp-tile { background: linear-gradient(157deg, color-mix(in srgb, var(--c) 32%, var(--panel)), var(--panel) 82%); }
  html[data-theme="light"] .kotp-tile.ft-bill, html[data-theme="light"] .kotp-tile.ft-waiting {
    background: linear-gradient(157deg, color-mix(in srgb, var(--c) 58%, var(--panel)), var(--panel) 84%); }
  /* Miller columns (desktop, owner 2026-07-23): panels sit SIDE BY SIDE like the Mac
     Finder's column view — the card grows a column per step, selections stay lit. */
  .kotm-colwrap { max-width: min(96vw, 1280px); width: fit-content; }
  .kotm-head { display: block; }
  .kotm-cols { display: flex; align-items: stretch; padding: 6px 8px 14px; max-width: 100%; overflow-x: auto; }
  /* ── THE FIRST COLUMN NEVER SCROLLS (owner, 2026-08-01) ────────────────────────────────
     "All should be shown at one there, so it not be scrollable — at least not for this first
     one where all the features are listed." He also said the card itself felt small, so the
     tiles got wider and the sheet grew rather than the text shrinking to nothing.
     Two across × 4 rows holds the seven operations with room for an eighth if we add one;
     no max-height and no overflow here, so nothing can hide below a fold. */
  /* TWO classes on purpose: the generic .kotm-col rule (width 360px) is declared BELOW this
     block in the same injected stylesheet, so a single-class selector here loses the width to it
     and the tiles come out 165px wide with every label wrapping.
     NOTE: this whole stylesheet is a JS template literal — never put a backtick in a comment
     here, it ends the string and takes the entire panel down with a syntax error. */
  /* ONE COLUMN, BIGGER (owner, 2026-08-01: "1 colum manage — why making small, this UI look more
     shittier, make it bigger if possible"). Two across made each tile ~236px and stacked the icon
     over the words, which read as cramped. One column at 470px puts the icon BESIDE the text like
     a proper menu row, and each row is taller and easier to hit. Seven rows (six with Split off,
     its new default) at ~70px still fit with NO scrolling — his other rule. */
  .kotm-col.kotm-col-ops { width: 470px; max-height: none; overflow: visible; }
  .kotm-ops { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; padding: 2px 0 4px; }
  .kotm-op { display: flex; flex-direction: row; align-items: center; gap: 13px; width: 100%;
    text-align: left; padding: 11px 14px; border-radius: 13px; border: 1px solid var(--line);
    background: var(--panel-2); color: var(--text); cursor: pointer;
    transition: border-color .14s ease, background .14s ease, transform .1s ease; }
  .kotm-op .kotm-txt { flex: 1 1 auto; min-width: 0; }
  .kotm-op:hover:not(:disabled) { border-color: var(--gold); background: color-mix(in srgb, var(--gold) 7%, var(--panel-2)); }
  .kotm-op:active:not(:disabled) { transform: scale(.985); }
  .kotm-op:disabled { opacity: .45; cursor: default; }
  .kotm-op.sel { border-color: var(--gold); background: color-mix(in srgb, var(--gold) 14%, var(--panel-2)); }
  .kotm-op .kotm-ico { width: 40px; height: 40px; border-radius: 11px; font-size: 20px; flex: none; }
  .kotm-op .kotm-txt b { font-size: 15px; line-height: 1.2; }
  .kotm-op .kotm-txt small { font-size: 12px; line-height: 1.3; }
  .kotm-op .kotm-off-why { flex: none; margin-left: auto; }
  /* A phone keeps the same one-per-row shape (it may scroll there — a phone screen cannot hold
     seven rows, and his no-scroll rule was about the desktop card he was looking at). */
  @media (max-width: 620px) {
    .kotm-col.kotm-col-ops { width: 100%; }
  }
  /* FIVE TABLES A ROW IN THE PICKER (owner, 2026-08-01: "5 table in 1 row, little bit make table
     some small and that thing big"). It was four across at 78px minimum, so a 30-table floor
     needed 8 rows and scrolled; five smaller tiles fit 30 tables in 6 rows in the same column. */
  /* Three classes deep on purpose: the generic two-class rule for .kotm-grid (auto-fill, 78px) is
     declared further DOWN this same injected stylesheet, so a two-class selector here would lose to
     it and the picker would stay four across. (Same trap as the column width above.) */
  .kotm-cols .kotm-col .kotm-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 7px; }
  .kotm-cols .kotm-col .kotm-tile { padding: 7px 4px; }
  .kotm-cols .kotm-col .kotm-tile b { font-size: 13.5px; }
  .kotm-cols .kotm-col .kotm-tile small { font-size: 9.5px; }
  /* A joined party is one button and it wears the floor's purple, so the picker and the floor
     agree about what "merged" looks like. Its label is wider than "T6", so it spans two cells. */
  .kotm-tile-party { --c: #a855f7; grid-column: span 2; }
  .kotm-tile-party b { font-size: 12.5px; letter-spacing: -0.01em; }
  .kotm-col { width: 360px; flex: none; padding: 6px 10px; overflow-y: auto;
    max-height: min(64vh, 560px); border-right: 1px solid var(--line);
    animation: kotmColIn .16s ease-out; }
  .kotm-col:last-child { border-right: 0; }
  .kotm-col .kotm-grid { grid-template-columns: repeat(auto-fill, minmax(78px, 1fr)); }
  .kotm-col-title { font-size: 12px; font-weight: 700; color: var(--muted);
    text-transform: uppercase; letter-spacing: .03em; margin: 4px 2px 10px; }
  .kotm-row.sel { border-color: var(--gold);
    background: color-mix(in srgb, var(--gold) 14%, var(--panel-2)); }
  .kotm-row.sel .kotm-chev { color: var(--gold); font-weight: 800; }
  @keyframes kotmColIn { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }`;
  const s = document.createElement("style"); s.textContent = css; document.head.appendChild(s);
})();

// ── MILLER COLUMNS (owner design pattern, 2026-07-23 — "like the Mac Finder") ──
// On a DESKTOP the KOT flows drill ACROSS, not back-and-forth: panel 1 = the
// operations, panel 2 = what to move (KOT / dish / target for 2-step ops), panel 3 =
// where to move it. Each selection stays highlighted so the whole path reads at a
// glance. Phones keep the step-by-step sheets (openKotMenu below). This is the
// STANDING pattern for every future multi-step popup on desktop.
// What each KOT operation actually does — shown as the hover tooltip on its row.
const KOT_TIPS = {"shift": "Moves this whole party — every order, waiter call and the bill — onto an empty table. The old table frees up instantly and the guests' phones follow automatically.", "merge": "Joins this party with another table's party: everything combines into ONE bill on the other table (discounts add up too). Use it when two groups decide to sit together.", "movekot": "Sends ONE order (one kitchen ticket) to another table's bill — for when a single order was punched on the wrong table. Both bills recalculate themselves.", "moveitem": "Sends a single dish to another table. It gets its own new kitchen ticket there, and both bills re-price automatically. A 2-plate line moves both plates.", "split": "Collect one bill as several payments: equal shares, custom amounts, or assign dishes per person. The shares must add up to the bill — the system checks.", "reprint": "Prints an order's kitchen ticket again — either right here on this device, or sent to the KITCHEN's own printer, where it comes out marked DUPLICATE in big letters. Nothing changes on the bill."};

// ── HOVER TOOLTIPS (owner, 2026-07-23): hovering ANY button that carries a title/
// data-tip shows a styled bubble describing what it does ("how it works"). One host
// element + document-level delegation, so every current AND future button is covered
// with zero per-feature wiring — give a button a `title` and it just works.
(function tipEngine() {
  const HOLD_MS = 2000; // owner 2026-07-23: only show after the pointer rests ~2s (no flicker while sweeping)
  const host = document.createElement("div");
  host.className = "lfh-tip";
  document.body.appendChild(host);
  let cur = null, timer = null;
  const hide = () => { cur = null; if (timer) { clearTimeout(timer); timer = null; } host.classList.remove("on"); };
  const showFor = (el) => {
    const r = el.getBoundingClientRect();
    host.textContent = el.dataset.tip;
    host.classList.add("on");
    const w = host.offsetWidth, h = host.offsetHeight;
    host.style.left = Math.max(8, Math.min(window.innerWidth - w - 8, r.left + r.width / 2 - w / 2)) + "px";
    host.style.top = (r.top - h - 9 > 6 ? r.top - h - 9 : r.bottom + 9) + "px";
  };
  document.addEventListener("mouseover", (e) => {
    const el = e.target.closest && e.target.closest("[data-tip], button[title], .btn[title]");
    if (el === cur) return;
    // Moving to a different (or no) target: drop the running timer + any shown bubble.
    if (timer) { clearTimeout(timer); timer = null; }
    host.classList.remove("on");
    cur = el || null;
    if (!el) return;
    // Migrate a native title to data-tip once so the browser's own tooltip never doubles up.
    if (!el.dataset.tip && el.title) { el.dataset.tip = el.title; el.removeAttribute("title"); }
    if (!el.dataset.tip) { cur = null; return; }
    // Only reveal once the pointer has RESTED on this element for HOLD_MS (a stable hover).
    timer = setTimeout(() => { if (cur === el) showFor(el); }, HOLD_MS);
  });
  document.addEventListener("mouseout", (e) => { const el = e.target.closest && e.target.closest("[data-tip]"); if (el && el === cur) hide(); });
  document.addEventListener("scroll", hide, true);
  document.addEventListener("click", hide, true);
})();

function openKotColumns(t, sess) {
  document.querySelector(".kotmenu-overlay")?.remove();
  const movable = ordersForTable(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid");
  const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  // THE FLOOR'S OWN TABLE LIST, not 1..table_count (T3 sweep, 2026-08-10). floorTableList exists
  // because a table numbered ABOVE the count can still be occupied and must never vanish with its
  // money — but every picker in this file rebuilt a bare 1..n range, so the floor could draw table
  // 34 with a live bill and no menu here would let you merge into it or move anything to it.
  const tables = floorTableList(n);
  let occupiedOthers = 0;
  for (const i of tables) if (String(i) !== String(t) && summaryTableOpen(i)) occupiedOthers++;
  // The header's "bill due" is the PARTY's bill — a merged parent's movable list is per-table
  // (that is what Move-a-KOT needs), but the money line must never show half a joint bill.
  const bill = billMath(partyOrders(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid" && o.status !== "received"));
  // WHAT THE FLOOR SAYS, NOT WHAT THE DATABASE SAYS (T3 sweep, 2026-08-10). Change table and Merge
  // gated on the raw session row, so a table drawn **Free** — a party row with no guests and no
  // orders, which normalizeTileState deliberately shows as Free — offered both. That is the exact
  // contradiction the owner reported on 2026-08-01 ("table 30 looks closed but at back-end it says
  // it's open … and you merge table it shows table 30 as open, why all this"): it was answered for
  // the TARGET lists (summaryTableOpen / tableHasAnyParty) and the source gate was left behind.
  const liveHere = !!sess && summaryTableOpen(t);
  const movableTotal = movable.reduce((s2, o) => s2 + (parseFloat(o.total) || 0), 0);
  const OPS = [
    // Works on an EMPTY table too — see the note in openKotMenu.
    { id: "type", icon: TABLE_TAG_INFO[tagForTable(t)] ? TABLE_TAG_INFO[tagForTable(t)].emoji : "🏷", label: "Table type", sub: "VIP · Family · Owner's guest", on: tagActionAllowed("table_tags"), why: "not enabled" },
    // A MERGED PARTY DOES NOT SHIFT (mig 264): moving it would renumber the child's orders —
    // the numbers an unmerge needs to be exact — and strand the merge record. The server
    // refuses too ('party_merged'); this row says why instead of offering a dead end.
    { id: "shift", icon: "⇄", label: "Change table", sub: "To a free table", on: liveHere && !mergeGroupLabel(t), why: mergeGroupLabel(t) ? "unmerge first" : "table is free" },
    // THE MONEY IS ON THE ROW (owner, 2026-08-11 — improvement 5). Merge and Move-a-KOT are the two
    // operations here that change whose bill money sits on, and the amounts were only ever shown a
    // step later. The hover tip explains them after a 2-second rest, which nobody waits for
    // mid-service; the number is the part you actually weigh up.
    { id: "merge", icon: "🪢", label: "Merge tables", sub: bill.total > 0 ? `One table, one bill · this side ${inr(bill.total)}` : "One table, one bill",
      // A JOINED TABLE IS NOT A CLOSED ONE (T3 sweep, 2026-08-10). A merged child has no session of
      // its own, so this row went dark with the chip "table closed" — about a table serving food on
      // an open bill. The row above it has said "unmerge first" for that case since mig 264.
      on: liveHere && occupiedOthers > 0, why: mergeGroupLabel(t) && !sess ? "unmerge first" : !liveHere ? "table is free" : "no other open table" },
    { id: "movekot", icon: "🧾", label: "Move a KOT", sub: movable.length ? `One order moves · ${movable.length} KOT${movable.length === 1 ? "" : "s"}, ${inr(movableTotal)}` : "One order moves", on: movable.length > 0, why: "no movable KOT" },
    { id: "moveitem", icon: "🍛", label: "Move a single dish", sub: "One dish moves", on: movable.some((o) => orderItemRows(o).some((r) => r.kind === "session")), why: "no movable dish" },
    { id: "reprint", icon: "🖨️", label: "Print / reprint a KOT", sub: "Here, or in the kitchen", on: ordersForTable(t).some((o) => o.status !== "cancelled"), why: "no KOTs" },
    // LAST, and only when the restaurant has switched it on (owner, 2026-08-01: "split a bill
    // should be on the last"). Sitting mid-list it was one mis-tap from a half-settled table.
    ...(splitBillOn() ? [{ id: "split", icon: "🍴", label: "Split the bill", sub: "Equal · custom · by dish", on: movable.some((o) => o.status !== "received"), why: "nothing settleable" }] : []),
  ];
  let sel1 = null, sel2 = null; // op id · chosen KOT/dish id
  const wrap = el(`<div class="sx-modal-overlay kotmenu-overlay"><div class="sx-modal kotm-colwrap">
    <div class="tbl-modal-head kotm-head"><div class="tp-detail-top"><div class="kotm-title"><h3>🧾 ${esc(tileFace(t))}</h3></div><button class="tbl-modal-close" aria-label="Close">✕</button></div>
    <div class="kotm-bill">KOT &amp; table operations${bill.total > 0 ? ` · bill due ${inr(bill.total)}` : ""}${sess && sess.bill_no != null ? ` · bill #${esc(sess.bill_no)}` : ""}</div></div>
    <div class="kotm-cols"></div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  const colsEl = wrap.querySelector(".kotm-cols");

  const done = (msg) => { closeM(); toast(msg, "ok"); };
  const fail = (m) => toast(m, "err");
  // okMsg may be a FUNCTION of the server's answer. Merge needs that: the RPC decides which table
  // survives (always the lower number), so a message built from the table that was TAPPED can name
  // the wrong one — "Merged into table 9" when the bill went to 4 (T3 sweep, 2026-08-10).
  const run = async (method, path, body, okMsg, after) => {
    try {
      const r = await api(method, path, body);
      if (r && r.ok === false) { fail("Couldn't do that: " + (KOT_REASON_TEXT[r.reason] || r.reason || "rejected")); return; }
      done(typeof okMsg === "function" ? okMsg(r) : okMsg); if (after) after(r);
    } catch (e) { fail("Failed: " + e.message); }
  };

  // Tile grids per purpose. `mark` = the currently-selected tile (kept highlighted).
  // A JOINED PARTY IS ONE CHOICE, NAMED AS ONE THING (owner, 2026-08-01: "if you click the eight
  // table and go inside merge the table, then it will show six plus seven … no hierarchy").
  // labelOf lets a picker print "T6 + T7" on the single button that stands for that whole party;
  // the VALUE stays the table that holds the bill, which is what the server needs.
  // tileFace, not "T"+i: a restaurant that names its tables sees those names on the floor, so a
  // picker that says "T7" is asking about something the manager cannot see (T3 sweep, 2026-08-10).
  const partyLabel = (i) => {
    const kids = mergeChildrenOf(i);
    return kids.length ? [tileFace(i), ...kids.map((k) => tileFace(k))].join(" + ") : tileFace(i);
  };
  const tiles = (list, attr, subOf, labelOf) => `<div class="kotm-grid">` +
    list.map((i) => `<button class="kotm-tile${summaryTableOpen(i) ? " occ" : ""}${mergeChildrenOf(i).length ? " kotm-tile-party" : ""}" data-${attr}="${i}"><b>${esc((labelOf || partyLabel)(i))}</b><small>${subOf(i)}</small></button>`).join("") + `</div>`;
  // The same grid, but showing tables that CANNOT be picked as dimmed and disabled instead of
  // leaving them out (owner, 2026-08-07). `blocked(i)` returns a one-word reason or "" — a table with
  // a reason keeps its place in the grid and says why, so a manager can tell "T12 is busy" apart from
  // "this restaurant has no T12". The pickable ones behave exactly as before.
  const tilesAll = (attr, subOf, blocked) => `<div class="kotm-grid">` +
    tables.map((i) => {
      const why = blocked(i);
      if (why) return `<button class="kotm-tile kotm-tile-off" disabled aria-disabled="true" title="${esc(partyLabel(i))} — ${esc(why)}"><b>${esc(partyLabel(i))}</b><small>${esc(why)}</small></button>`;
      return `<button class="kotm-tile${summaryTableOpen(i) ? " occ" : ""}${mergeChildrenOf(i).length ? " kotm-tile-party" : ""}" data-${attr}="${i}"><b>${esc(partyLabel(i))}</b><small>${subOf(i)}</small></button>`;
    }).join("") + `</div>`;
  // A "free" target must have NO party row at all — not even the invisible empty one the floor
  // draws as Free (see tableHasAnyParty). Moving a party onto it would put two sessions on one
  // table, and the second one is the kind of thing nobody notices until a bill is wrong.
  // …and a merged CHILD is never "free" either: it has no party row of its own, so
  // tableHasAnyParty can't see it, but shifting onto it would land a second party on a joined
  // table (the server refuses too — 'merged_child', mig 264; this list just never offers it).
  // ONE definition of "why not this table", used both to build the free list and to LABEL the dimmed
  // ones — so the list and the reason can never disagree (the exact drift that made the phone's
  // picker offer a table the desktop refused, T3 sweep 2026-08-06).
  const shiftBlocked = (i) => {
    if (String(i) === String(t)) return "this one";
    if (mergeParentOf(i)) return "joined";
    if (tableHasAnyParty(i)) return "taken";
    if ((state.summary && state.summary.requests || []).some((r) => String(r.table_number) === String(i))) return "wants in";
    return "";
  };
  // MOVING SOMETHING INSIDE ONE PARTY IS NOT A MOVE (T3 sweep, 2026-08-10). The move pickers offered
  // every other table, so on a T6+T7 party "Move a KOT from T6" showed T7 labelled "joins bill" —
  // and lfh_staff_move_order resolves T7 to T6's own bill and answers 'same_table'. A tap that can
  // never succeed, on a screen that already knows how to dim an impossible target.
  const moveBlocked = (i) => {
    if (String(i) === String(t)) return "this one";
    return partyTablesOf(t).some((x) => String(x) === String(i)) ? "same bill" : "";
  };
  const freeTables = () => tables.filter((i) => !shiftBlocked(i));
  const occTables = () => tables.filter((i) => String(i) !== String(t) && summaryTableOpen(i));
  const tileDue = (i) => { const tile = (state.summary && state.summary.tiles || {})[String(i)]; return tile && tile.due > 0 ? "due " + inr(tile.due) : "open"; };
  const kotCard = (o, attr) => { const nd = orderItemRows(o).reduce((s2, r) => s2 + (parseInt(r.qty, 10) || 1), 0); return `<button class="kotm-row${sel2 === o.id ? " sel" : ""}" data-${attr}="${esc(o.id)}"><span class="kotm-txt"><b>KOT #${o.kot_no != null ? esc(o.kot_no) : "—"}</b><small>${nd} dish${nd === 1 ? "" : "es"} · ${inr(parseFloat(o.total) || 0)}</small></span><span class="kotm-chev">›</span></button>`; };

  // What panel 2 shows per operation; ops with a 3rd step mark their picks sel-able.
  const col2 = () => {
    // Shift shows the WHOLE floor with the unavailable tables dimmed — same as the phone's own
    // picker, and the same four reasons in the same words, so the two doors read alike.
    if (sel1 === "shift") return { title: "Move to which table?", html: tilesAll("goshift", () => "free", shiftBlocked)
      + (freeTables().length ? "" : `<div class="muted" style="padding:10px">Nothing is free right now — every table is either taken, joined, or waiting on a guest.</div>`) };
    if (sel1 === "merge") return { title: "Join which party?", html: tiles(occTables(), "gomerge", (i) => (mergeChildrenOf(i).length ? "merged party · " + tileDue(i) : tileDue(i))) };
    if (sel1 === "movekot") return { title: "Which KOT moves?", html: movable.map((o) => kotCard(o, "pickkot")).join("") };
    if (sel1 === "moveitem") {
      const groups = movable.map((o) => {
        const items = orderItemRows(o).filter((r) => r.kind === "session");
        if (!items.length) return "";
        return `<div class="muted" style="font-size:11px;margin:6px 2px 4px">KOT #${o.kot_no != null ? esc(o.kot_no) : "—"}</div>` +
          items.map((r) => `<button class="kotm-row${sel2 === r.id ? " sel" : ""}" data-pickitem="${esc(r.id)}"><span class="kotm-txt"><b>${r.qty > 1 ? r.qty + "× " : ""}${esc(r.title)}</b><small>${inr(r.price * (r.qty || 1))}</small></span><span class="kotm-chev">›</span></button>`).join("");
      }).join("");
      return { title: "Which dish moves? (a multi-plate line moves whole)", html: groups };
    }
    if (sel1 === "reprint") return { title: "Which KOT?", html: ordersForTable(t).filter((o) => o.status !== "cancelled").map((o) => kotCard(o, "pickprint")).join("") };
    return null;
  };
  const col3 = () => {
    if (sel1 === "movekot" && sel2) return { title: "Send that KOT to which table?", html: tilesAll("gokot", (i) => (summaryTableOpen(i) ? "joins bill" : "free"), moveBlocked) };
    if (sel1 === "moveitem" && sel2) return { title: "Send that dish to which table? (new KOT there)", html: tilesAll("goitem", (i) => (summaryTableOpen(i) ? "joins bill" : "free"), moveBlocked) };
    // The owner's two-option print step (2026-08-04): PRINT = here, on this device;
    // REPRINT = a durable job the KITCHEN's printer picks up, branded DUPLICATE on paper.
    if (sel1 === "reprint" && sel2) return { title: "Print it where?", html:
      `<button class="kotm-row" data-printhere><span class="kotm-ico">🖨</span><span class="kotm-txt"><b>Print KOT</b><small>Prints here, on this device</small></span></button>
       <button class="kotm-row" data-printkitchen><span class="kotm-ico">👨‍🍳</span><span class="kotm-txt"><b>Reprint KOT — in the kitchen</b><small>Comes out of the kitchen printer, marked DUPLICATE</small></span></button>` };
    return null;
  };

  const render = () => {
    const c2 = sel1 ? col2() : null;
    const c3 = col3();
    colsEl.innerHTML =
      // EVERY OPERATION ON ONE SCREEN — NO SCROLLING (owner, 2026-08-01: "everything should be
      // shown at one page … there shouldn't be scrollable … at least not for this first one where
      // all the features are listed"). As a single tall column these seven rows came to ~670px
      // against a 560px cap, so the last two hid below the fold — on the one screen whose whole job
      // is to show you what you can do. They're a two-across grid of tiles now: 4 rows, ~390px
      // including the header, so all seven are visible at every window height we support.
      // The LATER columns (which table? which KOT?) keep scrolling — a 300-table floor cannot fit.
      `<div class="kotm-col kotm-col-ops"><div class="kotm-ops">` + OPS.map((r) => `<button class="kotm-op${sel1 === r.id ? " sel" : ""}" data-op="${r.id}" data-tip="${esc(KOT_TIPS[r.id] || "")}" ${r.on ? "" : "disabled"}>
        <span class="kotm-ico">${r.icon}</span><span class="kotm-txt"><b>${r.label}</b><small>${r.sub}</small></span>
        ${r.on ? "" : `<span class="kotm-off-why">${r.why}</span>`}</button>`).join("") + `</div></div>` +
      (c2 ? `<div class="kotm-col"><div class="kotm-col-title">${c2.title}</div>${c2.html}</div>` : "") +
      (c3 ? `<div class="kotm-col"><div class="kotm-col-title">${c3.title}</div>${c3.html}</div>` : "");
    // panel 1: pick an operation (split hands over to its form — it's a form, not a drill-down)
    colsEl.querySelectorAll("[data-op]").forEach((b) => (b.onclick = () => {
      const op = b.dataset.op;
      if (op === "split") { closeM(); markTablePaid(t, { openSplit: true }); return; }
      // Table type is its own little picker (VIP / Family / Owner's guest), not a drill-down —
      // same hand-over as split.
      if (op === "type") { closeM(); openTagModal(t); return; }
      sel1 = op; sel2 = null; render();
    }));
    // panel 2 executors / selectors
    colsEl.querySelectorAll("[data-goshift]").forEach((b) => (b.onclick = () => {
      const to = b.dataset.goshift;
      run("POST", `/sessions/${sess.id}/shift`, { to }, `Shifted to ${tileFace(to)}`, () => followShiftedTable(t, to));
    }));
    colsEl.querySelectorAll("[data-gomerge]").forEach((b) => (b.onclick = async () => {
      const to = b.dataset.gomerge;
      // BOTH HALVES OF THE MONEY, AND WHICH TABLE ENDS UP HOLDING IT (owner, 2026-08-11 —
      // improvement 5). This is the one tap that puts two parties' money on one bill, so the confirm
      // now shows what is being added to what, and names the surviving table instead of leaving
      // "the lowest number holds the bill" as a rule the manager has to apply in their head.
      const theirTile = (state.summary && state.summary.tiles || {})[String(to)];
      const theirDue = (theirTile && Number(theirTile.due)) || 0;
      const keeps = (Number(t) <= Number(to)) ? t : to;
      const money = (bill.total > 0 || theirDue > 0)
        ? ` ${inr(bill.total)} + ${inr(theirDue)} → ${inr(bill.total + theirDue)} on one bill.`
        : "";
      if (!(await confirmDialog(`Merge ${tileFace(t)} into ${partyLabel(to)}? They become ONE party on ONE bill, held by ${tileFace(keeps)} (the lowest table number).${money}`, "Merge"))) return;
      run("POST", `/sessions/${sess.id}/merge`, { to }, (r) => `Merged into ${tileFace((r && r.parent_table) || keeps)} — one bill`, async (r) => {
        // Refresh BOTH tiles + the live merges list BEFORE the detail re-renders — otherwise the
        // panel still thinks the tables are separate and the detail/tiles count one table's food
        // until the 60s backstop (owner, 2026-08-03). And follow the table the SERVER kept: the
        // lowest number holds the bill, which is not always the one that was tapped.
        const parent = (r && r.parent_table) || to;
        await pollTables([String(parent), String(t), String(to)]);
        followShiftedTable(t, parent);
      });
    }));
    colsEl.querySelectorAll("[data-pickkot]").forEach((b) => (b.onclick = () => { sel2 = b.dataset.pickkot; render(); }));
    colsEl.querySelectorAll("[data-pickitem]").forEach((b) => (b.onclick = () => { sel2 = b.dataset.pickitem; render(); }));
    colsEl.querySelectorAll("[data-pickprint]").forEach((b) => (b.onclick = () => { sel2 = b.dataset.pickprint; render(); }));
    colsEl.querySelectorAll("[data-printhere]").forEach((b) => (b.onclick = () => {
      const o = ordersForTable(t).find((x) => x.id === sel2);
      if (o) { printKotTicket(o); done(`KOT #${o.kot_no ?? "—"} sent to print`); }
    }));
    colsEl.querySelectorAll("[data-printkitchen]").forEach((b) => (b.onclick = async () => {
      const o = ordersForTable(t).find((x) => x.id === sel2);
      if (!o) return;
      closeM();
      await sendKotToKitchen(o);
    }));
    // panel 3 executors
    colsEl.querySelectorAll("[data-gokot]").forEach((b) => (b.onclick = () => run("POST", `/orders/${sel2}/move`, { to: b.dataset.gokot }, `KOT moved to ${tileFace(b.dataset.gokot)}`)));
    colsEl.querySelectorAll("[data-goitem]").forEach((b) => (b.onclick = () => run("POST", `/order-items/${sel2}/move`, { to: b.dataset.goitem }, `Dish moved to ${tileFace(b.dataset.goitem)} (new KOT)`)));
  };
  render();
}

// openKotTablePicker(): step one of the floor-wide 🧾 KOT ▾ — WHICH table? (owner, 2026-07-31).
// Then it hands straight over to the per-table menu, so everything downstream behaves exactly as
// it did when the button lived inside a table's own popup. Free tables are pickable on purpose:
// marking a table VIP before the guests order is one of the reasons this button exists.
// fitKotPicker(wrap): make the WHOLE floor fit the picker's box (owner, 2026-08-14: "when the
// amount of table is more that we have to scroll — at that time make it like it will show all on
// table first"). It measures instead of guessing, because the right size depends on three things a
// constant cannot know: how many tables the restaurant has, how big the screen is, and how tall the
// sections' headings make the content.
//
// The loop steps --kotp-min down 6px at a time and re-measures, so it stops at the LARGEST size
// that fits — a 30-table floor on a laptop never shrinks at all. Detail is shed on the way down in
// the floor tiles' own priority order (sub-line → state word → paid pill); the number and the state
// colour always stay, because those are what you are picking by.
//
// 44px IS THE FLOOR AND IT IS NOT NEGOTIABLE: a square smaller than that is not reliably tappable
// with a thumb, so a floor too big to fit even then keeps its scrollbar. That is the honest
// outcome — "everything on one screen" must never mean "everything too small to hit".
//
// Cost: up to ~9 layout measurements when the sheet opens (and again on resize). No data, no
// request; it reads geometry that the browser is about to compute anyway.
const KOTP_MIN_PX = 44;   // the tappable floor — see above
function fitKotPicker(wrap) {
  const scroll = wrap && wrap.querySelector(".kotp-scroll");
  if (!scroll) return;
  const phone = window.matchMedia("(max-width: 760px)").matches;
  let min = phone ? 78 : 96;
  const apply = (v) => {
    scroll.style.setProperty("--kotp-min", v + "px");
    scroll.style.setProperty("--kotp-gap", (v < 62 ? 5 : v < 80 ? 6 : 9) + "px");
    scroll.classList.toggle("kotp-sm", v < 80);
    scroll.classList.toggle("kotp-xs", v < 58);
  };
  apply(min);
  // scrollHeight > clientHeight means the sections are taller than the box they live in — i.e. it
  // would scroll. +2 absorbs sub-pixel rounding so we don't shrink a floor that already fits.
  while (scroll.scrollHeight > scroll.clientHeight + 2 && min > KOTP_MIN_PX) {
    min = Math.max(KOTP_MIN_PX, min - 6);
    apply(min);
  }
}
function openKotTablePicker() {
  document.querySelector(".kotpick-overlay")?.remove();
  const s = state.data.settings || {}; // (the sheet's styles are injected once at load)
  const n = Math.max(1, parseInt(s.table_count, 10) || 12);
  // WIDE, AND EVERY TABLE'S STATE ON ITS FACE (owner, 2026-08-01: "we have full screen, we can
  // select from it — and show the status of the table so it's easy to select, with all the paid /
  // not paid / served / not served things"). The first version was a narrow two-column list: on a
  // 30-table floor you scrolled to find a table you could already SEE behind the popup. It uses
  // the same tableTileState the tiles use, so the words match the floor exactly.
  // …which was not quite true until 2026-08-07: a free table was hard-coded to lowercase "free" here
  // while the floor says "Free". One screen, two spellings of the same state. It prints ts.label now,
  // which IS the floor's word for every state including Free — so the claim above is finally honest.
  let busyN = 0;
  // IN USE FIRST, FREE AFTER (owner, 2026-08-13). Same tiles, same states, same words — only the
  // ORDER changes, plus a heading per group so the count is readable instead of counted. Two
  // buckets are collected in ONE pass over the floor list so the tile order inside each group is
  // still the floor's own order (T3 before T6), which is how he reads the floor.
  const busyTiles = [], freeTiles = [];
  floorTableList(n).forEach((i) => {
    const ts = tableTileState(i);
    const busy = ts.st !== "free";
    if (busy) busyN++;
    const info = TABLE_TAG_INFO[tagForTable(i)];
    // pay: red = an accepted bill still owing, green = settled. Say it in words, not just colour.
    const money = ts.pay === "red" ? "unpaid" : ts.pay === "green" ? "paid" : "";
    const nm = ((s.table_names || {})[String(i)] || "").trim();
    (busy ? busyTiles : freeTiles).push(`<button class="kotm-tile kotp-tile ft-${esc(ts.st)}${busy ? " occ" : ""}${ts.pay ? " pay-" + esc(ts.pay) : ""}" data-kotpick="${esc(i)}" title="${esc(nm ? nm + " (T" + i + ")" : "T" + i)}">
      <b>${info ? info.emoji + " " : ""}${esc(tileFace(i))}</b>
      <small class="kotp-state">${esc(ts.label)}</small>
      ${busy && ts.meta ? `<small class="kotp-meta">${esc(ts.meta)}</small>` : ""}
      ${money ? `<small class="kotp-pay ${esc(money)}">${esc(money)}</small>` : ""}
    </button>`);
  });
  const total = floorTableList(n).length;
  // No fixed size any more: fitKotPicker() below MEASURES the sheet and shrinks the squares until
  // the whole floor is on one screen (owner, 2026-08-14). His earlier "auto switch" at 48 tables
  // (2026-08-13) was a two-step guess — it fixed a 60-table floor and still scrolled a 300-table
  // one, and on a big monitor it shrank tiles that already fitted.
  const sec = (title, tiles, emptyWord) =>
    `<div class="kotp-sec-title">${title} <span class="n">${tiles.length}</span></div>` +
    (tiles.length ? `<div class="kotm-grid kotp-grid">${tiles.join("")}</div>`
                  : `<div class="kotp-empty">${emptyWord}</div>`);
  const wrap = el(`<div class="sx-modal-overlay kotpick-overlay"><div class="sx-modal kotm-sheet kotp-sheet">
    <div class="tbl-modal-head kotm-head"><div class="tp-detail-top"><div class="kotm-title"><h3>🧾 Table &amp; KOT operations</h3></div><button class="tbl-modal-close" aria-label="Close">✕</button></div>
    <div class="kotm-bill">Which table? <span class="muted">· ${busyN} of ${total} in use</span></div></div>
    <div class="kotm-list"><div class="kotp-scroll">
      ${sec("In use", busyTiles, "No table has anything on it right now.")}
      ${sec("Free", freeTiles, "Every table is in use.")}
    </div></div></div>`);
  document.body.appendChild(wrap);
  fitKotPicker(wrap);                       // shrink the squares until the whole floor is on screen
  const onFit = () => fitKotPicker(wrap);   // a rotate / window resize changes the box it must fit
  window.addEventListener("resize", onFit);
  const closeM = () => { window.removeEventListener("resize", onFit); wrap.remove(); };
  wrap.__lfhClose = closeM;
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  wrap.querySelectorAll("[data-kotpick]").forEach((b) => (b.onclick = async () => {
    const t = String(b.dataset.kotpick);
    closeM();
    await ensureTableSlice(t); // the menu reads this table's orders (movable KOTs, dishes, bill)
    openKotMenu(t, openSessionForTable(t));
  }));
}

function openKotMenu(t, sess) {
  // Desktop → the Finder-style Miller columns above; phone keeps the step sheets.
  if (!isPhoneLayout()) return openKotColumns(t, sess);
  document.querySelector(".kotmenu-overlay")?.remove();
  // Movable KOTs = this table's orders that aren't paid or cancelled (same rule the
  // server's RPC enforces — the row is disabled rather than surprising with a 409).
  const movable = ordersForTable(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid");
  // Other OPEN tables (a merge target must already have a party).
  const nAll = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  let occupiedOthers = 0;
  for (const i of floorTableList(nAll)) if (String(i) !== String(t) && summaryTableOpen(i)) occupiedOthers++;
  // The header's "bill due" is the PARTY's bill — a merged parent's movable list is per-table
  // (that is what Move-a-KOT needs), but the money line must never show half a joint bill.
  const bill = billMath(partyOrders(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid" && o.status !== "received"));
  // Same three corrections as the desktop columns above, because a phone must never offer a
  // different set of operations from the screen next to it (T3 sweep, 2026-08-10):
  // the floor's own answer to "is anything happening here", the joined-table wording, and the money.
  const liveHere = !!sess && summaryTableOpen(t);
  const movableTotal = movable.reduce((s2, o) => s2 + (parseFloat(o.total) || 0), 0);
  const rows = [
    // Marking a table works with NO order on it — that is the point of reaching this menu from
    // the floor's own KOT button (owner, 2026-07-31: "before a table or order is taken you can
    // mark table as VIP from that option").
    { id: "type", icon: TABLE_TAG_INFO[tagForTable(t)] ? TABLE_TAG_INFO[tagForTable(t)].emoji : "🏷", label: "Table type", sub: "VIP · Family · Owner's guest", on: tagActionAllowed("table_tags"), why: "not enabled" },
    // A merged party doesn't shift (mig 264) — same rule as the desktop columns above.
    { id: "shift", icon: "⇄", label: "Change table", sub: "Party, orders & bill move to a free table", on: liveHere && !mergeGroupLabel(t), why: mergeGroupLabel(t) ? "unmerge first" : "table is free" },
    { id: "merge", icon: "🪢", label: "Merge tables", sub: bill.total > 0 ? `One table, one bill · this side ${inr(bill.total)}` : "Join another party — one table, one bill",
      on: liveHere && occupiedOthers > 0, why: mergeGroupLabel(t) && !sess ? "unmerge first" : !liveHere ? "table is free" : "no other open table" },
    { id: "movekot", icon: "🧾", label: "Move a KOT", sub: movable.length ? `One order moves · ${movable.length} KOT${movable.length === 1 ? "" : "s"}, ${inr(movableTotal)}` : "Send one order to another table's bill", on: movable.length > 0, why: "no movable KOT" },
    // Only DB-backed dish rows (kind "session") can move — legacy JSON lines have no row id.
    { id: "moveitem", icon: "🍛", label: "Move a single dish", sub: "One dish moves — it gets its own new KOT there", on: movable.some((o) => orderItemRows(o).some((r) => r.kind === "session")), why: "no movable dish" },
    { id: "reprint", icon: "🖨️", label: "Print / reprint a KOT", sub: "Here, or on the kitchen's printer", on: ordersForTable(t).some((o) => o.status !== "cancelled"), why: "no KOTs" },
    // Same order and the same switch as the desktop list above — a phone must not offer a
    // different set of operations from the screen next to it.
    ...(splitBillOn() ? [{ id: "split", icon: "🍴", label: "Split the bill", sub: "Equal · custom amounts · by dish", on: movable.some((o) => o.status !== "received"), why: "nothing settleable" }] : []),
  ];
  const rowHtml = (r) => `<button class="kotm-row" data-kotop="${r.id}" data-tip="${esc(KOT_TIPS[r.id] || "")}" ${r.on ? "" : "disabled"}>
    <span class="kotm-ico">${r.icon}</span>
    <span class="kotm-txt"><b>${r.label}</b><small>${r.sub}</small></span>
    ${r.on ? `<span class="kotm-chev">›</span>` : `<span class="kotm-off-why">${r.why}</span>`}</button>`;
  const wrap = el(`<div class="sx-modal-overlay kotmenu-overlay"><div class="sx-modal kotm-sheet">
    <div class="tbl-modal-head kotm-head"><div class="tp-detail-top"><div class="kotm-title"><h3>🧾 ${esc(tileFace(t))}</h3></div><button class="tbl-modal-close" aria-label="Close">✕</button></div>
    <div class="kotm-bill">KOT &amp; table operations${bill.total > 0 ? ` · bill due ${inr(bill.total)}` : ""}${sess && sess.bill_no != null ? ` · bill #${esc(sess.bill_no)}` : ""}</div></div>
    <div class="kotm-list">${rows.map(rowHtml).join("")}</div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  wrap.querySelectorAll("[data-kotop]").forEach((b) => (b.onclick = () => {
    const op = b.dataset.kotop; closeM();
    if (op === "type") openTagModal(t);
    if (op === "shift" && sess) openShiftPicker(t, sess);
    if (op === "merge" && sess) openMergePicker(t, sess);
    if (op === "movekot") openMoveKotPicker(t);
    if (op === "moveitem") openMoveItemPicker(t);
    if (op === "split") markTablePaid(t, { openSplit: true });
    if (op === "reprint") openReprintKotPicker(t);
  }));
}

// ── THE kitchen-ticket template — ONE recipe, used by every KOT print ────────────────
// The ticket is written down once, in /panels/billdoc.js, next to the bill: this panel, the
// kitchen board and the admin's Access preview all print THAT file, so a ticket cannot look
// one way here and another way there (owner, 2026-08-02: "both should be sync"). These two
// lines are this panel's handle on it, kept so every existing caller reads the same.
function kotLineHtml(r) { return LFH_BILLDOC.kotLineHtml(r); }
function kotTicketHtml(o) { return LFH_BILLDOC.kotDocHtml(o); }

// Print a ticket through a hidden iframe — no pop-up to allow, nothing left on screen.
// Answers false when the print could not even be started (billdoc missing after a bad deploy, the
// iframe blocked). The manager print station reports that to the server, which requeues the job —
// so a swallowed failure is no longer a silently lost ticket. Existing callers ignore the value.
function printTicketHtml(html) {
  try {
    const ifr = document.createElement("iframe");
    ifr.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;";
    document.body.appendChild(ifr);
    const d = ifr.contentWindow.document; d.open(); d.write(html); d.close();
    // Remove the hidden print frame only AFTER the browser signals it finished printing.
    // The old blind 1500ms timer often deleted the frame while Chrome's print preview was
    // still open, dropping Chrome's internal print callback ("The provided callback is no
    // longer runnable" — logged as a red client_error). onafterprint fires in both silent/
    // kiosk and preview modes; the long fallback covers a preview the user just walks away from.
    setTimeout(() => {
      const w = ifr.contentWindow;
      let done = false;
      const cleanup = () => { if (done) return; done = true; try { ifr.remove(); } catch (e) {} };
      try { w.onafterprint = cleanup; } catch (e) {}
      // A TICKET NEVER PULLS THE SCREEN AWAY FROM THE PERSON USING IT (owner, 2026-08-20: at Aangan
      // one man is the owner AND the manager — he sits at the counter in the owner panel, in Manager
      // mode, and "the chrome you open is switching the owner panel to the kitchen when the print is
      // being done. I want it works always in background"). This used to call w.focus() FIRST, on every
      // automatic ticket. Focusing a frame is a user-visible focus change, and in a browser where the
      // printing panel is a TAB beside the panel he is working in, that is enough to bring the printing
      // tab forward — so every order yanked him out of the floor plan he was reading.
      // focus() was here for old browsers that printed the PARENT document when an iframe was printed
      // unfocused. Chrome — the only browser a print station runs, and the one this guide sets up —
      // prints the frame either way. So: print WITHOUT touching focus, and keep the old behaviour as a
      // FALLBACK for the one case that justified it, a print() that actually threw.
      try { w.print(); }
      catch (e1) {
        try { w.focus(); w.print(); }
        catch (e) {}
      }
      setTimeout(cleanup, 60000);
    }, 250);
    return true;
  } catch (e) { return false; /* printing must NEVER break the panel */ }
}
// Reprint ONE order's kitchen ticket, on THIS device.
//
// It carries the SAME big `*** Reprint · Duplicate ***` banner the kitchen's copy does
// (owner, 2026-08-04: "every panel's reprint looks identical"). It used to pass no `reprint`
// flag and only whisper the word in the small header line, so the two reprint paths in this
// one panel produced two different pieces of paper — and on a rushed pass the quiet one is
// exactly the ticket a kitchen cooks a second time. The head goes back to the plain
// "KITCHEN TICKET" because the banner above it now says it, loudly.
function printKotTicket(o) {
  try {
    const allerg = Array.isArray(o.allergies) && o.allergies.length ? `<div class="al">⚠ AVOID: ${esc(o.allergies.join(", "))}</div>` : "";
    printTicketHtml(kotTicketHtml({
      title: `KOT ${o.kot_no != null ? o.kot_no : "—"}`,
      rname: (state.data.restaurant || {}).name || "Kitchen",
      head: "KITCHEN TICKET",
      reprint: true,
      kot: o.kot_no != null ? o.kot_no : "—",
      tableLabel: tablePrintLabel(o.table_number),
      // Shared with the kitchen (LFH_BILLDOC.kotWhen): carries the DAY when the ticket is not
      // from today, because a thermal head is black and white and cannot say it any other way.
      when: LFH_BILLDOC.kotWhen(o.created_at),
      linesHtml: orderItemRows(o).map(kotLineHtml).join(""),
      allergHtml: allerg,
      // THE BIG DUPLICATE BANNER, not just a word in the header (2026-08-05). This path is reached
      // from the reprint picker's "Print KOT — prints here on this device", right beside a button
      // that promises "marked DUPLICATE" — and it printed a ticket indistinguishable from a fresh
      // order. billdoc.js says why the flag exists rather than free text: "so every panel's reprint
      // looks identical". Worst of all here, because "print here" is the fallback used exactly when
      // the kitchen printer may already have printed it once.
      reprint: true,
    }));
  } catch (e) { /* printing must NEVER break the panel */ }
}
// "Reprint in kitchen" — the reprint becomes a durable job (mig 269): the kitchen screen
// claims it, prints it with the big DUPLICATE banner, and reports back. NOTHING prints on
// this device (owner, 2026-08-04: "I don't want it reprinted in the manager panel"). If the
// kitchen never picks it up (screen closed, printer dead), the floor strip says so and
// offers "Print here instead" — the ticket can never just vanish.
async function sendKotToKitchen(o) {
  try {
    const r = await api("POST", "/print-jobs", { order_id: o.id });
    if (r && r.queued) toast("Saved ✓ — the kitchen prints it the moment you're back online.", "ok");
    else toast(`KOT #${o.kot_no ?? "—"} sent to the kitchen printer — it comes out marked DUPLICATE.`, "ok");
  } catch (e) { toast("Couldn't send it to the kitchen: " + e.message, "err"); }
}
function openReprintKotPicker(t) {
  document.querySelector(".reprint-overlay")?.remove();
  const os = ordersForTable(t).filter((o) => o.status !== "cancelled");
  if (!os.length) { toast("No KOTs on this table", "err"); return; }
  let picked = null; // two steps on a phone: WHICH KOT → WHERE does it print
  const wrap = el(`<div class="sx-modal-overlay reprint-overlay"><div class="sx-modal" style="max-width:420px">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>🖨️ Print / reprint a KOT — ${esc(tableLabel(t))}</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="dish-edit-body" style="padding:10px 14px 14px"></div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  const bodyEl = wrap.querySelector(".dish-edit-body");
  const render = () => {
    if (!picked) {
      bodyEl.innerHTML = os.map((o) => {
        const nd = orderItemRows(o).reduce((s, r) => s + (parseInt(r.qty, 10) || 1), 0);
        return `<button class="btn" data-reprint="${esc(o.id)}" style="display:flex;justify-content:space-between;width:100%;margin:0 0 8px;padding:11px 14px"><span><b>KOT #${o.kot_no != null ? esc(o.kot_no) : "—"}</b> · ${nd} dish${nd === 1 ? "" : "es"}</span><span>›</span></button>`;
      }).join("");
      bodyEl.querySelectorAll("[data-reprint]").forEach((b) => (b.onclick = () => { picked = os.find((x) => x.id === b.dataset.reprint) || null; render(); }));
      return;
    }
    bodyEl.innerHTML = `<div class="muted" style="font-size:12px;margin:0 2px 8px">KOT #${picked.kot_no != null ? esc(picked.kot_no) : "—"} — print it where?</div>
      <button class="btn" data-printhere style="display:flex;gap:10px;align-items:center;width:100%;margin:0 0 8px;padding:12px 14px"><span>🖨</span><span style="text-align:left"><b>Print KOT</b><br><small>Prints here, on this device</small></span></button>
      <button class="btn" data-printkitchen style="display:flex;gap:10px;align-items:center;width:100%;margin:0 0 8px;padding:12px 14px"><span>👨‍🍳</span><span style="text-align:left"><b>Reprint KOT — in the kitchen</b><br><small>Comes out of the kitchen printer, marked DUPLICATE</small></span></button>
      <button class="btn" data-printback style="width:100%">‹ Back</button>`;
    bodyEl.querySelector("[data-printback]").onclick = () => { picked = null; render(); };
    bodyEl.querySelector("[data-printhere]").onclick = () => { const o = picked; closeM(); printKotTicket(o); toast(`KOT #${o.kot_no ?? "—"} sent to print`, "ok"); };
    bodyEl.querySelector("[data-printkitchen]").onclick = async () => { const o = picked; closeM(); await sendKotToKitchen(o); };
  };
  render();
}

// ── PRINTER TROUBLE ON THE MANAGER'S FLOOR (mig 269, owner 2026-08-04) ────────────────
// The kitchen's printer problems land HERE, where someone can act: a one-tap report from
// the kitchen (paper out / half print / jam), the automatic "tickets aren't printing"
// event, and any reprint job the kitchen never picked up. The strip sits above the table
// grid; the owner's Manager mode embeds this same panel, so the owner sees the identical
// warning with zero extra wiring. Everything self-heals: a successful kitchen print
// resolves the events server-side, and the strip disappears on the next floor read.
const PRINTER_KIND_TEXT = {
  paper_out: "Paper roll finished / paper out",
  half_print: "A ticket came out half-printed / cut off",
  jam: "Paper jammed in the printer",
  other: "Printer problem reported",
  auto_fail: "Kitchen tickets aren't printing",
};
let seenPrinterKeys = null; // null until the first summary — an already-open problem shows in the strip without a boot-time toast storm
function printerAlerts() {
  const pr = (state.summary && state.summary.printer) || null;
  if (!pr) return [];
  const out = [];
  for (const e of pr.events || []) out.push({
    key: "ev:" + e.id, id: e.id, kind: "event", icon: "🖨",
    // NAME THE PRINTER (mig 351). This said "— kitchen" beside every complaint, which was true while a
    // restaurant had one printer and is a wrong instruction the moment it has three: somebody walks to
    // the kitchen to look at a bill printer that is standing at the counter.
    text: `${PRINTER_KIND_TEXT[e.kind] || "Printer problem"} — ${e.printer ? e.printer : "kitchen"}${e.reported_by ? " · " + e.reported_by : ""}${(e.count || 1) > 1 ? ` · ×${e.count}` : ""}`,
    at: e.last_at,
  });
  // HOW FAR BEHIND THE PRINTER IS (owner, 2026-08-27). FIRST in the list on purpose: the named rows
  // below it are five individual tickets, and "eleven are stacked up" is the sentence that decides
  // whether somebody walks to the printer or starts reading orders off the screen.
  //
  // It appears only when the OLDEST one is genuinely old (the server sends the threshold). A row that
  // said "1 waiting" every time a ticket passed through would be permanent furniture — and this strip
  // is the manager's alarm, so anything permanent in it is the don't-cry-wolf rule being broken.
  const w = pr.waiting || null;
  const wAfter = typeof pr.stuckAfterMs === "number" ? pr.stuckAfterMs : 60000;
  if (w && Number(w.n) > 0 && Number(w.oldestMs || 0) >= wAfter) {
    const n = Number(w.n);
    out.push({
      key: "wait:" + n, id: "waiting", kind: "waiting", icon: "🧾",
      // "for 11m ago" — timeAgo() already carries the "ago", so the sentence has to be built around
      // it, not in front of it. Written out in words because a manager reads this at a glance.
      text: `${n} kitchen ticket${n === 1 ? "" : "s"} waiting to print — the oldest has been waiting ${
        Number(w.oldestMs) < 3600000 ? Math.round(Number(w.oldestMs) / 60000) + " minutes" : Math.round(Number(w.oldestMs) / 3600000) + " hours"
      }. Tell the kitchen to read the orders off their screen; every ticket still prints, in order, once the printer works.`,
      at: new Date(Date.now() - Number(w.oldestMs)).toISOString(),
    });
  }
  // ONE STORY, TOLD ONCE. The rows below name individual tickets, and they earn their place when a
  // single reprint jams while everything else prints. When the pile-up row above is showing, NOTHING
  // is printing — so five named rows are the same fault five times, and they push the row that
  // actually explains it off the screen. (Measured: seven rows for one dead printer.)
  //
  // The oldest one is kept, because it carries the one button the pile-up row cannot: "Print here
  // instead". So the manager still has a way to get that ticket onto paper.
  const pileUp = out.length > 0;
  const named = pileUp ? (pr.stuck || []).slice(0, 1) : (pr.stuck || []);
  for (const j of named) out.push({
    key: "job:" + j.id, id: j.id, kind: "job", icon: "🧾",
    text: `${pileUp ? "The oldest of them" : "A reprint"} (KOT #${j.kot_no ?? "—"}${j.table_number != null ? " · " + tableLabel(j.table_number) : ""}) hasn't printed in the kitchen${j.status === "failed" ? ` — it failed ${j.attempts} times` : pileUp ? " — print it here if it is needed now" : " — is the kitchen screen open?"}`,
    at: j.created_at,
  });
  return out;
}
// Toast NEW problems the moment a floor read carries them (realtime makes that near-instant);
// history never toasts on boot, and a problem only toasts once however many polls repeat it.
//
// "NO PAYLOAD" IS NOT "NO PROBLEMS" — never let a missing answer clear the seen-set (T13 sweep,
// 2026-08-05). This used to end `seenPrinterKeys = keys` unconditionally, so any pass that arrived
// WITHOUT a printer payload reset the set to empty, and the next pass that did carry one
// re-announced every still-open problem in red — the same printer fault shouted over and over. The
// server-side cause is fixed (the manager's printer read has its own shared key now), but a client
// must not depend on that: a targeted ?table= refetch, a boot before the first full read, or a
// failed read all legitimately arrive with nothing to say. Only a real, present, EMPTY list means
// "the problems are gone". This is the owner's don't-cry-wolf rule at the one place it costs him
// trust in the alarm.
// DELETED 2026-08-31 (owner): printerStripHtml, printStationStripHtml and bindPrintStationStrip.
// Three dead bodies left standing after the bands came off the floor. Never called again — but
// still holding a SECOND copy of the wording for "where does the paper come out", which
// syncGuestBell now owns. That duplicate is the exact thing he objected to: "there is two printing
// things, one is working and one is just showing." The live wording is in syncGuestBell; do not
// put a band back above the table grid. printerAlerts() stays — it still feeds the toasts below.
function noticePrinterNews() {
  if (!(state.summary && state.summary.printer)) return;  // nothing was reported this pass — leave the seen-set alone
  const list = printerAlerts();
  const keys = new Set(list.map((a) => a.key));
  if (seenPrinterKeys) for (const a of list) if (!seenPrinterKeys.has(a.key)) toast(a.icon + " " + a.text, "err");
  seenPrinterKeys = keys;
}
// (printJobHere() lived here — "Print here instead", the honest fallback when the kitchen
// printer could not take a stuck reprint. DELETED sweep #8 T7 with its only caller, the
// [data-prhere] binding in bindFloor: the strip that rendered that button was removed on
// 2026-08-31 and nothing has emitted the attribute since. A stuck ticket is still printable
// by hand from 🧾 KOT ▾ → Print / reprint a KOT → Print KOT, which prints on this device
// with the DUPLICATE banner and is the same document. If the shortcut is wanted again it
// belongs on the 🔔 bell's printer row, not on a new band above the floor.)

// ── THIS SCREEN CAN BE THE PRINTER (owner, 2026-08-17) ──────────────────────────────────────────
// "In the kitchen they can't keep a PC… if you minimize, or open another app on the same PC, the KOT
// prints totally stop. What I want is auto-print in the manager panel — when you turn that on, the
// ticket prints there instead of the kitchen."
//
// Since mig 335 a ticket is a ROW, so this screen can simply be a second claimant on the same queue;
// the atomic claim means the kitchen screen and this one can both watch and a ticket still comes out
// exactly once.
//
// TWO GATES, and both are needed:
//
//  1. THE ADMIN says whether a counter screen may print at all — /aevinite → the restaurant → 🖨 KOT
//     printing → "Which screen prints" (mig 336: kitchen | counter | both). It is not a control in
//     THIS panel: the Settings → Kitchen printing section is hidden from everyone here on purpose
//     (owner, 2026-07-31 — *"there shouldn't be grayed out option also"*), which is exactly why the
//     first version of this feature sat somewhere nobody could reach.
//
//  2. THIS DEVICE says yes, once, on the floor screen. Not optional and not a nicety: the manager
//     panel is also opened on PHONES. A phone that claimed a ticket would "print" it into a dialog
//     nobody looks at and report it done — a LOST ticket, caused by the feature meant to save it. So
//     a device that has not answered never claims, and the honest default is no.
// The setup guide the app serves (public/print-setup.html) — one constant, because it is linked from
// the floor strip AND from Settings → Printing, and a second copy of a path is how one of them rots.
// (This declaration was lost once while the print-station code was being reshaped, leaving both links
// referencing a name that no longer existed — a ReferenceError on every floor render. verify:print-queue
// caught it; that is what the check is for.)
const PRINT_SETUP_URL = "/print-setup.html";
// PRINT_HERE_KEY / printHereAnswer are GONE (owner, 2026-08-29). They stored, per browser, this
// device's answer to "should this screen print?" — a second place where the question could be
// answered differently from the Printing board. One question, one answer, one place.
// What the SERVER last told us about who prints ({ mayPrint, target }) — set by managerPrintPass's
// read, so the strip only ever asks a question the admin has actually opened.
let printTargetSays = null;
// { kot:{owned,agent,printer,connected}, bill:{…}, banquet:{…} } — refreshed on the same read that
// already asks whether this screen may print (mig 341). Empty until that first answer arrives, and
// an empty answer means "no computer owns it", which is the old behaviour: open the window.
let printOwners = {};
const printOwner = (kind) => { const o = printOwners && printOwners[kind]; return o && o.owned ? o : null; };
let lastPrintedHere = null;   // { kot, table, at } — the bell row proves printing is genuinely working

// ── THE STRIP SAYS WHAT IS HAPPENING. IT DOES NOT ASK. ───────────────────────────────────────
//
// Owner, 2026-08-29, on seeing the old one still there: *"why this is coming, the old logic of
// printing… I told you to remove old logic, keep only one logic which we have build right now."*
//
// It used to ask every screen "should THIS screen print the kitchen tickets?", keep that answer in
// this browser's localStorage, and offer to take the printer off whichever screen held it. That was
// the model BEFORE the Printing board: a restaurant worked out who printed by tapping around its own
// screens. It is not the model any more — the admin names one person on Printing, and this screen's
// job is to do it, not to re-open the question in a second place with a different answer.
//
// So: no question, no buttons, no per-device opt-in. Three facts and silence otherwise. The station
// is claimed automatically by the named screen (see managerPrintPass), because the decision was
// already made and a screen that waits to be tapped is a printer that never prints.
// NO LONGER RENDERED ANYWHERE (owner, 2026-08-30). Kept as the one place that knows how to word
// "where does the paper come out", now read by syncGuestBell() into a notification row instead of
// painted as a band across the floor. Do not put it back above the table grid.
// Bound wherever the floor renders the strip. Answering is instant (there is no Save to forget), and
// a yes prints anything already waiting straight away — so answering IS the test that it works.
// ── SETTINGS → PRINTING: where printing stands, and how to set a printer up ──────────────────────
// Owner, 2026-08-18: "tell me how the printer will work and inside the setting how it will be —
// every single bit of thing, how we're gonna print. It should be shown in kitchen panel… manager
// also and owner. Also a quick written guide… it should take me to the page."
//
// Rebuilt 2026-08-27 into the SAME FOUR STEPS the admin console shows, in the same order, with the
// same sentences (they come from the server, out of lib/printBoardWords.ts). Owner: "the UI/UX is
// also not identical… right now it feels too much complicated."
//
// And it is no longer read-only. A person the admin has given "May set the printers up" can do the
// whole job from the machine the printer is plugged into — register this computer, get the little
// helper file, and say which printer prints the kitchen slips, the bills and the banquet sheets.
// That is the owner's own design (2026-08-27): "that device is connected to the printer, so it will
// be easy for THAT device to set up the printer… admin can still see it… but that device will only
// get the option in settings, like everyone has their settings where they log out from."
//
// Everyone else sees exactly the same four cards with the answers stated as plain sentences and no
// buttons — never as dead controls (owner, 2026-07-31: "there shouldn't be grayed out option also").
function formPrinting(s) {
  const B = state.printBoard;
  // The board is fetched when this section opens (loadPrintBoard). Until it lands, say so — an
  // empty board would read as "you have no printers", which is a confident wrong answer.
  if (!B) {
    return `<div class="card"><h3>🖨 Printing</h3>
      <p class="hint" style="margin:0">${state.printBoardErr ? esc(state.printBoardErr) : "Reading the printing setup…"}</p>
      ${state.printBoardErr ? `<div style="margin-top:10px"><button type="button" class="btn" data-pw="reload">Try again</button></div>` : ""}
    </div>`;
  }
  const L = B.labels || { kind: {}, what: {}, off: {} };
  const STEP = B.steps || {};
  const mine = B.thisComputer || null;
  const may = B.maySetup === true;

  // ── 1 · IS PRINTING SWITCHED ON ────────────────────────────────────────────────────────────
  // Two facts, in the same shape the admin console shows them, so a person who has seen one board
  // recognises the other instantly. Facts, never dead switches (owner, 2026-07-31: "there shouldn't
  // be grayed out option also") — the one that IS theirs to change is the Kitchen slips line below.
  const stateRow = (on, label, what, who) => `
    <div class="pw-state-row ${on ? "yes" : "no"}">
      <span class="pw-dot" aria-hidden="true"></span>
      <span class="who"><b>${esc(label)}</b><br>${esc(what)}</span>
      <span class="pw-val">${on ? "YES" : "NO"}</span>
      <span class="muted" style="font-size:12px">${esc(who)}</span>
    </div>`;
  const step1 = `<div class="card"><h3>${esc(STEP.one || "1 · Is printing switched on")}</h3>
    <p class="muted" style="font-size:13px;margin:0 0 12px;line-height:1.5">
      A kitchen slip is put in a queue by the server the moment an order is sent, so it can never be
      lost — it waits until a printer takes it. These are the two switches above that queue.
    </p>
    <div class="pw-state">
      ${stateRow(B.printing.allowed, "Aevidine allows this restaurant to print", "With this off, nothing about printing appears anywhere — no greyed-out buttons, nothing at all.", "set by Aevidine")}
      ${stateRow(B.printing.on, "Kitchen slips print by themselves", "Your own pause button — off while a printer is being serviced. Slips wait; nothing is lost.", may ? "yours, on the Kitchen slips line below" : "set by Aevidine")}
    </div>
    ${!B.printing.allowed ? `<div class="hint">Printing is not switched on for this restaurant yet. Ask Aevidine to allow it — nothing on this page prints anything until then.</div>` : ""}
  </div>`;

  // ── 2 · THE COMPUTERS THAT CAN PRINT ───────────────────────────────────────────────────────
  // The half the owner asked for (2026-08-27): the machine WITH the printer sets itself up, in its
  // own Settings, beside where that person logs out. Everyone else sees the same list read-only.
  const seenWord = (a) => a.connected ? `connected · seen ${a.secondsAgo || 0}s ago`
    : a.last_seen_at ? `last heard from ${a.secondsAgo > 3600 ? Math.round(a.secondsAgo / 3600) + "h" : Math.round((a.secondsAgo || 0) / 60) + " min"} ago`
    : "has never started yet";
  const printerChips = (a, own) => (a.printers || []).length
    ? `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">
        ${a.printers.map((p) => `<span class="pw-printer"><i class="fa-solid fa-print" aria-hidden="true"></i>
          <b>${esc(p.name)}</b>${p.paper ? ` · ${esc(p.paper.wMm + " × " + p.paper.hMm + " mm")}` : ""}
          ${own && may ? `<button type="button" class="btn" style="padding:4px 9px;min-height:34px" data-pw="test" data-printer="${esc(p.name)}">Test page</button>` : ""}
        </span>`).join("")}
      </div>`
    : `<p class="muted" style="font-size:12.5px;margin:7px 0 0">It has not listed any printers yet — it does that the first moment the helper runs.</p>`;

  const others = (B.agents || []).filter((a) => !mine || a.id !== mine.id);
  // NO NUMBER ON THIS ONE. It is not a step any more — it is what card 2's toggle reveals when the
  // answer is "a computer", and two cards both numbered "2 ·" is worse than neither being numbered.
  const step2 = `<div class="card"><h3>2 · The computer that prints <span class="muted" style="font-weight:400;font-size:12.5px">(optional)</span></h3>
    <p class="muted" style="font-size:13px;margin:0 0 12px;line-height:1.5">
      A computer prints by running one small program — the <b>helper</b>. It asks us every two seconds
      whether there is anything to print, and prints it. No window has to be open, nobody has to stay
      logged in, and nothing can hide behind another window.
    </p>

    ${mine ? `
      <div class="pw-state">
        ${stateRow(!!mine.connected, `This computer — “${mine.name}”`,
          mine.connected ? "Its helper is running and talking to us right now." : "Its helper is not running. Anything routed here is waiting, and prints the moment it starts.",
          seenWord(mine))}
      </div>
      ${printerChips(mine, true)}
      ${may ? `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
        <button type="button" class="btn" data-pw="rename">Rename this computer</button>
        <button type="button" class="btn" data-pw="unlink">Unlink this computer</button>
      </div>
      <p class="muted" style="font-size:12px;margin:8px 0 0">
        “Unlink” stops this computer printing at once, and anything routed to it needs a printer
        choosing again. To bring it back: double-click the helper file here and press <b>Allow</b>.
      </p>` : ""}
    ` : may ? `
      <div class="hint" style="margin-bottom:10px">
        <b>This computer is not set up yet.</b> Do this on the computer the printer is actually plugged
        into — not on a phone, and not on a tablet. A phone cannot print silently; it can only open a
        print box nobody is watching.
      </div>
      <p class="what" style="margin:0 0 8px">
        Make the file below on that computer and double-click it. It opens a page that asks
        <b>Allow?</b> — press it, and this section fills itself in.
        <b>Nothing to name, nothing to copy across.</b>
      </p>
      ${(B.agents || []).length ? `
        <details class="pw-more"><summary>Already set up? Say which of these computers this is</summary>
          <p class="what" style="margin-top:6px">Pick it and this screen takes over managing it — nothing is
          reinstalled and no code changes. Use this after clearing your browser, on a new browser, or when
          Aevidine set the computer up for you.</p>
          <div class="pw-row">
            ${(B.agents || []).map((a) => `<button type="button" class="btn" data-pw="adopt" data-id="${esc(a.id)}">I am “${esc(a.name)}”</button>`).join("")}
          </div>
        </details>` : ""}
    ` : `<p class="muted" style="font-size:13px;margin:0">No computer has been set up from this screen.</p>`}

    ${others.length ? `<div style="margin-top:14px;border-top:1px solid var(--line);padding-top:10px">
      <p class="muted" style="font-size:12.5px;margin:0 0 8px">Other computers in this restaurant — read only from here. Aevidine sets those up.</p>
      ${others.map((a) => `<div style="padding:6px 0">
        <b style="font-size:13.5px">${esc(a.name)}</b>
        <span class="muted" style="font-size:12px"> · ${esc(seenWord(a))} · ${(a.printers || []).length} printer${(a.printers || []).length === 1 ? "" : "s"}</span>
      </div>`).join("")}
    </div>` : ""}
  </div>`;

  // ── 2 · HOW THIS RESTAURANT PRINTS — the one toggle, mirroring the console exactly ──────────
  // Owner, 2026-08-28: "I want a simple toggle… you only see the option you have selected, only the
  // setting for that option will be shown." — which was true until 2026-08-31, when he removed the
  // choice itself. The admin console's card and this one are still the SAME card, deliberately: same
  // sections, same words, same order, both setups present. The person with "May set the printers up"
  // is the one standing at the machine, so they are the one who may change any of it.
  // NO MODE (owner, 2026-08-31). `step2mode` held the same two big buttons as the admin board and
  // the same inline confirmation. Both setups are simply shown now — a computer if the restaurant
  // has one, and the kitchen screen which needs nothing — so there is nothing to pick between and
  // no stored choice that can disagree with the paper. Do not re-add it here either: this panel and
  // the admin board have drifted apart twice already, and a toggle in one of them is how it starts.
  // ── the chosen mode's SETUP — one of these two, never both ──────────────────────────────────
  const files = B.files || {};
  const sfiles = B.stationFiles || {};
  const pos = state.printOs || B.os || "mac";
  const OSN = { mac: "Mac", windows: "Windows", linux: "Linux / Raspberry Pi" };

  // ONE card shape for both launcher files. Two copies of this markup is two places for the wording
  // to drift, which is exactly how the printing screens became "not identical" the first time.
  const fileCard = (title, lead, set, steps, footer) => {
    const f = set[pos];
    if (!may || !f) return "";
    return `<div class="card"><h3>${esc(title)}</h3>
      <p class="muted" style="font-size:13px;margin:0 0 10px;line-height:1.5">${lead}</p>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">
        ${Object.keys(set).map((k) => `<button type="button" class="btn${pos === k ? " primary" : ""}" data-pw="os" data-os="${esc(k)}">${esc(OSN[k] || k)}</button>`).join("")}
      </div>
      <ol class="pw-steps">${steps(pos, f).map((n) => `<li>${n}</li>`).join("")}</ol>
      <p class="muted" style="font-size:12.5px;margin:0 0 10px">${footer(pos, f)}</p>
      <div class="pw-code">
        <button type="button" class="btn" data-pw="copy" data-set="${esc(set === sfiles ? "station" : "helper")}">Copy</button>
        <pre>${esc(f.text)}</pre>
      </div>
    </div>`;
  };

  const editorWord = (k) => k === "windows" ? "Notepad" : k === "mac" ? "TextEdit, then Format → Make Plain Text" : "nano";

  const step2setup = step2 + fileCard(
        "The helper file",
        `The same file for every restaurant, with <b>nothing secret in it</b>. <b>Nothing is downloaded:</b>
         a downloaded script is blocked outright by a Mac and warned about by Windows, while a file you
         typed yourself simply opens.`,
        files,
        (k, f) => [
          `On that computer, open <b>${editorWord(k)}</b>.`,
          `Press <b>Copy</b> below, and paste it in.`,
          `Save it on the Desktop as <b>${esc(f.filename)}</b>${k === "windows" ? " with <b>Save as type: All Files</b>" : ""}.`,
          k === "mac" ? `In Terminal, once: <b>chmod +x ~/Desktop/print-helper.command</b> — then double-click the file.` : "Double-click it.",
          `A page opens. Press <b>Allow</b>. That is the whole setup.`,
        ],
        (k, f) => `<b>After a shutdown:</b> ${esc(f.autostart)}`);

  // ── 4 · THE KITCHEN SCREEN — its own block, AFTER the paper lines ────────────────────────────
  // Order matters more than it looks. Rendered inside step2setup it came out as "the computer", "the
  // helper file", "the kitchen screen", "the print-station file", and only THEN "which printer gets
  // which paper" — so the paper lines, which belong to the computer above them, were separated from
  // it by a whole other subject. Read top to bottom it now goes: is it on · the computer · what that
  // computer prints · the screen that prints when it does not · what has printed.
  const stepScreen = `<div class="card"><h3>4 · The kitchen screen</h3>
        <p style="font-size:13px;margin:0 0 4px;line-height:1.5">
          Kitchen slips print on the <b>kitchen screen</b> already — there is nothing to switch on.
          ${((B.routes || {}).kot || {}).agent ? "Right now a computer above is set to print them, so it does that instead." : "No computer is set to print them, so the kitchen screen is doing it."}
        </p>
        <p class="muted" style="font-size:13px;margin:0 0 10px;line-height:1.5">
          Only change this to send the slips to <b>one particular person's</b> screen instead. Bills and
          banquet sheets are never affected — whoever presses Print gets the window.
        </p>
        ${(() => {
          const kot = (B.routes || {}).kot || {};
          const nm = kot.personName || "";
          const meIsIt = kot.person && B.person && kot.person === B.person.id;
          if (kot.via === "off") return `<p class="what"><b>Nobody</b> — kitchen slips do not print by themselves.</p>`;
          if (!kot.person) return `<p class="what">Anyone signed in on the <b>kitchen screen</b> prints them — no person to choose.${may ? " Press below to move them to this screen instead." : ""}</p>`;
          return `<p class="what"${meIsIt ? ' style="color:var(--green)"' : ""}>${meIsIt
            ? "Kitchen tickets print on <b>this</b> screen."
            : `Kitchen tickets print on <b>${esc(nm || "another person")}</b>'s screen.`}</p>`;
        })()}
        ${may ? `<div style="margin-top:10px"><button type="button" class="btn primary" data-pw="mine">Print them on this screen instead</button></div>` : ""}
      </div>` + fileCard(
        "The print-station file",
        `It opens a <b>separate</b> Chrome with its own profile, <b>out of the way</b>, with silent printing
         on — so it never comes to the front and never touches your own tabs or logins. Nothing secret is
         in it: you sign in <b>once</b> in the window it opens.`,
        sfiles,
        (k, f) => [
          `On the computer by the printer, open <b>${editorWord(k)}</b>.`,
          `Press <b>Copy</b> below, and paste it in.`,
          `Save it on the Desktop as <b>${esc(f.filename)}</b>${k === "windows" ? " with <b>Save as type: All Files</b>" : ""}.`,
          k === "mac" ? `In Terminal, once: <b>chmod +x ~/Desktop/print-station.command</b> — then double-click the file.` : "Double-click it.",
          esc(f.firstRun || ""),
        ],
        () => `Leave it running. It keeps the computer awake, because a sleeping machine prints nothing.`);

  // ── 3 · THE THREE PAPERS — the only question left ───────────────────────────────────────────
  // Each paper used to ask "who prints it" with three answers of its own, on top of the printer, the
  // person and the device. The ROUTE answers "who" — a paper names a computer's printer, or a screen,
  // or nobody — and with no computer set up yet the dropdown simply has nothing to offer and says so.
  const agentName = (id) => ((B.agents || []).find((a) => a.id === id) || {}).name || "another computer";

  // ── ONE CONTROL PER PAPER ──────────────────────────────────────────────────────────────────
  // The same shape as the admin console's board, on purpose: two screens describing one setup in
  // two visual languages is what made a person learn each separately. A line used to be an On
  // button, a Nobody button, a printer picker and a paper picker; the options ARE the answers now,
  // grouped by machine, saved on change.
  //
  // The value is "<agent uuid>|<printer name>" — a uuid can never contain a pipe, so splitting on
  // the FIRST one is safe even for a printer called "Front|Desk".
  const anyPrinters = (B.agents || []).some((a) => (a.printers || []).length);
  const line = (kind) => {
    const r = (B.routes || {})[kind] || {};
    const off = r.via === "off";
    const answered = !!r.via;
    const val = off ? "off" : (r.agent && r.printer ? r.agent + "|" + r.printer : "");
    if (!may) {
      return `<div class="pw-line">
        <h4>${esc(L.kind[kind] || kind)}</h4>
        <p class="what">${esc(L.what[kind] || "")}</p>
        <p class="what" style="margin-top:8px"><b>${esc(
          off ? (L.off[kind] || "Nobody")
          : r.printer ? `${r.printer} on ${agentName(r.agent)}`
          : "No printer chosen yet")}</b> — set by Aevidine.</p>
      </div>`;
    }
    return `<div class="pw-line">
      <h4>${esc(L.kind[kind] || kind)}</h4>
      <p class="what">${esc(L.what[kind] || "")}</p>
      <div class="pw-row" style="margin-top:9px">
        <select data-pw="printerpick" data-kind="${esc(kind)}" style="min-width:250px"${anyPrinters ? "" : ` disabled title="Set this computer up above first — the printers come from it."`}>
          <option value="off"${off ? " selected" : ""}>${esc(L.off[kind] || "Nobody")}</option>
          <option value=""${!off && !answered ? " selected" : ""}>— not decided yet —</option>
          ${(B.agents || []).map((a) => `<optgroup label="${esc(a.name)}">${(a.printers || []).map((pr) => {
            const v = a.id + "|" + pr.name;
            return `<option value="${esc(v)}"${v === val ? " selected" : ""}>${esc(pr.name)}</option>`;
          }).join("")}</optgroup>`).join("")}
        </select>
        ${(!off && r.agent && r.printer) ? `<button type="button" class="btn" style="padding:4px 9px;min-height:34px" data-pw="test" data-printer="${esc(r.printer)}">Test page</button>` : ""}
      </div>
      ${!anyPrinters ? `<p class="what" style="margin-top:8px">Set this computer up above first — the printers in this list come from it.</p>` : ""}
      ${off ? `<p class="what" style="margin-top:8px">${esc(kind === "kot"
          ? "No slip comes out by itself. Orders still appear on the kitchen screen, and this is the same switch as “Kitchen slips print by themselves” at the top."
          : "No printer does it silently — the ordinary print window opens for whoever presses Print.")}</p>` : ""}
    </div>`;
  };

  // THE THREE PAPERS EXIST ONLY IN COMPUTER MODE.
  // With no computer set up there is little to answer here: the kitchen slips fall to the kitchen
  // screen on their own, and the other two papers are printed by whoever presses Print, which is what
  // a restaurant with no helper has always done (owner, 2026-08-29). The lines are still shown — a
  // restaurant that adds a computer later answers them here — but they offer nothing until it has.
  // THE PAPER LINES ARE ALWAYS SHOWN NOW. This read `const step3 = mode !== "computer" ? "" : …`,
  // so with the mode gone the whole card threw `mode is not defined` and the board stopped at
  // "Reading the printing setup…" — the section rendered nothing at all. Which printer gets which
  // paper is a real question whether or not a computer is set up yet: the dropdowns simply have
  // nothing to offer until one is, and say so.
  const step3 = `<div class="card"><h3>3 · Which printer gets which paper</h3>
    <p class="muted" style="font-size:13px;margin:0 0 4px;line-height:1.5">
      The papers the helper takes come out on their own, with no window. Anything left on <b>normal</b>
      prints the way it always has: a window opens when somebody taps Print.
    </p>
    ${(B.kinds || ["kot", "bill", "banquet"]).map(line).join("")}
  </div>`;

  // ── 4 · WHAT HAS PRINTED ───────────────────────────────────────────────────────────────────
  const jobWord = (j) => j.status === "done" ? `<span style="color:var(--green)">printed</span>`
    : j.status === "failed" ? `<span style="color:var(--red)">gave up after ${j.attempts}</span>`
    : j.status === "dismissed" ? `<span class="muted">nothing to print</span>`
    : `<span style="color:var(--amber,#f5a524)">${esc(j.status)}</span>`;
  // HOW FAR BEHIND (owner, 2026-08-27) — the same fact the kitchen's 🖨 sheet and the floor strip
  // show, in the same words, from the same server field. A count on its own is not information:
  // "4 waiting" is normal for two seconds and an emergency after ten minutes.
  const sk = B.stuck || { n: 0, oldestMs: null, afterMs: 60000 };
  const skStuck = Number(sk.n) > 0 && Number(sk.oldestMs || 0) >= Number(sk.afterMs || 60000);
  // A DURATION, not a timestamp: "nothing since 14 min ago" is two ways of saying when at once.
  const skAge = !sk.oldestMs ? "" : Number(sk.oldestMs) < 60000 ? "under a minute"
    : Number(sk.oldestMs) < 3600000 ? Math.round(Number(sk.oldestMs) / 60000) + " minutes"
    : Math.round(Number(sk.oldestMs) / 3600000) + " hours";
  // Numbered by what came BEFORE it: choosing a computer adds a step that choosing a screen does not,
  // so this is 5 one way and 4 the other. The admin console numbers it the same way, from the same
  // rule, because two boards that number one setup differently are two setups to learn.
  const step4 = `<div class="card"><h3>5 · ${esc(STEP.four || "What has printed")} — waiting: ${Number(B.waiting || 0)}</h3>
    <p class="muted" style="font-size:13px;margin:0 0 10px">
      Nothing here is a guess: a job says <b>printed</b> only after the printer confirmed it.
    </p>
    ${Number(sk.n) > 0 ? `<div class="pw-state" style="margin-bottom:12px"><div class="pw-state-row ${skStuck ? "warn" : "yes"}">
      <span class="pw-dot" aria-hidden="true"></span>
      <span class="who"><b>${Number(sk.n)} kitchen slip${Number(sk.n) === 1 ? "" : "s"} waiting to print</b><br>${
        skStuck
          ? `Nothing has come out for <b>${esc(skAge)}</b>. Tell the kitchen to read the orders off their screen — every slip still prints, in order, once the printer is working.`
          : `The oldest has been waiting ${esc(skAge)} — they are going through normally.`}</span>
      <span class="pw-val">${skStuck ? "STUCK" : "OK"}</span>
    </div></div>` : ""}
    ${!(B.recent || []).length ? `<p class="muted" style="font-size:13px;margin:0">Nothing has printed yet.</p>` : `
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:12.5px">
        <thead><tr style="text-align:left;color:var(--muted)">
          <th style="padding:6px 8px">What</th><th style="padding:6px 8px">Where</th>
          <th style="padding:6px 8px">Result</th><th style="padding:6px 8px">When</th></tr></thead>
        <tbody>${B.recent.map((j) => `<tr style="border-top:1px solid var(--line)">
          <td style="padding:6px 8px">${esc(L.kind[j.kind] || j.kind)}</td>
          <td style="padding:6px 8px">${esc(j.printer || "—")}</td>
          <td style="padding:6px 8px">${jobWord(j)}${j.error ? `<div class="muted" style="font-size:11.5px">${esc(j.error)}</div>` : ""}</td>
          <td style="padding:6px 8px" class="muted">${esc(new Date(j.created_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }))}</td>
        </tr>`).join("")}</tbody>
      </table></div>`}
    <div style="margin-top:10px"><button type="button" class="btn" data-pw="reload">Refresh</button></div>
  </div>`;

  // THE GUIDE CARD IS GONE (owner, 2026-08-29). Setting a printer up is the admin's job on the
  // Printing screen, which carries the file and the five steps beside the thing they apply to. A
  // second copy of "how to print" in the restaurant's own settings was the old model's leftover:
  // it explained a setup this panel can no longer perform, in different words from the board above.
  const guide = "";

  return step1 + step2setup + step3 + stepScreen + step4 + guide;
}

// One pass of the queue: what is waiting → claim it → print it → say what happened.
//
// Called on every ops breadcrumb (so a ticket prints the instant the order lands) and by a 20s
// timer as the backstop. It deliberately does NOT check document.hidden: this screen being covered
// by another window is exactly the situation the owner reported, and a print that does not happen is
// reported failed and requeued rather than lost.
let printPassBusy = false;
// One automatic claim per page load. A screen that cannot take the printer (another live screen has
// it) must not hammer the endpoint every poll.
let stationClaimTried = false;
async function managerPrintPass() {
  if (printPassBusy) return;
  // NO PER-DEVICE OPT-IN ANY MORE. This used to read a localStorage answer to "should this screen
  // print?" and stay silent until somebody tapped yes. That question belongs to the Printing board
  // now — the admin names one person — so a screen that waits to be tapped is simply a printer that
  // never prints. The server's `off` is the only gate.
  printPassBusy = true;
  try {
    const r = await api("GET", "/print-jobs/pending");
    // `helper` is WHO REALLY PRINTS when a computer owns this paper (mig 341). It was missing from
    // this object at first, so every new line about it stayed invisible however right the server
    // was — the panel simply never carried the answer. Caught by driving the panel, not by reading.
    const says = { mayPrint: !(r && r.off), target: (r && r.target) || "kitchen", station: (r && r.station) || null, helper: (r && r.helper) || null };
    // WHO OWNS EACH KIND OF PAPER — kitchen slips, bills, banquet sheets. printBill() and
    // printBanquetBill() read this to decide whether to send the job to a computer or to open the
    // window as they always have.
    printOwners = (r && r.helpers) || printOwners;
    // CLAIM IT, DO NOT ASK FOR IT. The admin named this screen on the Printing board; if no live
    // station holds the printer, this one takes it silently. Only when the server says this screen
    // may print (`!r.off`) — every other screen leaves it alone, so two screens never race.
    // A PHONE MUST NEVER CLAIM A TICKET. This was the point of the old per-device question, and the
    // danger did not go away when the question did: the manager panel is opened on phones, and a
    // phone that claims a ticket drops it into a print dialog nobody looks at while the kitchen gets
    // no paper. The admin's choice names a PERSON, and that person may well open their phone.
    // So the mechanism changes and the rule does not: a COARSE pointer (touch, no mouse) never
    // auto-claims. A real computer with a printer attached does.
    const looksLikeAComputer = !(window.matchMedia && window.matchMedia("(pointer: coarse)").matches);
    if (r && !r.off && looksLikeAComputer && r.station && !r.station.mine && (!r.station.active || r.station.stale) && !stationClaimTried) {
      stationClaimTried = true;                       // once per load: a failed claim must not loop
      try { const t = await api("POST", "/print-station/take", {}); if (t && t.station) says.station = t.station; }
      catch { /* the next pass tries again after a reload — never a retry storm */ }
    }
    const stationKey = (v) => v && v.station && v.station.active ? `${v.station.active.device_id}:${v.station.mine}:${v.station.stale}` : String(!!(v && v.station));
    // A helper appearing or going quiet must repaint too, or the floor strip keeps yesterday's answer.
    const helperKey = (v) => v && v.helper && v.helper.owned ? `${v.helper.agent}:${v.helper.printer}:${v.helper.connected}` : "none";
    const changed = !printTargetSays || printTargetSays.mayPrint !== says.mayPrint || printTargetSays.target !== says.target
      || stationKey(printTargetSays) !== stationKey(says) || helperKey(printTargetSays) !== helperKey(says);
    printTargetSays = says;
    if (changed && state.tab === "tables") renderEditor();   // the question appears (or goes away)
    // THE SERVER'S ANSWER IS THE ONLY ONE. `ans` used to be this browser's own yes/no to "should
    // this screen print?", and when that opt-in was deleted this line was left reading it — an
    // undeclared name, so the whole pass threw and EVERY screen-mode ticket stayed queued for ever.
    // Nothing on screen said so: the strip was right, the board was right, the server offered the
    // job, and the panel silently dropped it. Caught by running two real Chromes and watching a real
    // order fail to print (owner, 2026-08-29). A deletion is not finished until the things that read
    // the deleted thing are gone too.
    if (!says.mayPrint) return;                              // a helper-owned restaurant lands here
    // ONE SCREEN PRINTS (mig 338). A live station elsewhere means this screen shows "printing happens
    // there · print here instead" and takes NOTHING — the server would refuse the claim anyway; not
    // asking is what stops two screens fighting over every ticket.
    if (says.station && says.station.active && !says.station.mine && !says.station.stale) return;
    const jobs = (r && r.jobs) || [];
    if (!jobs.length) return;
    // The CLAIM is a plain fetch, never the offline outbox: a claim replayed hours later would print
    // a stale ticket behind everyone's back. A claim that fails simply waits for the next pass.
    const cr = await fetch("/api/editor" + ridQ("/print-jobs/claim"), {
      method: "POST", headers: { "Content-Type": "application/json" }, credentials: "same-origin",
      body: JSON.stringify({ ids: jobs.map((j) => j.id) }),
    });
    if (!cr.ok) return;
    const won = new Set(((await cr.json().catch(() => ({}))).won) || []);
    for (const j of jobs.filter((x) => won.has(x.id))) {
      const o = j.order || {};
      const rows = (j.items && j.items.length) ? j.items : (Array.isArray(o.items) ? o.items : []);
      // A retry says so on the paper (`attempts > 0`) — see the same rule in the kitchen panel.
      const okPrint = printTicketHtml(kotTicketHtml({
        title: `KOT ${o.kot_no ?? "—"}`,
        rname: (state.data.restaurant || {}).name || "Kitchen",
        head: "KITCHEN TICKET",
        kot: o.kot_no ?? "—",
        tableLabel: tablePrintLabel(o.table_number),
        when: LFH_BILLDOC.kotWhen(o.created_at),
        lines: rows,
        allergies: Array.isArray(o.allergies) ? o.allergies : [],
        reprint: j.reprint !== false || (j.attempts || 0) > 0,
      })) !== false;
      // The done report DOES ride the outbox — it is idempotent, and losing it would let the
      // two-minute reclaim print the same ticket again.
      api("POST", `/print-jobs/${j.id}/done`, { ok: okPrint, error: okPrint ? undefined : "print call failed on the manager screen" }).catch(() => {});
      if (okPrint) {
        lastPrintedHere = { kot: o.kot_no ?? null, table: o.table_number != null ? tablePrintLabel(o.table_number) : null, at: new Date().toISOString() };
        // Repaint the card if the person happens to be looking at it, so "is this thing working?"
        // is answered on screen instead of by walking to the printer.
        if (state.tab === "tables") renderEditor();   // the strip shows the ticket it just printed
      } else {
        // Tell the manager once a minute at most — the same discipline the kitchen panel uses.
        notePrintTroubleHere();
      }
      await new Promise((res) => setTimeout(res, 400));   // serialized: a burst can't stack dialogs
    }
  } catch (e) { /* offline / busy — the next pass retries, and the job is still queued */ }
  finally { printPassBusy = false; }
}
let lastPrintTroubleHereAt = 0;
function notePrintTroubleHere() {
  if (Date.now() - lastPrintTroubleHereAt < 60000) return;
  lastPrintTroubleHereAt = Date.now();
  toast("A kitchen ticket wouldn't print on this screen — check the printer.", "err");
}

// SPLIT-SETTLE'S SECOND SCREEN IS GONE (owner, 2026-08-29: "I want all the options for both the
// interface should be similar", and "it should not look like a mess").
//
// openSplitSettle() used to open a SEPARATE overlay here — Equal / Custom / By dish — while the
// pay sheet's own split offered an even share and 🧾 By order, and the tablet offered all four on
// one screen. Three screens, three different answers to "how do I split this bill?", and the two
// manager ones could not even be reached from each other. The pay sheet's split now carries all
// four ways (see openPaymentMethodModal), so this one was a strictly smaller copy of it.
//
// Everything that used to open it — the table-ops menu, the ⋯ drill-down and the 🍴 Split button
// on the table sheet — opens the ONE split screen instead, via markTablePaid(t, { openSplit: true }).
// Do not reintroduce a second split screen in this panel: `verify:split-payment` already refuses
// one on the tablet, and now refuses one here too.

// Move ONE dish line to another table — two steps in one modal: pick the dish
// (grouped under its KOT), then pick the target table. The dish lands under a fresh
// KOT on the target and BOTH bills re-price server-side (mig 175).
function openMoveItemPicker(t) {
  document.querySelector(".moveitem-overlay")?.remove();
  const orders = ordersForTable(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid");
  const groups = orders.map((o) => {
    const items = orderItemRows(o).filter((r) => r.kind === "session");
    if (!items.length) return "";
    return `<div class="muted" style="font-size:11.5px;margin:8px 2px 4px">KOT #${o.kot_no != null ? esc(o.kot_no) : "—"}</div>` +
      items.map((r) => `<button class="btn" data-mvitem="${esc(r.id)}" style="display:flex;justify-content:space-between;width:100%;margin:0 0 6px;padding:10px 14px"><span>${r.qty > 1 ? r.qty + "× " : ""}${esc(r.title)}</span><span>${inr(r.price * (r.qty || 1))}</span></button>`).join("");
  }).join("");
  if (!groups) { toast("No movable dishes on this table", "err"); return; }
  const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  const wrap = el(`<div class="sx-modal-overlay moveitem-overlay"><div class="sx-modal" style="max-width:440px">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>🍛 Move a dish from ${esc(tileFace(t))}</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="muted small mvi-hint" style="padding:0 14px 8px">Step 1 · which dish should move? (a multi-plate line moves whole)</div>
    <div class="dish-edit-body mvi-body" style="padding:6px 14px 14px">${groups}</div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  const body = wrap.querySelector(".mvi-body");
  const hint = wrap.querySelector(".mvi-hint");
  wrap.querySelectorAll("[data-mvitem]").forEach((b) => (b.onclick = () => {
    const itemId = b.dataset.mvitem;
    hint.textContent = "Step 2 · move it to which table? (it gets its own new KOT there)";
    // Same rule as Move-a-KOT: the floor's list, the floor's names, and this party's own tables
    // dimmed rather than offered (T3 sweep, 2026-08-10).
    const party = new Set(partyTablesOf(t).map(String));
    const tiles = floorTableList(n).map((i) => {
      if (String(i) === String(t)) return "";
      if (party.has(String(i))) return `<button class="kotm-tile kotm-tile-off" disabled aria-disabled="true" title="${esc(tileFace(i))} — same bill"><b>${esc(tileFace(i))}</b><small>same bill</small></button>`;
      const open = summaryTableOpen(i);
      return `<button class="kotm-tile${open ? " occ" : ""}" data-mvto="${i}"><b>${esc(tileFace(i))}</b><small>${open ? "joins bill" : "free"}</small></button>`;
    });
    body.innerHTML = `<div class="kotm-grid">${tiles.join("")}</div>`;
    body.querySelectorAll("[data-mvto]").forEach((tb) => (tb.onclick = async () => {
      const to = tb.dataset.mvto; closeM();
      try {
        const r = await api("POST", `/order-items/${itemId}/move`, { to });
        if (r && r.ok === false) { toast("Couldn't move: " + (KOT_REASON_TEXT[r.reason] || r.reason || "rejected"), "err"); return; }
        okToast(r, `Dish moved to ${tileFace(to)} (new KOT)`);
      } catch (e) { toast("Failed: " + e.message, "err"); }
    }));
  }));
}

// MERGE picker — a grid of the OCCUPIED tables (the opposite of the shift picker's
// free-only grid): pick which party this table joins. Confirms first — a merge can't
// be un-done with one tap (the source session closes; orders/guests move for good).
function openMergePicker(t, sess) {
  document.querySelector(".merge-overlay")?.remove();
  const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  // floorTableList + the floor's own names, so the phone offers exactly what the desktop offers
  // and calls each table what the floor calls it (T3 sweep, 2026-08-10).
  const occ = floorTableList(n).filter((i) => String(i) !== String(t) && summaryTableOpen(i));
  const partyFace = (i) => { const kids = mergeChildrenOf(i); return kids.length ? [tileFace(i), ...kids.map(tileFace)].join(" + ") : tileFace(i); };
  const tileDue = (i) => { const tile = (state.summary && state.summary.tiles || {})[String(i)]; return tile && tile.due > 0 ? inr(tile.due) : ""; };
  const myDue = billMath(partyOrders(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid" && o.status !== "received")).total;
  const grid = occ.length
    ? `<div class="kotm-grid">` + occ.map((i) => `<button class="kotm-tile occ${mergeChildrenOf(i).length ? " kotm-tile-party" : ""}" data-mergeto="${i}"><b>${esc(partyFace(i))}</b><small>${tileDue(i) ? `due ${tileDue(i)}` : "open"}</small></button>`).join("") + `</div>`
    : `<div class="muted" style="padding:14px">No other open tables to merge with.</div>`;
  const wrap = el(`<div class="sx-modal-overlay merge-overlay"><div class="sx-modal shift-modal"><div class="tbl-modal-head"><div class="tp-detail-top"><h3>🪢 Merge ${esc(tileFace(t))} into →</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div><div class="muted small" style="padding:0 14px 10px">Everything — orders, guests, calls &amp; bill — joins as ONE bill, held by the LOWEST table number.</div><div class="shiftgrid">${grid}</div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  wrap.querySelectorAll("[data-mergeto]").forEach((b) => (b.onclick = async () => {
    const to = b.dataset.mergeto;
    // THE BILL GOES TO THE LOWER NUMBER, WHICHEVER ONE YOU TAPPED (T3 sweep, 2026-08-10). This said
    // "Both parties become ONE bill on T${to}" — so merging T4 into T9 promised the bill would be on
    // T9 and the server put it on T4. The desktop path has said it correctly since mig 249; the
    // phone was left with the old sentence. The money is shown for the same reason the desktop shows
    // it (owner, 2026-08-11 — improvement 5): this is the tap that joins two parties' money.
    const theirDue = (() => { const tile = (state.summary && state.summary.tiles || {})[String(to)]; return (tile && Number(tile.due)) || 0; })();
    const keeps = (Number(t) <= Number(to)) ? t : to;
    const money = (myDue > 0 || theirDue > 0) ? ` ${inr(myDue)} + ${inr(theirDue)} → ${inr(myDue + theirDue)} on one bill.` : "";
    if (!(await confirmDialog(`Merge ${tileFace(t)} into ${partyFace(to)}? They become ONE party on ONE bill, held by ${tileFace(keeps)} (the lowest table number).${money}`, "Merge"))) return;
    closeM();
    try {
      const r = await api("POST", `/sessions/${sess.id}/merge`, { to });
      if (r && r.ok === false) { toast("Couldn't merge: " + (KOT_REASON_TEXT[r.reason] || r.reason || "rejected"), "err"); return; }
      // WHICH TABLE HOLDS THE BILL IS THE SERVER'S ANSWER (T5 sweep #7, 2026-08-22). With no
      // signal `r.parent_table` is absent and this fell back to the guess made on screen, then
      // announced the merge as done — over a floor where the two tables are still separate.
      if (wasQueued(r)) { toast("Saved on this device ✓ — the tables will be joined onto one bill the moment you're back online.", "ok"); return; }
      toast(`Merged into ${tileFace((r && r.parent_table) || keeps)} — one bill`, "ok");
      // Fresh tiles + merges list first, then follow the table the SERVER kept (the lowest
      // number holds the bill — not always the one that was tapped). Same fix as the desktop
      // columns: without the poll the detail counts one table's food (owner, 2026-08-03).
      const parent = (r && r.parent_table) || to;
      await pollTables([String(parent), String(t), String(to)]);
      followShiftedTable(t, parent); // the detail follows the party to its combined home
    } catch (e) { toast("Failed: " + e.message, "err"); }
  }));
}

// Move ONE order (a single KOT) to another table — two steps in one modal: pick the
// KOT, then pick the target table. Unlike Change-table, the target may be OCCUPIED
// (the KOT joins that party's bill) or free (a fresh session opens for it).
function openMoveKotPicker(t) {
  document.querySelector(".movekot-overlay")?.remove();
  const movable = ordersForTable(t).filter((o) => o.status !== "cancelled" && o.payment_status !== "paid");
  if (!movable.length) { toast("No movable KOTs on this table", "err"); return; }
  const n = Math.max(1, parseInt((state.data.settings || {}).table_count, 10) || 12);
  const kotRow = (o) => {
    const items = orderItemRows(o);
    const nd = items.reduce((s, r) => s + (parseInt(r.qty, 10) || 1), 0);
    return `<button class="btn kotpick" data-kot="${esc(o.id)}" style="display:flex;justify-content:space-between;width:100%;margin:0 0 8px;padding:11px 14px">
      <span><b>KOT #${o.kot_no != null ? esc(o.kot_no) : "—"}</b> · ${nd} dish${nd === 1 ? "" : "es"}</span><span>${inr(parseFloat(o.total) || 0)}</span></button>`;
  };
  const wrap = el(`<div class="sx-modal-overlay movekot-overlay"><div class="sx-modal" style="max-width:440px">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>🧾 Move a KOT from ${esc(tileFace(t))}</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="muted small" style="padding:0 14px 8px">Step 1 · which KOT should move?</div>
    <div class="dish-edit-body movekot-body" style="padding:6px 14px 14px">${movable.map(kotRow).join("")}</div></div></div>`);
  document.body.appendChild(wrap);
  const closeM = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = closeM;
  wrap.onclick = (e) => { if (e.target === wrap) closeM(); };
  const body = wrap.querySelector(".movekot-body");
  const hint = wrap.querySelector(".muted.small");
  wrap.querySelectorAll("[data-kot]").forEach((b) => (b.onclick = () => {
    const orderId = b.dataset.kot;
    const o = movable.find((x) => x.id === orderId);
    hint.textContent = `Step 2 · move KOT #${o && o.kot_no != null ? o.kot_no : "—"} to which table?`;
    // The floor's own list and the floor's own names — and a table of THIS party is dimmed with a
    // reason instead of offered: it resolves to the bill this KOT is already on, so the server
    // answers 'same_table' every time (T3 sweep, 2026-08-10).
    const party = new Set(partyTablesOf(t).map(String));
    const tiles = floorTableList(n).map((i) => {
      if (String(i) === String(t)) return "";
      if (party.has(String(i))) return `<button class="kotm-tile kotm-tile-off" disabled aria-disabled="true" title="${esc(tileFace(i))} — same bill"><b>${esc(tileFace(i))}</b><small>same bill</small></button>`;
      const open = summaryTableOpen(i);
      return `<button class="kotm-tile${open ? " occ" : ""}" data-moveto="${i}"><b>${esc(tileFace(i))}</b><small>${open ? "joins bill" : "free"}</small></button>`;
    });
    body.innerHTML = `<div class="kotm-grid">${tiles.join("")}</div>`;
    body.querySelectorAll("[data-moveto]").forEach((tb) => (tb.onclick = async () => {
      const to = tb.dataset.moveto; closeM();
      try {
        const r = await api("POST", `/orders/${orderId}/move`, { to });
        if (r && r.ok === false) { toast("Couldn't move: " + (KOT_REASON_TEXT[r.reason] || r.reason || "rejected"), "err"); return; }
        okToast(r, `KOT moved to ${tileFace(to)}`);
        // Both tables repaint via the RPC's breadcrumbs (targeted refetch) — no manual reload.
      } catch (e) { toast("Failed: " + e.message, "err"); }
    }));
  }));
}

// openDiscountModal: replaces the old "type the ₹ amount to knock off" prompt() with
// two staff-friendly ways to land on the same number (owner, 2026-07-01 — "I don't want
// the amount-to-discount option like it's right now"):
//   "They pay"    — staff types the FINAL amount the customer will pay; we work BACKWARD
//                   to the discount (bill − pay) and show the % that comes out to.
//   "Percent off" — staff types a %; we work FORWARD to the discount (bill × %) and show
//                   what the customer ends up paying.
// Both modes just compute the same ₹ discount the server has always accepted — the API
// call at the bottom (POST .../discount {amount, note}) is byte-identical to before, so
// the clamp-to-bill-total safety net and the note field behave exactly as they did.
// Split the bill EVENLY between guests — a helper that shows each person's share (bill total ÷ N,
// the last share absorbs the rounding so they sum EXACTLY to the total). It does NOT change the bill
// or the payment: the manager still taps "Mark paid" to settle the whole bill once collected.
// (Per-item / per-seat splitting with separate payments is a planned bigger step.)
function openSplitBill(total) {
  document.querySelector(".split-overlay")?.remove();
  total = Math.max(0, Number(total) || 0);
  let n = 2;
  const wrap = el(`<div class="sx-modal-overlay split-overlay"><div class="sx-modal" style="max-width:420px">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>🍴 Split the bill</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="dish-edit-body">
      <div class="disc-bill-row"><span>Bill total</span><b>${inrExact(total)}</b></div>
      <div style="display:flex;align-items:center;gap:12px;margin:14px 0;flex-wrap:wrap">
        <label class="dish-edit-lbl" style="margin:0">Split between</label>
        <button class="btn" id="spMinus" type="button" style="min-width:44px">−</button>
        <b id="spN" style="font-size:18px;min-width:24px;text-align:center">2</b>
        <button class="btn" id="spPlus" type="button" style="min-width:44px">+</button>
        <span class="muted">people</span>
      </div>
      <div id="spBody"></div>
      <div class="muted small" style="margin-top:10px">A helper only — collect each share, then tap “Mark paid” to settle the whole bill.</div>
    </div>
  </div></div>`);
  document.body.appendChild(wrap);
  const close = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };
  const paint = () => {
    wrap.querySelector("#spN").textContent = n;
    // NUDGE BEFORE THE FLOOR, or a share loses a whole paisa (sweep #8 T7 — the same fault, and
    // the same repair, as the split-PAYMENT sheet's `Math.floor((due / n) * 100 + 1e-6)` above).
    // ₹555.55 ÷ 5 is exactly ₹111.11, but in binary the division lands on 11110.999999999998, so
    // a bare floor made it 111.10 — and the last person, who absorbs the remainder, was asked for
    // 111.15. Four people underpaying by a paisa each and one overpaying by four is not a
    // rounding detail on a screen a waiter reads out loud.
    const base = Math.floor((total / n) * 100 + 1e-6) / 100;   // each share, floored to paise
    const shares = Array(n).fill(base);
    shares[n - 1] = Math.round((total - base * (n - 1)) * 100) / 100; // last absorbs the remainder → exact sum
    // inrExact, NOT inr — this sheet is the one place the note above inr() names: "a figure the
    // person has to MATCH". inr() rounds to whole rupees, so the five shares of a ₹555.55 bill all
    // printed "₹111" and a waiter reading them out collected ₹555 for a ₹555.55 bill; four shares
    // of ₹1,234.50 printed "₹309" four times and asked for ₹1.50 too much. inrExact shows the
    // paise only when there are any, so an ordinary round bill still reads exactly as before.
    wrap.querySelector("#spBody").innerHTML = `<div class="tp-bill">` + shares.map((s, i) => `<div class="tp-bl"><span>Person ${i + 1}</span><b>${inrExact(s)}</b></div>`).join("") + `</div>`;
  };
  wrap.querySelector("#spMinus").onclick = () => { if (n > 2) { n--; paint(); } };
  wrap.querySelector("#spPlus").onclick = () => { if (n < 20) { n++; paint(); } };
  paint();
}

// `pending` (2026-08-03) — the ONE case where there is no order to POST to yet: the ⚡ QO/P
// builder, where the discount is typed while the order is still being assembled. Pass
// { onApply(amount, note) } and this modal computes and previews exactly as it always does,
// then hands the number back instead of calling the server. Everything above that line — the
// two linked fields, the % chips, the pre-tax base, the "They pay" preview — is shared, which
// is the point: one discount interface, not a second one that drifts.
function openDiscountModal(order, rerender, billTotal, bm, wholeBill, pending) {
  document.querySelector(".disc-overlay")?.remove();
  const round2 = (n) => Math.round(n * 100) / 100;
  const clamp = (n, lo, hi) => Math.min(Math.max(Number.isFinite(n) ? n : 0, lo), hi);
  const current = Number(order.discount) || 0;
  // The stored discount is a PRE-TAX rupee amount: billMath subtracts it from the subtotal
  // and THEN adds tax. So "They pay" must recompute the tax — subtracting the discount from
  // the tax-INCLUSIVE total overstated it by discount×taxrate and mis-scaled the % (fixed
  // 2026-07-06). We discount against the table's pre-tax base, preserving any discount
  // already on OTHER orders of the same table (bm = billMath(os), passed by the caller;
  // billTotal is kept only for legacy callers that don't pass bm).
  const rate = bm ? bm.rate : taxModel(state.data.settings).rate;
  // THE DISCOUNT IS CAPPED AT THE TAXABLE BASE, NOT THE WHOLE SUBTOTAL (mig 270). An MRP line
  // is a price that is legally FINAL — selling below it via a bill discount is as wrong as
  // selling above it — and the identity every panel computes "due" from
  // (due = total − discount × (1 + rate)) only holds while the discount stays inside the
  // taxable pile. So the untaxed money is carried alongside, added back at the end, and
  // simply never offered as something to discount. On a bill with no MRP lines (every
  // restaurant today) taxableBase IS the subtotal, so this is the old number exactly.
  // capBase = what may be discounted at all; fixedPart = the money that stays put whatever
  // the discount is (see billMath — with tax it is the untaxed lines, without tax it is only
  // the locked MRP). Legacy callers that pass no `bm` fall back to the old derivation, which
  // is the all-taxable case and therefore unchanged.
  const capBase = bm
    ? (bm.discountBase != null ? bm.discountBase : (bm.taxableBase != null ? bm.taxableBase : bm.subtotal))
    : ((Number(order.total) || 0) / (1 + rate) + current);
  const nontax = bm ? (bm.discountFixed != null ? bm.discountFixed : (Number(bm.nontax) || 0)) : 0;
  // wholeBill (manager bill discount): the amount passed IS the whole-bill discount (stored on the
  // session, split server-side), so there is no "other orders' discount" to preserve — discount the
  // full pre-tax bill. Legacy per-order callers keep the old "subtract other orders" behaviour.
  const otherDisc = wholeBill ? 0 : (bm ? Math.max(0, bm.disc - current) : 0);
  const base = Math.max(0, round2(capBase - otherDisc)); // the part THIS modal may discount
  const payFor = (d) => round2(Math.max(0, base - clamp(d, 0, base)) * (1 + rate) + nontax); // what the customer pays
  // WORDING MUST MATCH THE REASON. The undiscountable part is not always MRP: it is the
  // untaxed lines when tax applies, and only the locked MRP when it doesn't. Saying "MRP" over
  // a nil-rated dish would send a manager looking for a bottle that isn't on the bill, so the
  // message names MRP only when there genuinely is some.
  const lockedMrp = bm ? (Number(bm.mrpAmount) || 0) : 0;
  const lockedNote = lockedMrp > 0 ? inr(lockedMrp) : inr(nontax);
  const total = payFor(0); // the table total BEFORE this order's discount (shown as "Bill total")
  // THE PERSON'S OWN CEILING IS PART OF THE MAXIMUM (2026-08-11, T7 improvement I5).
  // Two limits decide how much may come off, and this modal only knew one of them:
  //   · the BILL's — you cannot discount more than the taxable food (mig 272), handled by `base`;
  //   · the PERSON's — a waiter's 5%, a manager's 50% (lib/discountCap.ts), which lived ONLY on the
  //     server. So a waiter could type ₹500 off a ₹1,000 bill, watch the preview agree, press Apply,
  //     and get "That discount is over your 5% limit — ask the owner." A refusal at the last tap is
  //     the failure this panel already argues against for the other cap; it just never had the
  //     number to argue with. whoami sends it now (`discountCapPct`, null = uncapped).
  // The SERVER still decides — overDiscountCap in orders/discount is untouched. Taking the smaller
  // of the two here only stops the screen offering a figure that was always going to be refused,
  // and it reuses the refusal machinery below word for word, so the person is told the real
  // maximum as they type instead of after committing.
  const roleCapPct = XRAY_WHO && typeof XRAY_WHO.discountCapPct === "number" ? XRAY_WHO.discountCapPct : null;
  const roleCapAmt = roleCapPct != null ? round2((capBase * roleCapPct) / 100) : Infinity;
  const maxDisc = Math.max(0, Math.min(base, roleCapAmt));
  // True when the PERSON is what set the ceiling, not the bill — so the message can say which,
  // because "why can't I take ₹200 off a ₹1,000 bill?" has a real answer and hiding it is what
  // makes staff distrust the screen.
  const cappedByRole = roleCapPct != null && roleCapAmt < base - 0.004;
  // ONE interface, no mode toggle (owner, 2026-07-03): a Percent and an Amount(₹) field,
  // two-way linked from a single discAmount (₹ off, pre-tax — the value the server stores),
  // so they can never disagree. The % is off the pre-tax base.
  //
  // THE FIGURE THEY ACTUALLY NEGOTIATE IS "THEY PAY" (owner, 2026-08-03: "I see 817, I can change
  // that to 800 and it can auto-calculate the discount and the discount percentage by itself").
  // A counter conversation is "make it 800", never "give 2.08% off", so the third field is
  // EDITABLE too: type what they'll hand over and the discount + the % fall out of it. All three
  // boxes are views of the same discAmount, so no two of them can ever disagree.
  let discAmount = clamp(current, 0, maxDisc);
  let pctVal = base > 0 ? Math.round((discAmount / base) * 1000) / 10 : 0;

  const wrap = el(`<div class="sx-modal-overlay disc-overlay"><div class="sx-modal disc-modal">
    <div class="tbl-modal-head"><div class="tp-detail-top"><h3>Apply discount</h3><button class="tbl-modal-close" aria-label="Close">✕</button></div></div>
    <div class="dish-edit-body disc-body">
      <div class="disc-bill-row"><span>Bill total</span><b>${inr(total)}</b></div>
      <div class="disc-linked-row">
        <div class="disc-field">
          <label class="dish-edit-lbl">Discount %</label>
          <!-- step="0.01", NOT "1" (T7 sweep #7, 2026-08-30 — the same rule the owner ruled on for this
                 panel's split-amount box on 2026-08-29). THIS SHEET FILLS THESE BOXES IN ITSELF: paintTip
                 writes a percentage to one decimal and an amount with r2(), and the discount modal's
                 paint() writes 12.5 into the percent box and 153.29 into the amount box. Declaring
                 whole numbers only made each box refuse its own contents — a hardware ↑/↓ snapped 12.5
                 to 13, and a person correcting a figure by hand was pushed to whole rupees on a bill
                 that carries paise. Found on the WAITER TABLET first (its three were identical) and
                 fixed there as item 18; this is the other half of the same fault. -->
              <input type="number" inputmode="decimal" min="0" max="100" step="0.01" class="dish-edit-custominput disc-input" id="discPctInput" placeholder="0">
        </div>
        <div class="disc-linked-eq">=</div>
        <div class="disc-field">
          <label class="dish-edit-lbl">Discount amount (₹)</label>
          <input type="number" inputmode="decimal" min="0" step="0.01" class="dish-edit-custominput disc-input" id="discAmtInput" placeholder="0">
        </div>
      </div>
      <div class="chips disc-pct-quick">${[0, 5, 10, 15, 20, 25, 50].map((p) => `<span class="chip disc-pct-pick" data-pct="${p}">${p ? p + "%" : "None"}</span>`).join("")}</div>
      <div class="disc-preview">
        <div class="disc-prev-row"><span>Discount</span><b id="discPrevAmt">− ${inr(current)}</b></div>
        <div class="disc-prev-row grand">
          <span>They pay</span>
          <label class="disc-pay-edit" title="Type what the customer will actually pay — the discount works itself out">
            <span class="disc-pay-cur">₹</span>
            <input type="number" inputmode="decimal" min="0" step="0.01" id="discPayInput" class="disc-pay-input" aria-label="Amount they pay">
          </label>
        </div>
      </div>
      <div class="disc-cap-msg" id="discCapMsg" role="status" hidden></div>
      <div class="disc-hint muted small">Change any one of the three — the other two follow.${nontax > 0 ? ` The % is off the discountable part only — ${lockedNote} of this bill ${lockedMrp > 0 ? "is MRP items, whose price is final" : "carries no GST"}.` : ""}</div>
      <label class="dish-edit-lbl" style="margin-top:14px">Reason <span class="muted small">(optional, shows on the bill)</span></label>
      <input type="text" class="dish-edit-custominput" id="discNoteInput" maxlength="200" placeholder="e.g. loyalty, comp, manager approval">
    </div>
    <div class="dish-edit-foot">
      ${current > 0 ? `<button type="button" class="btn danger disc-remove">Remove discount</button>` : ""}
      <span class="disc-foot-spacer"></span>
      <button type="button" class="btn dish-edit-cancel">Cancel</button>
      <button type="button" class="btn primary disc-apply">Apply</button>
    </div>
  </div></div>`);
  document.body.appendChild(wrap);
  wrap.querySelector("#discNoteInput").value = order.discount_note || "";
  const pctInput = wrap.querySelector("#discPctInput");
  const amtInput = wrap.querySelector("#discAmtInput");
  const payInput = wrap.querySelector("#discPayInput");
  const applyBtn = wrap.querySelector(".disc-apply");
  pctInput.value = pctVal ? String(pctVal) : "";
  amtInput.value = current ? String(round2(current)) : "";

  // Refresh ONLY the preview + the OTHER fields from discAmount — never the field the
  // user is typing in (so their caret/partial number isn't clobbered mid-keystroke).
  // The pay box is written in WHOLE rupees, the same figure inr() puts on the bill and the
  // paper: showing 799.99 for a bill that will print ₹800 is a disagreement, not precision.
  const paint = (typing) => {
    pctVal = base > 0 ? Math.round((discAmount / base) * 1000) / 10 : 0;
    if (typing !== "pct") pctInput.value = discAmount ? String(pctVal) : "";
    if (typing !== "amt") amtInput.value = discAmount ? String(round2(discAmount)) : "";
    if (typing !== "pay") payInput.value = String(Math.round(payFor(discAmount)));
    wrap.querySelector("#discPrevAmt").textContent = "− " + inr(discAmount);
  };
  // A HALF-TYPED FIGURE MUST NOT BE APPLIABLE. Clearing the pay box means "I'm about to type
  // a number", never "they pay ₹0" — comping a whole bill by deleting three characters is the
  // kind of silent money mistake this panel has been bitten by before (the waiter panel carries
  // the same guard). While a box is empty or nonsense, the old discount stands and Apply waits.
  const setBlank = (blank) => { applyBtn.disabled = blank; applyBtn.style.opacity = blank ? ".5" : ""; };

  // A REFUSAL IS SHOWN, NEVER A SILENT TRIM (the "a user's tap must never vanish in silence"
  // rule). Typing more than the bill can carry used to be clamped with NOTHING on screen: the
  // figure changed under the finger and the person could not tell whether the panel had heard
  // them or was broken. Now the modal shakes once and says what the real maximum is — and
  // names MRP as the reason when that is what set the floor, because "why can't I take ₹200
  // off a ₹250 bill?" has a real answer and hiding it is what makes staff distrust the screen.
  const capMsg = wrap.querySelector("#discCapMsg");
  let nudgeT = null;
  const capLine = () => `Most you can take off this bill is ${inr(maxDisc)}`
    // WHICH ceiling bit. The person's own %-limit wins the sentence when it is the tighter of the
    // two, because that is the one they can do something about (ask the owner) — naming MRP there
    // would send them looking for a bottle that isn't the reason.
    + (cappedByRole
        ? ` — that is your ${roleCapPct}% limit. Ask the owner if you need to go higher.`
        : nontax > 0
          ? ` — the other ${lockedNote} ${lockedMrp > 0 ? "is MRP items, whose price is final" : "carries no GST and can't be discounted"}.`
          : ".");
  const clearRefusal = () => { if (!capMsg.hidden) { capMsg.hidden = true; capMsg.textContent = ""; } };
  const refuse = (msg) => {
    capMsg.textContent = msg;
    capMsg.hidden = false;
    wrap.classList.remove("disc-nudge");
    void wrap.offsetWidth;                 // restart the shake on a second refusal in a row
    wrap.classList.add("disc-nudge");
    clearTimeout(nudgeT);
    nudgeT = setTimeout(() => wrap.classList.remove("disc-nudge"), 320);
  };

  // Edit % → derive amount (off the pre-tax TAXABLE base). Edit amount → derive %. Edit "they
  // pay" → work backward to the discount: pay is tax-INCLUSIVE and includes the untaxed MRP
  // money, so the pre-tax discount is base − (pay − MRP)/(1+rate). All clamp so the discount
  // can't exceed the taxable food value, and anything above that is refused OUT LOUD.
  pctInput.oninput = () => {
    const typed = parseFloat(pctInput.value);
    // The % box refuses against the SAME maximum as the ₹ box, so the two cannot disagree about
    // what is allowed — and it names the person's own limit when that is the tighter one (I5).
    if (Number.isFinite(typed) && typed > 100) refuse("100% is the most — that is the whole taxable value.");
    else if (Number.isFinite(typed) && base > 0 && round2((base * typed) / 100) > maxDisc + 0.004) refuse(capLine());
    else clearRefusal();
    const p = clamp(typed, 0, 100); discAmount = clamp(round2((base * p) / 100), 0, maxDisc); setBlank(false); paint("pct");
  };
  amtInput.oninput = () => {
    const typed = parseFloat(amtInput.value);
    if (Number.isFinite(typed) && typed > maxDisc + 0.004) refuse(capLine()); else clearRefusal();
    discAmount = clamp(typed, 0, maxDisc); setBlank(false); paint("amt");
  };
  payInput.oninput = () => {
    const raw = payInput.value.trim();
    const p = parseFloat(raw);
    if (raw === "" || !(p >= 0)) { setBlank(true); return; }   // leave the discount exactly as it was
    setBlank(false);
    const floor = payFor(maxDisc);   // the least this bill can ever be = its untaxed (MRP) part
    if (p < floor - 0.004) refuse(`The least this bill can be is ${inr(floor)}`
      + (lockedMrp > 0 ? " — MRP items are a final price." : nontax > 0 ? " — the rest carries no GST and can't be discounted." : ".")); else clearRefusal();
    discAmount = clamp(round2(base - (clamp(p, floor, total) - nontax) / (1 + rate)), 0, maxDisc);
    paint("pay");
  };
  // On blur, snap the field the user was typing in to the CLAMPED value — while typing we
  // leave it raw (caret-safe), but once they leave it the box shouldn't keep showing an
  // over-limit / negative figure that disagrees with the applied discount + "They pay". A
  // full paint() (no "typing" arg) refreshes every field from the clamped discAmount.
  pctInput.onblur = () => paint();
  amtInput.onblur = () => paint();
  payInput.onblur = () => { setBlank(false); paint(); };
  // The pay box already holds the full bill, so clicking it must SELECT that figure — otherwise
  // "make it 800" on a ₹817 bill types 817800 and the manager has to clear it first.
  payInput.onfocus = () => payInput.select();
  // A CHIP IS A TYPED FIGURE WITH ONE TAP, SO IT OBEYS THE SAME CEILING (T5 sweep, 2026-08-17).
  // The two boxes clamp to maxDisc and say why; the chips set the raw percentage and said
  // nothing — so with a manager capped at, say, 10%, tapping "25%" showed ₹250 off and a "They
  // pay" figure the server was always going to refuse. Measured with a 10% cap: typing 250 gave
  // "Most you can take off this bill is ₹100 — that is your 10% limit", the 25% chip gave ₹250
  // and no message at all. Refusing at the last tap is the failure this modal's own cap exists
  // to remove, so the chip now goes through the same clamp and the same sentence.
  wrap.querySelectorAll(".disc-pct-pick").forEach((c) => (c.onclick = () => {
    const want = round2((base * Number(c.dataset.pct)) / 100);
    if (want > maxDisc + 0.004) refuse(capLine()); else clearRefusal();
    discAmount = clamp(want, 0, maxDisc); setBlank(false); paint();
  }));
  paint();

  const close = () => wrap.remove();
  wrap.querySelector(".tbl-modal-close").onclick = close;
  wrap.querySelector(".dish-edit-cancel").onclick = close;
  wrap.onclick = (e) => { if (e.target === wrap) close(); };

  const save = async (amount) => {
    const note = wrap.querySelector("#discNoteInput").value.trim();
    close();
    // Pending (⚡ QO/P): there is no order id, so the number goes back to the builder and rides
    // to the server WITH the order. No toast — the footer shows the discount straight away, and
    // "applied" would be a lie until the order is actually placed.
    if (pending) { pending.onApply(Math.max(0, Math.min(amount, maxDisc)), amount > 0 ? note : ""); return; }
    try {
      const _wq = await api("POST", `/orders/${order.id}/discount`, { amount, note: amount > 0 ? note : "" }, { expect: { table: "orders", id: order.id, fields: { discount: Number(order.discount || 0) } } });
      await loadSessions(); if (rerender) rerender();
      okToast(_wq, amount > 0 ? `Discount ${inr(amount)} applied — they pay ${inr(payFor(amount))}` : "Discount removed");
    } catch (e) {
      // SOMEONE ELSE DISCOUNTED THIS BILL FIRST — say so in words (T3 sweep, 2026-08-06). This
      // write sends `expect`, so the server refuses rather than overwriting, and it sends back a
      // ready-made sentence in `clash.plain`. `e.message` is the CODE, so a manager read
      // "Failed: clash_changed_elsewhere" and had no idea their discount hadn't saved. Same shape
      // as editQty a few hundred lines below — the one pattern for a refused value edit.
      const clash = e && e.data && e.data.clash;
      toast(clash ? clash.plain : "Failed: " + errText(e), "err", undefined, clash ? 9000 : undefined);
      if (clash) { await loadSessions(); if (rerender) rerender(); }
    }
  };
  wrap.querySelector(".disc-apply").onclick = () => save(discAmount);
  const removeBtn = wrap.querySelector(".disc-remove"); if (removeBtn) removeBtn.onclick = () => save(0);
  setTimeout(() => pctInput.focus(), 30);
}

// bindTablePanel: wire up every button inside an already-rendered table detail.
// `root` is the container the detail's HTML lives in (the modal OR the side panel).
// `rerender` redraws the SAME view after a local-state change (modal vs side panel
// have different redraw paths), and `close` deselects/closes that view. Sharing
// this keeps the two views' behaviour identical.
function bindTablePanel(root, t, parts, { rerender, close }) {
  const { sess, os } = parts;
  // ✓ Close table — only rendered on a finished table (see endBtn); closeFinishedTable re-reads
  // the slice and re-checks both halves before it asks, so a stale detail can't close a live one.
  const cb = root.querySelector("#sxClose"); if (cb) cb.onclick = () => closeFinishedTable(t);
  // (No #sxOpen wiring — a table is never opened by hand.)
  // Shift the whole party (orders + calls move along) to an EMPTY table.
  const sh = root.querySelector("#sxShift");
  if (sh && sess) sh.onclick = () => openShiftPicker(t, sess);
  // KOT ▾ — the unified Table & KOT operations menu (replaces Shift when the ladder is on).
  const kb = root.querySelector("#sxKot");
  if (kb && sess) kb.onclick = () => openKotMenu(t, sess);
  // Print bill: a clean printable window with KOT numbers, discounts and totals.
  const pr = root.querySelector("#sxPrint");
  // PRINT MEANS "INVOICE IT, THEN PRINT IT" (owner, 2026-08-01). On a bill that has no invoice
  // yet this used to print an un-numbered piece of paper — a bill the books have no record of.
  // Same sequence the bill popup's Print already used: issue → re-read the SESSION (the invoice
  // number lives there, so printing the copy we were built from would print a blank number) →
  // print. If issuing fails or is cancelled, generateInvoice has already said so and nothing
  // prints, rather than paper going out that disagrees with the records.
  if (pr) pr.onclick = async () => {
    // The party's session lives on the table HOLDING the bill (mig 249). Re-reading via the
    // opened table alone meant a merged CHILD's Print issued the invoice, then found no session
    // at its own number and returned in silence — a numbered invoice with no paper and no
    // message (work-checker, 2026-08-03). Resolve the head for both the re-read and the print.
    const head = mergeParentOf(t) || String(t);
    let ss = sess;
    if (ss && (ss.invoice_no == null || ss.invoice_voided)) {
      await generateInvoice(ss.id);
      await ensurePartySlices(t);
      ss = openSessionForTable(head);
      if (!ss || ss.invoice_no == null || ss.invoice_voided) return;
    }
    printBill(head, ss || sess, os, { party: true });
  };
  // The issue-only button is gone (owner, 2026-08-05) — Print issues then prints. Reopen stays.
  const ro = root.querySelector("#sxReopen");
  if (ro && sess) ro.onclick = () => voidInvoice(sess.id);
  const payAll = root.querySelector("#sxPayAll"); if (payAll) payAll.onclick = () => markTablePaid(t);
  const tagB = root.querySelector("#sxTag"); if (tagB) tagB.onclick = () => openTagModal(t);
  // 🍴 Split: with the KOT ladder ON this is the REAL split-settle (several payment
  // legs, mig 176); with it off it stays the old even-share calculator — no regression.
  root.querySelectorAll("[data-split]").forEach((b) => (b.onclick = () => (tableOpsOn() ? markTablePaid(t, { openSplit: true }) : openSplitBill(parseFloat(b.dataset.split) || 0))));
  // MERGED CHILD: jump to the table that holds the bill, or split them apart.
  root.querySelectorAll("[data-goto-parent]").forEach((b) => (b.onclick = () => {
    const parent = b.dataset.gotoParent;
    closeFloatingTable(t);
    openFloatingTable(parent);
  }));
  // TWO PHASES, and the FIRST one says what will actually happen (owner, 2026-08-01: "it should have
  // two phase interface — are you sure you want to unmerge it — and in the are you sure, on the top
  // it will be written what thing will happen, like which KOT will be transferred to seven again, or
  // if anything doesn't transfer also note that"). Everything in this box is read from the real
  // orders, so it can't promise something the server then does differently.
  root.querySelectorAll("[data-unmerge]").forEach((b) => (b.onclick = async () => {
    const child = b.dataset.unmerge;
    const parent = mergeParentOf(child);
    if (!parent) { toast("That table isn't merged any more.", "err"); return; }
    const mine = ordersForTable(child).filter((o) => o.status !== "cancelled" && !o.archived);
    const theirs = ordersForTable(parent).filter((o) => o.status !== "cancelled" && !o.archived);
    const sum = (list) => list.reduce((a, o) => a + (parseFloat(o.total) || 0), 0);
    const sess = openSessionForTable(parent);
    const disc = parseFloat(sess && sess.discount) || 0;
    const lines = [
      mine.length
        ? `<b>Back to T${esc(child)}:</b> ${mine.map((o) => "KOT #" + (o.kot_no ?? "—")).join(", ")} — ${inr(sum(mine))}`
        : `<b>T${esc(child)}</b> gets nothing back — nothing was ordered at it. It simply becomes free.`,
      theirs.length ? `<b>Stays on T${esc(parent)}:</b> ${theirs.map((o) => "KOT #" + (o.kot_no ?? "—")).join(", ")} — ${inr(sum(theirs))}` : "",
      disc > 0 ? `<b>Does NOT move:</b> the ${inr(disc)} bill discount stays on T${esc(parent)} — it was given to the joint bill, so it cannot be split between the two tables.` : "",
      (sess && sess.guests > 0) ? `<b>Does NOT move:</b> the guest count stays with T${esc(parent)} — nobody recorded which guests sat where.` : "",
    ].filter(Boolean);
    const ok = await confirmDialog(
      `<div style="text-align:left"><div style="font-weight:800;margin-bottom:8px">Splitting T${esc(child)} from T${esc(parent)} will do this:</div>`
      + `<ul style="margin:0 0 10px 18px;padding:0;line-height:1.5;font-size:13px">${lines.map((l) => `<li>${l}</li>`).join("")}</ul>`
      + `<div>Are you sure you want to unmerge?</div></div>`,
      "Unmerge", { html: true });
    if (!ok) return;
    try {
      const r = await api("POST", `/tables/${child}/unmerge`, {});
      if (r && r.queued) { toast("Saved — will split when the connection is back", "ok"); return; }
      toast(`${tileFace(child)} split from ${tileFace(parent)}` + (r && r.moved ? ` · ${r.moved} ${r.moved === 1 ? "order" : "orders"} returned` : ""), "ok");
      closeFloatingTable(child);
      await pollTables([String(child), String(parent)]);
    } catch (e) { toast("Couldn't unmerge: " + e.message, "err"); }
  }));

  // Per-dish DELETE: confirm, then call the server, which deletes the order_item
  // AND recomputes the order's total from the survivors (lfh_delete_order_item) so
  // the bill can't keep charging for a removed dish. Reloads the live board after.
  root.querySelectorAll("[data-item-del]").forEach((b) => (b.onclick = async () => {
    const name = b.dataset.itemName || "this dish";
    // A dish coming off a live order takes money off the bill, so it asks WHY — the same six
    // one-tap reasons as a cancelled ticket or a deleted bill (owner, 2026-08-02: "delete a
    // particular item … all that record will be in the audit section"). The reason ask IS the
    // confirmation, so it replaces the old yes/no box rather than adding a second question.
    const reason = await askRemovalReason(`“${name}” — it comes off the order and the bill total updates.`);
    if (!reason) return;
    try {
      const r = await api("POST", `/items/${b.dataset.itemDel}/delete`, { reason_code: reason.code, reason_note: reason.note });
      await loadSessions();
      if (rerender) rerender();
      okToast(r, r && r.order_cancelled ? "Dish removed — order now empty, cancelled" : "Dish removed — bill updated");
    } catch (e) { toast("Failed: " + e.message, "err"); }
  }));
  // ── STAFF EDIT-AFTER-CONFIRM (owner, 2026-06-17) ──────────────────────────
  // Enter edit mode ONLY after confirming with the kitchen the order's editable
  // (it may already be cooking). The 2-step confirm IS the guard.
  root.querySelectorAll("[data-edit-table]").forEach((b) => (b.onclick = async () => {
    if (await confirmDialog("Have you checked with the kitchen that this order is still editable? Only edit if they haven't started making it.", "Yes — it's editable")) {
      editTables.add(String(b.dataset.editTable)); if (rerender) rerender();
    }
  }));
  root.querySelectorAll("[data-done-table]").forEach((b) => (b.onclick = () => { editTables.delete(String(b.dataset.doneTable)); if (rerender) rerender(); }));
  // Quantity −/＋ on one dish: re-prices the bill server-side (clamped 1..99).
  // `was` = the count this screen was showing, so two people stepping the same dish can't
  // overwrite each other (the server refuses the second and says what it is now).
  const editQty = async (id, qty, was) => {
    try { await api("POST", `/items/${id}/qty`, { qty }, { expect: { table: "order_items", id, fields: { qty: was } } }); await loadSessions(); if (rerender) rerender(); }
    catch (e) {
      const clash = e && e.data && e.data.clash;
      toast(clash ? clash.plain : "Failed: " + errText(e), "err", undefined, clash ? 9000 : undefined);
      if (clash) { await loadSessions(); if (rerender) rerender(); }
    }
  };
  root.querySelectorAll("[data-qty-inc]").forEach((b) => (b.onclick = () => editQty(b.dataset.qtyInc, Math.min(99, (parseInt(b.dataset.qty, 10) || 1) + 1), parseInt(b.dataset.qty, 10) || 1)));
  root.querySelectorAll("[data-qty-dec]").forEach((b) => (b.onclick = () => { const q = (parseInt(b.dataset.qty, 10) || 1) - 1; if (q < 1) { toast("Use 🗑 to remove the dish", "err"); return; } editQty(b.dataset.qtyDec, q, parseInt(b.dataset.qty, 10) || 1); }));
  // "✎ Edit" on a dish → the unified editor (allergens incl. custom + kitchen note).
  root.querySelectorAll("[data-edit-dish]").forEach((b) => (b.onclick = () => openDishEditModal(b.dataset.editDish, rerender)));
  // Per-order allergen toggle chips (edit mode): optimistic flip, then persist.
  root.querySelectorAll(".oae-chip[data-alg]").forEach((chip) => (chip.onclick = async () => {
    const id = chip.dataset.alg;
    const o = (state.data.orders || []).find((x) => x.id === id);
    if (!o) return;
    const wasAllergies = [...(o.allergies || [])];   // what the screen was showing
    const cur = new Set((o.allergies || []).map((x) => String(x).toLowerCase()));
    // ＋ Other → ask for the word, then treat it exactly like tapping a standard chip on.
    let slug = chip.dataset.slug;
    if (chip.dataset.algOther) { slug = await allergyPrompt(cur); if (!slug) return; }
    if (cur.has(slug)) cur.delete(slug); else cur.add(slug);
    o.allergies = [...cur]; if (rerender) rerender(); // flip the screen now
    try { await api("POST", `/orders/${id}/allergies`, { allergies: o.allergies }, { expect: { table: "orders", id, fields: { allergies: wasAllergies } } }); await loadSessions(); if (rerender) rerender(); }
    catch (e) {
      // AN ALLERGEN THE SERVER REFUSED MUST NOT STAY ON THE SCREEN (T3 sweep, 2026-08-06).
      // Two faults here, and this is a safety field: the chip was flipped optimistically two lines
      // up and the failure path neither put it back nor refetched, so the screen showed "no peanuts"
      // set while the order did not carry it; and the message was `e.message`, which for a clash is
      // the raw code `clash_changed_elsewhere`. Revert first, then say it in words.
      o.allergies = wasAllergies; if (rerender) rerender();
      const clash = e && e.data && e.data.clash;
      toast(clash ? clash.plain : "Couldn't update allergens: " + errText(e), "err", undefined, clash ? 9000 : undefined);
      if (clash) { await loadSessions(); if (rerender) rerender(); }
    }
  }));
  // Add a dish to THIS order: a compact dish-picker modal → /orders/:id/add-item.
  root.querySelectorAll("[data-add-dish-order]").forEach((b) => (b.onclick = () => openAddDishModal(b.dataset.addDishOrder, rerender)));
  // ＋ Take order: open the full order-builder for a brand-new order on this table.
  root.querySelectorAll("[data-take-order]").forEach((b) => (b.onclick = () => openTakeOrder(b.dataset.takeOrder, rerender)));
  // Per-bill discount: opens the "they pay / percent off" modal (openDiscountModal).
  // The discount is stored on ONE order but billMath applies it to the WHOLE table's
  // bill, so the modal must show + cap on the TABLE total (billMath(os)), not the one
  // target order's total — else a multi-order table showed the first order's bill and
  // capped the discount at it (bug H8, 2026-07-05).
  root.querySelectorAll("[data-disc]").forEach((b) => (b.onclick = () => {
    const order = (os || []).find((o) => o.id === b.dataset.disc) || { id: b.dataset.disc, total: parseFloat(b.dataset.discMax) || 0, discount: parseFloat(b.dataset.discCur) || 0 };
    const bm = (os && os.length) ? billMath(os) : null;
    // The manager discount is a WHOLE-BILL discount: the server stores it on the session and splits
    // it across the orders (so it can't shrink when the bill is marked paid). Show the SESSION's
    // total discount as "current" — NOT this one order's split share, which would mis-show the amount.
    const wholeBill = !!sess;
    const discOrder = wholeBill
      ? { ...order, discount: Number(sess.discount) || 0, discount_note: sess.discount_note || "" }
      : order;
    openDiscountModal(discOrder, rerender, bm ? bm.total : (Number(order.total) || 0), bm, wholeBill);
  }));
  const auto = root.querySelector("#sxAuto"); if (auto && sess) auto.onchange = () => setSessAutoApprove(sess.id, auto.checked);
  root.querySelectorAll("[data-mem-approve]").forEach((b) => (b.onclick = () => memberAction(b.dataset.memApprove, "approve")));
  root.querySelectorAll("[data-mem-deny]").forEach((b) => (b.onclick = () => memberAction(b.dataset.memDeny, "remove")));
  root.querySelectorAll("[data-mem-kick]").forEach((b) => (b.onclick = () => kickMember(b.dataset.memKick)));
  root.querySelectorAll("[data-mem-head]").forEach((b) => (b.onclick = () => makeHead(b.dataset.memHead)));
  root.querySelectorAll("[data-mem-ban]").forEach((b) => (b.onclick = () => banMember(b.dataset.memBan, b.dataset.banPhone)));
  // Pending open/join/access requests now show INSIDE the detail (tp-req-sec) — approve/
  // deny here, same resolveRequest the floor's Requests card uses. Must be wired HERE
  // (not only the delegated #editor handler): the delegated handler deliberately skips
  // clicks inside [data-table-detail], and the legacy modal lives on document.body.
  root.querySelectorAll("[data-req-approve]").forEach((b) => (b.onclick = () => resolveRequest(b.dataset.reqApprove, "approved")));
  root.querySelectorAll("[data-req-deny]").forEach((b) => (b.onclick = () => resolveRequest(b.dataset.reqDeny, "denied")));
  // (No Restart binding — the button is gone; a settled table clears itself.)
  root.querySelectorAll("[data-item-next]").forEach((b) => (b.onclick = () => itemStatus(b.dataset.itemNext, b.dataset.itemStatus)));
  root.querySelectorAll("[data-legacy-order]").forEach((b) => (b.onclick = () => legacyItemStatus(b.dataset.legacyOrder, b.dataset.legacyIdx, b.dataset.legacyStatus)));
  root.querySelectorAll("[data-accept]").forEach((b) => (b.onclick = () => acceptOrder(b.dataset.accept)));
  root.querySelectorAll("[data-accept-all]").forEach((b) => (b.onclick = () => acceptTableOrders(b.dataset.acceptAll)));
  root.querySelectorAll("[data-serveall]").forEach((b) => (b.onclick = () => serveAllOrder(b.dataset.serveall)));
  root.querySelectorAll("[data-serve-all-orders]").forEach((b) => (b.onclick = () => serveAllOrders(b.dataset.serveAllOrders)));
  root.querySelectorAll("[data-pay]").forEach((b) => (b.onclick = () => setOrderPayment(b.dataset.pay, b.dataset.paid !== "1")));
  root.querySelectorAll("[data-call-attend]").forEach((b) => (b.onclick = () => attendCall(b.dataset.callAttend)));
  root.querySelectorAll("[data-attend-all]").forEach((b) => (b.onclick = () => attendTableCalls(b.dataset.attendAll)));
  // ✕ Cancel a whole ticket — the walk-out path. cancelOrder() confirms once, then frees the
  // table by itself if that was its last live order.
  root.querySelectorAll("[data-cancel-order]").forEach((b) => (b.onclick = () => cancelOrder(b.dataset.cancelOrder)));
}

// renderTablePanel: the legacy POP-UP modal version of the table detail. Kept so any
// remaining caller (state.openSess) still works exactly as before; the Tables tab now
// uses the in-panel master-detail instead (see selectTable / floorHtml's side panel).
function renderTablePanel() {
  if (state.openSess == null) return;
  // keep the scroll position so serving an item doesn't fling the panel back to the top
  const prevModal = document.querySelector(".tbl-modal-overlay .tbl-modal");
  const savedScroll = prevModal ? prevModal.scrollTop : 0;
  document.querySelector(".tbl-modal-overlay")?.remove();
  const t = state.openSess;
  const parts = tablePanelParts(t, "modal");
  const { headPill, headMeta, requestsSec, sessionSec, ordersSec, callsSec, billSec, foot } = parts;
  const wrap = el(`<div class="sx-modal-overlay tbl-modal-overlay"><div class="tbl-modal sx-modal"><div class="tbl-modal-head"><div class="tp-detail-top"><h3>${esc(tableLabel(t))}</h3>${headPill}${parts.kotHeadBtn || ""}<button class="tbl-modal-close" aria-label="Close">✕</button></div>${headMeta}</div><div class="tbl-modal-body">${requestsSec}${sessionSec}${ordersSec}${callsSec}${billSec}</div><div class="tbl-modal-foot">${foot}</div></div></div>`);
  document.body.appendChild(wrap);
  const newModal = wrap.querySelector(".tbl-modal"); if (newModal) newModal.scrollTop = savedScroll;
  wrap.querySelector(".tbl-modal-close").onclick = closeTablePanel;
  wrap.onclick = (e) => { if (e.target === wrap) closeTablePanel(); };
  bindTablePanel(wrap, t, parts, { rerender: renderTablePanel, close: closeTablePanel });
}

// Advance ONE dish in a legacy order (items stored in the order's JSON).
async function legacyItemStatus(orderId, index, status) {
  const o0 = (state.data.orders || []).find((x) => x.id === orderId);
  const prev = (o0 && Array.isArray(o0.items) && o0.items[index]) ? (o0.items[index].status || "received") : null;
  const name = (o0 && Array.isArray(o0.items) && o0.items[index] && o0.items[index].title) || "Dish";
  try {
    await api("POST", "/orders/" + orderId + "/item", { index: Number(index), status }); // persist now
    const o = (state.data.orders || []).find((x) => x.id === orderId);                    // optimistic local update
    if (o && Array.isArray(o.items) && o.items[index]) o.items[index].status = status;
    refreshTableDetail();                                                                 // instant redraw from local state (modal OR in-panel detail)
    scheduleServeFlush();                                                                 // one real refresh after you stop clicking
    if (status === "served" && prev && prev !== "served" && window.LFH_UNDO) {
      LFH_UNDO.show({ message: `${name} served`, onUndo: () => editorUndoServe([{ kind: "legacy", orderId, idx: Number(index), prev }]) });
    }
  } catch (e) { toast("Failed: " + e.message, "err"); }
}

// Accept a whole order (received -> preparing). Flips the order AND its dishes,
// optimistically + poll-shielded so it can't flicker back mid-accept.
// Snapshot the still-"received" dishes an accept is about to send to the kitchen, so an
// accidental Accept can be taken back to the new-order queue (owner undo bar, 2026-07-22).
function snapReceived(o) {
  return orderItemRows(o)
    .filter((r) => r.status === "received")
    .map((r) => (r.kind === "session"
      ? { kind: "session", id: r.id, prev: "received" }
      : { kind: "legacy", orderId: r.orderId, idx: r.idx, prev: "received" }));
}
async function acceptOrder(orderId) {
  const o = (state.data.orders || []).find((x) => x.id === orderId);
  const snap = o ? snapReceived(o) : [];
  if (o) { o.status = "preparing"; flipOrderItems(o, "received", "preparing"); opBegin(o.id); }
  floorOpsInFlight++;
  loadSessions(true); renderTablePanel();
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; if (o) opEnd(o.id); } };
  try {
    const qA = wasQueued(await api("POST", "/orders/" + orderId + "/accept", null, { table: o && o.table_number })); release();
    if (!qA) await loadSessions();   // saved-not-sent → keep what the tap just showed
    // NO UNDO BAR ON ACCEPT (owner, 2026-08-26: "remove for accept keep for serve"). Accepting is
    // the most repeated tap of a service and the least consequential — it only tells the kitchen to
    // start, and a wrongly-accepted ticket is still cancellable from the table until it is served.
    // A card sliding up on every single accept was the noise; SERVE keeps its undo because a
    // wrongly-served dish has no other way back on this panel. Do not re-add one here.
    toast("Order accepted → preparing", "ok");
  }
  catch (e) { release(); toast("Failed: " + e.message, "err"); await loadSessions(); }
}
// Serve every dish on an order at once → order complete. Optimistic + shielded.
// Snapshot the dishes an order is about to serve (their prior status), so a mis-tapped
// serve can be sent back exactly where each dish was (owner undo bar, 2026-07-22).
// Works for both session order_items (id) and legacy JSON items (orderId + idx).
function snapServable(o) {
  return orderItemRows(o)
    .filter((r) => r.status !== "served")
    .map((r) => (r.kind === "session"
      ? { kind: "session", id: r.id, prev: r.status }
      : { kind: "legacy", orderId: r.orderId, idx: r.idx, prev: r.status }));
}
// Take back a serve: restore each dish's prior status locally + on the server, then
// reconcile. The item-status endpoint only accepts received/preparing/served, so a dish
// that was "ready" (cooked, not yet served) comes back as "preparing".
async function editorUndoServe(snap) {
  if (!snap || !snap.length) return;
  const clamp = (s) => (s === "ready" ? "preparing" : (["received", "preparing", "served"].includes(s) ? s : "preparing"));
  snap.forEach((s) => {
    const to = clamp(s.prev);
    if (s.kind === "session") { const it = (state.board.items || []).find((x) => x.id === s.id); if (it) it.status = to; }
    else { const o = (state.data.orders || []).find((x) => x.id === s.orderId); if (o && Array.isArray(o.items) && o.items[s.idx]) o.items[s.idx].status = to; }
  });
  refreshTableDetail();
  scheduleServeFlush();
  try {
    for (const s of snap) {
      if (s.kind === "session") await api("POST", "/items/" + s.id + "/status", { status: clamp(s.prev) });
      else await api("POST", "/orders/" + s.orderId + "/item", { index: s.idx, status: clamp(s.prev) });
    }
    await loadSessions();
  } catch (e) { toast("Undo failed: " + e.message, "err"); await loadSessions(); }
}

async function serveAllOrder(orderId) {
  const o = (state.data.orders || []).find((x) => x.id === orderId);
  const snap = o ? snapServable(o) : [];
  if (o) { o.status = "served"; flipOrderItems(o, null, "served"); opBegin(o.id); }
  floorOpsInFlight++;
  loadSessions(true); renderTablePanel();
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; if (o) opEnd(o.id); } };
  try {
    const qS = wasQueued(await api("POST", "/orders/" + orderId + "/serve-all", null, { table: o && o.table_number })); release();
    if (!qS) await loadSessions();   // saved-not-sent → keep what the tap just showed
    // The undo bar IS the confirmation now (message + a few-second takeback line),
    // so it replaces the old plain "served" toast.
    if (snap.length && window.LFH_UNDO) LFH_UNDO.show({
      message: "All dishes served",
      sub: o ? `T${o.table_number} · ${snap.length} dish${snap.length > 1 ? "es" : ""}` : `${snap.length} dishes`,
      onUndo: () => editorUndoServe(snap),
    });
    else toast("All items served", "ok");
  }
  catch (e) { release(); toast("Failed: " + e.message, "err"); await loadSessions(); }
}
// Quick action: accept ALL new orders on a table in one tap. Used by BOTH the
// floor tile's Accept AND the detail's "Accept all & prepare" button — one tap
// accepts the whole table (owner: never open the detail just to accept each).
// Optimistic tile feedback for a NON-selected table: the grid + "To accept" card render
// from state.summary (NOT the board), so an accept/attend that only patched state.data.*
// left the tile looking dead until the server round-trip (fixed 2026-07-06). These patch
// the slim summary tile immediately; pollTables() reconciles exact counts right after.
// WAS THAT WRITE ACTUALLY DELIVERED, OR ONLY SAVED ON THIS DEVICE?
//
// `api()` answers { ok:true, queued:true } when the change went into this device's queue instead
// of to the server (no signal, or the server could not take it). Every optimistic path below
// finishes by REFRESHING from the server — and with no signal that refresh is answered from the
// device's saved copy, which is by definition older than the tap that just happened. So the
// screen flipped correctly and was then put straight back.
//
// Measured on the real manager floor (2026-08-13): a waiter tapped ✓ Accept on table 19 with no
// signal, the change WAS saved (the queue held it, the bar said so, the undo bar appeared) — and
// the tile went on reading "New order" as though nothing had been touched. So they tap again.
//
// Nothing here invents a state: patchSummaryTileAccept() already flips the tile and is already
// trusted on the online path. This only stops a stale read undoing it. The truth still lands the
// moment the queue drains — the panel refreshes on `lfh:outbox-flushed` (see the listener at the
// bottom of this file) — and until then the table carries the ⏳ mark that says so.
const wasQueued = (r) => !!(r && r.queued === true);

// ── ONE SENTENCE FOR EVERY WRITE THAT HAS NOT LEFT THIS DEVICE (owner, 2026-08-26) ────────────
//
// "on bad wifi every message tells the truth, so a manager can trust what he reads."
//
// api() hands every non-GET to the offline outbox, and the outbox resolves { ok:true, queued:true }
// instead of throwing — so a handler with only a try/catch sees a SUCCESS and says so. Eight sites
// that announce money or mint a numbered document were fixed one at a time (items 2-5); this is the
// rest of the panel, and it is deliberately ONE helper rather than fifty rewordings:
//
//   · a manager learns the sentence ONCE and then recognises it anywhere;
//   · fifty hand-written variations is how two screens end up disagreeing about the same state;
//   · and a new write site gets the behaviour by using okToast() instead of remembering a rule.
//
// It is not a warning and not an error: the work IS saved, it IS going, and the queue drawer and
// the offline bar already say how much is waiting. It only stops the panel claiming a thing has
// happened when it has not.
const QUEUED_LINE = "Saved on this device ✓ — it'll send by itself the moment you're back online.";
const okToast = (r, msg, ms) => toast(wasQueued(r) ? QUEUED_LINE : msg, "ok", undefined, ms);

// ── WHERE SERVER TRUTH MEETS THIS DEVICE'S OWN WORK ──────────────────────────────────────────
//
// A tile the person has just changed must not be put back by a read that predates the change.
// The two `!floorOpsInFlight` guards below already say exactly this — "don't clobber an optimistic
// tile mid-action" — but they only hold while the save is IN FLIGHT. With no signal the save is
// not in flight; it is sitting in this device's queue, sometimes for minutes, and every routine
// poll in between was handing the tile back its old state.
//
// Measured on the real manager floor: a waiter tapped ✓ Accept with no signal, the tile flipped to
// "Preparing" exactly as it does online — and four seconds later a background poll turned it back
// to "New order", with the change still saved and still waiting. So they tap again.
//
// Nothing is invented here. The tile was already flipped by patchSummaryTileAccept(), which is
// shipped and trusted on the online path; this only stops a read that is older than the tap from
// undoing it. It ends by itself: the moment the change reaches the server the table has nothing
// unsent, the incoming tile wins again, and what is on screen is the server's own answer.
// STILL ON ITS WAY — not "has ever been stuck here".
//
// pendingByTable() deliberately counts the failed list too (it drives the ⏳/⚠ marks), and using it
// here would be the one way this whole idea could tell a lie: a change the server has REFUSED — the
// table was closed by someone else while the phone was down — never leaves that list until a person
// taps "Not needed anymore", so the tile would sit on "Preparing" for the rest of the shift for food
// the kitchen never heard about. That is exactly the fault this change exists to avoid, pointed the
// other way. So only work that is genuinely still queued holds a tile; the moment it lands in
// "These changes need you" the person has been told, and the tile goes back to the server's truth.
function tablesWithUnsentWork() {
  try {
    const ob = window.LFH_OUTBOX;
    if (!ob || !ob.getSnapshot || !ob.tablesOf) return null;
    const out = new Set();
    for (const it of (ob.getSnapshot().queued || [])) for (const t of ob.tablesOf(it)) out.add(String(t));
    return out.size ? out : null;
  } catch (e) { return null; }
}
// Merge a freshly-read summary over the one on screen, keeping OUR tile for any table that is
// still carrying work this device has not managed to send.
function mergeServerSummary(incoming) {
  const held = tablesWithUnsentWork();
  if (!held) return incoming;                       // nothing waiting → the server is the truth
  const mine = (state.summary || {}).tiles || {};
  const tiles = Object.assign({}, (incoming || {}).tiles || {});
  let kept = 0;
  for (const t of held) if (mine[t]) { tiles[t] = mine[t]; kept++; }
  return kept ? Object.assign({}, incoming, { tiles }) : incoming;
}

function patchSummaryTileAccept(t) {
  const s = state.summary || {};
  const tile = (s.tiles || {})[String(t)];
  if (!tile) return;
  const nt = Object.assign({}, tile, { hasNew: false });
  const c = Object.assign({ nw: 0, ck: 0, rd: 0, sv: 0 }, nt.counts || {});
  c.ck += c.nw; c.nw = 0; nt.counts = c;                 // the just-accepted dishes are now cooking
  if (nt.state === "new") { nt.state = "prep"; nt.label = "Preparing"; }
  state.summary = Object.assign({}, s, { tiles: Object.assign({}, s.tiles, { [String(t)]: nt }) });
}
function patchSummaryTileAttend(t) {
  const s = state.summary || {};
  // The whole PARTY's tables — "Attend all" now clears the party's calls (T3 sweep, 2026-08-10),
  // so the optimistic patch has to clear the same set or one partner's tile keeps a 🔔 for a call
  // that has just been answered, until the next poll.
  const party = new Set(partyTablesOf(t).map(String));
  const calls = (s.calls || []).filter((c) => !party.has((c.table_number || "").trim()));
  const patch = { calls };
  const tiles = Object.assign({}, s.tiles);
  let touched = false;
  for (const x of party) if (tiles[x]) { tiles[x] = Object.assign({}, tiles[x], { hasCall: false }); touched = true; }
  if (touched) patch.tiles = tiles;
  state.summary = Object.assign({}, s, patch);
}
async function acceptTableOrders(t) {
  // TWO-TIER: a tile quick-action can fire on a NON-selected table, whose full order rows
  // aren't in the cache (the grid renders from the slim summary). Ensure this table's slice
  // is loaded so ordersForTable(t) returns its real orders to act on. (No-op cost when it's
  // the selected table — already loaded — but cheap and correct to always refresh first.)
  await ensurePartySlices(t); // a merged party accepts as ONE bill (owner, 2026-08-01)
  // Accept every order that still has un-accepted (received) DISHES — this matches
  // the tile's "New order" cue, which is ITEM-level (anyReceived). An order can be
  // order-level "preparing" yet still carry a freshly-added dish at "received" (e.g.
  // a dish added after accepting); the old order-LEVEL filter (o.status==="received")
  // silently did NOTHING for those, so the tile showed "Accept" but clicking it fired
  // no request — the "Accept doesn't work" bug. The /accept endpoint flips received
  // item rows → preparing regardless of order status, so this is safe. (2026-06-26)
  const recv = partyOrders(t).filter((o) => o.status !== "cancelled" && orderItemRows(o).some((r) => r.status === "received"));
  // NEVER RETURN ON A TAP WITHOUT A TRACE (owner rule; sweep 2026-08-04). The ✓ quick-accept only
  // exists while the SUMMARY tile says hasNew, but the line above reads the slice we just forced
  // fresh — so if a waiter accepted this order on the tablet a second earlier, `recv` is empty and
  // this used to return with nothing on screen at all. He taps again. Still nothing. The button
  // reads as dead and there is no trace anywhere that he tried. Say it, and put the stale tile
  // back in step with the truth it just showed.
  if (!recv.length) {
    toast(`Nothing new to accept on ${tableLabel(t)} — the tile was out of date`, "err");
    await pollTables([String(t)]);
    return;
  }
  const snap = recv.flatMap((o) => snapReceived(o)); // for the takeback
  // OPTIMISTIC: tile flips to "Preparing" instantly, server told in background.
  recv.forEach((o) => { o.status = "preparing"; flipOrderItems(o, "received", "preparing"); opBegin(o.id); });
  floorOpsInFlight++;
  patchSummaryTileAccept(t); // instant tile feedback even on a non-selected table
  loadSessions(true); renderTablePanel();
  // release first, then refresh — see restartTable for why this order matters.
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; recv.forEach((o) => opEnd(o.id)); } };
  try {
    let qAll = false;
    for (const o of recv) { if (wasQueued(await api("POST", "/orders/" + o.id + "/accept", null, { table: t }))) qAll = true; }
    release();
    // refresh THIS tile's summary so the grid reflects truth — unless the change is still on
    // this device, in which case the saved copy would revert the tile we just flipped.
    if (!qAll) await pollTables([String(t)]);
    // No undo bar on accept — same rule as the single accept above (owner, 2026-08-26).
    toast(recv.length > 1 ? recv.length + " orders accepted → preparing" : "Order accepted → preparing", "ok");
  }
  catch (e) { release(); toast("Failed: " + e.message, "err"); await pollTables([String(t)]); } // reload truth on failure
  finally { release(); }
}
// Serve EVERY order on a table at once (the table-wide "mark all served").
// OPTIMISTIC like accept: every dish row flips to served on screen first.
//
// ⚠️ A CANCELLED TICKET IS NOT SERVEABLE (sweep 2026-08-04). This used to hand EVERY row of
// partyOrders(t) to /serve-all with no status filter — and a cancelled order is still in that
// list, because cancelling sets status='cancelled' and deliberately leaves `archived` false
// (which is exactly why every DISPLAY path here filters cancelled separately: liveOs,
// newOrdersN, anyUnservedAccepted, liveOsEnd). The endpoint had no guard either, so one tap
// of 🍽️ Serve all wrote status='served' onto a VOIDED ticket: it stopped being a void, isUnpaidBill
// matched it again, and its money went straight back onto the guest's bill — with no audit row and
// no 30-minute window, unlike the one sanctioned un-cancel (PATCH /orders/:id → 'received').
// The waiter panel already filtered this correctly; the manager panel was the outlier.
// Filter the same three things the tablet does, and the server now refuses a cancelled order too.
async function serveAllOrders(t) {
  await ensurePartySlices(t); // a merged party's other tables are separate slices
  const all = partyOrders(t);
  const orders = all.filter((o) => o.status !== "cancelled" && o.status !== "received"
    && orderItemRows(o).some((r) => r.status !== "served"));
  // A tap is never dropped in silence (owner rule): the button is drawn from the tile's summary,
  // which can be a beat behind, so "nothing left to serve" must SAY so and put the tile back in
  // step with the truth — not return with an untouched screen and no explanation.
  if (!orders.length) {
    toast(all.length ? `Nothing left to serve on ${tableLabel(t)}` : `${tableLabel(t)} has nothing to serve`, "err");
    await pollTables([String(t)]);
    return;
  }
  const snap = orders.flatMap((o) => snapServable(o));
  orders.forEach((o) => { o.status = "served"; flipOrderItems(o, null, "served"); opBegin(o.id); });
  floorOpsInFlight++;
  loadSessions(true);
  renderTablePanel();
  // release first, then refresh — see restartTable for why this order matters.
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; orders.forEach((o) => opEnd(o.id)); } };
  try {
    let qSt = false;
    for (const o of orders) { if (wasQueued(await api("POST", "/orders/" + o.id + "/serve-all", null, { table: t }))) qSt = true; }
    release();
    if (!qSt) await pollTables([String(t)]);   // saved-not-sent → keep what the tap just showed
    if (snap.length && window.LFH_UNDO) LFH_UNDO.show({
      message: "All dishes served",
      sub: `T${t} · ${snap.length} dish${snap.length > 1 ? "es" : ""}`,
      onUndo: () => editorUndoServe(snap),
    });
    else toast("All orders served", "ok");
  }
  catch (e) { release(); toast("Failed: " + e.message, "err"); await pollTables([String(t)]); }
  finally { release(); }
}
// Quick action: mark every open call on a table attended (clears the tile's emoji).
async function attendTableCalls(t) {
  // The PARTY's slices — "✓ Attend all" on a joined table must clear the party's calls, not one
  // table's, for the same reason "Accept all" does (T3 sweep, 2026-08-10).
  await ensurePartySlices(t);
  const cs = partyCalls(t);
  // A tap always leaves a trace (owner rule; sweep 2026-08-04) — the 🔔 comes from the summary
  // tile, so another device answering the call first left this returning in total silence.
  if (!cs.length) {
    toast(`No open calls on ${tableLabel(t)} any more`, "err");
    await pollTables([String(t)]);
    return;
  }
  // OPTIMISTIC: the call emojis leave the tile instantly (detail panel reads state.data.calls).
  const before = state.data.calls || [];
  const beforeSummary = state.summary;
  const ids = new Set(cs.map((c) => c.id));
  state.data.calls = before.filter((c) => !ids.has(c.id));
  patchSummaryTileAttend(t); // instant tile feedback (grid reads state.summary, not the board)
  floorOpsInFlight++;
  loadSessions(true);
  // ONE IDEMPOTENT RELEASE, like every sibling quick-action (sweep 2026-08-04). This function used
  // to decrement floorOpsInFlight inline in the try AND again in the catch, so anything throwing
  // after the first decrement (pollTables → reconcileBoard → renderEditor all run synchronously in
  // that awaited chain) took the counter to -1. It is only ever tested for truthiness, and !(-1) is
  // false — so from then on EVERY poll fetched the floor and threw the result away: the tiles quietly
  // stop being live, with no error, until some other balanced action brings the counter back to 0.
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; } };
  try {
    let anyQueued = false;
    for (const c of cs) anyQueued = wasQueued(await api("PATCH", "/calls/" + c.id, { resolved: true })) || anyQueued;
    release(); await pollTables([String(t)]); // clears the tile's call emoji from the summary
    const callIds = [...ids];
    if (window.LFH_UNDO) LFH_UNDO.show({
      message: `${callIds.length} call${callIds.length > 1 ? "s" : ""} attended`,
      sub: `T${t} · tap undo to put them back`,
      icon: "🔔",
      onUndo: async () => { try { await Promise.all(callIds.map((cid) => api("PATCH", "/calls/" + cid, { resolved: false }))); await loadSessions(); } catch (e) { toast("Undo failed: " + e.message, "err"); await loadSessions(); } },
    });
    else okToast(anyQueued ? { queued: true } : null, "Attended");
  }
  catch (e) { release(); state.data.calls = before; state.summary = beforeSummary; await pollTables([String(t)]); toast("Failed: " + errText(e), "err"); }
  finally { release(); }
}
// RST: clear a finished table's orders off the floor but KEEP the table open for a new round.
// restartTable: clear the round, keep the table. NO LONGER REACHED FROM THE MANAGER UI — its
// ↻ Restart button was removed with the open/close family (owner, 2026-08-01). Kept because the
// SERVER's auto-restart mode mirrors this exact sequence and two comments above point at it for
// why release-then-refresh matters; the waiter tablet still has its own restart.
async function restartTable(t) {
  await ensureTableSlice(t); // a non-selected table's orders aren't cached otherwise
  const ids = ordersForTable(t).map((o) => o.id);
  if (!ids.length) { toast(`${tableLabel(t)} has nothing to clear`, "err"); return; } // never silent
  if (!(await confirmDialog(`Restart T${t}? Its orders clear off the floor and the table stays OPEN for a fresh round.`, "Restart"))) return;
  // OPTIMISTIC after the confirm: the tile resets instantly, server follows.
  // Orders become SERVED + archived (the round is done; they stay as real,
  // completed orders in records/revenue — NOT cancelled, which would void them).
  (state.data.orders || []).forEach((o) => { if (ids.includes(o.id)) { o.archived = true; o.status = "served"; opBegin(o.id); } });
  floorOpsInFlight++;
  loadSessions(true);
  // release: drop our "mid-save" markers BEFORE the reconciling refresh below —
  // loadSessions only trusts the server's board once nothing is in flight, so
  // holding the markers through the refresh would delay our own reconcile.
  let released = false;
  const release = () => { if (!released) { released = true; floorOpsInFlight--; ids.forEach((id) => opEnd(id)); } };
  try {
    // ONE atomic server call: archive the round + release members + CLEAR the table's live signals
    // (so no ghost waiter-call bell lingers on the emptied table) + reopen if sessions are on.
    // (B12 — was a client PATCH loop that never cleared the signals.)
    const _wq = await api("POST", "/tables/" + t + "/restart", {});
    release();
    await pollTables([String(t)]); // refresh this tile's summary (cheap, single-table)
    okToast(_wq, `${tableLabel(t)} restarted — still open`);
  } catch (e) { release(); toast("Couldn't restart: " + e.message, "err"); await pollTables([String(t)]); }
  finally { release(); }
}
// CLS: free the table (archive orders + close any open session).
// ===================== USERS / LOG =====================
// Every guest who joined a table (auto ID = their member id) + the blocklist. From here
// the owner can EXIT (kick) a guest or BLOCK them (they then see a blocked screen).
// loadUsers: fetch the Log tab's data (guests, customers, blocklist, plus their
// order/call activity) and redraw if the Log tab is showing.
async function loadUsers() {
  try { state.users = await api("GET", "/users"); if (state.tab === "log") renderEditor(); }
  catch (e) { toast("Couldn't load log: " + errText(e), "err"); }
}

// logHtml: build the Log tab — a table listing every guest (name, table, role,
// what they did, status, when) with Exit/Block actions, plus the blocklist below.
function logHtml() {
  // Two logs share this tab: the customer/guest log (default) and the staff
  // Operation log (who-did-what across the panels).
  const view = state.logView || "customers";
  // The Customer/Operation switch now lives in the LEFT SIDEBAR (see renderList),
  // so there's no top toggle here.
  if (view === "operations") return oplogHtml();
  const u = state.users || {};
  const members = u.members || [];
  const blocks = u.blocklist || [];
  const blockedPhones = new Set(blocks.filter((b) => b.phone).map((b) => b.phone)); // quick "is this phone blocked?" lookup
  // What each guest DID — aggregate orders + waiter calls by their member id.
  const orderCount = {}, callCount = {};
  (u.orders || []).forEach((o) => { if (o.member_id) orderCount[o.member_id] = (orderCount[o.member_id] || 0) + 1; });
  (u.calls || []).forEach((c) => { if (c.member_id) callCount[c.member_id] = (callCount[c.member_id] || 0) + 1; });

  const head = `<div class="ed-head"><h2>Customer log <span class="sub">· guests & visits</span></h2><div class="ed-head-actions">${retentionControl("custlog_retention_days")}<button class="btn" id="refreshLog">↻ Refresh</button></div></div>
    <div class="ord-note">Every guest gets an automatic ID. <b>Role</b> shows who ran the table (👑 Head) vs a joiner (🤝 Partner); <b>Did</b> shows whether they ordered or just called a waiter. Use <b>Exit</b> to remove someone, or <b>Block</b> to stop a misbehaving guest (e.g. someone who calls a waiter but isn't here). <b>Click a row</b> for full details. <span class="lg-muted">This timer clears old guest-activity records only — your bills are kept.</span></div>`;
  const rows = members.length ? members.map((m) => {
    const table = m.session ? m.session.table_number : "—"; // which table they're at
    const open = m.session && m.session.status === "open"; // is that table's session still open?
    const blocked = m.phone && blockedPhones.has(m.phone);
    // Work out a single word for their current status, in priority order.
    const status = m.removed ? "left" : blocked ? "blocked" : open ? (m.approved ? "in session" : "waiting") : "ended";
    const isHead = m.role === "owner"; // the person who started the table
    const role = isHead ? `<span class="logrole head">👑 Head</span>` : `<span class="logrole partner">🤝 Partner</span>`;
    const nOrders = orderCount[m.id] || 0, nCalls = callCount[m.id] || 0;
    let did = "";
    if (nOrders) did += `<span class="logdid order">🛒 ${nOrders} order${nOrders > 1 ? "s" : ""}</span>`;
    if (nCalls) did += `<span class="logdid call">🔔 ${nCalls} call${nCalls > 1 ? "s" : ""}</span>`;
    if (!did) did = (open && !m.approved) ? `<span class="lg-muted">asked to join</span>` : `<span class="lg-muted">joined only</span>`;
    let acts = "";
    if (open && !m.removed) acts += `<button class="btn small" data-exit="${esc(m.id)}">Exit</button>`;
    if (!blocked) acts += `<button class="btn small danger" data-block-phone="${esc(m.phone || "")}" data-block-table="${esc(table)}">Block</button>`;
    return `<div class="logrow logrow-click" data-cust-detail="${esc(m.id)}">
        <div class="logcell"><b>${esc(m.name || (isHead ? "Head" : "Guest"))}</b><small>${esc(String(m.id).slice(0, 8))}</small></div>
        <div class="logcell">T${esc(table)}</div>
        <div class="logcell">${role}</div>
        <div class="logcell logdidcell">${did}</div>
        <div class="logcell"><span class="logstat logstat-${status.replace(/ /g, "-")}">${status}</span></div>
        <div class="logcell"><small>${esc(whenLabel(m.joined_at))}</small></div>
        <div class="logcell logacts">${acts}</div>
      </div>`;
  }).join("") : `<div class="sx-empty">No guests have joined a table yet.</div>`;
  const table = `<div class="logtable"><div class="logrow loghead"><div>Guest</div><div>Table</div><div>Role</div><div>Did</div><div>Status</div><div>When</div><div></div></div>${rows}</div>`;
  // A blocked guest can ask to be let back in: the "you've been blocked" wall takes a mobile
  // number and stamps it on their block record (mig 077). Until now NOTHING here read it, so the
  // wall's promise — "leave your number and ask a member of staff" — reached no staff screen and
  // the guest waited on a request nobody could see. Show it, and put the people who ASKED first,
  // because that list is a queue: it's the only reason to open this panel between bans.
  // NOTE: .sx-blk / .sx-blk-top / .sx-blk.has-req / .sx-blk-unban were all styled for exactly
  // this row (style.css:984-987) and never wired to any markup — the look was designed, the
  // wiring was missed. This uses that structure rather than inventing a second one.
  const asked = blocks.filter((b) => b.unban_requested_at).length;
  const blkSorted = blocks.slice().sort((a, b) => (b.unban_requested_at ? 1 : 0) - (a.unban_requested_at ? 1 : 0));
  const blkRows = blkSorted.length ? blkSorted.map((b) => {
    // A ban can target a phone, a table, or just the DEVICE (mig 077 — the common case, since an
    // anonymous menu browser has no phone). The device case used to fall through to the table
    // branch and render "🚫 table " with nothing after it; say what was actually blocked.
    const who = b.phone ? "📵 " + esc(b.phone)
      : b.table_number ? "🚫 table " + esc(b.table_number)
      : b.device_id ? "📱 this guest's device"
      : "🚫 blocked";
    const why = b.reason ? ` — <small>${esc(b.reason)}</small>` : "";
    // The appeal line: the number they left (often the FIRST number we have for them) + when.
    const appeal = b.unban_requested_at
      ? `<div class="sx-blk-unban">🙋 Asked to be unblocked${b.unban_phone ? ` · ${esc(b.unban_phone)}` : ""} · ${esc(whenLabel(b.unban_requested_at))}</div>`
      : "";
    return `<div class="sx-blk${b.unban_requested_at ? " has-req" : ""}">`
      + `<div class="sx-blk-top"><span>${who}${why}</span><button class="btn small" data-unblock="${esc(b.id)}">Unblock</button></div>`
      + appeal
      + `</div>`;
  }).join("") : `<div class="sx-empty">Nobody is blocked.</div>`;
  const blkPanel = `<div class="sx-panel" style="margin-top:18px;max-width:560px"><h3>🚫 Blocked <span class="sub">· ${blocks.length}${asked ? ` · ${asked} asked to be unblocked` : ""}</span></h3>${blkRows}</div>`;
  return head + table + blkPanel;
}

// A gold "manager PIN" pill for a TABLET action that a manager's PIN unlocked. The
// tablet has no per-person login, so a non-empty `actor` on a tablet row is always the
// manager whose PIN authorised the action (recorded server-side, mig-free — the actor
// column). A name containing " / " means the SAME PIN belongs to more than one manager,
// so it's genuinely ambiguous who tapped it — we name them all and tint the pill.
// A person's OWN identity actions (login/logout/profile/password/PIN) also stamp `actor`
// with that person's name, but that's NOT a manager-PIN authorisation — exclude them so a
// tablet login row doesn't wrongly show a gold PIN pill / "Manager PIN" block.
const SELF_ACTOR_ACTIONS = new Set(["login", "logout", "profile_setup", "profile_update", "password_change", "pin_set"]);
function isManagerPinRow(r) {
  return !!r && r.panel === "tablet" && !!r.actor && !SELF_ACTOR_ACTIONS.has(r.action);
}
function pinPill(r) {
  if (!isManagerPinRow(r)) return "";
  const shared = String(r.actor).includes(" / ");
  const title = shared
    ? "This PIN is shared by these managers — any of them could have entered it"
    : "Unlocked by this manager's PIN";
  return ` <span class="op-pinpill${shared ? " op-pinpill-shared" : ""}" title="${esc(title)}">🔑 ${esc(r.actor)}</span>`;
}

// The "Where" column reads as a sentence, never as stored JSON (2026-08-03). The black-box tap
// logger (public/panels/errlog.js) stores a batch as `[{"t":12,"l":"Add dish"}]`, and this column
// printed that verbatim — a wall of JSON on the manager's own Activity log. Same rule and same
// output as the admin screens (components/admin/shared.tsx → formatActionDetail); the two are
// checked against each other by npm run verify:audit.
function opDetailText(action, detail, plain) {
  // AN ERROR ROW ARRIVES WITH ITS PLAIN SENTENCE ALREADY WRITTEN (owner, 2026-09-02: "make sure
  // every possible log and stuff in human language"). /oplog attaches `plain` to level:'error'
  // rows (lib/plainError.ts, called in app/api/editor/[...path]/route.ts) rather than this file
  // carrying a JS copy of the translator — a second copy is what drifted last time, when this
  // panel's own label map covered 19 of ~130 action codes. A stale cached app.js talking to a
  // newer server simply doesn't get `plain` and falls through to the old behaviour, and a NEW
  // app.js talking to an older server does the same, so neither half can lose the line.
  if (plain) return String(plain);
  if (!detail) return "";
  if (action !== "ui_taps") return String(detail).replace(/_/g, " ");
  let arr; try { arr = JSON.parse(detail); } catch { return detail; }
  if (!Array.isArray(arr)) return detail;
  const order = [], counts = new Map();
  for (const it of arr) {
    if (!it || typeof it !== "object") continue;
    const l = String(it.l == null ? "" : it.l).trim();
    if (!l || /^connection\b/i.test(l)) continue;
    if (!counts.has(l)) order.push(l);
    counts.set(l, (counts.get(l) || 0) + 1);
  }
  if (!order.length) return "checked the screen";
  return order.map((l) => (counts.get(l) > 1 ? l + " \u00d7" + counts.get(l) : l)).join(", ");
}
// oplogHtml: the Operation log — every staff action across the panels (which
// panel did what, where, and when). Fed by /oplog (the staff_actions table).
function oplogHtml() {
  const all = state.oplog || [];
  // ── THE SAME CHIPS AND SORT THE AUDIT HAS (owner, 2026-08-14) ─────────────────────────────────
  // "you can able to sort in activity log such as from printer and all that." Grouping, counting
  // and ordering all come from /panels/auditsort.js — the module this panel already loads for the
  // Audit tab, and which the owner console and the admin console read too, so "Printer" means the
  // same rows on all three. Guarded exactly like the Audit's use: a stale cached app.js talking to
  // a page without the script falls back to the flat list rather than losing the screen.
  const AS2 = typeof LFH_AUDITSORT !== "undefined" && LFH_AUDITSORT.activityView ? LFH_AUDITSORT : null;
  const opChips = AS2 ? AS2.activityCounts(all) : [];
  // A group whose rows have aged off the feed falls back to All, so a stale chip can never leave an
  // empty list with no way back.
  const opGroup = state.oplogGroup && opChips.some((c) => c.group === state.oplogGroup) ? state.oplogGroup : "";
  const opSort = state.oplogSort || (AS2 ? AS2.ACTIVITY_DEFAULT_SORT : "new");
  const opQ = (state.oplogQ || "").trim();
  const rows = AS2 ? AS2.activityView(all, { group: opGroup, sort: opSort, q: opQ }) : all;
  const head = `<div class="ed-head"><h2>Activity log <span class="sub">· staff actions</span></h2><div class="ed-head-actions">${retentionControl("oplog_retention_days")}<button class="btn" id="staffWatch">🔍 Staff watch</button><button class="btn" id="refreshOplog">↻ Refresh</button></div></div>
    <div class="ord-note">Every staff action across the panels — which panel <b>and which device</b> did it, where, and when. Each device gets an automatic ID (shown as <b>#id</b>) until real staff login lands. <b>Click any row</b> for its full date, time and details.</div>`
    + (opChips.length > 1 ? `<div class="au-chips">
      <button class="au-chip${opGroup === "" ? " on" : ""}" data-op-group="">All <i>${all.length}</i></button>
      ${opChips.map((c) => `<button class="au-chip${opGroup === c.group ? " on" : ""}" data-op-group="${esc(c.group)}" title="Show only: ${esc(c.label)}">${c.icon} ${esc(c.label)} <i>${c.count}</i></button>`).join("")}
    </div>` : "")
    + (AS2 ? `<div class="au-controls">
      <input id="opQ" class="au-q" type="search" placeholder="Search an action, a person, a table or a panel…" value="${esc(state.oplogQ || "")}">
      <label class="au-sort">Sort <select id="opSort">${AS2.ACTIVITY_SORTS.map((o) => `<option value="${esc(o.id)}"${o.id === opSort ? " selected" : ""}>${esc(o.label)}</option>`).join("")}</select></label>
    </div>` : "");
  if (!all.length) return head + `<div class="sx-empty">No staff actions logged yet — accept/serve an order, open/close a table, etc.</div>`;
  // Narrowed to nothing is a different sentence from "nothing has happened" — and it must offer the
  // way back, or a chip becomes a trap (the same rule the Audit's empty state follows).
  if (!rows.length) return head + `<div class="sx-empty">${opQ ? "Nothing matches that." : "Nothing of that type on this list — tap All to see everything."}</div>`;
  // Which staff devices are currently blocked → map device_id to its blocklist
  // row id (so we can offer Unblock). Loaded alongside the customer-log data.
  const blockedDev = {};
  ((state.users && state.users.blocklist) || []).forEach((b) => { if (b.device_id) blockedDev[b.device_id] = b.id; });
  // Table-style (like the Customer log): a Device column first so you can see
  // exactly WHICH tablet/kitchen screen did each action, plus Block/Unblock.
  const headRow = `<div class="oprow ophead"><div>Device</div><div>Panel</div><div>Action</div><div>Where</div><div>When</div><div></div></div>`;
  const body = rows.map((r) => {
    const device = r.device_id
      ? `<span class="op-dev">📱 #${esc(r.device_id)}</span>`
      : `<span class="lg-muted">—</span>`;
    const where = r.table_number ? "T" + esc(r.table_number) : (r.detail ? esc(opDetailText(r.action, r.detail, r.plain)) : "");
    // Block/Unblock only for field devices (tablet/kitchen) — never the editor,
    // so the owner can't lock themselves out of the panel that does the unblocking.
    let act = "";
    if (r.device_id && r.panel !== "editor") {
      act = blockedDev[r.device_id]
        ? `<span class="logstat logstat-blocked">blocked</span> <button class="btn small" data-unblock-dev="${esc(blockedDev[r.device_id])}">Unblock</button>`
        : `<button class="btn small danger" data-block-dev="${esc(r.device_id)}">Block</button>`;
    }
    return `<div class="oprow oprow-click${blockedDev[r.device_id] ? " op-blocked" : ""}" data-op-detail="${esc(r.id)}">
      <div class="opcell">${device}</div>
      <div class="opcell"><span class="op-panel op-${esc(r.panel)}">${esc(PANEL_LABEL[r.panel] || r.panel)}</span></div>
      <div class="opcell"><b>${esc(actLabel(r.action))}</b>${pinPill(r)}${r.actor_id === "00000000-0000-0000-0000-0000000000ad" ? ` <span class="op-pinpill" title="You did this from an admin panel view — staff and owner logs show it as a plain panel action">🛡 Admin</span>` : ""}</div>
      <div class="opcell lg-muted">${where}</div>
      <div class="opcell"><small>${esc(whenLabel(r.created_at))}</small></div>
      <div class="opcell opacts">${act}</div>
    </div>`;
  }).join("");
  return head + `<div class="oplist">${headRow}${body}</div>`;
}

// Fetch the operation log (lazily, when that view is shown).
async function loadOplog() {
  try { state.oplog = await api("GET", "/oplog"); if (state.tab === "log") renderEditor(); }
  catch (e) { toast("Couldn't load the activity log: " + errText(e), "err"); }
}

// The Activity log's chips, search and sort. Same shape as bindAudit() beside it: every control
// re-renders what is already in hand — no request, no egress — and none of them may swallow a tap.
function bindOplog() {
  document.querySelectorAll("[data-op-group]").forEach((b) => {
    b.onclick = () => { state.oplogGroup = b.dataset.opGroup || ""; renderEditor(); };
  });
  const so = document.getElementById("opSort");
  if (so) so.onchange = () => { state.oplogSort = so.value; renderEditor(); };
  const q = document.getElementById("opQ");
  if (q) q.oninput = () => {
    state.oplogQ = q.value;
    // Keep the caret where the person left it — a full re-render otherwise sends it to the end
    // after every keystroke, which is what the Audit's own search box learned to do.
    const at = q.selectionStart;
    renderEditor();
    const n = document.getElementById("opQ");
    if (n) { n.focus(); try { n.setSelectionRange(at, at); } catch {} }
  };
}

// bindLog: wire up the Log tab's buttons (refresh, exit a guest, block, unblock).
function bindLog() {
  const ed = $("#editor");
  const rb = document.getElementById("refreshLog"); if (rb) rb.onclick = loadUsers;
  ed.querySelectorAll("[data-exit]").forEach((b) => (b.onclick = () => exitUser(b.dataset.exit)));
  ed.querySelectorAll("[data-block-phone]").forEach((b) => (b.onclick = () => blockUser(b.dataset.blockPhone, b.dataset.blockTable)));
  ed.querySelectorAll("[data-unblock]").forEach((b) => (b.onclick = () => unblockLog(b.dataset.unblock)));
  // Operation log: block / unblock a staff DEVICE (tablet / kitchen screen).
  ed.querySelectorAll("[data-block-dev]").forEach((b) => (b.onclick = () => blockDevice(b.dataset.blockDev)));
  ed.querySelectorAll("[data-unblock-dev]").forEach((b) => (b.onclick = () => unblockLog(b.dataset.unblockDev)));
  // (The old top Customer/Operation toggle is gone — the left sidebar is the one switch.)
  const ro = document.getElementById("refreshOplog"); if (ro) ro.onclick = loadOplog;
  const sw = document.getElementById("staffWatch"); if (sw) sw.onclick = openStaffRisk;
  // "Keep logs for …" dropdown (both logs) → save the new retention.
  ed.querySelectorAll(".ret-select").forEach((s) => (s.onchange = () => saveRetention(s.dataset.ret, s.value)));
  // Click a row to open its full detail (ignore clicks that landed on a button,
  // e.g. Block/Unblock/Exit — those do their own thing).
  ed.querySelectorAll("[data-op-detail]").forEach((row) => (row.onclick = (e) => { if (!e.target.closest("button")) showOpDetail(row.dataset.opDetail); }));
  ed.querySelectorAll("[data-cust-detail]").forEach((row) => (row.onclick = (e) => { if (!e.target.closest("button")) showCustDetail(row.dataset.custDetail); }));
}

// showOpDetail: open the full-info card for one operation-log row — everything about
// that action, laid out in tidy sections (When / Who / What / Manager PIN / Status).
// The Manager-PIN section appears ONLY when a manager's PIN actually authorised the
// action (a tablet row with an `actor`); otherwise it isn't there at all.
function showOpDetail(id) {
  const r = (state.oplog || []).find((x) => x.id === id);
  if (!r) return;
  // On a TABLET row, a non-empty `actor` is the manager whose PIN unlocked it (the tablet has
  // no per-person login) — except the person's own login/profile actions. " / " means one PIN
  // shared by several managers → ambiguous.
  const isPin = isManagerPinRow(r);
  const pinShared = isPin && String(r.actor).includes(" / ");
  const isErr = r.level === "error";
  const isResolved = isErr && !!r.resolved_at;
  const rows = [
    { section: "When" },
    { label: "Date & time", value: fullWhen(r.created_at) },
    { label: "How long ago", value: whenLabel(r.created_at) },
    { section: "Who" },
    isPin
      ? { label: "Panel", value: "Waiter tablet" }
      : { label: "Done by", value: r.actor_id === "00000000-0000-0000-0000-0000000000ad" ? "🛡 Admin (via panel view — invisible to staff & owner logs)" : (r.actor || (r.panel === "db" ? "Direct database edit" : "Panel action (no staff login yet)")) },
    { label: "Panel", value: isPin ? "" : (PANEL_LABEL[r.panel] || r.panel) },
    { label: "Device", value: r.device_id ? "#" + r.device_id : "" },
  ];
  if (isPin) {
    rows.push(
      { section: "Manager PIN", accent: "#d4af37" },
      { label: pinShared ? "Shared PIN of" : "Authorised by", value: "🔑 " + r.actor, strong: true, color: pinShared ? "var(--warn, #e0a800)" : "#d4af37" },
    );
    if (pinShared) rows.push({ label: "Note", value: "This PIN belongs to more than one manager — any of them could have entered it." });
  }
  rows.push(
    { section: "What happened" },
    { label: "Details", value: r.detail || "" },
    { label: "Table", value: r.table_number ? "T" + r.table_number : "" },
    { label: "Order id", value: r.order_id || "" },
  );
  if (isErr) {
    rows.push(
      { section: "Status" },
      { label: "State", value: isResolved ? "Resolved" : "Open — needs attention" },
      { label: "Resolved at", value: isResolved ? fullWhen(r.resolved_at) : "" },
    );
  }
  rows.push(
    { section: "Reference" },
    { label: "Action code", value: r.action },
    { label: "Log id", value: r.id },
  );
  logDetailDialog(actLabel(r.action), rows);
}

// showCustDetail: open the full-info card for one customer-log (guest) row.
function showCustDetail(id) {
  const u = state.users || {};
  const m = (u.members || []).find((x) => x.id === id);
  if (!m) return;
  const nOrders = (u.orders || []).filter((o) => o.member_id === id).length;
  const nCalls = (u.calls || []).filter((c) => c.member_id === id).length;
  const table = m.session ? m.session.table_number : "—";
  logDetailDialog("Guest log entry", [
    { label: "Guest", value: m.name || "(unnamed)" },
    { label: "Guest id", value: m.id },
    { label: "Table", value: "T" + table },
    { label: "Role", value: m.role === "owner" ? "👑 Head" : "🤝 Partner" },
    { label: "Phone", value: m.phone || "" },
    { label: "Orders placed", value: String(nOrders) },
    { label: "Waiter calls", value: String(nCalls) },
    { label: "Joined", value: fullWhen(m.joined_at) },
  ]);
}

// exitUser: remove a guest from their table (from the Log tab).
async function exitUser(memberId) {
  if (!(await confirmDialog("Remove this guest from the table? They can't order or call until they rejoin.", "Remove"))) return;
  try { const _wq = await api("POST", "/members/" + memberId + "/remove"); await loadUsers(); okToast(_wq, "Guest removed"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
// blockUser: block a guest by phone (preferred) or table, so they hit a blocked screen.
async function blockUser(phone, table) {
  const by = phone ? `phone ${phone}` : `table ${table}`;
  if (!(await confirmDialog(`Block this guest (by ${by})? They'll see a blocked screen and can't order or call.`, "Block"))) return;
  try { const _wq = await api("POST", "/blocklist", phone ? { phone } : { table }); await loadUsers(); okToast(_wq, "Blocked"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
// blockDevice: block a staff DEVICE (a tablet / kitchen screen) by its device id.
// The tablet & kitchen APIs then refuse every request from it until unblocked.
async function blockDevice(deviceId) {
  if (!deviceId) return;
  if (!(await confirmDialog("Block this device? The tablet/kitchen screen using it won't be able to take orders or act until you unblock it.", "Block device"))) return;
  try { const _wq = await api("POST", "/blocklist", { device_id: deviceId, reason: "device" }); await loadUsers(); okToast(_wq, "Device blocked"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
// unblockLog: remove someone from the blocklist (a guest OR a device). After it,
// loadUsers refreshes the blocklist so the operation-log buttons flip back too.
async function unblockLog(id) {
  try { const _wq = await api("DELETE", "/blocklist/" + id); await loadUsers(); okToast(_wq, "Unblocked"); }
  catch (e) { toast("Failed: " + e.message, "err"); }
}

// ---------- tabs + init ----------
// setTab: switch the editor to a different tab. It records the choice (so a refresh
// stays here), resets the selection, shows/hides the search + "New" controls as
// appropriate, redraws, and kicks off any data load that tab needs.
// ── Platform (Zomato / Swiggy / takeaway) orders ────────────────────────────
// Reads the separate aggregator_orders table via GET /platform; renders a
// status board (New → Preparing → Ready → Handed over). Dine-in is untouched.
const PLAT_META = {
  zomato:   { label: "Zomato",   cls: "z" },
  swiggy:   { label: "Swiggy",   cls: "s" },
  takeaway: { label: "Website",  cls: "t" }, // the restaurant's own site (mig 209)
  parcel:   { label: "Parcel",   cls: "p" }, // staff-punched counter parcel — never "Takeaway"
  other:    { label: "Other",    cls: "o" },
};
const platMoney = (n) => "₹" + Math.round(Number(n) || 0).toLocaleString("en-IN");
// HOW OLD IS THIS PLATFORM ORDER? Minutes, then hours, then days — the same steps the kitchen
// wall uses (public/panels/kitchen/app.js, T4 sweep 2026-08-11) and the same reason.
// THE UNIT USED TO NEVER CHANGE (T5 sweep #7, 2026-08-23). This returned bare minutes forever, so
// a parcel left from the day before read "2709m" on the Platform board — measured on the running
// panel. At a glance "2709m" reads as roughly forty-five minutes; it is forty-five HOURS, which is
// the opposite of the truth, on the one board where age is the whole point (a delivery order
// nobody has picked up). Minutes are dropped past a day: nobody needs them at that range and the
// chip is a tight space. Under an hour nothing changes at all.
function platAge(iso) {
  const t = new Date(iso).getTime();
  if (!isFinite(t)) return "";                    // say nothing rather than nonsense
  const m = Math.floor(Math.max(0, (Date.now() - t) / 60000));
  if (m < 1) return "just now";
  if (m < 60) return m + "m";
  const h = Math.floor(m / 60);
  if (h >= 24) return Math.floor(h / 24) + "d " + (h % 24) + "h";
  return h + "h " + (m % 60) + "m";
}
function platColOf(st) {
  if (st === "new") return "new";
  if (st === "accepted" || st === "preparing") return "prep";
  if (st === "ready") return "ready";
  if (st === "handed_over") return "done";
  return null; // cancelled etc. are not shown on the board
}
function platCardHtml(o) {
  const m = PLAT_META[o.source] || PLAT_META.other;
  const items = Array.isArray(o.items) ? o.items : [];
  const lines = items.map((it) =>
    `<div class="plat-line"><span class="q">${esc(it.qty)}×</span> ${esc(it.title)}${Array.isArray(it.removed) && it.removed.length ? `<span class="no"> no ${esc(it.removed.join(", "))}</span>` : ""}</div>`).join("");
  let action = "";
  if (o.status === "new") action = `<button class="btn primary" data-plat-act="accepted" data-plat-id="${esc(o.id)}">Accept</button><button class="btn ghost" data-plat-act="cancelled" data-plat-id="${esc(o.id)}" title="Reject">✕</button>`;
  else if (o.status === "accepted" || o.status === "preparing") action = `<button class="btn primary" data-plat-act="ready" data-plat-id="${esc(o.id)}">Mark ready</button>`;
  else if (o.status === "ready") action = `<button class="btn primary" data-plat-act="handed_over" data-plat-id="${esc(o.id)}">Hand over</button>`;
  // Payment is tracked for a counter PARCEL and a WEBSITE order (both may be pay-on-pickup);
  // Zomato/Swiggy are prepaid by the platform. Unpaid → a "Collect" button that settles it;
  // paid → a PAID pill.
  const showPay = o.source === "parcel" || o.source === "takeaway";
  const paidPill = showPay ? (o.paid ? `<span class="plat-paid">PAID</span>` : `<span class="plat-unpaid">UNPAID</span>`) : "";
  const collect = (showPay && !o.paid) ? `<button class="btn ghost plat-collect" data-plat-pay="${esc(o.id)}" title="Take payment for this order">💰 Collect</button>` : "";
  // 🖨 Print bill straight off the card, in EVERY column including Handed over (owner,
  // 2026-08-02). A parcel is handed to a customer who wants their bill, and that can be
  // asked for before it's ready, at the counter, or a minute after it left — so the button
  // is on the card itself, not only inside the detail. Parcels only: a Zomato/Swiggy order
  // is billed by the platform, so printing one here would produce a bill nobody should give out.
  const printBtn = o.source === "parcel" ? `<button class="btn ghost plat-print" data-plat-print="${esc(o.id)}" title="Print this parcel's bill">🖨 Print bill</button>` : "";
  // The whole card opens the parcel's detail (owner, same day) — the SAME popup the floor's
  // Parcel tile opens, so there is one parcel detail, not two that can drift apart. The
  // buttons inside stop the click bubbling, so tapping one never also opens the detail.
  const isParcel = o.source === "parcel";
  const openAttrs = isParcel ? ` data-plat-open="${esc(o.id)}" role="button" tabindex="0" title="Open this parcel"` : "";
  return `<div class="plat-card ${m.cls}${isParcel ? " plat-card-open" : ""}"${openAttrs}>
    <div class="plat-ch"><span class="plat-badge ${m.cls}">${esc(m.label)}</span><span class="plat-kot">#${esc(o.kot_no ?? "—")}</span>${paidPill}<span class="plat-age">${esc(platAge(o.created_at))}</span></div>
    <div class="plat-cust">${esc(o.customer_name || "—")}</div>
    <div class="plat-items">${lines || '<span class="plat-empty">no items</span>'}</div>
    <div class="plat-cf"><span class="plat-tot">${platMoney(o.total)}</span><span class="plat-acts">${printBtn}${collect}${action}</span></div>
  </div>`;
}
function platformHtml() {
  const all = state.data.platform || [];
  const cols = { new: [], prep: [], ready: [], done: [] };
  all.forEach((o) => { const c = platColOf(o.status); if (c) cols[c].push(o); });
  // An empty lane used to print a bare em dash. On a quiet afternoon that meant the whole board
  // read as three dashes and a manager could not tell "no delivery orders right now" from "this
  // failed to load" — the honest-empty-state rule, in the one place it was skipped (T14 tablet
  // sweep, 2026-08-05). Each lane now says what its own emptiness means.
  const EMPTY = { new: "nothing waiting to be accepted", prep: "nothing being made right now", ready: "nothing waiting to be picked up", done: "nothing handed over yet" };
  const col = (key, label) => `<div class="plat-col"><div class="plat-col-h">${label} <span class="ct">${cols[key].length}</span></div><div class="plat-col-body">${cols[key].map(platCardHtml).join("") || `<div class="plat-col-empty">${EMPTY[key]}</div>`}</div></div>`;
  // The "Add test order" button and the "Show in bills" toggle were REMOVED (owner 2026-07-06):
  //  • the test button inserted a REAL, auto-accepted order that polluted live revenue / the
  //    Z-report with fake money and couldn't be told apart — turned OFF so it can't happen.
  //  • "Show in bills" wrote a flag nothing ever read — it did nothing, so it's gone.
  // The "🆕 New" column shows ONLY when something is actually awaiting acceptance; today every
  // order auto-accepts, so an always-empty New column + its Accept/Reject buttons were dead,
  // misleading UI. It reappears automatically if a real integration ever sends a 'new' order.
  const newCol = cols.new.length ? col("new", "🆕 New") : "";
  // Header title + subtitle built from what's actually live for this restaurant (mig 209): the
  // delivery channels that are on, plus parcels. A restaurant with only parcels reads "Parcels".
  const ch = state.platformChannels || {};
  const platOn = state.platformOn !== false;
  const parcelOn = state.parcelOn === true;
  const chLabels = [];
  if (platOn) { if (ch.zomato) chLabels.push("Zomato"); if (ch.swiggy) chLabels.push("Swiggy"); if (ch.website) chLabels.push("Website"); }
  const title = (platOn && chLabels.length) ? "Platform" : "Parcels";
  const subParts = [...chLabels]; if (parcelOn) subParts.push("Parcels");
  const sub = subParts.length ? `<span class="sub">· ${subParts.join(" · ")}</span>` : "";
  // "Simulate order" — the demo/representation control (no API keys needed). ADMIN/OWNER ONLY:
  // it's a demo tool, so real floor staff never see it (they'd otherwise be able to add fake
  // orders to live revenue — the reason the old test button was removed). The server refuses a
  // non-owner staff request too. Shows a channel picker of the live delivery channels.
  const canSimulate = !!(XRAY_WHO && XRAY_WHO.higherView);
  const simChannels = (platOn && canSimulate) ? [["zomato", "Zomato"], ["swiggy", "Swiggy"], ["website", "Website"]].filter(([k]) => ch[k]) : [];
  const simMenu = simChannels.length
    ? `<div class="plat-sim">
        <button class="btn" id="platSim" title="Add a demo order to try the flow (owner / admin only)">＋ Simulate order ▾</button>
        <div class="plat-sim-menu" id="platSimMenu" hidden>${simChannels.map(([k, l]) => `<button class="btn ghost" data-plat-sim="${k}">${esc(l)}</button>`).join("")}</div>
      </div>` : "";
  return `<div class="ed-head plat-head">
      <h2>${title} ${sub}</h2>
      <div class="plat-head-actions">
        ${simMenu}
        <button class="btn" id="platRefresh" title="Refresh">↻ Refresh</button>
      </div>
    </div>
    <!-- The board is a FIXED 4-column grid, but "🆕 New" is deliberately dropped when nothing is
         awaiting acceptance (see newCol above) — so normally only THREE lanes render into four
         slots and the fourth sits empty. Measured on an iPad (1194px): the three cards ended at
         x=877 with 317px of blank screen beside them (T14 tablet sweep, 2026-08-05). Tell the grid
         how many lanes there actually are so it always fills the width. -->
    <div class="plat-board" style="--plat-cols:${newCol ? 4 : 3}">
      ${newCol}${col("prep", "🍳 Preparing")}${col("ready", "✅ Ready")}${col("done", "📦 Handed over")}
    </div>`;
}
let platSimOutsideBound = false;   // the document-level "click away to close" is added once
function bindPlatform() {
  const rf = document.getElementById("platRefresh"); if (rf) rf.onclick = loadPlatform;
  // Simulate-order menu (demo mode): toggle the channel picker; a pick fires POST /platform/test.
  const sim = document.getElementById("platSim"); const simMenu = document.getElementById("platSimMenu");
  if (sim && simMenu) {
    sim.onclick = (e) => { e.stopPropagation(); simMenu.hidden = !simMenu.hidden; };
    // CLOSE-ON-OUTSIDE-CLICK HAS TO SURVIVE THE FIRST CLICK (sweep #8 T7). This was
    // `{ once: true }`, registered when the tab binds — so the very first click anywhere spent
    // it, and from the second time the menu was opened nothing outside it closed it any more.
    // The menu then sat over the board until the next full repaint. A live listener that simply
    // asks whether the click was inside the menu costs nothing and cannot run out.
    // Registered ONCE for the life of the page, on the document, and it re-finds the menu each
    // time — bindPlatform() runs on every repaint of this tab, and one listener per repaint is
    // how a long shift ends up with hundreds of them.
    if (!platSimOutsideBound) {
      platSimOutsideBound = true;
      document.addEventListener("click", (e) => {
        const m = document.getElementById("platSimMenu");
        if (!m || m.hidden) return;
        if (e.target.closest && e.target.closest("#platSimMenu, #platSim")) return;
        m.hidden = true;
      });
    }
    simMenu.querySelectorAll("[data-plat-sim]").forEach((b) => b.onclick = async (e) => {
      e.stopPropagation(); simMenu.hidden = true; b.disabled = true;
      try { const _wq = await api("POST", "/platform/test", { channel: b.dataset.platSim }); okToast(_wq, "Demo order added ✓"); await loadPlatform(); }
      catch (err) { toast("Failed: " + err.message, "err"); }
    });
  }
  // Open a parcel's detail from its card — the same popup the floor's Parcel tile opens.
  document.querySelectorAll("[data-plat-open]").forEach((c) => (c.onclick = (e) => {
    if (e.target.closest("button")) return;   // a tap on Print / Collect / Mark ready is not "open"
    openParcelTile(c.dataset.platOpen);
  }));
  // 🖨 Print bill on the card itself, in every column. Prints first, then records it — a
  // printer that never opened must not leave a stamp saying paper went out.
  document.querySelectorAll("[data-plat-print]").forEach((b) => b.onclick = async (e) => {
    e.stopPropagation();
    const id = b.dataset.platPrint;
    const o = (state.data.platform || []).find((x) => String(x.id) === String(id));
    if (!o) { toast("That order is no longer on the board", "err"); return; }
    b.disabled = true;
    // The discount rides along here too — same reason as the floor tile's Print (T18, 2026-08-16):
    // the row carries it (payload->discount, aliased by the Platform read) and a bill printed
    // without it charges the customer more than the record says they paid.
    try { printParcelReceipt({ kot: o.kot_no, phone: o.customer_phone, bill_no: o.bill_no, invoice_no: o.invoice_no, invoice_at: o.invoice_at, created_at: o.created_at, items: Array.isArray(o.items) ? o.items : [], total: o.total, customer: o.customer_name, paid: !!o.paid, method: o.payment_method, discount: o.discount ?? (o.payload || {}).discount, discount_note: o.discount_note ?? (o.payload || {}).discount_note ?? null }); }
    catch { toast("Couldn't open the print window", "err"); b.disabled = false; return; }
    try { const _wq = await api("POST", `/platform/${id}/printed`, {}); okToast(_wq, "Bill printed ✓"); await loadPlatform(); }
    catch (err) { b.disabled = false; toast("Printed, but couldn't record it: " + ((err && err.message) || err), "err"); }
  });
  document.querySelectorAll("[data-plat-act]").forEach((b) => b.onclick = async () => {
    b.disabled = true;
    try { await api("POST", `/platform/${b.dataset.platId}/status`, { status: b.dataset.platAct }); await loadPlatform(); }
    catch (e) { toast("Failed: " + e.message, "err"); b.disabled = false; }
  });
  // Collect payment for an unpaid parcel / website order (pay-on-pickup) — settles it, flips
  // the pill to PAID.
  //
  // IT ASKS HOW THEY PAID (2026-08-05). This posted { method: "cash" } unconditionally — the
  // very fault fixed on the floor's parcel tile on 2026-08-04, which this sibling button never
  // got. Every parcel collected here by UPI, card or wallet was booked as CASH, so the day's
  // payment-method breakdown was wrong by their whole value, and cash-vs-digital is exactly
  // the split a GST audit looks at. Same sheet, same options as the tile: methodOnly (this
  // endpoint takes no tip and no split) and crm:false (the counter already took the name).
  document.querySelectorAll("[data-plat-pay]").forEach((b) => b.onclick = async () => {
    const id = b.dataset.platPay;
    const o = (state.data.platform || []).find((x) => String(x.id) === String(id));
    // Say so rather than opening a sheet for ₹0 — the same refusal the Print button gives.
    if (!o) { toast("That order is no longer on the board", "err"); return; }
    b.disabled = true;
    const picked = await openPaymentMethodModal(Number(o.total) || 0, `Collect ${o.source === "parcel" ? "parcel" : "order"}`, { methodOnly: true, crm: false });
    if (!picked || picked.special) { b.disabled = false; return; }   // cancelled — the card stays
    try { const _wq = await api("POST", `/platform/${id}/pay`, { method: picked.method }); okToast(_wq, `Collected via ${picked.method} ✓`); await loadPlatform(); }
    catch (e) { toast("Failed: " + e.message, "err"); b.disabled = false; }
  });
}
// Count of platform orders STILL in play (not handed over / cancelled) — shown on
// the Platform tab so the manager sees how many are live without opening the tab.
function updatePlatformBadge() {
  const live = (state.data.platform || []).filter((o) => o.status !== "handed_over" && o.status !== "cancelled").length;
  const b = $("#platformBadge");
  if (b) { b.textContent = live; b.hidden = live === 0; }
  syncBurgerNews();
}
let platSeq = 0; // own latest-wins guard so platform loads never cancel the board loaders
async function loadPlatform() {
  // Skip the poll entirely when BOTH the platform and parcel modules are off for this
  // restaurant (mig 209) — no board to show, and hitting GET /platform would 403 every tick.
  // (Admin/owner higher-view still polls so the X-ray board works.) Falls through if settings
  // aren't loaded yet (first call) so the initial fetch still runs.
  const s = state.data.settings;
  if (s) {
    // TWO modules again (mig 259): Platforms = takeaway_* (Zomato/Swiggy/website), Parcel =
    // parcel_* (the counter). Either one alone is a reason to load the board.
    const platEff = platformModuleOn(), parcelEff = parcelModuleOn();
    // The two flags the rest of the panel reads are set HERE as well as from the response.
    // Leaving them `undefined` on a restaurant with neither module — which is what the old
    // early return did — read as "on" everywhere they were tested with `!== false`.
    state.platformOn = platEff; state.parcelOn = parcelEff;
    if (!platEff && !parcelEff) { state.data.platform = []; updatePlatformBadge(); return; }
  }
  const seq = ++platSeq;
  try {
    const res = await api("GET", "/platform");
    if (seq !== platSeq) return;
    state.data.platform = res.orders || [];
    state.platformToggles = res.toggles || {};
    state.platformChannels = res.channels || {};   // which delivery channels are live (mig 209)
    state.platformOn = res.platform_on;             // is the platform module effective
    state.parcelOn = res.parcel_on;                 // is the parcel module effective
    updatePlatformBadge();
    // Only the Platform board draws parcels now (owner, 2026-08-14), so a parcel change no longer
    // has any reason to repaint the TABLES tab — the strip it used to keep fresh is gone. The tab's
    // own badge is refreshed by updatePlatformBadge() just above, which is what tells a manager on
    // the floor that a parcel is waiting.
    if (state.tab === "platform") renderEditor();
  } catch { /* keep last good board */ }
}

function setTab(tab) {
  // Menu-only embed: the only reachable tabs are the menu ones — redirect any other target
  // (boot fallbacks, realtime handlers) to Dishes, and mark the body so the CSS hides the rest.
  // NB: always `applyEmbedSkin(CUR_SKIN)`, never "skin-" + MENU_SKIN — see the note at the
  // top. MENU_SKIN is the skin this iframe was BORN with; CUR_SKIN is the one the cockpit
  // is wearing right now.
  if (MENU_ONLY) { document.body.classList.add("menu-only"); applyEmbedSkin(CUR_SKIN); if (!MENU_TABS.includes(tab)) tab = "items"; }
  // Layout-preview embed (mig 226): the admin is only looking at tile SIZE, so pin the floor
  // and let .floor-preview CSS strip the chrome. Same shape as the menu-only redirect above.
  if (FLOOR_PREVIEW) { document.body.classList.add("floor-preview"); tab = "tables"; }
  if (INV_ONLY) { document.body.classList.add("menu-only"); applyEmbedSkin(CUR_SKIN); if (tab !== "inventory") tab = "inventory"; }
  // Owner "Manager mode" embed: the four tabs the owner panel already covers are
  // unreachable — any target pointing at one (a stale saved tab, a boot fallback, a
  // realtime handler) lands on the live floor instead.
  if (OWNER_MODE) { document.body.classList.add("owner-mode"); applyEmbedSkin(CUR_SKIN); if (OWNER_HIDDEN_TABS.includes(tab)) tab = "tables"; }
  // Leaving the Dashboard: destroy its live Chart.js instances so their detached canvases +
  // resize handlers don't linger until the next Dashboard visit.
  if (state.tab === "dash" && tab !== "dash") { dashCharts.forEach((c) => { try { c.destroy(); } catch {} }); dashCharts = []; }
  // Leaving the Tables floor: close any open table detail/popup and tear down its hardware-BACK
  // layers (they were only re-synced on the Tables render, so a stray popup left one registered
  // on another tab → a wasted Back press).
  if (state.tab === "tables" && tab !== "tables") {
    state.floatingTables = [];
    state.selectedTable = null;
    state.openSess = null;
    syncTableBackLayers();
  }
  // ENTERING Settings refetches the team (owner, 2026-08-02: the admin deleted a user and the
  // manager's Users list still showed them — the list was fetched ONCE per panel session, so a
  // person removed elsewhere lingered until a full page reload). Clearing the once-flag here
  // makes the render hook fetch fresh rows each visit; the stale list stays on screen until the
  // real one lands (same skeleton-then-real pattern loadStaffTeam already uses), and a manager
  // parked on another tab still pays nothing.
  if (tab === "general" && state.tab !== "general") state.staffLoaded = false;
  state.tab = tab;
  try { localStorage.setItem("lfh_editor_tab", tab); } catch {}
  state.isNew = false;
  state._snapPending = true; // re-baseline the unsaved-changes guard for the new tab
  // Search/category-filter are per-sub-tab: carrying "burger" from Dishes into
  // Categories/Tags made those lists look empty. Clear them on any tab switch.
  state.search = "";
  state.catFilter = ""; // "" = All (matches the default)
  const _sb = document.getElementById("search"); if (_sb) _sb.value = "";
  state.sel = tab === "general"
    ? clone(state.data.settings || { id: "site", bubbles_enabled: true, service_mode: false })
    : null;
  // The single "Editor" top tab (data-tab="items") stays highlighted across its
  // three sub-views (Dishes / Categories / Tags).
  const EDITOR_SUB = ["items", "categories", "filters"];
  document.querySelectorAll(".tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === tab || (t.dataset.tab === "items" && EDITOR_SUB.includes(tab))));
  // Show the Dishes/Categories/Tags sub-nav only inside the Editor section, and
  // mark which sub-view is open.
  const sub = document.getElementById("editorSubtabs");
  if (sub) {
    sub.hidden = !EDITOR_SUB.includes(tab);
    sub.querySelectorAll(".subtab").forEach((s) => s.classList.toggle("active", s.dataset.tab === tab));
  }
  // The search box and "+ New" don't apply to the General/Orders/Tables tabs.
  const noList = tab === "general" || tab === "orders" || tab === "tables" || tab === "platform" || tab === "log" || tab === "features" || tab === "dash" || tab === "banquet" || tab === "ratings" || tab === "inventory";
  $("#newBtn").style.display = noList ? "none" : "";
  // Multi-select is Dishes-only; leaving the Dishes tab exits it. syncBulkBtn shows/hides
  // the "Select" button and reflects the current mode.
  if (tab !== "items") { state.bulkMode = false; state.bulkSel.clear(); }
  // …and publish the tab on <body> so CSS can hide that button too. syncBulkBtn()'s `hidden`
  // attribute rides on the button NODE, and the sidebar is re-rendered from innerHTML — the
  // replacement node carries no attribute, so a stale "☑︎ Select" was measured visible on
  // Dashboard / Bills / Settings / Audit & logs (T12 phone sweep, 2026-08-05). A body attribute
  // cannot be lost with the node. See `body[data-tab]` in style.css.
  document.body.dataset.tab = tab;
  syncBulkBtn();
  $("#search").style.display = noList ? "none" : "";
  closeSuggest(); // the open suggestions belong to the tab we're leaving
  // Tables tab: drop the whole left sidebar (it only held a dead "Floor map" label).
  // The floor already has its own left tiles + right detail, so it takes the full
  // width — the .no-sidebar class collapses the grid's first column to nothing.
  const layout = document.querySelector(".layout");
  if (layout) layout.classList.toggle("no-sidebar", tab === "tables" || tab === "platform" || tab === "banquet" || tab === "ratings" || tab === "inventory" || tab === "dash");
  renderCatFilter(); // show category chips on Dishes, hide elsewhere
  renderList();
  renderEditor();
  if (tab === "orders") {
    loadOrders();
    unseenOrders = 0;
    updateOrdersBadge(); // also refreshes the tab title (orders + tables combined)
  }
  if (tab === "tables") {
    loadSessions(); // unified live floor (orders + sessions in one)
    unseenTables = 0; // opening the floor clears its unseen-request badge
    updateTablesBadge();
  }
  if (tab === "log") {
    // Fetch only the views this manager is allowed (whoami.logParts) — a forbidden read
    // would just 403. The customer-log data also powers the operation log's Block/Unblock
    // column, so it loads whenever it's allowed, not only on its own view. The removals
    // view loads lazily in renderEditor (existing pattern).
    const parts = logPartsAllowed();
    if (parts.customers) loadUsers(); // customer-log data
    // If we're restoring straight onto the Activity log (e.g. a refresh stayed
    // there), fetch its data too — otherwise the table would be empty.
    if (state.logView === "operations" && parts.activity) loadOplog();
  }
  if (tab === "platform") loadPlatform();
}

// loadOrders: fetch the latest orders (and waiter calls) and redraw if we're on
// the Orders tab. Used by the Refresh button and after any order change.
// Invoice pipeline (manager). generate locks the bill + assigns a permanent number;
// void reopens it for edits (number kept in record). Server-authoritative (migration 073).
// Guard against a double-tap on "Generate invoice": on a laggy tablet two quick taps
// fire two POSTs before the button re-renders, and each consumes an invoice sequence
// number (one gets overwritten) → a gap in the numbering. Keyed per session so two
// DIFFERENT bills can still invoice at once; the same bill can't fire twice in flight.
const _invBusy = new Set();
// askBillCustomer(session): the mobile-first "who is this bill for?" sheet.
// Returns { phone, name } to send with the invoice, undefined to send nothing (the
// restaurant doesn't ask, or this bill already has its customer), or null if the
// waiter backed out — in which case NO invoice is generated.
async function askBillCustomer(sid, sess) {
  const s = state.data.settings || {};
  const required = s.bill_customer_required !== false;
  if (!required) return undefined;
  if (!window.LFH_BILLCUST) return undefined;   // module missing → never block billing
  // What THIS bill already carries: re-issuing after a reopen opens the sheet pre-filled
  // with that session's own customer (owner, 2026-07-30). Scoped strictly to this
  // session_id — one table's customer never appears on another's bill.
  const row = (state.data.orders || []).find((o) => o.session_id === sid && (o.bill_cust_name || o.bill_cust_phone));
  const prefill = (sess && sess.cust_phone) ? { phone: sess.cust_phone, name: sess.cust_name }
    : row ? { phone: row.bill_cust_phone, name: row.bill_cust_name } : null;
  return LFH_BILLCUST.ask({ api, required, print: s.bill_customer_print !== false, prefill });
}
async function generateInvoice(sid) {
  if (_invBusy.has(sid)) return false;
  // REJECTED (owner, 2026-08-19): PRINTING NEVER ASKS WHY. From 2026-08-05 to 2026-08-19 a
  // re-issue (a number already exists → the previous was voided) stopped here and demanded a typed
  // reason. The owner killed it: "when I click print bill why it show like I wanna reopen the bill
  // and stuff, it should not happen like this … reprinting should also not ask any question".
  // The reason was ALREADY given, one step earlier, in the reopen picker (askReopenReason, which
  // is required and IS recorded) — so this was the same question a second time, worded as if
  // pressing Print were itself a reopen. Reopening a bill and printing a bill are different acts,
  // and only the first one is an event.
  // Nothing is lost from the record: the server now takes the reopen's own reason as the re-issue
  // reason (route.ts, sessions/:id/invoice), the new invoice number is still logged, and the
  // before → after "bill changed after a reopen" row is still written. Do not add a prompt,
  // a confirm, or an "are you sure" to any print path here.
  const ss = (state.board.sessions || []).find((s) => s.id === sid);
  const isReissue = ss && ss.invoice_no != null;
  // Who is this bill for? (owner, 2026-07-30 — mobile first, name auto-fills for a
  // returning number). This one STAYS on a re-issue and he confirmed why (2026-08-19):
  // "reopening can also change name and number … when you click print after reopen it asks for
  // no and name again and the old one is autofilled". It is not a "why did you do this" question
  // — it is the bill's own field, pre-filled, and changing it is a legitimate reason to reopen.
  const body = {};
  const cust = await askBillCustomer(sid, ss);
  if (cust === null) return false;         // cancelled — nothing is issued
  if (cust) { body.cust_phone = cust.phone; body.cust_name = cust.name; }
  _invBusy.add(sid);
  // Returns TRUE only when a number was actually issued — printIssuingInvoice relies on it, so a
  // failed issue can never be followed by a printed bill carrying no invoice number.
  try {
    const r = await api("POST", `/sessions/${sid}/invoice`, body);
    // ── A QUEUED WRITE HAS NOT ISSUED A NUMBER (T5 sweep #7, 2026-08-22) ────────────────────
    // The comment above says this returns true "only when a number was actually issued", and
    // with no signal it did the opposite: api() hands a non-GET to the outbox, which resolves
    // { ok:true, queued:true } instead of throwing, so nothing here saw a failure. The toast
    // said "Invoice generated", this returned TRUE, and printIssuingInvoice() went straight on
    // to print — from loadOrders()' saved copy, where invoice_no is still null. A printed bill
    // carrying no invoice number is the exact thing invoice-first exists to stop.
    // An invoice number can only be minted by the server (it is a gapless per-year series), so
    // there is nothing honest to print until the queue drains. The write still goes — it is in
    // the queue under its own action id and lands at-most-once on reconnect — so this says what
    // is true and refuses to print, rather than cancelling the person's work.
    if (wasQueued(r)) {
      toast("No internet — the invoice number is given by the server, so nothing is printed yet. It will be issued the moment you're back online.", "err");
      return false;
    }
    await loadOrders();
    toast(isReissue ? "Invoice re-issued" : "Invoice generated", "ok");
    return true;
  } catch (e) { toast("Failed: " + e.message, "err"); return false; }
  finally { _invBusy.delete(sid); }
}
// Print a bill that has no invoice yet: ISSUE it, then print it. One tap, and if issuing fails
// nothing is printed (a printed bill with no number is the thing invoice-first exists to stop).
// generateInvoice() already asks for the customer and handles a re-issue reason, so this just
// sequences the two and prints the FRESH rows (the invoice number is assigned server-side, so we
// must re-read before printing or the paper carries no number).
async function printIssuingInvoice(sid, groupKey) {
  const issued = await generateInvoice(sid);
  if (!issued) return;               // cancelled or failed — generateInvoice already said why
  const os = groupKey ? ordersInGroup(groupKey)
    : (state.data.orders || []).filter((o) => o.session_id === sid && !o.archived);
  const o0 = os[0];
  if (!o0) { toast("Bill issued, but there was nothing to print", "err"); return; }
  printBill(o0.table_number, { invoice_no: o0.invoice_no, bill_no: o0.bill_no, invoice_at: o0.invoice_at }, os);
}
async function voidInvoice(sid) {
  // ONE dialog, not two: the old flow was a confirm AND THEN a free-text "why?", so the most
  // common reason in a restaurant — the guest wants to order more — took two taps and typing.
  // The picker below IS the confirmation (owner, 2026-08-05).
  const ss = (state.board.sessions || []).find((x) => x.id === sid) || {};
  const where = ss.table_number != null ? tableLabel(ss.table_number) : "this bill";
  const rr = await askReopenReason(`${where}${ss.invoice_no != null ? ` · invoice #${ss.invoice_no}` : ""}`);
  if (!rr) return; // cancelled — a reason is required
  const label = (REOPEN_REASONS.find((x) => x[0] === rr.code) || [, rr.code])[1].replace(/^\S+\s/, "");
  const reason = [label, rr.note].filter(Boolean).join(" — ");
  try {
    const _wq = await api("POST", `/sessions/${sid}/void-invoice`, { reason, reason_code: rr.code, reason_note: rr.note || null });
    await loadOrders();
    okToast(_wq, "Bill reopened — add or change items, then Print again for a new invoice");
  } catch (e) { toast("Failed: " + e.message, "err"); }
}
// PUT A FINISHED TABLE BACK ON THE FLOOR (owner, 2026-08-26; mig 365).
//
// "You should reopen table not the bill … if the table has already taken the order, it shouldn't
//  be able to reopen. If the table is free, then only it should be able to reopen, and after
//  reopen you can add the order to that particular bill, you can't delete."
//
// The party paid, left, and came back. voidInvoice() above is the OTHER case — a bill still live
// on the floor being corrected before it is settled — and it refuses a closed one, correctly.
//
// What this does NOT do, and must never be made to do: un-pay anything. The money collected stays
// collected, the retired invoice number stays retired and on record, and every KOT already on the
// bill stays put — the route has always refused to cancel a PAID order, which is what makes the
// reopened bill add-only without needing a new rule for it.
async function reopenTable(sid) {
  const ss = (state.board.sessions || []).find((x) => x.id === sid) || {};
  const where = ss.table_number != null ? tableLabel(ss.table_number) : "this table";
  // The same reason picker a reopen has always used — this IS the confirmation, so there is no
  // second yes/no on top of it (owner, 2026-08-05).
  const rr = await askReopenReason(`${where}${ss.invoice_no != null ? ` · invoice #${ss.invoice_no}` : ""} — the table comes back so this party can order again`);
  if (!rr) return; // cancelled — a reason is required
  const label = (REOPEN_REASONS.find((x) => x[0] === rr.code) || [, rr.code])[1].replace(/^\S+\s/, "");
  const reason = [label, rr.note].filter(Boolean).join(" — ");
  try {
    const r = await api("POST", `/sessions/${sid}/reopen-table`, { reason, reason_code: rr.code, reason_note: rr.note || null });
    // A queued write has not reopened anything — the floor behind this is unchanged (item 5's rule).
    if (wasQueued(r)) { toast("Saved on this device ✓ — the table will come back the moment you're back online.", "ok"); return; }
    await loadSessions(); await loadOrders();
    toast(`${where} is back on the floor — add the order, then Print for a new invoice`, "ok");
  } catch (e) { toast(errText(e), "err", undefined, 9000); }
}

// Issue a CREDIT NOTE — the legal way to refund/correct a bill WITHOUT changing it (used
// once a bill is settled and can't be edited). Records a new, numbered credit document.
async function creditNote(sid) {
  const amtStr = await promptDialog("Credit note — refund/correction amount (₹)?", { confirmLabel: "Next", placeholder: "e.g. 200", required: true });
  if (amtStr == null) return;
  const amount = Math.round(parseFloat(amtStr) * 100) / 100;
  if (!amount || amount <= 0) { toast("Enter a valid amount", "err"); return; }
  const reason = await promptDialog("Why this credit note? (required)", { confirmLabel: "Issue credit note", placeholder: "overcharge, refund, correction…", required: true });
  if (reason == null) return;
  // A CREDIT NOTE IS A NUMBERED DOCUMENT, AND THE SERVER GIVES THE NUMBER (T5 sweep #7,
  // 2026-08-22). With no signal the outbox resolves { ok:true, queued:true }, so this printed
  // the sentence "Credit note # issued" — a document announced with a blank number.
  try {
    const cn = await api("POST", `/sessions/${sid}/credit-note`, { amount, reason });
    if (wasQueued(cn)) { toast("Saved on this device ✓ — no internet, so the credit note has no number yet. It will be issued the moment you're back online.", "ok"); return; }
    await loadOrders(); toast(`Credit note #${cn && cn.credit_no ? cn.credit_no : ""} issued`, "ok");
  }
  catch (e) { toast("Failed: " + e.message, "err"); }
}
async function loadOrders() {
  const seq = ++dataSeq;
  try {
    const orders = await api("GET", "/orders");
    if (seq !== dataSeq) return; // a newer refresh started — drop this stale response
    state.data.orders = orders;
    // A write just changed the board (every money action reloads through here) — keep the
    // bills record in step while it is on screen, so a reopened/deleted/paid bill moves
    // between Live and Previous without a manual refresh (owner: "everything should sync").
    if (state.tab === "orders" && ordersViewKey() === "previous") loadBillsRecord(true);
    // (Don't set lastOrderCount/lastCallCount here — reconcileBoard owns them from the
    //  summary's live counts; a full-list baseline here would clash and misfire the chime.)
    try {
      const calls = await api("GET", "/calls");
      if (seq !== dataSeq) return; // superseded mid-fetch
      state.data.calls = calls;
    } catch {}
    if (state.tab === "orders") { renderList(); renderEditor(); } // sidebar counts + cards
  } catch (e) {
    toast("Couldn't load orders: " + errText(e), "err");
  }
}

// ---------- live order alerts (owner) ----------
// The editor polls the orders endpoint and chimes + badges when a new order
// lands, no matter which tab the owner is on.
let lastOrderCount = null; // baseline; set on first poll so we don't alert on startup
let lastCallCount = null;  // pending waiter calls baseline (kept for the unseen badge)
// New-call alerts are keyed by CALL ID, not by count. A count can re-trip a toast
// when several pollers fire for the same call (realtime tick + backup poll + wake)
// — the owner saw one call buzz ~3 times. Tracking which call ids we've already
// announced makes the alert fire EXACTLY once per real call, no matter how many
// times we re-poll. null = not baselined yet (don't alert for calls already there).
let seenCallIds = null;
// Optimistic-click bookkeeping: while a save is still travelling to the
// server, the 1-second poll must not overwrite that order with stale data
// (it would flicker the click back). Deletes get the same protection.
const pendingOrderOps = new Map();  // order id -> number of in-flight saves
const pendingDeletes = new Set();   // ids removed on screen, server catching up
const opBegin = (id) => pendingOrderOps.set(id, (pendingOrderOps.get(id) || 0) + 1);
const opEnd = (id) => { const n = (pendingOrderOps.get(id) || 1) - 1; n <= 0 ? pendingOrderOps.delete(id) : pendingOrderOps.set(id, n); };
let lastPollSig = "";               // fingerprint of the last drawn orders view
// While any FLOOR action (open/free/attend/approve…) is mid-save, the poll
// must not replace the board or redraw the Tables tab — it would briefly
// flicker the optimistic change back before the server confirms.
let floorOpsInFlight = 0;
let lastReqCount = null;   // pending requests (join/access/open/waiter) baseline
let unseenOrders = 0;
// Table requests (a guest asking to open/join/access a table) belong to the
// FLOOR, not Orders — so they get their OWN unseen counter and badge on the
// Tables tab. Previously they wrongly bumped the Orders badge (owner report).
let unseenTables = 0;

// updateOrdersBadge: show/hide the little red number on the Orders tab counting
// new things you haven't looked at yet.
function updateOrdersBadge() {
  const b = $("#ordersBadge");
  if (b) { b.textContent = unseenOrders; b.hidden = unseenOrders === 0; }
  syncBurgerNews();
  refreshTitle();
}

// updateTablesBadge: same idea for the Tables tab — counts unseen floor requests
// (wants-in / join / access) so the owner's eye goes to the FLOOR, where the
// matching 📨 badge already sits on the actual table tile.
function updateTablesBadge() {
  const b = $("#tablesBadge");
  if (b) { b.textContent = unseenTables; b.hidden = unseenTables === 0; }
  syncBurgerNews();
  refreshTitle();
}

// syncBurgerNews: put the tab badges' "there is something for you" ON THE ☰ ITSELF.
//
// WHY (T14 tablet sweep, 2026-08-05): syncNavFit picks .nav-compact — the ☰ drawer — whenever the
// tab strip cannot fit, and on a 1194px iPad it always can't (8 tabs of pills plus a 355px action
// cluster need more than the bar has). That decision is right and nothing is cut. But the Bills,
// Tables and Platform badges live ON those tabs, so in compact mode all three measured
// offsetParent === null: a manager on a tablet could not see "3 bills waiting / 2 tables need you"
// without first opening a drawer, and the ☰ carried no hint at all. refreshTitle() puts the total
// in the document title, which is invisible here because this panel runs inside an iframe.
// So the ☰ wears a dot whenever any badge is showing, and its aria-label says the number out loud
// for anyone using a screen reader. No new data, no request — it reads the badges we already set.
function syncBurgerNews() {
  const burger = document.querySelector(".nav-burger");
  if (!burger) return;
  let n = 0;
  for (const id of ["ordersBadge", "tablesBadge", "platformBadge"]) {
    const b = document.getElementById(id);
    if (b && !b.hidden) n += Number(b.textContent) || 0;
  }
  burger.classList.toggle("has-news", n > 0);
  burger.setAttribute("aria-label", n > 0 ? `Menu & settings — ${n} need${n === 1 ? "s" : ""} you` : "Menu & settings");
}

// refreshTitle: the browser-tab title shows the TOTAL unseen (orders + floor
// requests) so a notification is visible even when this tab is in the background.
function refreshTitle() {
  const n = unseenOrders + unseenTables;
  // This panel runs inside an IFRAME on /manager, and an iframe's document.title never reaches
  // the browser tab — so the count the comment above promises was written where nobody could
  // see it, and "Menu Editor" is a retired name besides (T15 sweep, 2026-08-05). Set the title
  // on the PARENT document when we are framed; fall back to our own when opened directly.
  const title = n ? `(${n}) Manager — Aevidine` : "Manager — Aevidine";
  document.title = title;
  try {
    // Same-origin parent (the /manager page hosts us), so this is a plain property write.
    if (window.parent && window.parent !== window) window.parent.document.title = title;
  } catch (e) { /* cross-origin embed: our own title is the best we can do */ }
}

// A short, soft two-note chime via the Web Audio API — no sound file needed.
function playOrderChime() {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    [880, 1320].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = freq;
      const t = ctx.currentTime + i * 0.16;
      gain.gain.setValueAtTime(0, t);
      gain.gain.linearRampToValueAtTime(0.18, t + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.35);
      osc.connect(gain).connect(ctx.destination);
      osc.start(t);
      osc.stop(t + 0.4);
    });
    setTimeout(() => ctx.close(), 1200);
  } catch {}
}

// pollOrders: this runs on every realtime tick / 60s backup (see startOrderWatch). It
// ALWAYS fetches the slim SUMMARY (tiny — drives the GRID, the side-panel queues, AND the
// chimes from any tab via order_count/calls/requests). The full /orders + /calls lists are
// fetched ONLY when the Orders tab is showing (that tab renders all ~200 order cards); the
// owner's 300-table fear is the floor grid, not that one detail tab. On the Tables tab the
// SELECTED table's full slice is refreshed so its detail stays live.
async function pollOrders(opts) {
  const seq = ++dataSeq;
  let summary;
  try {
    summary = await api("GET", "/summary");
  } catch (e) {
    // The catch-up poll below needs to KNOW the read failed so it can back off (LFH_RT.catchUp
    // doubles its interval while reads fail and returns to 5s the moment one succeeds — if the
    // failure is swallowed it has nothing to back off from, and every device keeps hammering a
    // database that is already struggling). Every ordinary caller keeps the quiet
    // "network blip — try again next tick" behaviour. (sweep 2026-08-04)
    if (opts && opts.rethrow) throw e;
    return;
  }
  if (seq !== dataSeq) return; // a newer loader started — this poll snapshot is stale
  if (!floorOpsInFlight) { state.summary = mergeServerSummary(summary); noticePrinterNews(); } // don't clobber an optimistic tile mid-action
  state.boardLoaded = true;

  // Orders tab → also pull the full order/call lists it renders (merged, optimistic-safe).
  if (state.tab === "orders") {
    try {
      let orders = await api("GET", "/orders");
      if (seq !== dataSeq) return;
      orders = orders
        .filter((o) => !pendingDeletes.has(o.id))
        .map((o) => (pendingOrderOps.has(o.id) ? ((state.data.orders || []).find((x) => x.id === o.id) || o) : o));
      state.data.orders = orders;
    } catch {}
    try { const calls = await api("GET", "/calls"); if (seq !== dataSeq) return; state.data.calls = calls; } catch {}
  } else if (state.tab === "tables" && detailTables().length && !floorOpsInFlight) {
    // Keep EVERY open detail (docked, collapsed-mode modal, or floating) order rows + members fresh.
    try {
      const tables = detailTables();
      const results = await Promise.all(tables.map((t) => {
        const q = "?table=" + encodeURIComponent(t);
        return Promise.all([api("GET", "/sessions" + q), api("GET", "/orders" + q), api("GET", "/calls" + q)]);
      }));
      if (seq !== dataSeq) return;
      tables.forEach((t, i) => mergeTableSlice(t, results[i][0], results[i][1], results[i][2]));
    } catch {}
  }

  // Counts + alerts + redraw live in reconcileBoard(), now driven by the SUMMARY aggregates
  // so the chimes fire identically from any tab and the targeted refetch (pollTables) reuses them.
  reconcileBoard();
}

// reconcileBoard: from the slim SUMMARY aggregates (state.summary), update the live counts,
// redraw the visible tab only when something changed, and fire the new-order / waiter-call /
// request chimes. The summary is fetched on every poll regardless of tab, so the chimes fire
// identically from any tab (no dual-source baseline drift). Called by BOTH the full poll
// (pollOrders) and the targeted refetch (pollTables) so neither path can silently drop an alert.
function reconcileBoard() {
  const summary = state.summary || {};
  // SUMMARY-driven counts (live-only order_count + unresolved calls + pending requests).
  const orderCount = Number(summary.order_count) || 0;
  const calls = summary.calls || [];          // already unresolved-only from the RPC
  const requests = summary.requests || [];    // already pending-only from the RPC
  // Remember the previous counts, then update to the new ones. The "did it grow?"
  // checks below compare prev vs now to detect something brand-new arriving.
  const prev = lastOrderCount;
  lastOrderCount = orderCount;
  lastCallCount = calls.length; // kept for any external reader; alerts now use seenCallIds
  const reqCount = requests.length;
  const prevR = lastReqCount;
  lastReqCount = reqCount;

  // While a serve flush is pending (staff is actively marking dishes), don't let
  // the poll redraw the view under their fingers — the optimistic local render is
  // already on screen and the debounced flush will reconcile it shortly. We still
  // fetched fresh data above, so the new-order/call/request alerts below still fire.
  if (!serveFlushPending()) {
    // Only redraw the Orders tab when something VISIBLE actually changed —
    // rebuilding 200 cards every second ate clicks and scroll position. (The Orders
    // tab still renders from the full state.data.orders fetched in pollOrders.)
    const orders = state.data.orders || [];
    // Redraw fingerprint. It MUST cover every field a bill card renders, or a change made
    // on another device/tab (discount, a new/removed dish, invoice generate/void, bill_no)
    // refetches but never repaints — the card shows a STALE total/invoice state until you
    // touch something or Refresh. So we serialise the FULL rows minus a tiny volatile set
    // (the exact rule kitchen/tablet use — see the boardSig gotcha in CLAUDE.md). Adding a
    // new editable order column needs NO change here; a new heartbeat-y column goes in the set.
    const RT_VOLATILE_ORDER = new Set(["updated_at"]);
    const stripVol = (o) => { const c = {}; for (const k in o) if (!RT_VOLATILE_ORDER.has(k)) c[k] = o[k]; return c; };
    const sig = JSON.stringify([
      orders.map(stripVol),
      calls.map((c) => c.id),
      reqCount,
    ]);
    const typing = document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    // Don't advance lastPollSig when we SKIP the redraw because the owner is typing (B19): otherwise a
    // bill change that lands mid-typing is fingerprinted-as-seen and never repaints until the NEXT
    // change. Leaving it stale means the next poll (once typing stops) still sees a diff and redraws.
    const skippedForTyping = state.tab === "orders" && sig !== lastPollSig && typing;
    if (state.tab === "orders" && sig !== lastPollSig && !typing) { renderList(); renderEditor(); }
    if (!skippedForTyping) lastPollSig = sig;
    if (state.tab === "tables" && !floorOpsInFlight) {
      // TARGETED realtime path (pollTables named specific tables) → patch JUST those tiles +
      // the stats/queues, NOT the whole grid. Any other path (full poll, optimistic action,
      // initial) → the full loadSessions(true) render. patchFloorTiles self-falls-back to a
      // full render if the grid/tiles aren't present or a table detail is open.
      if (targetedPatchTables && targetedPatchTables.length) patchFloorTiles(targetedPatchTables);
      else loadSessions(true); // keep the live floor fresh
    }
  }

  // new order alert (order_count is live orders only; the latest order's table comes
  // alongside it in the summary so the toast still names the table).
  if (prev !== null && orderCount > prev) {
    const newCount = orderCount - prev;
    const where = summary.latest_order_table ? "T" + summary.latest_order_table : "Walk-in";
    playOrderChime();
    toast(`🔔 ${newCount} new order${newCount > 1 ? "s" : ""} — ${where}`, "ok", null, 6000);
    if (state.tab !== "orders") { unseenOrders += newCount; updateOrdersBadge(); }
  }
  // new waiter-call alert — fire ONCE per call id (see seenCallIds note above)
  const openIds = calls.map((c) => c.id);
  if (seenCallIds === null) {
    seenCallIds = new Set(openIds); // first poll: baseline, don't alert for existing calls
  } else {
    const fresh = calls.filter((c) => !seenCallIds.has(c.id));
    if (fresh.length) {
      const latest = fresh[0];
      const where = latest && latest.table_number ? "T" + latest.table_number : "a guest";
      playOrderChime();
      toast(`🔔 ${fresh.length > 1 ? fresh.length + " waiter calls" : "Waiter call"} — ${where}`, "ok", null, 6000);
      if (state.tab !== "orders") { unseenOrders += fresh.length; updateOrdersBadge(); }
    }
    seenCallIds = new Set(openIds); // track exactly the calls still open; a re-call gets a new id
  }
  // new request alert (a guest asked to join/access a table, or requested a waiter
  // when they couldn't be auto-let-in). Newest request is last (queue is ascending).
  if (prevR !== null && reqCount > prevR) {
    const latest = requests[reqCount - 1];
    const verb = latest && latest.type === "open" ? "wants to open" : latest && latest.type === "join" ? "wants to join" : "needs access to";
    const where = latest && latest.table_number ? `T${latest.table_number}` : "a table";
    playOrderChime();
    toast(`🙋 Request — ${verb} ${where}`, "ok", null, 6000);
    // Floor request → light the TABLES badge (not Orders). The table tile itself
    // already shows the 📨 badge + "Wants in", so this just points the owner there.
    if (state.tab !== "tables") { unseenTables += (reqCount - prevR); updateTablesBadge(); }
  }
}

// pollTables(tables): TARGETED refetch — for each named table fetch ONLY its slim SUMMARY
// tile (?table=N, ~5 kB) and patch it into state.summary.tiles, instead of re-reading the
// whole 84 kB floor on every breadcrumb. The aggregates (calls/requests/joiners/blocklist +
// order_count) are tiny and restaurant-wide, so each per-table call returns them and we take
// the latest. If a named table is the SELECTED one, ALSO refresh its FULL slice so its detail
// stays live. Then reconcileBoard() runs the same counts/chimes/redraw as the full poll. ANY
// surprise → full pollOrders (safe fallback). (owner 2026-06-26 — scope egress per table.)
const tileSeq = {}; // per-table ticket for targeted polls (see below)
async function pollTables(tables) {
  if (!tables || !tables.length) return pollOrders();
  // A FULL reload (pollOrders/loadSessions) bumps dataSeq; capture it so we drop these tile
  // patches only if a full reload started meanwhile (its whole-board snapshot is fresher).
  // pollTables no longer bumps dataSeq itself: two targeted polls for DIFFERENT tables must
  // NOT cancel each other — sharing one counter meant the earlier table's tile went stale
  // until the 60s backstop (fixed 2026-07-06). A per-table ticket handles same-table overlap.
  const born = dataSeq;
  // A MERGED PARTY'S TILES MOVE TOGETHER (owner, 2026-08-03: "one is marked served, the other is
  // not — the green outline is not coming in one of them"). A child tile renders from its PARENT's
  // summary tile, and an order keeps the table number it was ORDERED at (mig 249) — so a targeted
  // poll for one member of the party refreshed one tile and left its partners painted stale until
  // the 60s backstop. Widen every requested table to its whole party: the extra fetches are the
  // same cheap ?table= reads, and only ever happen while a merge is live.
  const tlist = [...new Set(tables.map(String).flatMap((t) => partyTablesOf(t)))];
  const mySeq = {};
  for (const t of tlist) mySeq[t] = (tileSeq[t] = (tileSeq[t] || 0) + 1);
  let results;
  try {
    results = await Promise.all(tlist.map(async (t) => {
      const sum = await api("GET", "/summary?table=" + encodeURIComponent(t));
      return { table: t, sum: sum || {} };
    }));
  } catch (e) { return pollOrders(); }      // network/parse blip → safe full reload
  if (dataSeq !== born) return;             // a FULL reload started — its fresher board wins

  // Patch the changed tables' tiles + refresh the restaurant-wide aggregates (unless a floor
  // action is mid-save, mirroring the board's floorOpsInFlight guard so optimism isn't clobbered).
  if (!floorOpsInFlight) {
    const s = state.summary || { tiles: {} };
    const tiles = Object.assign({}, s.tiles || {});
    const tset = new Set(tlist);
    let latest = null;
    for (const r of results) {
      const t = r.table;
      if (mySeq[t] !== tileSeq[t]) continue; // a newer targeted poll for THIS table won → skip just its tile
      // A table still holding unsent work keeps what is on screen — see mergeServerSummary().
      const heldNow = tablesWithUnsentWork();
      if (heldNow && heldNow.has(String(t)) && tiles[t]) { latest = r.sum; continue; }
      const tile = r.sum.tiles && r.sum.tiles[t];
      if (tile) tiles[t] = tile;            // the table now has a tile (occupied)
      else delete tiles[t];                 // the table dropped off the floor universe → back to plain Free
      latest = r.sum;                       // aggregates are identical across calls; keep the last
    }
    state.summary = Object.assign({}, s, { tiles }, latest ? {
      order_count: latest.order_count,
      latest_order_table: latest.latest_order_table,
      calls: latest.calls || [],
      requests: latest.requests || [],
      joiners: latest.joiners || [],
      blocklist: latest.blocklist || [],
      // WHICH TABLES ARE ONE PARTY rides on every summary response. It used to refresh only on
      // a FULL poll, so right after a merge the tiles had no "⇄ with T…" chip and the detail
      // counted one table's dishes until the 60s backstop caught up. (owner, 2026-08-03)
      merges: Array.isArray(latest.merges) ? latest.merges : (s.merges || []),
    } : {});
    state.boardLoaded = true;

    // Any OPEN-DETAIL table (docked, collapsed modal, or floating) that's among the changed
    // ones gets its full slice refreshed for the detail.
    //
    // …AND THE BILLS TAB'S LIVE LIST, WHICH IS NOT THE FLOOR (sweep #7, T30, 2026-08-30).
    // Everything this function refreshes above is the FLOOR: the tiles, the aggregates, the open
    // table details. The Bills → Live list is a different screen built from `state.data.orders`,
    // and the only writers of that array are loadAll / loadOrders / pollOrders (whole-board reads)
    // and mergeTableSlice (per table). So on a TARGETED breadcrumb — the common case, since every
    // order/item/session change names its table — the tile moved instantly and the bill card beside
    // it kept the old status for up to 60 seconds, until the backstop poll.
    //
    // MEASURED, not reasoned about: a probe order on its own table read "NEW ORDER" on the Bills
    // list, was set to `preparing` in the database, did not change in 30s while the panel logged
    // the breadcrumb arriving and refetching, and flipped to "PREPARING" the moment the 60s
    // backstop landed. (Two earlier attempts to measure this with a COUNT of cards were withdrawn:
    // ten sweep terminals write to the shared dev database and the count moved under the test.)
    //
    // The refresh is the SAME per-table slice the open details already use — three `?table=N`
    // reads, merged in — never a whole-board pollOrders(). That matters: the targeted path exists
    // because whole-board reads were ~96% of this product's egress, and "fix the Bills list by
    // reloading the board" would hand that straight back. Gated on the tab actually being open on
    // the live view, so a manager on the Tables tab (where a shift is spent) pays nothing at all.
    const billsListNeedsRows = state.tab === "orders" && ordersViewKey() === "live";
    const toRefresh = [...new Set([...detailTables(), ...(billsListNeedsRows ? tlist : [])])]
      .filter((t) => tset.has(t));
    if (toRefresh.length) {
      try {
        if (dataSeq !== born) return;
        await Promise.all(toRefresh.map((t) => loadTableSlice(t)));
      } catch {}
    }
  }

  // Route reconcileBoard's RENDER step through the INCREMENTAL patch for just these tables
  // (the chimes/alerts/counts are unchanged — only the floor's draw differs). Set the flag
  // right before, clear it right after: reconcileBoard runs synchronously, so the full-poll
  // path (pollOrders → reconcileBoard) can never see it set.
  // The PARTY-EXPANDED list, so a merged partner's tile is repainted too — its pixels come
  // from the parent tile that was just refetched above.
  targetedPatchTables = tlist;
  try { reconcileBoard(); } finally { targetedPatchTables = null; }
}

// startOrderWatch: put the floor on LIVE UPDATES. Nothing here repeats on a fast beat, and the
// summary used to say it did ("setInterval repeats it every second") — a sentence describing code
// that was replaced long ago, sitting at the top of the one function somebody opens to answer "how
// often does this panel ask the server?" (T3 sweep, 2026-08-10; the owner's rule is that the floor
// is never on a poll — reads are the cost, and a fast beat from every screen in the estate is what
// makes a busy evening worse, not better).
//
// What actually happens, in order of who does the work:
//   1. ONE first read to set the baseline, so nothing chimes for orders that were already there.
//   2. REALTIME does the updating: a breadcrumb naming the changed tables → pollTables(those), a
//      breadcrumb without tables → one full refresh, a menu/permission change → loadAll/whoami.
//   3. A 60-SECOND BACKSTOP, and only while the tab is visible — an idle tab in a back pocket
//      costs nothing at all.
//   4. LFH_RT.catchUp: ~5s, but ONLY while the socket is down AND reads are succeeding; it backs
//      off to a minute for as long as reads FAIL, and jitters, so a struggling database is never
//      hammered by twenty devices on the same beat.
//   5. If realtime never loaded at all, the same shape written out small (2s → doubling to 60s on
//      failure, jittered, nothing while hidden or offline).
function startOrderWatch() {
  // Boot grace: the initial page load already fetches /all + /summary + /platform fresh
  // (loadAll + this pollOrders + loadPlatform). The realtime CONNECT then fires its own
  // "full reconcile" (menu→loadAll, ops-full→pollOrders+loadPlatform) a moment later,
  // which just re-fetches all three a SECOND time — the boot-load duplication (each was
  // hit ~3×). Skip only the FULL realtime refresh during this short window; TARGETED
  // table events are never skipped, and after the window everything runs normally, so
  // there's zero steady-state staleness. (egress, 2026-07-06)
  rtBootGraceUntil = Date.now() + 3000;
  pollOrders(); // sets the baseline immediately (no alert on first run)
  // Realtime does the updating — the floor refreshes the instant an order or dish changes, and is
  // never on a beat of its own. The 60s timer below is a BACKSTOP for a dropped socket (skipped on
  // a hidden tab); the branch after it is the last resort for a browser where realtime never
  // loaded, and it backs off rather than repeating.
  if (window.LFH_RT) {
    // Split by topic: ops churn → cheap pollOrders(); menu content edits (dishes,
    // categories, filters, settings) → loadAll() so the dish lists refresh live too.
    LFH_RT.start({ handlers: {
      // TARGETED when the breadcrumb names specific tables; FULL otherwise (platform
      // change, wake, reconnect, initial). The full path also refreshes the Platform
      // tab badge — a dine-in table event can't have changed a platform order, so the
      // targeted path skips that extra fetch too.
      ops: (detail) => {
        if (detail && !detail.full && detail.tables && detail.tables.length) pollTables(detail.tables);
        else if (Date.now() >= rtBootGraceUntil) { pollOrders(); loadPlatform(); } // else: boot already loaded it
        // Pay Later view open? A park or collect touches orders → refresh the book LIVE
        // (loadKhataBook self-guards against overlap; one scoped read per event burst).
        if (state.tab === "orders" && ordersViewKey() === "khata") { state.khataLoadedAt = 0; loadKhataBook(); }
        // Inventory tab open? Stock DRAINS BY ITSELF on every order (trg_inv_deplete_order, mig
        // 224), so the figures on that screen were frozen from the moment it was opened while
        // service quietly emptied them. This is the only signal needed — stock moves because an
        // order moved — and LFH_INV.live() self-guards on "tab actually visible / no popup open /
        // not backgrounded" and coalesces a rush, so an idle floor pays nothing. (T13, 2026-08-05)
        if (state.tab === "inventory" && window.LFH_INV && window.LFH_INV.live) window.LFH_INV.live();
        // Is THIS screen the printer? Then an ops breadcrumb is also "a ticket may be waiting" — the
        // same event the kitchen screen prints on (mig 335 deliberately gives an auto job NO
        // breadcrumb of its own; it rides the order's). A no-op unless the device switch is on.
        managerPrintPass();
      },
      // `menu` carries dish/category/filter/settings edits AND — since mig 299 — a change to this
      // restaurant's permissions. So re-read who we are alongside the menu: refreshWhoami() is one
      // small GET that repaints only when the answer actually differs, so an ordinary dish edit
      // costs nothing extra. This is what makes an Access change land on an open panel instead of
      // waiting for someone to reload (T13 sweep, 2026-08-05). Not gated by the boot grace — the
      // boot read is the same one-shot, and a permission change must never be the thing we skip.
      menu: () => { refreshWhoami(); if (Date.now() >= rtBootGraceUntil) loadAll(); }, // boot already loaded the menu
    }});
    setInterval(() => { if (document.hidden) return; pollOrders(); loadPlatform(); }, 60000); // backup sync; skip on a hidden/backgrounded tab (realtime refetches on wake) so an idle tab stops costing egress (B18)
    // The print station's own backstop, and it runs even while the tab is HIDDEN — being covered by
    // another window is precisely the case this feature exists for. It is a tiny scoped read and it
    // returns immediately unless this device is switched on to print.
    setInterval(() => { managerPrintPass(); }, 20000);
    managerPrintPass();   // …and once on boot, so a ticket queued while this screen was shut prints now
    // CATCH UP WHILE THE SOCKET IS DOWN BUT READS STILL WORK (sweep 2026-08-04).
    // The 60s timer above was the ONLY backstop for a socket that is connected-but-dead — a
    // blocked websocket (restaurant wifi, a proxy) or a drop the browser hasn't noticed. So a
    // waiter sent an order and the manager's floor didn't show it for up to a MINUTE: no tile,
    // no badge, no chime, and the connection light often still reading weak rather than
    // offline, so nothing on screen explained the wait. The kitchen was given exactly this fix
    // (bug M9, 2026-07-05); the manager floor never got it.
    //
    // LFH_RT.catchUp is the sanctioned way and it is safe here: it does nothing while the
    // socket is live, the tab is hidden or the device is genuinely offline; it polls at ~5s
    // only while the socket is down AND reads are succeeding; it doubles to a minute for as
    // long as reads FAIL (so a struggling database is not hammered); and it jitters ±20% so
    // twenty devices never poll on the same beat. The `rethrow` flag is what lets it see a
    // failed read — without it there is nothing to back off from.
    if (LFH_RT.catchUp) LFH_RT.catchUp(() => pollOrders({ rethrow: true }));
  } else {
    // NO REALTIME AT ALL (realtime.js failed to load, or is blocked). This used to be a flat
    // `setInterval(..., 2000)` firing TWO whole-board reads (pollOrders + loadPlatform) — a fixed
    // two-second beat, from every manager screen in the estate, for as long as the page was open,
    // never backing off and never jittered. That is the exact shape CLAUDE.md's rush rule 4
    // forbids, and the reason is that a saturated database is what makes realtime unavailable in
    // the FIRST place: the moment things get bad every device switches to hammering it in
    // lockstep and keeps it down. The KITCHEN (backoffPoll) and the TABLET (_fbTick) were both
    // rewritten for this; the manager — the busiest panel of the three — was left behind
    // (T13 sweep, 2026-08-05).
    //
    // LFH_RT.catchUp() is the sanctioned shape but unreachable here (window.LFH_RT is absent, which
    // is what put us in this branch), so the same behaviour, written out small: 2s while the reads
    // succeed, doubling to a minute for as long as they FAIL, straight back to quick on the first
    // success, ±20% jitter so twenty screens never share a beat, and nothing at all while the tab
    // is hidden or the device is genuinely offline. `rethrow` is what lets it SEE a failed read —
    // without it there is nothing to back off from.
    let fbStep = 0;
    const fbSpread = (ms) => Math.round(ms * (0.8 + Math.random() * 0.4));
    const fbTick = async () => {
      if (document.hidden || navigator.onLine === false) { fbStep = 0; }   // nothing to catch up on
      else {
        try { await pollOrders({ rethrow: true }); loadPlatform(); fbStep = 0; }
        catch (e) { fbStep = Math.min(fbStep + 1, 5); }                    // 2s → 4 → 8 … → 60s
      }
      setTimeout(fbTick, fbSpread(Math.min(2000 * Math.pow(2, fbStep), 60000)));
    };
    setTimeout(fbTick, fbSpread(2000));
  }
}

